/**
 * Knowledge Ingestion Service
 *
 * Indexes learnings into the KnowledgeStore for hybrid retrieval.
 * Bridges the gap between JSONL learning storage and SQLite+FTS5+embeddings.
 *
 * @module services/knowledge-ingestion-service
 *
 * DEPRECATED (Day 4): Direct @vreko/intelligence imports replaced with daemon IPC.
 * Knowledge ingestion now routes through the daemon.
 */

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { errorMessage } from "@vreko/core";
import {
	ensureEmbeddingsReadyViaDaemon,
	generateEmbeddingViaDaemon,
	ingestKnowledgeViaDaemon,
} from "../daemon/local-service-adapter.js";

// =============================================================================
// TYPES
// =============================================================================

interface Learning {
	id: string;
	type: string;
	trigger: string | string[];
	action: string;
	source?: string;
	timestamp?: string;
	tier?: string;
	domain?: string;
	priority?: string;
}

export interface IngestionResult {
	success: boolean;
	indexed: number;
	skipped: number;
	errors: string[];
	embeddingsGenerated: number;
}

interface IngestionStats {
	totalChunks: number;
	withEmbedding: number;
	missingEmbedding: number;
	byType: Record<string, number>;
}

// =============================================================================
// SERVICE
// =============================================================================

/**
 * Track indexed learning IDs to avoid re-indexing (per workspace)
 * Day 4: Daemon manages the actual KnowledgeStore, we just track locally
 */
const indexedIds = new Map<string, Set<string>>();

/**
 * Whether embeddings model is ready (cached from daemon)
 */
let embeddingsReady = false;

/**
 * Get or create indexed IDs set for a workspace
 */
function getIndexedIds(workspaceRoot: string): Set<string> {
	let ids = indexedIds.get(workspaceRoot);
	if (!ids) {
		ids = new Set();
		indexedIds.set(workspaceRoot, ids);
	}
	return ids;
}

/**
 * Ensure embeddings model is loaded via daemon
 * Day 4: Daemon manages embeddings model lifecycle
 */
export async function ensureEmbeddingsReady(workspaceRoot?: string): Promise<boolean> {
	if (embeddingsReady) {
		return true;
	}

	if (!workspaceRoot) {
		return false;
	}

	try {
		const result = await ensureEmbeddingsReadyViaDaemon();
		if (result.success && result.ready) {
			embeddingsReady = true;
			return true;
		}
		return false;
	} catch (_error) {
		return false;
	}
}

/**
 * Check if embeddings are available without loading
 */
export function isEmbeddingsAvailable(): boolean {
	return embeddingsReady;
}

/**
 * Index a single learning into the KnowledgeStore
 *
 * Day 4: Uses daemon IPC for knowledge ingestion.
 *
 * @param workspaceRoot - Workspace root path
 * @param learning - Learning to index
 * @param generateEmbedding - Whether to generate embedding (default: true if model ready)
 */
export async function indexLearning(
	workspaceRoot: string,
	learning: Learning,
	generateEmbedding = true,
): Promise<{ success: boolean; error?: string }> {
	try {
		const indexed = getIndexedIds(workspaceRoot);

		// Skip if already indexed
		if (indexed.has(learning.id)) {
			return { success: true };
		}

		// Build chunk text from trigger (can be string or array)
		const triggerText = Array.isArray(learning.trigger) ? learning.trigger.join(", ") : learning.trigger;

		// Day 4: Use daemon IPC for knowledge ingestion
		const result = await ingestKnowledgeViaDaemon(workspaceRoot, {
			text: `${triggerText}\n${learning.action}`,
			source: learning.id,
			metadata: {
				type: learning.type,
				source: learning.source,
				domain: learning.domain,
				priority: learning.priority,
				timestamp: learning.timestamp,
				tier: learning.tier,
			},
		});

		if (result.success) {
			indexed.add(learning.id);

			// Generate embedding via daemon if requested
			if (generateEmbedding && result.id) {
				try {
					const textForEmbedding = `${triggerText} ${learning.action}`;
					const embeddingResult = await generateEmbeddingViaDaemon(textForEmbedding);
					if (!embeddingResult.success) {
						// Intentionally ignored: embedding generation failure is non-fatal for ingestion
					}
				} catch (_error) {
					// Intentionally ignored: embedding generation is best-effort
				}
			}

			return { success: true };
		}

		return { success: false, error: result.error };
	} catch (error) {
		return { success: false, error: errorMessage(error) };
	}
}

/**
 * Index all learnings from JSONL files into KnowledgeStore
 *
 * @param workspaceRoot - Workspace root path
 * @param options - Indexing options
 */
export async function indexAllLearnings(
	workspaceRoot: string,
	options: {
		/** Force re-index even if already indexed */
		force?: boolean;
		/** Skip embedding generation for speed */
		skipEmbeddings?: boolean;
		/** Specific files to index (default: all) */
		files?: string[];
	} = {},
): Promise<IngestionResult> {
	const result: IngestionResult = {
		success: true,
		indexed: 0,
		skipped: 0,
		errors: [],
		embeddingsGenerated: 0,
	};

	const learningsDir = join(workspaceRoot, ".vreko", "learnings");
	if (!existsSync(learningsDir)) {
		return result;
	}

	// Determine which files to index
	const defaultFiles = [
		"hot.jsonl",
		"learnings.jsonl",
		"domain-vscode.jsonl",
		"domain-web.jsonl",
		"domain-mcp-cli.jsonl",
		"domain-testing.jsonl",
		"anti-patterns.jsonl",
		"architecture-patterns.jsonl",
		"user-learnings.jsonl",
	];
	const filesToIndex = options.files || defaultFiles;

	// Ensure embeddings ready if not skipping
	const generateEmbeddings = !options.skipEmbeddings && (await ensureEmbeddingsReady());

	// Clear indexed IDs if forcing
	if (options.force) {
		indexedIds.delete(workspaceRoot);
	}

	// Index each file
	for (const filename of filesToIndex) {
		const filePath = join(learningsDir, filename);
		if (!existsSync(filePath)) {
			continue;
		}

		try {
			const content = readFileSync(filePath, "utf8");
			const lines = content.split("\n").filter((line) => line.trim());

			for (const line of lines) {
				try {
					const learning = JSON.parse(line) as Learning;
					if (!learning.id) {
						// Generate ID for seed data without IDs
						learning.id = `seed_${filename.replace(".jsonl", "")}_${result.indexed}`;
					}

					const indexResult = await indexLearning(workspaceRoot, learning, generateEmbeddings);

					if (indexResult.success) {
						result.indexed++;
						if (generateEmbeddings) {
							result.embeddingsGenerated++;
						}
					} else if (indexResult.error) {
						result.errors.push(`${learning.id}: ${indexResult.error}`);
					}
				} catch (parseError) {
					result.errors.push(`Parse error in ${filename}: ${parseError}`);
				}
			}
		} catch (readError) {
			result.errors.push(`Read error for ${filename}: ${readError}`);
		}
	}

	result.success = result.errors.length === 0;
	return result;
}

/**
 * Get indexing statistics for a workspace
 * Day 4: Daemon manages stats, return local tracking only
 */
export function getIngestionStats(workspaceRoot: string): IngestionStats {
	const indexed = getIndexedIds(workspaceRoot);
	return {
		totalChunks: indexed.size,
		withEmbedding: embeddingsReady ? indexed.size : 0,
		missingEmbedding: embeddingsReady ? 0 : indexed.size,
		byType: {}, // Would need daemon endpoint for detailed stats
	};
}

/**
 * Invalidate cache for a workspace
 * Call when learnings are added/updated
 */
export function invalidateCache(workspaceRoot: string): void {
	indexedIds.delete(workspaceRoot);
}

/**
 * Dispose all resources
 */
export function disposeAll(): void {
	indexedIds.clear();
	embeddingsReady = false;
}

// =============================================================================
// HELPERS
// =============================================================================

/**
 * Map learning type string to source type
 */
function _mapLearningTypeToSourceType(type: string): string {
	switch (type.toLowerCase()) {
		case "pattern":
		case "pat":
			return "pattern";
		case "pitfall":
		case "pit":
		case "anti-pattern":
			return "violation";
		case "architecture":
		case "arch":
		case "adr":
			return "adr";
		default:
			return "learning";
	}
}

/**
 * Calculate authority score based on learning metadata
 */
function _getAuthorityScore(learning: Learning): number {
	let score = 0.5; // Base score

	// Hot tier gets higher authority
	if (learning.tier === "hot") {
		score += 0.3;
	} else if (learning.tier === "warm") {
		score += 0.1;
	}

	// Priority boost
	if (learning.priority === "critical") {
		score += 0.2;
	} else if (learning.priority === "high") {
		score += 0.1;
	}

	// Seed data is authoritative
	if (learning.source === "seed") {
		score += 0.1;
	}

	return Math.min(1.0, score);
}
