// =============================================================================
// CONNECTION MANAGEMENT
// =============================================================================

/** Minimum time between connection attempts (ms) */
const MIN_RETRY_INTERVAL_MS = 2000;

/** Max consecutive failures before backing off */
const MAX_CONSECUTIVE_FAILURES = 10;

/** Socket path for the local service */
const SERVICE_SOCKET_PATH = process.env.VREKO_DAEMON_SOCKET ?? getDefaultSocketPath();

/** Deduplicates concurrent auto-start attempts */
let autoStartInProgress: Promise<void> | null = null;

/** Ready marker path for daemon startup probe */
const READY_MARKER_PATH = join(homedir(), ".vreko", ".ready");

/**
 * Check if daemon ready marker exists and is valid.
 * Returns true only if marker exists, has valid JSON, and PID matches running process.
 */
function isReadyMarkerValid(): boolean {
	try {
		if (!existsSync(READY_MARKER_PATH)) {
			return false;
		}

		const content = readFileSync(READY_MARKER_PATH, "utf8");
		const marker = JSON.parse(content);

		// Must have ready: true
		if (marker.ready !== true) {
			return false;
		}

		// If marker is older than 5 minutes, check the PID is still alive
		// rather than rejecting it. The daemon may have been running for hours.
		const readyAt = new Date(marker.readyAt).getTime();
		if (Date.now() - readyAt > 5 * 60 * 1000) {
			if (!marker.pid) {
				return false;
			}
			try {
				process.kill(marker.pid, 0); // signal 0 = existence check only
				return true;
			} catch {
				return false; // PID dead: marker is genuinely stale
			}
		}

		return true;
	} catch {
		return false;
	}
}

/**
 * Wait for daemon ready marker with exponential backoff.
 * Returns true if marker appears within timeout, false otherwise.
 */
async function waitForReadyMarker(timeoutMs = 30000): Promise<boolean> {
	const startTime = Date.now();
	let delay = 100;

	while (Date.now() - startTime < timeoutMs) {
		if (isReadyMarkerValid()) {
			return true;
		}
		await new Promise((r) => setTimeout(r, delay));
		delay = Math.min(delay * 2, 2000); // Exponential backoff up to 2s
	}

	return false;
}

/**
 * Attempt to auto-start the Vreko daemon.
 * Spawns the daemon binary (apps/local-service/dist/main.js) directly with 60min idle timeout.
 * Deduplicates concurrent calls  -  only one spawn happens at a time.
 */
/**
 * Resolve the daemon binary path.
 * CLI is at <workspace>/apps/cli/dist/index.js  -  navigate from there.
 */
function findDaemonBin(): string {
	// Allow explicit override (npx, symlink, or wrapper invocations)
	if (process.env.VREKO_DAEMON_BIN) {
		const explicit = process.env.VREKO_DAEMON_BIN;
		if (!existsSync(explicit)) {
			throw new Error(`VREKO_DAEMON_BIN points to missing file: ${explicit}`);
		}
		return explicit;
	}
	// Fallback: navigate from CLI binary location
	const cliBin = process.argv[1];
	if (!cliBin) {
		throw new Error("process.argv[1] not set  -  cannot locate daemon binary. Set VREKO_DAEMON_BIN env var.");
	}
	// apps/cli/dist → apps/cli → apps → workspace root
	const workspaceRoot = resolve(dirname(cliBin), "../../..");
	const daemonBin = join(workspaceRoot, "apps", "local-service", "dist", "main.js");
	if (!existsSync(daemonBin)) {
		throw new Error(`Daemon binary not found at: ${daemonBin}. Set VREKO_DAEMON_BIN env var.`);
	}
	return daemonBin;
}

async function autoStartDaemon(): Promise<void> {
	// Dedup check FIRST  -  before any async probe  -  so that two concurrent callers
	// that both see the socket missing are guaranteed to share a single spawn.
	if (autoStartInProgress) {
		return autoStartInProgress;
	}

	autoStartInProgress = (async () => {
		try {
			// Check if daemon is actually responsive, not just if socket file exists
			if (existsSync(SERVICE_SOCKET_PATH)) {
				// Verify daemon is actually listening by testing connection
				try {
					await new Promise<void>((resolve, reject) => {
						const sock = createConnection(SERVICE_SOCKET_PATH, () => {
							sock.end();
							resolve();
						});
						sock.on("error", reject);
						setTimeout(() => {
							sock.destroy();
							reject(new Error("connection timeout"));
						}, 500);
					});
					// Daemon is responsive - no need to start
					return;
				} catch {
					try {
						const { unlinkSync } = await import("node:fs");
						unlinkSync(SERVICE_SOCKET_PATH);
					} catch {
						// Ignore unlink errors
					}
				}
			}

			const daemonBin = findDaemonBin();

			// Check if Doppler is available for proper environment injection
			let useDoppler = false;
			try {
				execSync("which doppler", { stdio: "ignore" });
				useDoppler = true;
			} catch {
				// Doppler not installed, fall back to direct spawn
			}

			// CRITICAL: Redirect stdout/stderr to log files for detached processes
			// Using pipes causes SIGPIPE when parent exits; using "ignore" crashes on write
			const logDir = join(homedir(), ".vreko", "daemon");
			const logPath = join(logDir, "daemon.log");
			let logFd: number;
			try {
				mkdirSync(logDir, { recursive: true });
				logFd = openSync(logPath, "a");
			} catch {
				// Fallback: use stdout (will be ignored by parent)
				logFd = 1;
			}

			// Spawn the daemon binary directly (bypasses CLI's require.resolve ESM issue)
			// Use Doppler if available to inject secrets
			const spawnArgs = useDoppler
				? ["run", "--", process.execPath, daemonBin, "--idle-timeout", "60"]
				: [daemonBin, "--idle-timeout", "60"];
			const spawnCmd = useDoppler ? "doppler" : process.execPath;

			const child = spawn(spawnCmd, spawnArgs, {
				detached: true,
				stdio: ["ignore", logFd, logFd], // Redirect to log file
				env: process.env,
			});
			child.unref();
			// B3: Close the log file descriptor  -  child is fully detached after unref()
			if (logFd !== 1) {
				closeSync(logFd);
			}

			// B1: Log spawn errors instead of silently discarding them
			child.on("error", (spawnErr) => {
				// Log to stderr  -  logger may not be initialized in this context
				process.stderr.write(`[vreko] daemon spawn error: ${spawnErr.message}\n`);
			});

			// Wait up to 10 seconds for daemon to accept connections
			const deadline = Date.now() + 10_000;
			let lastError: Error | null = null;
			while (Date.now() < deadline) {
				if (existsSync(SERVICE_SOCKET_PATH)) {
					// Socket file exists  -  verify daemon is actually listening
					try {
						await new Promise<void>((resolve, reject) => {
							const sock = createConnection(SERVICE_SOCKET_PATH, () => {
								sock.end();
								resolve();
							});
							sock.on("error", reject);
							setTimeout(() => {
								sock.destroy();
								reject(new Error("connection timeout"));
							}, 500);
						});
						// Small delay to let daemon finish initializing after accepting connection
						await new Promise((r) => setTimeout(r, 300));
						// Clear all stale connection statuses so every workspace can
						// connect fresh to the new daemon without being blocked by
						// prior consecutive-failure counters.
						clearAllPoolConnectionStatuses();
						return; // Success!
					} catch (e) {
						lastError = e instanceof Error ? e : new Error(String(e));
						// Socket file exists but daemon not ready yet  -  wait and retry
					}
				}
				await new Promise((r) => setTimeout(r, 200));
			}
			throw new Error(
				`Daemon did not become ready within 10 seconds: ${lastError?.message ?? "socket not created"}`,
			);
		} finally {
			autoStartInProgress = null;
		}
	})();

	return autoStartInProgress;
}

/**
 * Normalize method names from dot notation (old daemon) to slash notation (new local-service).
 *
 * Lookup order:
 * 1. METHOD_NAME_MAP in @vreko/contracts (canonical, covers all known methods)
 * 2. Naive first-dot replace as fallback for unmapped methods
 */
export function normalizeMethod(method: string): string {
	const mapped = normalizeMethodName(method);
	// If the map returned the method unchanged, apply naive first-dot replace as fallback
	if (mapped === method && method.includes(".")) {
		return method.replace(".", "/");
	}
	return mapped;
}

/**
 * Get or create a connected VrekoLocalClient for a workspace.
 * Delegates connection/initialization to the shared client pool.
 * Applies per-workspace backoff and handles daemon auto-start on ENOENT.
 */
async function getClient(workspaceRoot: string): Promise<VrekoLocalClient | null> {
	// Backoff: if too many consecutive failures, wait before retrying
	const status = getPoolConnectionStatus(workspaceRoot);
	if (status) {
		const timeSinceLastAttempt = Date.now() - status.lastAttempt;
		if (status.consecutiveFailures >= MAX_CONSECUTIVE_FAILURES && timeSinceLastAttempt < MIN_RETRY_INTERVAL_MS) {
			return null;
		}
	}

	try {
		// acquireClient uses the shared pool  -  returns immediately if already connected
		const client = await acquireClient(workspaceRoot);

		setPoolConnectionStatus(workspaceRoot, {
			connected: true,
			lastAttempt: Date.now(),
			consecutiveFailures: 0,
		});

		// Reset circuit breaker on successful connection
		resetCircuitBreaker(workspaceRoot);

		return client;
	} catch (connectErr) {
		// If the socket doesn't exist OR daemon crashed (stale socket), try to auto-start it
		// "Connection closed" occurs when socket file exists but daemon isn't listening
		const isSocketMissingOrDead =
			connectErr instanceof Error &&
			(connectErr.message.includes("ENOENT") ||
				connectErr.message.includes("no such file") ||
				connectErr.message.includes("ECONNREFUSED") ||
				connectErr.message.includes("Connection timeout") ||
				connectErr.message.includes("connection timeout") ||
				connectErr.message.includes("Not connected") ||
				connectErr.message.includes("Connection closed") ||
				connectErr.message.includes("connection closed"));

		if (isSocketMissingOrDead) {
			try {
				// Clean up stale socket file before attempting to start daemon
				// This prevents "Connection closed" errors when daemon crashed but socket persists
				if (existsSync(SERVICE_SOCKET_PATH)) {
					try {
						unlinkSync(SERVICE_SOCKET_PATH);
					} catch {
						// Ignore cleanup errors - daemon start will fail if socket truly stuck
					}
				}

				await autoStartDaemon();

				// Wait for daemon ready marker before connecting
				// This prevents "degraded mode" by ensuring all services are initialized
				const ready = await waitForReadyMarker(30000);
				if (!ready) {
					// Daemon started but didn't become ready within timeout
					throw new Error("Daemon failed to initialize within 30 seconds");
				}

				// Stop the old client's ReconnectManager before discarding it.
				// Leaving it alive with autoReconnect:true races with the fresh
				// retryClient and causes a dual-reconnect storm.
				removePooledClient(workspaceRoot);

				// Fresh client for clean retry  -  stored back into the pool
				const retryClient = new VrekoLocalClient({
					timeout: 60000,
					autoReconnect: true,
					maxReconnectAttempts: 5,
					reconnectDelay: 1000,
					maxReconnectDelay: 30000,
				});
				await retryClient.connect();
				await retryClient.initialize({
					protocolVersion: "1.0.0",
					clientInfo: { name: "vreko-mcp", version: "1.0.0" },
					capabilities: { notifications: true },
				});

				setPooledClient(workspaceRoot, retryClient);
				setPoolConnectionStatus(workspaceRoot, {
					connected: true,
					lastAttempt: Date.now(),
					consecutiveFailures: 0,
				});

				// Reset circuit breaker on successful auto-start reconnect
				resetCircuitBreaker(workspaceRoot);

				return retryClient;
			} catch (_autoStartErr) {
				// Intentionally ignored: auto-start reconnect is best-effort, falls through to failure tracking
			}
		}

		const prevStatus = getPoolConnectionStatus(workspaceRoot);
		const failures = (prevStatus?.consecutiveFailures ?? 0) + 1;
		setPoolConnectionStatus(workspaceRoot, {
			connected: false,
			lastAttempt: Date.now(),
			consecutiveFailures: failures,
		});
		return null;
	}
}

/**
 * Check if the local service is available for a workspace
 */
export function isServiceAvailable(workspaceRoot: string): boolean {
	return getPooledClient(workspaceRoot)?.isConnected() ?? false;
}

/**
 * Disconnect and remove client for a workspace
 */
export async function disposeServiceConnection(workspaceRoot: string): Promise<void> {
	removePooledClient(workspaceRoot);
	clearPoolConnectionStatus(workspaceRoot);
}

/**
 * Disconnect all service connections.
 */
export async function disposeAllServiceConnections(): Promise<void> {
	clearPool();
}

// =============================================================================
// SNAPSHOT OPERATIONS (Daemon IPC - replaces SnapshotService)
// =============================================================================

export interface SnapshotViaDaemonResult {
	success: boolean;
	snapshotId?: string;
	fileCount?: number;
	totalSize?: number;
	createdAt?: string;
	reused?: boolean;
	reusedSnapshotId?: string;
	error?: string;
}

/**
 * Create snapshot via daemon IPC
 */
export async function createSnapshotViaDaemon(
	workspaceRoot: string,
	files: string[],
	options?: { reason?: string; trigger?: "manual" | "auto" | "ai-detection" },
): Promise<SnapshotViaDaemonResult> {
	const client = await getClient(workspaceRoot);
	if (!client) {
		return { success: false, error: "Daemon unavailable" };
	}

	try {
		const result = await client.call<{
			snapshotId: string;
			fileCount: number;
			totalSize: number;
			createdAt: string;
		}>("snapshot/create", {
			workspace: workspaceRoot,
			files,
			reason: options?.reason,
			trigger: options?.trigger ?? "auto",
		});

		return {
			success: true,
			snapshotId: result.snapshotId,
			fileCount: result.fileCount,
			totalSize: result.totalSize,
			createdAt: result.createdAt,
		};
	} catch (error) {
		return { success: false, error: errorMessage(error) };
	}
}

/**
 * List snapshots via daemon IPC
 */
export async function listSnapshotsViaDaemon(
	workspaceRoot: string,
	limit?: number,
): Promise<Array<{ id: string; createdAt: string; fileCount: number; reason?: string; protected?: boolean }>> {
	const client = await getClient(workspaceRoot);
	if (!client) {
		return [];
	}

	try {
		const result = await client.call<{
			snapshots: Array<{
				id: string;
				createdAt: string;
				fileCount: number;
				reason?: string;
				protected?: boolean;
			}>;
		}>("snapshot/list", {
			workspace: workspaceRoot,
			limit: limit ?? 20,
		});
		return result.snapshots;
	} catch {
		return [];
	}
}

/**
 * Restore snapshot via daemon IPC
 */
export async function restoreSnapshotViaDaemon(
	workspaceRoot: string,
	snapshotId: string,
	options?: { files?: string[]; dryRun?: boolean },
): Promise<{ success: boolean; restoredFiles?: string[]; errors?: string[] }> {
	const client = await getClient(workspaceRoot);
	if (!client) {
		return { success: false, errors: ["Daemon unavailable"] };
	}

	try {
		const result = await client.call<{
			restored: boolean;
			filesRestored: number;
			changes: Array<{ file: string; action: string }>;
			errors?: string[];
		}>("snapshot/restore", {
			workspace: workspaceRoot,
			snapshotId,
			files: options?.files,
			dryRun: options?.dryRun,
		});

		return {
			success: result.restored,
			restoredFiles: result.changes.map((c) => c.file),
			errors: result.errors,
		};
	} catch (error) {
		return { success: false, errors: [error instanceof Error ? error.message : String(error)] };
	}
}

