/**
 * Track when a learning is applied/used via daemon IPC.
 * Routes to the daemon's learning service which updates confidence using
 * Bayesian confidence scoring based on signal strength.
 *
 * @param workspaceRoot - Workspace root path for the learning context
 * @param learningId - ID of the learning that was applied (e.g., "learn_abc123")
 * @param signalStrength - Evidence strength for confidence update:
 *   - "weak": Minor observation (+0.05 confidence)
 *   - "medium": Moderate confirmation (+0.10 confidence, default)
 *   - "strong": Strong user confirmation (+0.20 confidence)
 * @returns Promise resolving to success status, new confidence, or error message
 *
 * @example
 * ```typescript
 * // Fire-and-forget pattern (used by TieredLearningService)
 * trackAppliedViaDaemon(workspaceId, learningId, "medium").catch(() => {});
 *
 * // With error handling
 * const result = await trackAppliedViaDaemon("/project", "learn_123", "strong");
 * if (result.success) {
 *   logger.debug(...);
 * }
 * ```
 */
export async function trackAppliedViaDaemon(
	workspaceRoot: string,
	learningId: string,
	signalStrength?: "weak" | "medium" | "strong",
): Promise<{ success: boolean; newConfidence?: number; error?: string }> {
	const client = await getClient(workspaceRoot);
	if (!client) {
		return { success: false, error: "Daemon unavailable" };
	}

	try {
		const result = await client.call<{ success: boolean; newConfidence?: number }>("learning/track-applied", {
			workspace: workspaceRoot,
			learningId,
			signalStrength: signalStrength ?? "medium",
		});
		return result;
	} catch (error) {
		return { success: false, error: errorMessage(error) };
	}
}

/**
 * Observe a pattern occurrence via daemon IPC for potential promotion to learning.
 * Records pattern signatures and tracks observation counts. When patterns reach
 * the promotion threshold (typically 3 observations), they become learnings.
 *
 * @param workspaceRoot - Workspace root path for pattern context
 * @param signature - Unique pattern signature (e.g., "rapid-write:config.ts")
 * @param patternType - Category of pattern: "pattern" | "pitfall" | "efficiency" | "discovery" | "workflow"
 * @param sessionId - Session ID where the pattern was observed
 * @param confidence - Initial confidence for the observation (0-1, default: 0.3)
 * @returns Promise resolving to observation result or error
 *
 * @example
 * ```typescript
 * // Observe a co-change pattern
 * const result = await observePatternViaDaemon(
 *   "/project",
 *   "cochange:auth.ts+session.ts",
 *   "pattern",
 *   "sess_abc123",
 *   0.5
 * );
 *
 * if (result.success && result.promoted) {
 *   logger.debug(...);
 * }
 * ```
 */
export async function observePatternViaDaemon(
	workspaceRoot: string,
	signature: string,
	patternType: "pattern" | "pitfall" | "efficiency" | "discovery" | "workflow",
	sessionId: string,
	confidence?: number,
): Promise<{
	success: boolean;
	promoted?: boolean;
	observationCount?: number;
	patternId?: string;
	error?: string;
}> {
	const client = await getClient(workspaceRoot);
	if (!client) {
		return { success: false, error: "Daemon unavailable" };
	}

	try {
		const result = await client.call<{ promoted: boolean; observationCount: number; patternId: string }>(
			"learning/observe-pattern",
			{
				workspace: workspaceRoot,
				signature,
				patternType,
				sessionId,
				confidence: confidence ?? 0.3,
			},
		);
		return { success: true, ...result };
	} catch (error) {
		return { success: false, error: errorMessage(error) };
	}
}

