// SESSION-04: reconnect retry backoff delays (ms)
const RECONNECT_DELAYS = [100, 500, 2000] as const;

// SESSION-04: error messages indicating a stale/broken socket (not a logic error)
function isStaleSocketError(error: unknown): boolean {
	if (!(error instanceof Error)) {
		return false;
	}
	const msg = error.message;
	return (
		msg.includes("ECONNRESET") ||
		msg.includes("ECONNREFUSED") ||
		msg.includes("EPIPE") ||
		msg.includes("ENOTCONN") ||
		msg.includes("Connection closed") ||
		msg.includes("connection closed") ||
		msg.includes("Not connected") ||
		msg.includes("Broken pipe") ||
		msg.includes("broken pipe")
	);
}

/**
 * Contract validation failures must surface to callers.
 * Collapsing them into `null` makes protocol drift look like daemon unavailability.
 */
export function shouldRethrowDaemonRequestError(error: unknown): boolean {
	return error instanceof JsonRpcClientError && error.code === ProtocolErrorCode.InvalidParams;
}

export function createServiceClient(workspaceRoot: string): {
	isAvailable: () => boolean;
	request: <T>(method: string, params: Record<string, unknown>) => Promise<T | null>;
	notifySnapshotCreated: (snapshotId: string, filePath?: string) => Promise<boolean>;
} {
	return {
		isAvailable: () => isServiceAvailable(workspaceRoot),
		// SESSION-04: retry wrapper  -  detects stale-socket errors and forces a fresh connection
		request: async <T>(method: string, params: Record<string, unknown>): Promise<T | null> => {
			for (let attempt = 0; attempt <= RECONNECT_DELAYS.length; attempt++) {
				const client = await getClient(workspaceRoot);
				if (!client) {
					return null;
				}
				try {
					return await client.call<T>(normalizeMethod(method) as LocalServiceMethod, params);
				} catch (error) {
					if (attempt < RECONNECT_DELAYS.length && isStaleSocketError(error)) {
						// Force fresh connection on next attempt
						removePooledClient(workspaceRoot);
						await new Promise<void>((r) => setTimeout(r, RECONNECT_DELAYS[attempt]));
						continue;
					}
					if (shouldRethrowDaemonRequestError(error)) {
						throw error;
					}
					// Non-retryable error OR exhausted all retries
					return null;
				}
			}
			return null;
		},
		notifySnapshotCreated: async (snapshotId: string, filePath?: string): Promise<boolean> => {
			return notifySnapshotCreatedViaService(workspaceRoot, snapshotId, filePath);
		},
	};
}

