export async function recordFileModificationViaService(
	workspaceRoot: string,
	filePath: string,
	linesChanged: number,
	aiAttributed: boolean,
): Promise<boolean> {
	const client = await getClient(workspaceRoot);
	if (!client) {
		return false;
	}
	// Resolve to the actual git repository root before forwarding to the daemon.
	// When the MCP server runs from a sub-package directory (e.g. apps/cli),
	// workspaceRoot reflects that sub-package rather than the repo root. The daemon
	// normalises filePath against the workspace it receives, so passing a sub-package
	// path would produce spurious prefixes (e.g. apps/cli/packages/mcp/…) in
	// fileIndex keys. Resolving to the git root eliminates the prefix.
	const resolvedWorkspace = resolveToGitRoot(workspaceRoot) ?? workspaceRoot;
	try {
		await client.mcp.fileModified({
			workspace: resolvedWorkspace,
			path: filePath,
			linesChanged,
			aiAttributed,
			aiTool: "claude",
		});
		return true;
	} catch {
		return false;
	}
}

export async function notifySnapshotCreatedViaService(
	workspaceRoot: string,
	snapshotId: string,
	filePath?: string,
	trigger?: "manual" | "auto" | "ai-detection",
): Promise<boolean> {
	const client = await getClient(workspaceRoot);
	if (!client) {
		return false;
	}

	try {
		await client.mcp.snapshotCreated({
			workspace: workspaceRoot,
			id: snapshotId,
			filePath: filePath || "unknown",
			trigger: trigger || "ai-detection",
			source: "mcp",
		});
		return true;
	} catch (error) {
		const _mcpError =
			error instanceof Error
				? createMcpErrorFromCause(
						McpErrorCode.DAEMON_REQUEST_FAILED,
						"Failed to notify service of snapshot creation",
						error,
						{ snapshotId, filePath },
					)
				: createMcpError(McpErrorCode.DAEMON_REQUEST_FAILED, `Failed to notify service: ${String(error)}`, {
						snapshotId,
						filePath,
					});
		return false;
	}
}

export async function notifySnapshotCreatedResult(
	workspaceRoot: string,
	snapshotId: string,
	filePath?: string,
	trigger?: "manual" | "auto" | "ai-detection",
): Promise<Result<void, McpError>> {
	const client = await getClient(workspaceRoot);
	if (!client) {
		return err(
			createMcpError(McpErrorCode.DAEMON_UNAVAILABLE, "Local service is not available", {
				workspaceRoot,
				snapshotId,
			}),
		);
	}

	try {
		await client.mcp.snapshotCreated({
			workspace: workspaceRoot,
			id: snapshotId,
			filePath: filePath || "unknown",
			trigger: trigger || "ai-detection",
			source: "mcp",
		});
		return ok(undefined);
	} catch (error) {
		const mcpError =
			error instanceof Error
				? createMcpErrorFromCause(
						McpErrorCode.DAEMON_REQUEST_FAILED,
						"Failed to notify service of snapshot creation",
						error,
						{ snapshotId, filePath },
					)
				: createMcpError(McpErrorCode.DAEMON_REQUEST_FAILED, `Failed to notify service: ${String(error)}`, {
						snapshotId,
						filePath,
					});
		return err(mcpError);
	}
}

