/**
 * Seed initial learnings via daemon IPC
 */
export async function seedLearningsViaDaemon(
	workspaceRoot: string,
	learnings: Array<{
		id?: string;
		type: string;
		tier?: string;
		trigger: string | string[];
		action: string;
		solution?: string;
		source?: string;
		timestamp?: string;
		priority?: string;
		domain?: string;
	}>,
): Promise<{ success: boolean; seeded?: number; error?: string }> {
	const client = await getClient(workspaceRoot);
	if (!client) {
		return { success: false, error: "Daemon unavailable" };
	}

	try {
		// Normalize trigger to string for daemon
		const normalizedLearnings = learnings.map((l) => ({
			...l,
			trigger: Array.isArray(l.trigger) ? l.trigger.join(", ") : l.trigger,
		}));
		const result = await client.call<{ seeded: number }>("learning/seed", {
			workspace: workspaceRoot,
			learnings: normalizedLearnings,
		});
		return { success: true, seeded: result.seeded };
	} catch (error) {
		return { success: false, error: errorMessage(error) };
	}
}

