export interface SimilarPatternMatch {
	file: string;
	relevance: string;
	score: number;
}

/**
 * Find files with similar structural patterns via daemon IPC.
 * Replaces direct PatternReuseService instantiation in advise.ts.
 * Returns empty array if daemon unavailable (graceful fallback).
 */
export async function findSimilarPatternsViaDaemon(
	workspaceRoot: string,
	targetFiles: string[],
	limit = 5,
): Promise<SimilarPatternMatch[]> {
	const client = await getClient(workspaceRoot);
	if (!client) {
		// Graceful fallback: return empty patterns when daemon unavailable
		return [];
	}

	try {
		const result = await client.call<{
			patterns: Array<{ file: string; relevance: string; score: number }>;
		}>("intelligence/findSimilarPatterns", {
			workspace: workspaceRoot,
			targetFiles,
			limit,
		});
		return result.patterns || [];
	} catch {
		// Graceful fallback: return empty patterns on error
		return [];
	}
}

