/**
 * Pending Queue  -  Offline Learning Buffer
 *
 * When vreko_learn is called while the daemon is offline, learnings are
 * written to a workspace-local JSONL file (.vreko/learnings/pending.jsonl)
 * instead of being silently dropped. The next vreko call drains the file
 * by replaying each entry as a daemon IPC call.
 *
 * File layout (workspace-local, NOT global ~/.vreko):
 *   pending.jsonl          -  active queue, drained on next vreko call
 *   pending.archive.jsonl  -  overflow archive when active queue hits the cap
 *
 * Size cap: 10MB OR 10,000 entries → atomic rename to pending.archive.jsonl.
 * Archive is also drained by drainPendingQueue (after pending.jsonl).
 *
 * @module tools/v2/utils/pending-queue
 */

import { existsSync, mkdirSync, readFileSync, renameSync, rmSync, statSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

// =============================================================================
// Types
// =============================================================================

export interface PendingEntry {
	/** Learning type - must be a value accepted by the daemon's LearningType enum */
	type: string;
	/** The condition under which this rule applies */
	trigger: string;
	/** What to do when the trigger fires */
	action: string;
	/** Optional source tag */
	source?: string;
	/** ISO 8601 timestamp of when the entry was queued */
	queuedAt: string;
}

export interface DeadLetterEntry {
	entry: PendingEntry;
	rejectedAt: string;
	errorCode?: number;
	errorMessage: string;
}

// =============================================================================
// Constants
// =============================================================================

const MAX_BYTES = 10 * 1024 * 1024; // 10MB
const MAX_ENTRIES = 10_000;

// =============================================================================
// Path helpers
// =============================================================================

function getPendingPath(workspacePath: string): string {
	return join(workspacePath, ".vreko", "learnings", "pending.jsonl");
}

function getArchivePath(workspacePath: string): string {
	return join(workspacePath, ".vreko", "learnings", "pending.archive.jsonl");
}

function getDeadLetterPath(workspacePath: string): string {
	return join(workspacePath, ".vreko", "learnings", "dead-letter.jsonl");
}

// =============================================================================
// Public API
// =============================================================================

/**
 * Append a learning entry to the pending queue.
 *
 * If the queue reaches 10MB or 10,000 entries, it is atomically renamed
 * to pending.archive.jsonl before the new entry is written to a fresh
 * pending.jsonl. The archive is also drained by drainPendingQueue.
 *
 * Uses O_APPEND write mode  -  atomic for writes < PIPE_BUF (~4KB) on local
 * filesystems. Individual JSON entries are well under that limit.
 *
 * @param workspacePath - Absolute path to the workspace root
 * @param entry - The learning entry to queue
 */
export function appendToPendingQueue(workspacePath: string, entry: PendingEntry): void {
	const queuePath = getPendingPath(workspacePath);
	const archivePath = getArchivePath(workspacePath);

	// Ensure the directory exists before writing
	mkdirSync(dirname(queuePath), { recursive: true });

	// Check size/entry cap before appending
	if (existsSync(queuePath)) {
		const stat = statSync(queuePath);
		const capHit =
			stat.size >= MAX_BYTES ||
			readFileSync(queuePath, "utf8")
				.split("\n")
				.filter((l) => l.trim().length > 0).length >= MAX_ENTRIES;

		if (capHit) {
			if (existsSync(archivePath)) {
				// Archive already exists  -  merge rather than clobber to avoid data loss.
				// Append the current queue's content to the existing archive, then remove the queue.
				writeFileSync(archivePath, readFileSync(queuePath, "utf8"), { flag: "a", encoding: "utf8" });
				rmSync(queuePath);
			} else {
				renameSync(queuePath, archivePath);
			}
		}
	}

	// Append entry (O_APPEND  -  never overwrites existing content)
	const line = `${JSON.stringify(entry)}\n`;
	writeFileSync(queuePath, line, { flag: "a", encoding: "utf8" });
}

/**
 * Drain pending.jsonl and pending.archive.jsonl by replaying each entry
 * as a daemon IPC call.
 *
 * Drain order: pending.jsonl first (most recent), then pending.archive.jsonl.
 * For each file: read all entries → call sendToIPC for each → clear file on
 * completion. If sendToIPC throws for an individual entry, that entry is
 * skipped and the drain continues (fail-open to avoid blocking all learnings
 * on a single bad entry).
 *
 * This function is called at the top of handleVreko, BEFORE the
 * intelligence briefing is assembled and returned.
 *
 * @param workspacePath - Absolute path to the workspace root
 * @param sendToIPC - Async function that sends one PendingEntry to the daemon
 */
export async function drainPendingQueue(
	workspacePath: string,
	sendToIPC: (entry: PendingEntry) => Promise<void>,
): Promise<void> {
	const filePaths = [getPendingPath(workspacePath), getArchivePath(workspacePath)];

	for (const filePath of filePaths) {
		if (!existsSync(filePath)) {
			continue;
		}

		const raw = readFileSync(filePath, "utf8");
		const lines = raw.split("\n").filter((l) => l.trim().length > 0);

		if (lines.length === 0) {
			continue;
		}

		for (const line of lines) {
			try {
				const entry = JSON.parse(line) as PendingEntry;
				await sendToIPC(entry);
			} catch (err) {
				// Dead-letter entries that fail IPC (schema rejection, malformed, etc.)
				// so they are observable and countable rather than silently lost.
				// Do NOT abort the drain - continue processing remaining entries.
				try {
					let parsedEntry: PendingEntry;
					try {
						parsedEntry = JSON.parse(line) as PendingEntry;
					} catch {
						parsedEntry = {
							type: "unknown",
							trigger: line,
							action: "",
							queuedAt: new Date().toISOString(),
						};
					}
					const deadEntry: DeadLetterEntry = {
						entry: parsedEntry,
						rejectedAt: new Date().toISOString(),
						errorCode:
							err instanceof Error && "code" in err ? (err as Error & { code?: number }).code : undefined,
						errorMessage: err instanceof Error ? err.message : String(err),
					};
					const dlPath = getDeadLetterPath(workspacePath);
					mkdirSync(dirname(dlPath), { recursive: true });
					writeFileSync(dlPath, `${JSON.stringify(deadEntry)}\n`, { flag: "a", encoding: "utf8" });
				} catch {
					// If writing to dead-letter also fails, we cannot do more - continue drain.
				}
			}
		}

		// Clear the file after processing all entries
		writeFileSync(filePath, "", "utf8");
	}
}
