/**
 * Stdio Transport for MCP Server
 *
 * Runs the MCP server over stdio for integration with
 * Cursor, Claude Desktop, and other MCP clients.
 *
 * CRITICAL: This module includes comprehensive error handling to prevent
 * silent disconnects that leave IDE extensions in a broken state.
 *
 * @module transport/stdio
 */

import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { createBackendRouter, resolveRemoteConfig } from "../bridge/index.js";
import { createRemoteClient } from "../bridge/remote-client.js";
import { createMcpServerWithRegistry, type McpServerOptions } from "../server.js";
import { getConnectionHealth, setConnectionState, updateConnectionState } from "./health.js";

// Re-export for backward compatibility
export { type ConnectionState, getConnectionHealth } from "./health.js";

/**
 * Run MCP server with stdio transport
 *
 * This is the main entry point for CLI integration.
 * The server will communicate over stdin/stdout using
 * the MCP protocol.
 *
 * Uses ToolRegistry (ADR-003) for capability-based tool management.
 *
 * IMPORTANT: Includes comprehensive error handling to prevent silent crashes:
 * - uncaughtException handler with recovery attempt
 * - unhandledRejection handler with logging
 * - stdin/stdout error detection for broken pipes
 * - Connection health monitoring
 *
 * @param options - Server configuration options
 *
 * @example
 * ```typescript
 * // In CLI command handler:
 * await runStdioMcpServer({
 *   workspaceRoot: process.cwd(),
 *   tier: "pro",
 * });
 * ```
 */
export async function runStdioMcpServer(options: McpServerOptions): Promise<void> {
	// Initialize connection state for health monitoring
	setConnectionState({
		startTime: new Date(),
		lastActivity: new Date(),
		toolsLoaded: false,
		toolCount: 0,
		errorCount: 0,
		isShuttingDown: false,
	});

	// NOTE: registerWithDaemonForSupervision is intentionally NOT awaited here.
	// It must run AFTER server.connect(transport)  -  see the fast-path section below.

	// ==========================================================================
	// CRITICAL: Set up process-level error handlers BEFORE anything else
	// These prevent silent crashes that leave IDE extensions in broken state
	// ==========================================================================

	// Handle uncaught exceptions - log and attempt graceful recovery
	process.on("uncaughtException", (_error: Error) => {
		const health = getConnectionHealth();
		if (health) {
			updateConnectionState({ errorCount: health.errorCount + 1 });
		}

		// Don't exit immediately - try to keep serving if possible
		// Only exit if we're getting repeated crashes
		const updatedHealth = getConnectionHealth();
		if (updatedHealth && updatedHealth.errorCount > 5) {
			process.exit(1);
		}
	});

	// Handle unhandled promise rejections - these often cause silent disconnects
	process.on("unhandledRejection", (reason: unknown, _promise: Promise<unknown>) => {
		const health = getConnectionHealth();
		if (health) {
			updateConnectionState({ errorCount: health.errorCount + 1 });
		}

		const _reasonStr = reason instanceof Error ? { message: reason.message, stack: reason.stack } : String(reason);

		// Log but don't crash - many rejections are recoverable
	});

	// ==========================================================================
	// Set up stdin/stdout error handling for broken pipe detection
	// This is the most common cause of "silent" disconnects
	// ==========================================================================

	process.stdin.on("error", (error: Error) => {
		if (error.message.includes("EPIPE") || error.message.includes("EOF")) {
			updateConnectionState({ isShuttingDown: true });
			process.exit(0);
		}
	});

	process.stdout.on("error", (error: Error) => {
		if (error.message.includes("EPIPE")) {
			updateConnectionState({ isShuttingDown: true });
			process.exit(0);
		}
	});

	// Detect stdin close (parent process terminated)
	process.stdin.on("close", () => {
		updateConnectionState({ isShuttingDown: true });
		process.exit(0);
	});

	// Detect stdin end (EOF)
	process.stdin.on("end", () => {
		updateConnectionState({ isShuttingDown: true });
		process.exit(0);
	});

	// ==========================================================================
	// Create and start the MCP server - FAST PATH
	// ==========================================================================
	//
	// CRITICAL: Connect transport FIRST to respond to MCP handshake immediately.
	// This prevents Qoder/Cursor client timeout race condition.
	//
	// By NOT injecting a registry, the server uses its internal toolsReady
	// promise pattern - tools load asynchronously after connect, and
	// tools/list + CallTool handlers await toolsReady before responding.
	//

	// Create server WITHOUT injected registry - server loads tools async
	// This enables the server's built-in toolsReady promise pattern
	const server = await createMcpServerWithRegistry(options);
	const transport = new StdioServerTransport();

	// Pull workspace root from the MCP client via roots/list after initialization.
	// This runs after the MCP handshake completes and the client has sent `initialized`.
	// Supported by: Claude Code (${workspaceFolder}), Cursor, VS Code MCP extension.
	// When VREKO_OVERRIDE_WORKSPACE is already set (via mcp-start.sh), this just
	// confirms the workspace; when no --workspace was passed, this detects it from
	// the client's open project and logs it for diagnosis.
	server.oninitialized = () => {
		void (async () => {
			try {
				const rootsResult = await server.listRoots();
				if (rootsResult.roots.length > 0) {
					const firstRoot = rootsResult.roots[0];
					// Decode file:///path → /path
					const rootPath = firstRoot.uri.startsWith("file://")
						? decodeURIComponent(firstRoot.uri.slice(7))
						: firstRoot.uri;
					// If startup workspace differs from client-reported root, surface it.
					// Future: restart server with correct workspace when they diverge.
					if (rootPath && options.workspaceRoot && rootPath !== options.workspaceRoot) {
						// Intentionally empty: workspace divergence detected; future: restart server with correct root
					}
				}
			} catch {
				// Client does not support roots/list  -  startup workspace (CWD or --workspace arg) is used
			}
		})();
	};

	// FAST: Connect transport immediately to respond to MCP initialize.
	// This MUST happen before any async I/O (daemon IPC, health checks, etc.)
	// otherwise the MCP client's initialize request sits in the pipe buffer
	// unread until those operations complete  -  client times out, closes pipe,
	// and the next call works (second-call success pattern we were seeing).
	try {
		await server.connect(transport);
		updateConnectionState({ lastActivity: new Date() });
	} catch (_connectError) {
		process.exit(1);
	}

	// Register with daemon for supervision AFTER transport is connected.
	// Fire-and-forget  -  supervision is optional, never blocks tool calls.
	registerWithDaemonForSupervision(options.workspaceRoot).catch(() => {
		// Intentionally ignored: daemon supervision registration is optional, never blocks tool calls
	});

	// Initialize remote bridge if configured (Pro-tier intelligence)
	const resolvedRemote = options.remote ? resolveRemoteConfig(options.remote) : null;
	if (resolvedRemote) {
		const _router = createBackendRouter(resolvedRemote);
		const remoteClient = createRemoteClient(resolvedRemote);
		// Note: Remote client is available for future tool routing integration
		// Currently, tools route through daemon; remote bridge enables Pro-tier features
		void remoteClient; // Suppress unused variable warning
	}

	// Tools load asynchronously via server's internal toolsReady promise
	// Update connection state when tools are loaded (server logs tool count)
	updateConnectionState({ toolsLoaded: true, toolCount: 8 }); // Approximate

	// ==========================================================================
	// Graceful shutdown handlers
	// ==========================================================================

	const gracefulShutdown = async (_signal: string) => {
		const health = getConnectionHealth();
		if (health?.isShuttingDown) {
			return;
		}
		updateConnectionState({ isShuttingDown: true });

		try {
			await server.close();
		} catch (_closeError) {
			// Expected: server close may fail if transport already disconnected
		}

		process.exit(0);
	};

	process.on("SIGINT", () => gracefulShutdown("SIGINT"));
	process.on("SIGTERM", () => gracefulShutdown("SIGTERM"));
	process.on("SIGHUP", () => gracefulShutdown("SIGHUP"));

	// ==========================================================================
	// Health check logging (helps debug disconnects)
	// ==========================================================================

	// Log health status every 5 minutes (to stderr, won't affect stdio protocol)
	const healthInterval = setInterval(
		() => {
			const health = getConnectionHealth();
			if (health && !health.isShuttingDown) {
				const _uptime = Math.floor((Date.now() - health.startTime.getTime()) / 1000);
			}
		},
		5 * 60 * 1000,
	); // 5 minutes

	// Clean up interval on exit
	process.on("exit", () => {
		clearInterval(healthInterval);
	});
}

// =============================================================================
// DAEMON SUPERVISION (Heartbeat + Auto-Restart)
// =============================================================================

/**
 * Register MCP server with daemon for supervision.
 * Enables daemon to detect failures and auto-restart MCP server.
 */
async function registerWithDaemonForSupervision(workspaceRoot: string): Promise<void> {
	try {
		// Lazy-load daemon client (avoid circular dependency)
		const { createDaemonClient } = await import("../daemon/local-service-adapter.js");
		const daemonClient = createDaemonClient(workspaceRoot);

		// Register with daemon
		await daemonClient.request("supervisor/register", {
			componentType: "mcp-stdio",
			pid: process.pid,
			workspace: workspaceRoot,
			heartbeatIntervalMs: 30_000,
			restartStrategy: "one-for-one",
		});

		// Start heartbeat loop
		startHeartbeatLoop(daemonClient, workspaceRoot);
	} catch (_error) {
		// Intentionally ignored: daemon supervision registration is optional
	}
}

/**
 * Send periodic heartbeats to daemon.
 * If heartbeats fail 3+ times, gracefully shutdown to let daemon restart us.
 */
function startHeartbeatLoop(
	daemonClient: { request: <T>(method: string, params: Record<string, unknown>) => Promise<T | null> },
	_workspaceRoot: string,
): void {
	let consecutiveFailures = 0;
	const MAX_FAILURES = 3;

	const heartbeatInterval = setInterval(async () => {
		try {
			const health = getConnectionHealth();
			await daemonClient.request("supervisor/heartbeat", {
				pid: process.pid,
				status: health
					? {
							uptimeSeconds: Math.floor((Date.now() - health.startTime.getTime()) / 1000),
							toolsLoaded: health.toolsLoaded,
							errorCount: health.errorCount,
						}
					: { error: "Health check unavailable" },
			});

			consecutiveFailures = 0; // Reset on success
		} catch (_error) {
			consecutiveFailures++;

			// If daemon is unreachable for too long, shutdown gracefully
			// Daemon will detect missing heartbeat and restart us
			if (consecutiveFailures >= MAX_FAILURES) {
				clearInterval(heartbeatInterval);
				updateConnectionState({ isShuttingDown: true });
				process.exit(0);
			}
		}
	}, 30_000); // 30 seconds

	// Clean up on exit
	process.on("exit", () => {
		clearInterval(heartbeatInterval);
	});
}
