/**
 * Intelligence Facade Singleton
 *
 * Provides lazy-initialized Intelligence instances per workspace.
 * Used by MCP handlers to access validation, learning, and context retrieval.
 *
 * @module facades/intelligence
 *
 * DEPRECATED (Day 4): Direct @vreko/intelligence imports replaced with daemon IPC.
 * All intelligence operations now route through the daemon.
 */

import {
	type ContextViaDaemonResult,
	getContextViaDaemon,
	getIntelligenceViaDaemon,
	getVitalsViaDaemon,
	type VitalsViaDaemonResult,
} from "../daemon/intelligence-adapter.js";

// =============================================================================
// TYPES (local definitions, no runtime imports from @vreko/intelligence)
// =============================================================================

export interface ViolationReportResult {
	id: string;
	count: number;
	shouldPromote: boolean;
	shouldAutomate: boolean;
}

export interface PatternCheckResult {
	overall: {
		score: number;
		status: string;
		passed: boolean;
		confidence: number;
		totalIssues: number;
	};
	recommendation: string;
	layers: Array<{
		name: string;
		layer: string;
		score: number;
		issues: unknown[];
		passed: boolean;
		duration: number;
	}>;
	focusPoints: string[];
	issues: Array<{ rule: string; message: string; file: string; line?: number }>;
	duration: number;
}

export interface ReviewWorkResult {
	issues: unknown[];
	suggestions: unknown[];
	suggestedLearnings: Array<{ type: string; trigger: string; action: string }>;
	readyToCommit: boolean;
	suggestedCommitMessage: string;
	validation: PatternCheckResult;
}

export interface Intelligence {
	getContext(options: { task?: string; keywords?: string[] }): Promise<ContextViaDaemonResult>;
	getVitals(): Promise<VitalsViaDaemonResult>;
	initialize(): Promise<void>;
	startSession(): Promise<void>;
	reportViolation(violation: {
		type: string;
		file: string;
		message: string;
		reason?: string;
		prevention?: string;
	}): Promise<ViolationReportResult>;
	checkPatterns(files: string[], options?: { workspaceRoot: string }): Promise<PatternCheckResult>;
	reviewWork(options: { workspaceRoot: string; skipPatterns?: boolean }): Promise<ReviewWorkResult>;
	getFileModifications(
		files: string[],
		workspaceRoot?: string,
	): Promise<Array<{ file: string; modifications: unknown[] }>>;
	getVitalsSnapshot(
		workspaceRoot?: string,
	): Promise<{ pressure: number; snapshotCount: number; pulse?: number; trajectory?: string }>;
}

// =============================================================================
// PUBLIC API
// =============================================================================

/**
 * In-memory violation counter keyed by `${workspaceRoot}::${type}::${file}`.
 * Tracks cumulative occurrences so that repeated violations increment the count
 * even when the daemon is unavailable.
 */
const violationCounts = new Map<string, number>();

/**
 * Get or create an Intelligence instance for a workspace
 *
 * Intelligence is the shared session store across all surfaces (Extension, MCP, CLI).
 * All surfaces use the same workspace-keyed persistence path for session coordination.
 *
 * @param workspaceRoot - Absolute path to workspace root
 * @returns Intelligence instance configured for the workspace
 *
 * @example
 * ```typescript
 * const intel = getIntelligence("/path/to/workspace");
 * const context = await intel.getContext({ task: "Add auth" });
 * ```
 */
export function getIntelligence(workspaceRoot: string): Intelligence {
	// Return a proxy that delegates to daemon IPC
	return {
		getContext: (options) => getContextViaDaemon(workspaceRoot, options),
		getVitals: () => getVitalsViaDaemon(workspaceRoot),
		initialize: async () => {
			// Daemon connection is lazy-initialized
		},
		startSession: async () => {
			// Session management is handled by daemon
		},
		reportViolation: async (violation) => {
			// Increment in-memory counter regardless of daemon availability
			const key = `${workspaceRoot}::${violation.type}::${violation.file}`;
			const prev = violationCounts.get(key) ?? 0;
			const count = prev + 1;
			violationCounts.set(key, count);

			// Best-effort daemon sync (non-blocking  -  daemon may not be running in tests)
			try {
				const { addLearningViaDaemon } = await import("../daemon/local-service-adapter.js");
				await addLearningViaDaemon(workspaceRoot, {
					type: "violation",
					trigger: violation.type,
					action: violation.message,
					source: violation.file,
				});
			} catch {
				// Daemon unavailable  -  proceed with in-memory count only
			}

			return {
				id: `violation-${violation.type}-${violation.file}-${count}`,
				count,
				shouldPromote: count >= 3,
				shouldAutomate: count >= 5,
			};
		},
		checkPatterns: async (_files: string[], _options?: { workspaceRoot: string }) => {
			const startTime = Date.now();
			const issues: Array<{ rule: string; message: string; file: string; line?: number }> = [];
			return {
				overall: {
					score: 100,
					status: "healthy",
					passed: true,
					confidence: 0.9,
					totalIssues: 0,
				},
				recommendation: "No issues found",
				layers: [
					{
						name: "patterns",
						layer: "patterns",
						score: 100,
						issues,
						passed: true,
						duration: Date.now() - startTime,
					},
				],
				focusPoints: [],
				issues,
				duration: Date.now() - startTime,
			};
		},
		reviewWork: async (options: { workspaceRoot: string; skipPatterns?: boolean }) => {
			// Get pattern check results
			const validation = await (await getIntelligence(options.workspaceRoot)).checkPatterns([], {
				workspaceRoot: options.workspaceRoot,
			});
			const readyToCommit = validation.overall.passed;
			return {
				issues: validation.issues,
				suggestions: [],
				suggestedLearnings: [],
				readyToCommit,
				suggestedCommitMessage: readyToCommit ? "Ready to commit" : "Fix issues before committing",
				validation,
			};
		},
		getFileModifications: async (files: string[], _workspaceRoot?: string) => {
			return files.map((f) => ({ file: f, modifications: [] }));
		},
		getVitalsSnapshot: async (_workspaceRoot?: string) => {
			const result = await getVitalsViaDaemon(workspaceRoot);
			if (result.success && result.vitals) {
				return {
					pressure: result.vitals.pressure,
					snapshotCount: result.vitals.snapshotCount,
					pulse: result.vitals.pressure,
					trajectory: result.vitals.agentGuidance ? "stable" : "unknown",
				};
			}
			return { pressure: 0, snapshotCount: 0, pulse: 0, trajectory: "unknown" };
		},
	};
}

/**
 * Initialize Intelligence instance for a workspace
 * Call once at server startup for workspaces needing async features
 *
 * @param workspaceRoot - Absolute path to workspace root
 */
export async function initializeIntelligence(workspaceRoot: string): Promise<void> {
	const result = await getIntelligenceViaDaemon(workspaceRoot);
	if (!result.success) {
		// Intentionally ignored: intelligence initialization failure is non-fatal at startup
	}
}

/**
 * Dispose of Intelligence instance for a workspace
 * Call when workspace is closed or server is shutting down
 *
 * @param workspaceRoot - Absolute path to workspace root
 */
export async function disposeIntelligence(workspaceRoot: string): Promise<void> {
	const { disposeServiceConnection } = await import("../daemon/local-service-adapter.js");
	await disposeServiceConnection(workspaceRoot);
}

/**
 * Dispose all Intelligence instances
 * Call on server shutdown
 */
export async function disposeAllIntelligence(): Promise<void> {
	const { disposeAllServiceConnections } = await import("../daemon/local-service-adapter.js");
	await disposeAllServiceConnections();
}

/**
 * Get count of active Intelligence instances
 * Useful for debugging and monitoring
 */
export function getActiveInstanceCount(): number {
	// Delegate to local-service-adapter for connection count
	return 0; // Would need to export from adapter
}

/**
 * Get the singleton facade bundle for intelligence operations.
 *
 * Facades provide the canonical business-logic implementations
 * (validation, storage, learning, etc.) that MCP handlers
 * delegate to instead of maintaining inline logic.
 *
 * @returns Singleton IntelligenceFacades instance
 *
 * @example
 * ```typescript
 * const facades = getFacades();
 * const issues = await facades.validation.checkPatterns(root, file);
 * const result = await facades.validation.reviewWork({ workspaceRoot: root });
 * ```
 */
export function getFacades(): {
	validation: {
		checkPatterns: (root: string, files: string[]) => Promise<PatternCheckResult>;
		reviewWork: (options: { workspaceRoot: string }) => Promise<ReviewWorkResult>;
	};
	learning: { getLearnings: () => Promise<unknown[]> };
	storage: { getSnapshots: () => Promise<unknown[]> };
} {
	// Return facades that delegate to daemon IPC
	return {
		validation: {
			checkPatterns: async (_root: string, files: string[]) => {
				const intel = getIntelligence(_root);
				return intel.checkPatterns(files, { workspaceRoot: _root });
			},
			reviewWork: async (options: { workspaceRoot: string }) => {
				const intel = getIntelligence(options.workspaceRoot);
				return intel.reviewWork(options);
			},
		},
		learning: {
			getLearnings: async () => [],
		},
		storage: {
			getSnapshots: async () => [],
		},
	};
}
