/**
 * SnapshotService - Shared snapshot operations for MCP tools
 *
 * Eliminates duplication across:
 * - handlers.ts (snapshot_create)
 * - begin-task.ts (auto-snapshot)
 * - complete-task.ts (final snapshot)
 *
 * @module services/snapshot-service
 */

import { createHash } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { errorMessage } from "@vreko/core";
import type { SnapshotManifest } from "@vreko/engine";
import {
	createDaemonClient,
	createSnapshotViaDaemon,
	notifySnapshotCreatedViaDaemon,
	restoreSnapshotViaDaemon,
} from "../daemon/local-service-adapter.js";
import { validateFilePaths } from "../validation.js";
import type {
	CreateSnapshotInput,
	FinalizeSnapshotInput,
	GetSnapshotStateInput,
	ISnapshotService,
	ServiceResult,
	Snapshot,
	SnapshotState,
} from "./contracts/service-contracts.js";

// =============================================================================
// TYPES
// =============================================================================

export interface SnapshotOptions {
	/** Description for the snapshot */
	description: string;
	/** Trigger type */
	trigger: "manual" | "auto" | "ai-detection";
	/** Skip deduplication check */
	skipDedup?: boolean;
	/** Number of recent snapshots to check for duplicates */
	dedupWindow?: number;
}

export interface SnapshotResult {
	success: boolean;
	snapshot?: {
		id: string;
		fileCount: number;
		totalSize: number;
		createdAt: number;
	};
	/** True if existing snapshot was reused */
	reused?: boolean;
	reusedSnapshotId?: string;
	reusedReason?: string;
	error?: string;
}

export interface FileHashResult {
	path: string;
	hash: string;
	exists: boolean;
}

export interface RestoreResult {
	success: boolean;
	/** Files that were restored */
	restoredFiles?: string[];
	/** Preview mode indicator */
	preview?: boolean;
	/** Files info for preview mode */
	files?: Array<{ path: string; size: number }>;
	/** Errors encountered during restore */
	errors?: string[];
	/** Error message if restore failed */
	error?: string;
}

export interface FileDiff {
	file: string;
	snapshotSize: number;
	currentSize: number | null;
	changed: boolean;
	exists: boolean;
}

export interface DiffResult {
	success: boolean;
	snapshotId?: string;
	createdAt?: number;
	files?: FileDiff[];
	summary?: {
		total: number;
		changed: number;
		unchanged: number;
	};
	error?: string;
}

// =============================================================================
// HASH UTILITIES
// =============================================================================

/**
 * Compute SHA-256 hash for file content
 */
function hashContent(content: string): string {
	return createHash("sha256").update(content).digest("hex").substring(0, 16);
}

/**
 * Get hashes for multiple files
 */
export function getFileHashes(files: string[], workspaceRoot: string): FileHashResult[] {
	return files.map((file) => {
		const fullPath = resolve(workspaceRoot, file);
		if (!existsSync(fullPath)) {
			return { path: file, hash: "", exists: false };
		}
		try {
			const content = readFileSync(fullPath, "utf8");
			return { path: file, hash: hashContent(content), exists: true };
		} catch {
			return { path: file, hash: "", exists: false };
		}
	});
}

/**
 * Check if current files match a recent snapshot
 */
export function findMatchingSnapshot(
	currentHashes: FileHashResult[],
	snapshots: SnapshotManifest[],
	windowSize = 5,
): { matched: boolean; snapshotId?: string; createdAt?: number } {
	const recentSnapshots = snapshots.slice(0, windowSize);

	for (const snapshot of recentSnapshots) {
		// Check if all current files match snapshot files by hash (blobId is the hash)
		const snapshotFileHashes = new Map(
			(snapshot.files || []).map((f: { path: string; blobId: string }) => [f.path, f.blobId]),
		);

		const allMatch = currentHashes.every((current) => {
			if (!current.exists) {
				return false;
			}
			const snapshotHash = snapshotFileHashes.get(current.path);
			return snapshotHash === current.hash;
		});

		if (allMatch && currentHashes.length === snapshot.files.length) {
			return {
				matched: true,
				snapshotId: snapshot.id,
				createdAt: snapshot.createdAt,
			};
		}
	}

	return { matched: false };
}

// =============================================================================
// SNAPSHOT SERVICE
// =============================================================================

export class SnapshotService implements ISnapshotService {
	private workspaceRoot: string;

	constructor(workspaceRoot: string) {
		this.workspaceRoot = workspaceRoot;
	}

	// =============================================================================
	// ISnapshotService Interface Implementation
	// =============================================================================

	/**
	 * Create a new snapshot (ISnapshotService interface method)
	 */
	async create(input: CreateSnapshotInput): Promise<ServiceResult<Snapshot>> {
		try {
			// Convert interface input to internal options
			const options: SnapshotOptions = {
				description: input.description || input.taskDescription || "",
				trigger: input.trigger || "manual",
				skipDedup: input.skipDedup,
				dedupWindow: input.dedupWindow,
			};

			// Use existing createFromFiles method
			const filesToSnapshot = input.files || [];
			if (filesToSnapshot.length === 0) {
				return {
					ok: false,
					error: "No files provided for snapshot",
					code: "SNAPSHOT_CREATE_FAILED",
				};
			}

			const result = await this.createFromFiles(filesToSnapshot, options);

			if (!result.success || !result.snapshot) {
				return {
					ok: false,
					error: result.error || "Failed to create snapshot",
					code: "SNAPSHOT_CREATE_FAILED",
				};
			}

			// Convert to interface Snapshot type
			const snapshot: Snapshot = {
				id: result.snapshot.id,
				taskId: input.taskId,
				createdAt: new Date(result.snapshot.createdAt),
				status: "pending",
				fileCount: result.snapshot.fileCount,
				totalSize: result.snapshot.totalSize,
			};

			return {
				ok: true,
				data: snapshot,
			};
		} catch (error) {
			return {
				ok: false,
				error: errorMessage(error),
				code: "SNAPSHOT_CREATE_ERROR",
			};
		}
	}

	/**
	 * Get snapshot state (ISnapshotService interface method)
	 */
	async getState(input: GetSnapshotStateInput): Promise<ServiceResult<SnapshotState>> {
		try {
			// Route through daemon IPC
			const daemon = createDaemonClient(this.workspaceRoot);
			const result = await daemon.request<{
				snapshot?: {
					snapshotId: string;
					createdAt: number;
					files: Array<{ path: string; hash?: string; size?: number }>;
					totalSize?: number;
				};
			}>("snapshot/get", { workspace: this.workspaceRoot, snapshotId: input.snapshotId });

			const vreko = result?.snapshot;
			if (!vreko) {
				return {
					ok: false,
					error: `Snapshot not found: ${input.snapshotId}`,
					code: "SNAPSHOT_NOT_FOUND",
				};
			}

			const files = vreko.files.map((f) => ({
				path: f.path,
				hash: f.hash ?? "",
				size: f.size ?? 0,
			}));

			const snapshotState: SnapshotState = {
				snapshot: {
					id: vreko.snapshotId,
					taskId: input.snapshotId,
					createdAt: new Date(vreko.createdAt),
					status: "completed",
					fileCount: vreko.files.length,
					totalSize: vreko.totalSize ?? 0,
				},
				files,
			};

			return { ok: true, data: snapshotState };
		} catch (error) {
			return {
				ok: false,
				error: errorMessage(error),
				code: "SNAPSHOT_GET_ERROR",
			};
		}
	}

	/**
	 * Finalize a snapshot (ISnapshotService interface method)
	 */
	async finalize(input: FinalizeSnapshotInput): Promise<ServiceResult<void>> {
		try {
			// Validate snapshot exists via daemon IPC
			const daemon = createDaemonClient(this.workspaceRoot);
			const result = await daemon.request<{ snapshot?: { snapshotId: string } }>("snapshot/get", {
				workspace: this.workspaceRoot,
				snapshotId: input.snapshotId,
			});

			if (!result?.snapshot) {
				return {
					ok: false,
					error: `Snapshot not found: ${input.snapshotId}`,
					code: "SNAPSHOT_NOT_FOUND",
				};
			}

			return { ok: true, data: undefined };
		} catch (error) {
			return {
				ok: false,
				error: errorMessage(error),
				code: "SNAPSHOT_FINALIZE_ERROR",
			};
		}
	}

	// =============================================================================
	// Existing Methods (Backwards Compatibility)
	// =============================================================================

	/**
	 * Create a snapshot from file paths with optional deduplication
	 *
	 * @example
	 * ```typescript
	 * const service = new SnapshotService(workspaceRoot);
	 * const result = await service.createFromFiles(
	 *   ["src/index.ts", "src/utils.ts"],
	 *   { description: "Pre-refactor", trigger: "ai-detection" }
	 * );
	 * if (result.success) {
	 *   logger.debug(...);
	 * }
	 * ```
	 */
	async createFromFiles(files: string[], options: SnapshotOptions): Promise<SnapshotResult> {
		if (!files || files.length === 0) {
			return { success: false, error: "No files provided" };
		}

		// Validate paths
		const pathValidation = validateFilePaths(files, this.workspaceRoot);
		if (!pathValidation.valid) {
			return {
				success: false,
				error: `Invalid path: ${pathValidation.invalidPath} - ${pathValidation.error}`,
			};
		}

		// Route through daemon IPC  -  daemon reads file contents and creates snapshot
		try {
			const daemonResult = await createSnapshotViaDaemon(this.workspaceRoot, files, {
				reason: options.description,
				trigger: options.trigger,
			});

			if (!daemonResult.success || !daemonResult.snapshotId) {
				return {
					success: false,
					error: daemonResult.error || "Daemon failed to create snapshot",
				};
			}

			// Notify daemon so Extension vitals can reset pressure
			void notifySnapshotCreatedViaDaemon(this.workspaceRoot, daemonResult.snapshotId, files[0], options.trigger);

			return {
				success: true,
				snapshot: {
					id: daemonResult.snapshotId,
					fileCount: daemonResult.fileCount ?? files.length,
					totalSize: daemonResult.totalSize ?? 0,
					createdAt: daemonResult.createdAt ? new Date(daemonResult.createdAt).getTime() : Date.now(),
				},
			};
		} catch (error) {
			return {
				success: false,
				error: errorMessage(error),
			};
		}
	}

	/**
	 * List recent snapshots
	 * @deprecated Synchronous engine access removed. Returns empty array.
	 * Use `listSnapshotsViaDaemon(workspaceRoot)` from local-service-adapter directly.
	 */
	listSnapshots(_limit = 20): SnapshotManifest[] {
		// Cannot route through async daemon IPC from a sync method without breaking
		// the downstream SnapshotServiceResult type contract. Callers that need live
		// snapshot data must use listSnapshotsViaDaemon() directly.
		return [];
	}

	/**
	 * Get a specific snapshot
	 * @deprecated Synchronous engine access removed. Returns null.
	 * Use `getDaemonClient(workspaceRoot).request('snapshot/get', ...)` directly.
	 */
	getSnapshot(_id: string): SnapshotManifest | null {
		// Cannot route through async daemon IPC from a sync method without breaking
		// the downstream SnapshotServiceResult type contract.
		return null;
	}

	/**
	 * Restore files from a snapshot via daemon IPC
	 *
	 * @param snapshotId - Snapshot ID to restore from
	 * @param options - Restore options
	 * @returns Restored file paths or preview info
	 */
	async restore(
		snapshotId: string,
		options?: {
			/** Specific files to restore (optional, defaults to all) */
			files?: string[];
			/** If true, return file info without writing to disk */
			preview?: boolean;
		},
	): Promise<RestoreResult> {
		try {
			const result = await restoreSnapshotViaDaemon(this.workspaceRoot, snapshotId, {
				files: options?.files,
				dryRun: options?.preview ?? false,
			});

			if (!result.success) {
				return {
					success: false,
					error: result.errors?.[0] ?? `Failed to restore snapshot: ${snapshotId}`,
				};
			}

			if (options?.preview) {
				return {
					success: true,
					preview: true,
					files: (result.restoredFiles ?? []).map((path) => ({ path, size: 0 })),
				};
			}

			return {
				success: true,
				restoredFiles: result.restoredFiles ?? [],
				errors: result.errors,
			};
		} catch (error) {
			return {
				success: false,
				error: errorMessage(error),
			};
		}
	}

	/**
	 * Get diff between snapshot and current file state
	 * @deprecated Direct engine storage access removed. Use daemon request 'snapshot/get'
	 * with file content to perform diffs, or use the compare_snapshots MCP tool.
	 */
	async diff(
		_snapshotId: string,
		_options?: {
			file?: string;
		},
	): Promise<DiffResult> {
		return {
			success: false,
			error: "Diff via local engine storage is no longer supported. Use the compare_snapshots tool or daemon request 'snapshot/get' for file content.",
		};
	}
}

// =============================================================================
// FACTORY
// =============================================================================

/**
 * Service cache to prevent race conditions from concurrent storage initialization
 * Each workspace gets a single SnapshotService instance shared across all MCP tool calls
 */
const serviceCache = new Map<string, SnapshotService>();

/**
 * Create a SnapshotService instance (cached per workspace)
 *
 * Caching prevents race conditions where multiple concurrent MCP tool calls
 * would each create a new Storage instance and try to mkdir the same directories.
 *
 * @param workspaceRoot - Absolute path to workspace
 * @returns Cached or new SnapshotService instance
 */
export function createSnapshotService(workspaceRoot: string): SnapshotService {
	if (!serviceCache.has(workspaceRoot)) {
		serviceCache.set(workspaceRoot, new SnapshotService(workspaceRoot));
	}
	const service = serviceCache.get(workspaceRoot);
	if (!service) {
		throw new Error(`Failed to create snapshot service for ${workspaceRoot}`);
	}
	return service;
}
