// =============================================================================
// Git Integration
// =============================================================================

/**
 * Detect git conflicts in the workspace.
 * Returns conflicted files and the source of the conflict.
 */
async function detectGitConflicts(
	workspaceRoot: string,
): Promise<{ hasConflicts: boolean; conflictedFiles: string[]; source: string }> {
	const { spawn } = await import("node:child_process");
	const { access } = await import("node:fs/promises");

	// Check for conflicted files (unmerged)
	const conflictedFiles = await new Promise<string[]>((resolve) => {
		const proc = spawn("git", ["diff", "--name-only", "--diff-filter=U"], {
			cwd: workspaceRoot,
			stdio: ["pipe", "pipe", "pipe"],
		});
		let stdout = "";

		proc.stdout?.on("data", (data) => {
			stdout += data.toString();
		});

		proc.on("close", () => {
			const files = stdout
				.split("\n")
				.map((f) => f.trim())
				.filter((f) => f.length > 0);
			resolve(files);
		});

		proc.on("error", () => resolve([]));
	});

	// Determine conflict source
	let source = "unknown";
	try {
		await access(`${workspaceRoot}/.git/MERGE_HEAD`);
		source = "merge";
	} catch {
		try {
			await access(`${workspaceRoot}/.git/rebase-merge`);
			source = "rebase";
		} catch {
			try {
				await access(`${workspaceRoot}/.git/CHERRY_PICK_HEAD`);
				source = "cherry-pick";
			} catch {
				if (conflictedFiles.length > 0) {
					source = "stash";
				}
			}
		}
	}

	return {
		hasConflicts: conflictedFiles.length > 0,
		conflictedFiles,
		source,
	};
}

/**
 * Get files from git based on diff scope.
 * Enables targeted checking of only modified files for speed.
 */
async function getGitDiffFiles(workspaceRoot: string, scope: DiffScope = "staged"): Promise<string[]> {
	const { spawn } = await import("node:child_process");

	return new Promise((resolve) => {
		let args: string[];
		switch (scope) {
			case "staged":
				args = ["diff", "--cached", "--name-only", "--diff-filter=ACMR"];
				break;
			case "changed":
				args = ["diff", "--name-only", "--diff-filter=ACMR"];
				break;
			case "uncommitted":
				args = ["diff", "HEAD", "--name-only", "--diff-filter=ACMR"];
				break;
			case "all":
				args = ["ls-files"];
				break;
		}

		const proc = spawn("git", args, { cwd: workspaceRoot, stdio: ["pipe", "pipe", "pipe"] });
		let stdout = "";

		proc.stdout?.on("data", (data) => {
			stdout += data.toString();
		});

		proc.on("close", (code) => {
			if (code !== 0) {
				resolve([]);
				return;
			}
			const files = stdout
				.split("\n")
				.map((f) => f.trim())
				.filter((f) => f.length > 0)
				.filter((f) => /\.(ts|tsx|js|jsx)$/.test(f));
			resolve(files);
		});

		proc.on("error", () => resolve([]));
	});
}

/**
 * Auto-detect files from git (staged > uncommitted).
 */
async function autoDetectFiles(workspaceRoot: string): Promise<{ files: string[]; source: string }> {
	const staged = await getGitDiffFiles(workspaceRoot, "staged");
	if (staged.length > 0) {
		return { files: staged, source: "staged" };
	}

	const uncommitted = await getGitDiffFiles(workspaceRoot, "uncommitted");
	if (uncommitted.length > 0) {
		return { files: uncommitted, source: "uncommitted" };
	}

	return { files: [], source: "none" };
}

// =============================================================================
// Parameter Normalization
// =============================================================================

function normalizeCheckParams(params: CheckParams): { mode: string; files: string[]; compact: boolean } {
	const mode = normalizeMode(params, CHECK_MODE_MAP);
	const files = normalizeFiles(params);
	const compact = params.compact || false;
	return { mode, files, compact };
}

// =============================================================================
// Result Formatting
// =============================================================================

interface CheckResultData {
	passed: boolean;
	errors?: Array<{
		message?: string;
		file?: string;
		line?: number;
		column?: number;
		code?: string;
		severity?: string;
	}>;
	warnings?: number;
}

async function formatCheckResult(
	result: ToolResult,
	mode: string,
	options: WireFormatOptions,
	fileSource: string,
	workspaceRoot?: string,
): Promise<ToolResult> {
	try {
		const text = result.content[0]?.text || "";
		const data: CheckResultData = JSON.parse(text);
		const passed = data.passed;
		const errors = data.errors?.length || 0;
		const warnings = data.warnings || 0;

		// Update workflow stage
		if (workspaceRoot) {
			await updateWorkflowStageAsync(workspaceRoot, "validating");
			await recordValidationEventAsync(workspaceRoot, {
				source: "snap_tool",
				category: mode === "quick" ? "typescript" : "build",
				tool: "check",
				mode,
				success: passed,
				details: passed ? "All checks passed" : `${errors} error(s), ${warnings} warning(s)`,
			});
		}

		// Build wire format
		const wireFields: Record<string, string> = {
			mode,
			status: passed ? "✓" : "✗",
			err: `${errors}E`,
			warn: `${warnings}W`,
		};
		if (fileSource && fileSource !== "explicit" && fileSource !== "none") {
			wireFields.src = fileSource;
		}

		const wire = formatWireLabeled("C", wireFields, options);

		// Add issue details if failed - ENRICHED with file:line:column
		let issueDetails = "";
		if (!passed && data.errors) {
			const issues = data.errors.slice(0, 3).map((e) => {
				const file = e.file ? basename(e.file) : "";
				const location =
					e.line !== undefined ? `:${e.line}${e.column !== undefined ? `:${e.column}` : ""}` : "";
				const code = e.code ? `[${e.code}]` : "";
				const msg = (e.message || "error").slice(0, 40);
				return file ? `${file}${location} ${code} ${msg}`.trim() : msg;
			});
			issueDetails = `|issues:${issues.join(",")}`;
		}

		// Human-readable message
		const humanMessage = passed ? messages.validation.passed() : messages.validation.issues(errors, warnings);

		// Next action hint
		let nextActionHint = "";
		if (workspaceRoot && passed) {
			const { shouldSuggest, reason } = await shouldSuggestSnapEndAsync(workspaceRoot);
			if (shouldSuggest) {
				nextActionHint = `\n\n👉 **Next:** ${reason}\n   → Call snap_end() to close session`;
			} else {
				const suggestions = await suggestNextActionAsync(workspaceRoot, "check", mode);
				if (suggestions.length > 0) {
					const primary = suggestions[0];
					nextActionHint = `\n\n👉 **Next:** ${primary.reason}\n   → ${primary.tool}${primary.mode ? `({ mode: "${primary.mode}" })` : "()"}`;
				}
			}
		}

		const structuredContent = {
			passed,
			mode,
			errors,
			warnings,
			// ENRICHED: Include full diagnostic details with file:line:column for LLM parsing
			issues:
				data.errors?.slice(0, 5).map((e) => ({
					file: e.file,
					line: e.line,
					column: e.column,
					code: e.code,
					message: e.message,
					severity: e.severity,
				})) || [],
			fileSource: fileSource !== "explicit" ? fileSource : undefined,
		};

		return {
			content: [
				{ type: "text", text: `${wire}${issueDetails}${INTERNAL_SEPARATOR}${humanMessage}${nextActionHint}` },
			],
			structuredContent,
		};
	} catch {
		return result;
	}
}

