async function handleQuick(files: string[], context: ToolContext): Promise<ToolResult> {
	const service = getValidationService();
	const input: ValidationInput = { workspacePath: context.workspaceRoot, files };
	const result = await service.quickCheck(input);

	if (!result.ok) {
		return {
			content: [{ type: "text", text: JSON.stringify({ passed: false, errors: [{ message: result.error }] }) }],
		};
	}

	return { content: [{ type: "text", text: JSON.stringify(result.data) }] };
}

