async function handleSecurity(files: string[], context: ToolContext): Promise<ToolResult> {
	const service = getValidationService();
	const input: SecurityScanInput = { workspacePath: context.workspaceRoot, files };
	const result = await service.scanSecurity(input);

	if (!result.ok) {
		return {
			content: [{ type: "text", text: JSON.stringify({ passed: false, errors: [{ message: result.error }] }) }],
		};
	}

	const passed = result.data.criticalCount === 0 && result.data.highCount === 0;
	return {
		content: [
			{
				type: "text",
				text: JSON.stringify({
					passed,
					errors: result.data.findings.filter((f) => f.severity === "critical" || f.severity === "high"),
					warnings: result.data.findings.filter((f) => f.severity === "medium" || f.severity === "low")
						.length,
				}),
			},
		],
	};
}

