async function handleIntegrations(context: ToolContext): Promise<ToolResult> {
	const service = getValidationService();
	const input: IntegrationsInput = { workspacePath: context.workspaceRoot };
	const result = await service.checkIntegrations(input);

	if (!result.ok) {
		return {
			content: [{ type: "text", text: JSON.stringify({ passed: false, errors: [{ message: result.error }] }) }],
		};
	}

	// IntegrationsResult has healthy and services, not checks
	const unhealthyServices = Object.entries(result.data.services)
		.filter(([, s]) => !s.healthy)
		.map(([name, _s]) => ({ message: `${name}: unhealthy` }));

	return {
		content: [
			{
				type: "text",
				text: JSON.stringify({
					passed: result.data.healthy,
					errors: unhealthyServices,
					warnings: 0,
				}),
			},
		],
	};
}

