// =============================================================================
// Main Handler
// =============================================================================

export const handleCheck: ToolHandler = async (args, context) => {
	// Security: Validate and sanitize all user inputs
	const validation = validateCheckParams(args);
	if (!validation.success) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Input validation failed:\n${validation.errors?.join("\n") ?? "Unknown validation error"}`,
				},
			],
			isError: true,
		};
	}

	const params = validation.data as CheckParams;
	let { mode, files, compact } = normalizeCheckParams(params);

	// PERFORMANCE: Only check for git conflicts in comprehensive modes
	// Quick mode skips this check to save 100-300ms
	// Conflict check is important for full/security/build but not for quick validation
	const shouldCheckConflicts = ["full", "security", "build"].includes(mode);
	if (shouldCheckConflicts) {
		const conflictCheck = await detectGitConflicts(context.workspaceRoot);
		if (conflictCheck.hasConflicts) {
			return {
				content: [
					{
						type: "text",
						text: JSON.stringify({
							passed: false,
							errors: [
								{
									message: `Git ${conflictCheck.source} conflicts detected in ${conflictCheck.conflictedFiles.length} file(s): ${conflictCheck.conflictedFiles.join(", ")}. Resolve conflicts before running Vreko checks.`,
									code: "GIT_CONFLICTS",
									conflictedFiles: conflictCheck.conflictedFiles,
									source: conflictCheck.source,
									suggestedAction:
										"Resolve conflicts: git status, edit files, git add <files>, git commit",
								},
							],
							warnings: [],
						}),
					},
				],
				isError: true,
			};
		}
	}

	// Diff-aware file selection
	const needsFiles = ["quick", "full", "patterns", "impact", "trace", "security", "coverage"].includes(mode);
	let fileSource = "explicit";

	if (files.length === 0 && needsFiles && !params.code) {
		if (params.diff) {
			const diffFiles = await getGitDiffFiles(context.workspaceRoot, params.diff);
			files = diffFiles;
			fileSource = params.diff;
		} else {
			const detected = await autoDetectFiles(context.workspaceRoot);
			files = detected.files;
			fileSource = detected.source;
		}
	}

	// Track validated files
	if (files.length > 0 && mode !== "learnings") {
		const tracker = getSessionFileTracker(context.workspaceRoot);
		tracker.trackFiles(files, "validated");
	}

	const options: WireFormatOptions = { compact };

	// Dispatch to mode handler
	let result: ToolResult;
	switch (mode) {
		case "quick":
			result = await handleQuick(files, context);
			break;
		case "full":
			result = await handleFull(files, context);
			break;
		case "patterns":
			result = await handlePatterns(params, context);
			break;
		case "build":
			result = await handleBuild(context);
			break;
		case "impact":
			result = await handleImpact();
			break;
		case "circular":
			result = await handleCircular(files, context);
			break;
		case "complexity":
			result = await handleComplexity();
			break;
		case "docs":
			result = await handleDocs();
			break;
		case "learnings":
			result = await handleLearnings();
			break;
		case "architecture":
			result = await handleArchitecture();
			break;
		case "trace":
			result = await handleTrace();
			break;
		case "security":
			result = await handleSecurity(files, context);
			break;
		case "coverage":
			result = await handleCoverage(files, context);
			break;
		case "orphans":
			result = await handleOrphans(context);
			break;
		case "health":
			result = await handleHealth(context);
			break;
		case "evolution":
			result = await handleEvolution(files, context);
			break;
		case "integrations":
			result = await handleIntegrations(context);
			break;
		case "wiring":
			result = await handleWiring(files, context);
			break;
		default:
			result = {
				content: [
					{
						type: "text",
						text: JSON.stringify({ passed: false, errors: [{ message: `Unknown mode: ${mode}` }] }),
					},
				],
			};
	}

	return await formatCheckResult(result, mode, options, fileSource, context.workspaceRoot);
};

