/**
 * Remote API Client
 *
 * HTTPS client for Pro-tier API intelligence tools.
 * Extracted from apps/mcpb/src/proxy/remote-proxy.ts for consolidation.
 *
 * Architecture:
 * - Sends JSON-RPC requests to remote MCP endpoint
 * - Supports both API key and session token authentication
 * - Returns MCP-compatible tool results
 *
 * @module bridge/remote-client
 */

import ky, { type HTTPError } from "ky";
import type {
	JsonRpcResponse,
	RemoteConfig,
	RemoteToolDefinition,
	RemoteToolResult,
	ResolvedRemoteConfig,
} from "./types.js";

// =============================================================================
// Constants
// =============================================================================

/** Default remote URL (Fly.io deployment) */
const DEFAULT_REMOTE_URL = "https://mcp.vreko.dev/mcp";

/** Default timeout for remote operations (30 seconds) */
const DEFAULT_TIMEOUT_MS = 30_000;

/** Maximum retry attempts for transient failures */
const MAX_RETRIES = 2;

/** HTTP status codes that trigger retry */
const RETRY_STATUS_CODES = [502, 503, 504];

// =============================================================================
// Remote Tool Definitions
// =============================================================================

/**
 * Tools that are exclusively served by the remote API.
 * These require Pro-tier or higher subscription.
 */
export const REMOTE_ONLY_TOOLS: RemoteToolDefinition[] = [
	{
		name: "vreko_get_risk_score",
		description: "Intelligence tool (remote): Get risk score for code change",
		inputSchema: {
			type: "object",
			properties: {
				filePath: { type: "string", description: "Path to the file being changed" },
				changeType: { type: "string", description: "Type of change (add, modify, delete)" },
			},
		},
	},
	// Future Pro-tier tools can be added here
];

// =============================================================================
// Config Resolution
// =============================================================================

/**
 * Resolve remote configuration with defaults.
 * Returns null if no authentication is provided (remote disabled).
 *
 * @param config - User-provided remote configuration
 * @returns Resolved config or null if remote should be disabled
 */
export function resolveRemoteConfig(config: RemoteConfig): ResolvedRemoteConfig | null {
	// Require at least one auth method
	if (!config.apiKey && !config.sessionToken) {
		return null;
	}

	// Require workspace root for context
	if (!config.workspaceRoot) {
		return null;
	}

	return {
		url: config.url ?? DEFAULT_REMOTE_URL,
		apiKey: config.apiKey,
		sessionToken: config.sessionToken,
		sessionType: config.sessionType ?? "bearer",
		workspaceId: config.workspaceId,
		workspaceRoot: config.workspaceRoot,
		timeoutMs: config.timeoutMs ?? DEFAULT_TIMEOUT_MS,
	};
}

// =============================================================================
// Remote Client
// =============================================================================

/**
 * Create a remote API client for Pro-tier intelligence tools.
 *
 * @param config - Resolved remote configuration
 * @returns Client with invoke and healthCheck methods
 */
export function createRemoteClient(config: ResolvedRemoteConfig) {
	// Build headers based on auth method
	const headers: Record<string, string> = {
		"Content-Type": "application/json",
		"X-Workspace-Path": config.workspaceRoot,
	};

	// Authentication: prefer session token, fall back to API key
	if (config.sessionToken) {
		const authPrefix = config.sessionType === "api_key" ? "ApiKey" : "Bearer";
		headers.Authorization = `${authPrefix} ${config.sessionToken}`;
	} else if (config.apiKey) {
		headers["X-API-Key"] = config.apiKey;
	}

	// Optional workspace ID for multi-tenant scoping
	if (config.workspaceId) {
		headers["X-Workspace-ID"] = config.workspaceId;
	}

	// Create ky instance with retry logic
	const client = ky.create({
		prefixUrl: config.url,
		timeout: config.timeoutMs,
		retry: {
			limit: MAX_RETRIES,
			methods: ["post"],
			statusCodes: RETRY_STATUS_CODES,
		},
		headers,
	});

	return {
		/**
		 * Invoke a remote tool via JSON-RPC.
		 *
		 * @param toolName - Name of the tool to invoke
		 * @param args - Tool arguments
		 * @returns Tool result in MCP format
		 */
		async invoke(toolName: string, args: Record<string, unknown>): Promise<RemoteToolResult> {
			try {
				const response = await client
					.post("mcp", {
						json: {
							jsonrpc: "2.0",
							method: "tools/call",
							params: { name: toolName, arguments: args },
							id: Date.now(),
						},
					})
					.json<
						JsonRpcResponse<{
							content: Array<{ type: "text"; text: string }>;
						}>
					>();

				if (response.error) {
					return {
						content: [
							{
								type: "text",
								text: `Remote error: ${response.error.message}`,
							},
						],
						isError: true,
					};
				}

				return {
					content: response.result?.content ?? [{ type: "text", text: "No content returned from remote" }],
				};
			} catch (error) {
				return handleRemoteError(error);
			}
		},

		/**
		 * Check if remote API is healthy.
		 *
		 * @returns true if API responds to health check
		 */
		async healthCheck(): Promise<boolean> {
			try {
				const response = await client.get("health");
				return response.ok;
			} catch {
				return false;
			}
		},

		/**
		 * Get list of remote-only tool definitions.
		 */
		getToolDefinitions(): RemoteToolDefinition[] {
			return REMOTE_ONLY_TOOLS;
		},

		/**
		 * Get the resolved configuration (for debugging).
		 */
		getConfig(): ResolvedRemoteConfig {
			return config;
		},
	};
}

// =============================================================================
// Error Handling
// =============================================================================

/**
 * Handle errors from remote API calls.
 * Extracts meaningful messages from HTTP errors and network failures.
 */
function handleRemoteError(error: unknown): RemoteToolResult {
	if (isHTTPError(error)) {
		const message = error.message || "HTTP error";
		return {
			content: [
				{
					type: "text",
					text: `Intelligence unavailable: ${message}\n\nThe remote intelligence server is currently unavailable. Local tools are still available.`,
				},
			],
			isError: true,
		};
	}

	const message = error instanceof Error ? error.message : "Unknown error";
	return {
		content: [
			{
				type: "text",
				text: `Remote bridge failed: ${message}`,
			},
		],
		isError: true,
	};
}

/**
 * Type guard for HTTPError from ky.
 */
function isHTTPError(error: unknown): error is HTTPError {
	return typeof error === "object" && error !== null && "response" in error && "request" in error;
}

// =============================================================================
// Type Exports
// =============================================================================

export type RemoteClient = ReturnType<typeof createRemoteClient>;
