/**
 * Telemetry and structured logging for V2 tools
 *
 * Provides non-blocking error logging with context for debugging
 * silent catch blocks and daemon interaction failures.
 *
 * @module tools/v2/utils/telemetry
 */

export interface ErrorContext {
	tool: string;
	operation: string;
	workspace?: string;
	error?: unknown;
	metadata?: Record<string, unknown>;
}

/**
 * Log a non-fatal error with structured context
 *
 * Non-blocking - errors in logging are swallowed to prevent
 * cascading failures. Logs to stderr for daemon/CI capture.
 */
export function logNonFatalError(context: ErrorContext): void {
	try {
		const timestamp = new Date().toISOString();
		const errorMessage = context.error instanceof Error ? context.error.message : String(context.error);
		const errorStack = context.error instanceof Error ? context.error.stack : undefined;

		const logEntry = {
			timestamp,
			level: "warn",
			tool: context.tool,
			operation: context.operation,
			workspace: context.workspace,
			error: errorMessage,
			stack: errorStack,
			metadata: context.metadata,
		};

		// Log to stderr (captured by daemon logs and CI)
		// biome-ignore lint/suspicious/noConsole: Intentional logging to stderr for daemon/CI capture
		console.error(`[Vreko V2 Tool] ${JSON.stringify(logEntry)}`);
	} catch {
		// Swallow logging errors - telemetry must never break tool execution
	}
}

/**
 * Log a degraded mode event (daemon unavailable, feature disabled)
 */
export function logDegradedMode(context: Omit<ErrorContext, "error"> & { reason: string }): void {
	try {
		const timestamp = new Date().toISOString();

		const logEntry = {
			timestamp,
			level: "info",
			tool: context.tool,
			operation: context.operation,
			workspace: context.workspace,
			degraded: true,
			reason: context.reason,
			metadata: context.metadata,
		};

		// biome-ignore lint/suspicious/noConsole: Intentional logging to stderr for daemon/CI capture
		console.error(`[Vreko V2 Tool] ${JSON.stringify(logEntry)}`);
	} catch {
		// Swallow logging errors
	}
}
