/**
 * InteractionProtocol - Intelligence Layer v2.0
 *
 * Protocol enforcement with interaction gates for safe AI assistance.
 * Per spec: Clarification gates, scope confirmation, staleness warnings.
 *
 * Gates:
 * 1. Staleness check - Warn if analysis is outdated
 * 2. Ambiguity check - Clarify if task is unclear
 * 3. Scope confirmation - Confirm if changes are massive
 * 4. Confidence check - Warn if confidence is very low
 *
 * @module protocol/InteractionProtocol
 */

import type { ConfidenceSignals, StalenessCheck } from "@vreko/intelligence";

// =============================================================================
// Types (re-export from intelligence for convenience)
// =============================================================================

// Re-export shared types from intelligence package
export type { ConfidenceSignals, StalenessCheck } from "@vreko/intelligence";

// =============================================================================
// Protocol-Specific Types
// =============================================================================

/** Protocol action types */
export type ProtocolAction = "proceed" | "clarify" | "confirm" | "warn" | "block";

/** Option for user choice */
export interface ProtocolOption {
	id: string;
	label: string;
}

/** Protocol decision result */
export interface ProtocolDecision {
	action: ProtocolAction;
	reason: string;
	options?: ProtocolOption[];
}

/** Scope information */
export interface ScopeInfo {
	fileCount: number;
	packageCount: number;
}

/** Task context for evaluation */
export interface TaskContext {
	signals: ConfidenceSignals;
	staleness: StalenessCheck;
	explicitConfirmation: boolean;
	scope?: ScopeInfo;
	ambiguityLevel?: "low" | "medium" | "high";
	ambiguityReason?: string;
	ambiguitySuggestions?: string[];
}

// =============================================================================
// Constants
// =============================================================================

/** Confidence threshold for low confidence warning */
const LOW_CONFIDENCE_THRESHOLD = 0.25;

// =============================================================================
// InteractionProtocol Implementation
// =============================================================================

/**
 * InteractionProtocol
 *
 * Evaluates tasks through a series of gates to ensure safe interaction.
 */
export class InteractionProtocol {
	/**
	 * Evaluate a task through protocol gates
	 *
	 * @param _task - The task description (unused but kept for API consistency)
	 * @param context - Task context including signals, staleness, etc.
	 * @returns Protocol decision with action and options
	 */
	async evaluate(_task: string, context: TaskContext): Promise<ProtocolDecision> {
		// Gate 0: File existence check
		if (!context.signals.fileExists) {
			return {
				action: "warn",
				reason: "File not found - unable to perform analysis",
				options: [
					{ id: "create", label: "Create the file" },
					{ id: "skip", label: "Skip this task" },
				],
			};
		}

		// Gate 1: Staleness check
		if (context.staleness.stale) {
			return {
				action: "warn",
				reason: context.staleness.suggestion || "Analysis is stale",
				options: [
					{ id: "refresh", label: "Re-run analysis" },
					{ id: "proceed", label: "Use cached (may be incomplete)" },
				],
			};
		}

		// Gate 2: Ambiguity check
		if (context.ambiguityLevel === "high") {
			return {
				action: "clarify",
				reason: context.ambiguityReason || "Multiple interpretations possible",
				options: (context.ambiguitySuggestions || []).map((s, i) => ({
					id: `opt_${i}`,
					label: s,
				})),
			};
		}

		// Gate 3: Scope confirmation for massive changes
		if (context.signals.scopeSize === "massive" && !context.explicitConfirmation) {
			const scope = context.scope;
			return {
				action: "confirm",
				reason: scope
					? `This affects ${scope.fileCount} files across ${scope.packageCount} packages.`
					: "This is a large-scale change.",
				options: [
					{ id: "proceed", label: scope ? `Yes, modify all ${scope.fileCount} files` : "Yes, proceed" },
					{ id: "narrow", label: "Let me narrow the scope" },
				],
			};
		}

		// Gate 4: Confidence check
		const confidenceScore = this.calculateConfidence(context.signals);
		if (confidenceScore < LOW_CONFIDENCE_THRESHOLD) {
			return {
				action: "warn",
				reason: `Low confidence (${Math.round(confidenceScore * 100)}%): Insufficient evidence for reliable analysis`,
				options: [
					{ id: "proceed", label: "Proceed anyway" },
					{ id: "investigate", label: "Gather more context first" },
				],
			};
		}

		// All gates passed
		return {
			action: "proceed",
			reason: "All gates passed",
		};
	}

	/**
	 * Calculate simplified confidence score
	 */
	private calculateConfidence(signals: ConfidenceSignals): number {
		// Simplified confidence calculation
		const base = 0.35;
		const evidenceScore = (signals.graphCoverage + signals.learningRelevance) / 2;
		const historicalScore = signals.similarTaskSuccessRate * 0.7 + signals.userTrustScore * 0.3;

		let score = base + evidenceScore * 0.4 + historicalScore * 0.25;

		// Apply penalties
		if (signals.hasConflictingLearnings) {
			score *= 0.8;
		}
		if (signals.taskAmbiguity === "vague") {
			score *= 0.7;
		}

		return Math.max(0.1, Math.min(0.95, score));
	}
}

// =============================================================================
// Default export
// =============================================================================

export default InteractionProtocol;
