/**
 * Parameter Normalization Utilities
 *
 * Centralized parameter normalization for MCP tools to eliminate duplication.
 * Handles mode mappings, alias resolution, and type conversions.
 *
 * @module utils/param-normalizer
 */

import { IMPLEMENTED_CHECK_MODES } from "../check-modes-registry.js";

// =============================================================================
// Mode Mapping Types
// =============================================================================

/** Common mode aliases used across tools */
export type ModeAlias = "s" | "c" | "x" | "q" | "f" | "p";

/** Full mode names */
export type FullMode = "start" | "check" | "context" | "quick" | "full" | "patterns";

/** Mode mapping configuration */
export interface ModeMapConfig {
	/** Default mode if none provided */
	default: string;
	/** Mapping from alias to full mode name */
	aliases: Record<string, string>;
}

// =============================================================================
// Parameter Alias Types
// =============================================================================

/** Common parameter aliases */
export interface ParameterAliases {
	mode?: string;
	m?: string;
	task?: string;
	t?: string;
	files?: string | string[];
	f?: string | string[];
	keywords?: string | string[];
	k?: string | string[];
	intent?: string;
	i?: string;
	compact?: boolean;
	thorough?: boolean;
	code?: string;
}

/** Normalized parameters (full names only) */
export interface NormalizedParams {
	mode: string;
	task?: string;
	files: string[];
	keywords: string[];
	intent?: string;
	compact: boolean;
	thorough?: boolean;
	code?: string;
	[key: string]: unknown;
}

// =============================================================================
// Predefined Mode Mappings
// =============================================================================

/** Standard mode mapping for vreko tool (start/check/context) */
export const SNAP_MODE_MAP: ModeMapConfig = {
	default: "start",
	aliases: {
		s: "start",
		c: "check",
		x: "context",
		start: "start",
		check: "check",
		context: "context",
	},
};

/** Standard mode mapping for check tool - derived from CHECK_MODE_REGISTRY */
export const CHECK_MODE_MAP: ModeMapConfig = {
	default: "quick",
	aliases: {
		// Short aliases for common modes
		q: "quick",
		f: "full",
		p: "patterns",
		// All implemented modes (derived from registry - SSOT)
		...Object.fromEntries(IMPLEMENTED_CHECK_MODES.map((mode) => [mode, mode])),
	},
};

// =============================================================================
// Normalization Functions
// =============================================================================

/**
 * Normalize mode parameter with alias support
 *
 * @param params - Raw parameters with mode or m
 * @param modeMap - Mode mapping configuration
 * @returns Normalized mode string
 *
 * @example
 * normalizeMode({ m: "s" }, SNAP_MODE_MAP) // Returns "start"
 * normalizeMode({ mode: "quick" }, CHECK_MODE_MAP) // Returns "quick"
 */
export function normalizeMode(params: ParameterAliases, modeMap: ModeMapConfig): string {
	const rawMode = params.mode || params.m || modeMap.default;
	return modeMap.aliases[rawMode] || modeMap.default;
}

/**
 * Normalize files parameter (handles string or array)
 *
 * @param params - Raw parameters with files or f
 * @returns Normalized files array
 *
 * @example
 * normalizeFiles({ f: "src/app.ts" }) // Returns ["src/app.ts"]
 * normalizeFiles({ files: ["a.ts", "b.ts"] }) // Returns ["a.ts", "b.ts"]
 */
export function normalizeFiles(params: ParameterAliases): string[] {
	const rawFiles = params.files || params.f;
	if (!rawFiles) {
		return [];
	}
	return Array.isArray(rawFiles) ? rawFiles : [rawFiles];
}

/**
 * Normalize keywords parameter (handles string, comma-separated, or array)
 *
 * @param params - Raw parameters with keywords or k
 * @returns Normalized keywords array
 *
 * @example
 * normalizeKeywords({ k: "auth,jwt" }) // Returns ["auth", "jwt"]
 * normalizeKeywords({ keywords: ["auth", "jwt"] }) // Returns ["auth", "jwt"]
 */
export function normalizeKeywords(params: ParameterAliases): string[] {
	const rawKeywords = params.keywords || params.k;
	if (!rawKeywords) {
		return [];
	}

	// Handle string (comma-separated) or array
	if (typeof rawKeywords === "string") {
		return rawKeywords
			.split(",")
			.map((k) => k.trim())
			.filter((k) => k.length > 0);
	}

	return rawKeywords;
}

/**
 * Normalize intent parameter with alias support
 *
 * @param params - Raw parameters with intent or i
 * @returns Normalized intent string or undefined
 *
 * @example
 * normalizeIntent({ i: "debug" }) // Returns "debug"
 * normalizeIntent({ intent: "implement" }) // Returns "implement"
 */
export function normalizeIntent(
	params: ParameterAliases,
): "implement" | "debug" | "refactor" | "review" | "explore" | undefined {
	const rawIntent = params.intent || params.i;
	if (!rawIntent) {
		return undefined;
	}

	// Validate intent is one of the allowed values
	const validIntents = ["implement", "debug", "refactor", "review", "explore"];
	return validIntents.includes(rawIntent)
		? (rawIntent as "implement" | "debug" | "refactor" | "review" | "explore")
		: undefined;
}

/**
 * Normalize task parameter with alias support
 *
 * @param params - Raw parameters with task or t
 * @param defaultTask - Default task if none provided
 * @returns Normalized task string
 *
 * @example
 * normalizeTask({ t: "fix auth" }) // Returns "fix auth"
 * normalizeTask({ task: "implement login" }) // Returns "implement login"
 */
export function normalizeTask(params: ParameterAliases, defaultTask = "development task"): string {
	return params.task || params.t || defaultTask;
}

/**
 * Normalize boolean flags (compact, thorough, etc.)
 *
 * @param params - Raw parameters
 * @param flagName - Name of the boolean flag
 * @param defaultValue - Default value if not provided
 * @returns Normalized boolean value
 *
 * @example
 * normalizeBoolean(params, "compact", false) // Returns boolean
 */
export function normalizeBoolean(params: ParameterAliases, flagName: string, defaultValue = false): boolean {
	return ((params as Record<string, unknown>)[flagName] as boolean | undefined) ?? defaultValue;
}

/**
 * Normalize all parameters at once (convenience function)
 *
 * @param params - Raw parameters with aliases
 * @param modeMap - Mode mapping configuration
 * @returns Fully normalized parameters object
 *
 * @example
 * const normalized = normalizeAllParams({ m: "s", t: "fix auth", f: ["a.ts"] }, SNAP_MODE_MAP)
 * // Returns { mode: "start", task: "fix auth", files: ["a.ts"], ... }
 */
export function normalizeAllParams(params: ParameterAliases, modeMap: ModeMapConfig): NormalizedParams {
	return {
		mode: normalizeMode(params, modeMap),
		task: normalizeTask(params),
		files: normalizeFiles(params),
		keywords: normalizeKeywords(params),
		intent: normalizeIntent(params),
		compact: normalizeBoolean(params, "compact"),
		thorough: normalizeBoolean(params, "thorough"),
		code: params.code,
	};
}

// =============================================================================
// Intent Detection
// =============================================================================

/**
 * Auto-detect intent from task description and files
 * Inspired by SuperClaude's trigger conditions for automatic context loading
 *
 * @param task - Task description
 * @param files - Files being worked on
 * @returns Detected intent
 *
 * @example
 * detectIntent("fix auth bug", []) // Returns "debug"
 * detectIntent("refactor components", ["app.tsx"]) // Returns "refactor"
 */
export function detectIntent(task: string, files: string[]): "implement" | "debug" | "refactor" | "review" | "explore" {
	const taskLower = task.toLowerCase();

	// Debug triggers
	if (/\b(fix|bug|debug|error|crash|leak|broken|issue)\b/.test(taskLower)) {
		return "debug";
	}

	// Refactor triggers
	if (/\b(refactor|restructure|reorganize|clean|simplify|optimize)\b/.test(taskLower)) {
		return "refactor";
	}

	// Review triggers (test files or explicit review mentions)
	if (files.some((f) => /test|spec/.test(f)) || /\b(review|audit|check|validate)\b/.test(taskLower)) {
		return "review";
	}

	// Explore triggers
	if (/\b(explore|investigate|research|understand|analyze)\b/.test(taskLower)) {
		return "explore";
	}

	// Default to implement
	return "implement";
}

/**
 * Normalize parameters with intent detection
 *
 * @param params - Raw parameters
 * @param modeMap - Mode mapping configuration
 * @returns Normalized parameters with detected or explicit intent
 *
 * @example
 * const normalized = normalizeWithIntentDetection({ m: "s", t: "fix auth bug" }, SNAP_MODE_MAP)
 * // Returns { ..., intent: "debug" }
 */
export function normalizeWithIntentDetection(params: ParameterAliases, modeMap: ModeMapConfig): NormalizedParams {
	const base = normalizeAllParams(params, modeMap);

	// Auto-detect intent if not explicitly provided
	if (!base.intent) {
		base.intent = detectIntent(base.task || "", base.files);
	}

	return base;
}
