// =============================================================================
// Migration Guidance
// =============================================================================

/**
 * Get migration guidance for a legacy tool name.
 * Returns undefined if the tool is not a known legacy name.
 */
export function getMigrationGuidance(legacyTool: string): string | undefined {
	const mapping = LEGACY_TO_CONSOLIDATED[legacyTool];
	return mapping?.message;
}
