/**
 * MCP Health Integration Module
 *
 * Provides workspace health monitoring and validation for the MCP server.
 * Integrates with workspace-health package for startup validation and
 * exposes health status via MCP tools.
 *
 * @module health/integration
 */

import { existsSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { generateWorkspaceId } from "@vreko/workspace-identity";

/**
 * Health check result for a single validation
 */
export interface HealthCheck {
	name: string;
	passed: boolean;
	message?: string;
	severity: "info" | "warning" | "error";
}

/**
 * Workspace health status
 */
export interface WorkspaceHealth {
	/** Overall health status */
	healthy: boolean;
	/** Individual health checks */
	checks: HealthCheck[];
	/** Issues that can be auto-fixed */
	autoFixable: HealthCheck[];
	/** Issues requiring user action */
	requiresUserAction: HealthCheck[];
	/** Workspace root path */
	workspaceRoot: string;
	/** Generated workspace ID */
	workspaceId: string;
}

/**
 * Result of health repair operations
 */
export interface RepairResult {
	/** Whether repairs were successful */
	success: boolean;
	/** Number of issues fixed */
	fixed: number;
	/** Remaining issues */
	remaining: HealthCheck[];
}

/**
 * Validate workspace health on startup
 *
 * Performs comprehensive checks:
 * 1. .vreko directory exists
 * 2. Workspace ID is valid
 * 3. Required subdirectories exist
 * 4. Permissions are correct
 *
 * @param workspaceRoot - Absolute path to workspace root
 * @returns Health status with fixable issues categorized
 */
export async function validateWorkspaceHealth(workspaceRoot: string): Promise<WorkspaceHealth> {
	const checks: HealthCheck[] = [];
	const autoFixable: HealthCheck[] = [];
	const requiresUserAction: HealthCheck[] = [];

	// Check 1: Workspace exists and is directory
	const workspaceExists = existsSync(workspaceRoot);
	checks.push({
		name: "workspace_exists",
		passed: workspaceExists,
		message: workspaceExists ? undefined : `Workspace does not exist: ${workspaceRoot}`,
		severity: "error",
	});

	if (!workspaceExists) {
		return {
			healthy: false,
			checks,
			autoFixable,
			requiresUserAction: [
				{
					name: "workspace_exists",
					passed: false,
					message: `Workspace does not exist: ${workspaceRoot}`,
					severity: "error",
				},
			],
			workspaceRoot,
			workspaceId: "",
		};
	}

	// Check 2: .vreko directory exists
	const vrekoDir = join(workspaceRoot, ".vreko");
	const vrekoExists = existsSync(vrekoDir);
	checks.push({
		name: "vreko_dir",
		passed: vrekoExists,
		message: vrekoExists ? undefined : ".vreko directory missing",
		severity: "warning",
	});

	if (!vrekoExists) {
		autoFixable.push({
			name: "vreko_dir",
			passed: false,
			message: ".vreko directory missing - will auto-create",
			severity: "warning",
		});
	}

	// Check 3: Required subdirectories
	const requiredDirs = ["learnings", "snapshots", "audit"];
	for (const dir of requiredDirs) {
		const dirPath = join(vrekoDir, dir);
		const dirExists = existsSync(dirPath);
		checks.push({
			name: `subdir_${dir}`,
			passed: dirExists,
			message: dirExists ? undefined : `${dir}/ subdirectory missing`,
			severity: "info",
		});

		if (!dirExists && vrekoExists) {
			autoFixable.push({
				name: `subdir_${dir}`,
				passed: false,
				message: `${dir}/ subdirectory will be auto-created`,
				severity: "info",
			});
		}
	}

	// Check 4: Workspace ID validity
	const workspaceId = generateWorkspaceId(workspaceRoot);
	const workspaceIdValid = workspaceId.startsWith("ws_") && workspaceId.length >= 32;
	checks.push({
		name: "workspace_id",
		passed: workspaceIdValid,
		message: workspaceIdValid ? undefined : `Invalid workspace ID format: ${workspaceId}`,
		severity: "error",
	});

	if (!workspaceIdValid) {
		requiresUserAction.push({
			name: "workspace_id",
			passed: false,
			message: `Invalid workspace ID format: ${workspaceId}`,
			severity: "error",
		});
	}

	// Determine overall health
	const hasErrors = checks.some((c) => !c.passed && c.severity === "error");
	const hasWarnings = checks.some((c) => !c.passed && c.severity === "warning");

	return {
		healthy: !hasErrors && !hasWarnings,
		checks,
		autoFixable,
		requiresUserAction,
		workspaceRoot,
		workspaceId,
	};
}

/**
 * Repair workspace issues that are auto-fixable
 *
 * @param workspaceRoot - Absolute path to workspace root
 * @param issues - Issues to repair (must be from autoFixable list)
 * @returns Repair result
 */
export async function repairWorkspaceIssues(workspaceRoot: string, issues: HealthCheck[]): Promise<RepairResult> {
	let fixed = 0;
	const remaining: HealthCheck[] = [];

	for (const issue of issues) {
		try {
			switch (issue.name) {
				case "vreko_dir": {
					const vrekoDir = join(workspaceRoot, ".vreko");
					mkdirSync(vrekoDir, { recursive: true });
					fixed++;
					break;
				}
				case "subdir_learnings":
				case "subdir_snapshots":
				case "subdir_audit": {
					const dirName = issue.name.replace("subdir_", "");
					const dirPath = join(workspaceRoot, ".vreko", dirName);
					mkdirSync(dirPath, { recursive: true });
					fixed++;
					break;
				}
				default:
					remaining.push(issue);
			}
		} catch (error) {
			remaining.push({
				...issue,
				message: `Failed to repair: ${error instanceof Error ? error.message : String(error)}`,
			});
		}
	}

	return {
		success: remaining.length === 0,
		fixed,
		remaining,
	};
}

/**
 * Check current workspace health (lightweight)
 *
 * Used by the workspace_health tool for client queries.
 *
 * @param workspaceRoot - Absolute path to workspace root
 * @returns Current health status
 */
export async function checkWorkspaceHealth(workspaceRoot: string): Promise<WorkspaceHealth> {
	return validateWorkspaceHealth(workspaceRoot);
}

/**
 * Format health status for logging
 *
 * @param health - Health status to format
 * @returns Human-readable summary
 */
export function formatHealthStatus(health: WorkspaceHealth): string {
	const lines: string[] = [];

	lines.push(`Workspace: ${health.workspaceRoot}`);
	lines.push(`Workspace ID: ${health.workspaceId}`);
	lines.push(`Healthy: ${health.healthy ? "✓" : "✗"}`);
	lines.push("");

	if (health.checks.length > 0) {
		lines.push("Checks:");
		for (const check of health.checks) {
			const icon = check.passed ? "✓" : check.severity === "error" ? "✗" : "⚠";
			lines.push(`  ${icon} ${check.name}: ${check.passed ? "OK" : check.message || "Failed"}`);
		}
	}

	if (health.autoFixable.length > 0) {
		lines.push("");
		lines.push(`Auto-fixable issues: ${health.autoFixable.length}`);
	}

	if (health.requiresUserAction.length > 0) {
		lines.push("");
		lines.push("Requires user action:");
		for (const issue of health.requiresUserAction) {
			lines.push(`  ✗ ${issue.name}: ${issue.message}`);
		}
	}

	return lines.join("\n");
}
