/**
 * Snap Help Tool
 *
 * Help and discovery. Replaces:
 * - meta
 * - get_pairing_protocol
 *
 * @see stress_test_remediation.md Section "Tool 4: vreko.?"
 * @module tools/consolidated/vreko-help
 */

import { BRAND_PREFIX } from "../../branding/index.js";
import { CHECK_MODE_REGISTRY, IMPLEMENTED_CHECK_MODES, IMPLEMENTED_MODE_COUNT } from "../../check-modes-registry.js";
import type { ToolHandler, VrekoTool } from "../../types/tool-types.js";

// =============================================================================
// Types
// =============================================================================

/**
 * Snap help parameters
 */
export interface SnapHelpParams {
	/** Query topic: tools, status, wire, modes, thresholds, decision, all */
	topic?: "tools" | "status" | "wire" | "modes" | "thresholds" | "decision" | "all";
	/** @deprecated Use 'topic' instead */
	q?: "tools" | "status" | "wire";
}

// =============================================================================
// Help Content (Plain Text - NO wire format)
// =============================================================================

/**
 * Get active tools list
 * Returns plain text for LLM comprehension
 */
function getToolsHelp(): string {
	const intelligenceSurface = process.env.VREKO_MCP_INTELLIGENCE_SURFACE || "minimal";
	const surfaceNote =
		intelligenceSurface === "full"
			? "\n\n⚡ FULL SURFACE MODE: Intelligence tools enabled (vreko_*, intelligence.*)"
			: "\n\n💡 MINIMAL SURFACE (default): To enable intelligence tools, set VREKO_MCP_INTELLIGENCE_SURFACE=full";

	return `${BRAND_PREFIX} Available Tools

CORE COMMANDS (7):
TOOL            MODES                           DESCRIPTION
────────────────────────────────────────────────────────────────────
advise          files                           Get recommendations (REASON)
guide           files + intent                  Plan multi-step workflows (REASON)
vreko            mode: start|context             Universal entry point (ACT)
check           mode: (${IMPLEMENTED_MODE_COUNT} modes)                Deep validation modes (ACT)
snap_learn      type: pattern|pitfall|...       Capture mid-session learning (REFLECT)
snap_end        outcome: completed|abandoned|blocked  Complete task with learnings (REFLECT)

SUPPORTING TOOLS (always available):
snap_fix        action: list|restore|diff|suggest   Snapshot operations (UTILITY)
snap_help       topic: tools|wire|thresholds    This help (plain text)

ADVANCED TOOLS (full surface only):
snap_violation  type + file + description       Report code violation
learning_gc     operation: archive|delete|all   Learning lifecycle management
vreko_*      (5 tools)                       External context integration (GitHub, Sentry, Context7)
intelligence.*  (5 tools)                       Pattern-based learning system${surfaceNote}

WORKFLOW STAGES:
  REASON   → advise()|guide()         Get recommendations and a plan
  ACT      → vreko()|check()           Execute with validation
  REFLECT  → snap_learn()|snap_end()  Capture learnings
  (pulse is available but vreko(start) already includes vitals)

Use full-word parameters (e.g., mode:"start") for clarity.
Legacy single-letter params (m:"s") still work for backward compatibility.`;
}

/**
 * Get current session status
 * Returns plain text status
 */
function getStatusHelp(): string {
	return `${BRAND_PREFIX} Session Status

STATUS: Active
TASK: None currently active
LEARNINGS: Ready to load
SNAPSHOTS: Available for restore

To start a task:
  vreko({ mode: "start", task: "your task description" })

To check code:
  vreko({ mode: "check", files: ["path/to/file.ts"] })`;
}

/**
 * Get wire format reference
 * Returns plain text (NOT wire format) - this is the escape hatch
 */
function getWireHelp(): string {
	return `${BRAND_PREFIX} Wire Format Reference

RESPONSE STRUCTURE:
  [wire format line]
  ---
  [human-readable summary]

FALLBACK: If wire format is confusing, use the human summary after ---.
          The summary contains the same information in natural language.

WIRE FORMAT (labeled by default):
  🦎|TYPE|field:value|field:value|...

TYPE CODES:
  S = Start task response
  C = Check/validation result
  X = Context snapshot
  E = End task summary
  R = Snapshot list/restore
  L = Learning captured
  V = Violation recorded
  🧠 = Advise (recommendations)
  🪦 = Pulse (vitals)
  ! = Error

FIELD DECODE (for TYPE=S start):
  id:      Task identifier for subsequent calls
  vreko:    Snapshot ID (use with snap_fix to restore)
  risk:    L=Low, M=Medium, H=High
  prot:    Protection coverage 0-100%
  dirty:   Count of uncommitted files
  status:  created|reused|skipped
  learn:   Relevant learnings (spaces compressed to →)

FIELD DECODE (for TYPE=🧠 advise):
  conf:    Confidence score 0-100%
  rec:     Recommendation (proceed|caution|stop)
  warn:    Warning count
  learn:   Applicable learnings count
  viol:    Recent violations count
  loop:    Loop detected (Y/N)
  lc:      Loop confidence 0-100%
  lt:      Loop type (s=structural, m=semantic, b=both)
  ev:      Loop evidence (first 25 chars)
  hint:    Advisory hint (30 chars max)

FIELD DECODE (for TYPE=C check):
  status:  ✓=passed, ✗=failed
  err:     Error count (e.g., 3E)
  warn:    Warning count (e.g., 2W)
  ts:      TypeScript check (✓/✗/⏭️)
  lint:    Lint check (✓/✗/⏭️)
  tests:   Tests (✓/✗/⏭️)
  issues:  Issue summaries (compressed)

STATUS SYMBOLS:
  ✓ = passed
  ✗ = failed
  ⏭️ = skipped`;
}

/**
 * Get mode explanations - GENERATED FROM REGISTRY (SSOT)
 * This eliminates the doc-implementation gap by deriving from CHECK_MODE_REGISTRY
 */
function getModesHelp(): string {
	// Group modes by category for better organization
	const byCategory = CHECK_MODE_REGISTRY.filter((m) => m.implemented).reduce(
		(acc, mode) => {
			if (!acc[mode.category]) {
				acc[mode.category] = [];
			}
			acc[mode.category].push(mode);
			return acc;
		},
		{} as Record<string, typeof CHECK_MODE_REGISTRY>,
	);

	const formatMode = (m: (typeof CHECK_MODE_REGISTRY)[0]) =>
		`  ${m.name.padEnd(12)} - ${m.description} ${m.estimatedTime}`;

	const sections = [];

	// Validation section
	if (byCategory.validation?.length) {
		sections.push("VALIDATION:", ...byCategory.validation.map(formatMode));
	}

	// Analysis section
	if (byCategory.analysis?.length) {
		sections.push("", "ANALYSIS:", ...byCategory.analysis.map(formatMode));
	}

	// Security section
	if (byCategory.security?.length) {
		sections.push("", "SECURITY:", ...byCategory.security.map(formatMode));
	}

	// Maintenance section
	if (byCategory.maintenance?.length) {
		sections.push("", "MAINTENANCE:", ...byCategory.maintenance.map(formatMode));
	}

	return `${BRAND_PREFIX} Mode Reference

SNAP MODES:
  start   - Begin a new task, load context, create snapshot
  context - Get current workspace status without starting task
  check   - (DEPRECATED) Use the check tool instead

CHECK MODES (${IMPLEMENTED_MODE_COUNT} implemented):
${sections.join("\n")}

INTENT TYPES (for vreko/guide/advise):
  implement - Adding new features or functionality
  debug     - Finding and fixing bugs
  refactor  - Restructuring code without changing behavior
  review    - Code review and quality assessment
  explore   - Learning codebase structure and patterns

LEARNING TYPES (for snap_learn):
  pattern    - Reusable approach that worked
  pitfall    - Mistake to avoid
  efficiency - Token/time optimization
  discovery  - New codebase knowledge
  workflow   - Process improvement

SNAP_FIX ACTIONS:
  list    - Show recent snapshots with age and file counts
  restore - Restore files from a specific snapshot
  diff    - Compare two snapshots to see what changed
  suggest - Get AI-scored suggestions for which snapshot to restore

SNAP_END OUTCOMES:
  completed - Task finished successfully
  abandoned - Gave up or wrong approach
  blocked   - External dependency preventing progress`;
}

/**
 * Get threshold explanations
 */
function getThresholdsHelp(): string {
	return `${BRAND_PREFIX} Auto-Promotion Thresholds

VIOLATIONS:
  1-2 occurrences  → Stored for reference
  3 occurrences    → Auto-promoted to PATTERN (affects future task starts)
  5 occurrences    → Marked for AUTOMATION (🤖 flag in response)

LEARNINGS:
  Learnings accessed 3+ times are promoted to "hot tier" for faster loading.
  Hot tier learnings appear automatically in relevant task contexts.

RISK LEVELS:
  L (Low)    - Simple changes, well-tested areas
  M (Medium) - Moderate complexity or less coverage
  H (High)   - Complex changes, critical paths, low protection`;
}

/**
 * Get decision tree for tool selection
 * Critical for LLM comprehension of when to use which tool
 * GENERATED FROM REGISTRY (SSOT) - eliminates doc-implementation gap
 */
function getDecisionTreeHelp(): string {
	// Use case mapping for common check mode scenarios
	const checkUseCases: Array<{ useCase: string; mode: string }> = [
		{ useCase: "Security scan", mode: "security" },
		{ useCase: "Find dead code", mode: "orphans" },
		{ useCase: "Architecture review", mode: "architecture" },
		{ useCase: "Circular deps", mode: "circular" },
		{ useCase: "Test coverage", mode: "coverage" },
		{ useCase: "Dependency trace", mode: "trace" },
		{ useCase: "Deprecated patterns", mode: "evolution" },
		{ useCase: "DI wiring", mode: "wiring" },
		{ useCase: "External integrations", mode: "integrations" },
		{ useCase: "MCP health", mode: "health" },
		{ useCase: "Bundle impact", mode: "impact" },
		{ useCase: "Doc freshness", mode: "docs" },
		{ useCase: "Learning tiers", mode: "learnings" },
		{ useCase: "Pattern validation", mode: "patterns" },
		{ useCase: "Build verification", mode: "build" },
		{ useCase: "Quick validation", mode: "quick" },
		{ useCase: "Full validation", mode: "full" },
	];

	// Filter to only implemented modes
	const validUseCases = checkUseCases.filter((uc) => IMPLEMENTED_CHECK_MODES.includes(uc.mode));

	// Format as tree items
	const deepAnalysisLines = validUseCases.map(
		(uc, i) =>
			`${i === validUseCases.length - 1 ? "└──" : "├──"} ${uc.useCase.padEnd(18)} → check({ mode: "${uc.mode}" })`,
	);

	return `${BRAND_PREFIX} Tool Selection Decision Tree

STARTING WORK?
└── vreko({ task: "description" })
    CLI: npx vreko start

MID-TASK NEEDS:
├── Quick status?        → vreko() (resumes existing session)
│                           CLI: npx vreko status
├── Validate code?       → check({ mode: "quick" }) or check({ mode: "full" })
│                           CLI: npx vreko check --mode quick
├── Something broke?     → snap_violation({ type, file, description, prevention })
│                           CLI: npx vreko report-violation
├── Learned something?   → vreko_learn({ trigger, action, type })
│                           CLI: npx vreko learn
└── Need old version?    → snap_fix({ action: "list" })
                            CLI: npx vreko snapshots

ENDING WORK?
└── vreko_end({ outcome: "completed", learnings: [...] })
    CLI: npx vreko end

MAINTENANCE (periodic):
├── Preview learning cleanup  → learning_gc({ operation: "archive", dry_run: true })
├── Execute learning cleanup  → learning_gc({ operation: "archive", dry_run: false })
└── Delete archived learnings → learning_gc({ operation: "delete", dry_run: false })

DEEP ANALYSIS (use check tool - ${IMPLEMENTED_MODE_COUNT} modes):
${deepAnalysisLines.join("\n")}

QUICK REFERENCE:
┌─────────────────┬─────────────────────────────────────────┬─────────────────────────────┐
│ I want to...    │ Use this...                             │ CLI Equivalent              │
├─────────────────┼─────────────────────────────────────────┼─────────────────────────────┤
│ Start work      │ vreko({ task: "..." })               │ npx vreko start          │
│ Get advice      │ advise({ files: ["path"] })             │ npx vreko advise         │
│ Quick check     │ check({ mode: "quick" })                │ npx vreko check          │
│ Deep analysis   │ check({ mode: "full" })                 │ npx vreko check --full   │
│ Record mistake  │ snap_violation()                        │ npx vreko report-violation│
│ Save insight    │ vreko_learn()                        │ npx vreko learn          │
│ Restore files   │ snap_fix({ action: "restore", id })     │ npx vreko restore <id>   │
│ Finish task     │ vreko_end({ outcome: "completed" })  │ npx vreko end            │
│ Clean learnings │ learning_gc({ operation: "archive" })   │ npx vreko gc --archive   │
│ Get help        │ snap_help({ topic: "..." })             │ npx vreko help           │
│ Check daemon    │ (N/A - internal)                        │ npx vreko daemon status  │
└─────────────────┴─────────────────────────────────────────┴─────────────────────────────┘

TROUBLESHOOTING:
┌─────────────────────────┬──────────────────────────────────────┐
│ Issue                   │ Solution                             │
├─────────────────────────┼──────────────────────────────────────┤
│ Daemon not responding   │ npx vreko daemon status           │
│ Session stuck           │ snap_fix({ action: "list" })         │
│ Need to restore files   │ snap_fix({ action: "suggest" })      │
│ Circular deps error     │ check({ mode: "circular" })          │
│ High risk score         │ advise({ files: [...] })             │
│ Tests failing           │ check({ mode: "quick", tests: true }) │
│ Forgot session details  │ vreko_pulse() or vreko()       │
└─────────────────────────┴──────────────────────────────────────┘`;
}

// =============================================================================
// Handler
// =============================================================================

/**
 * Handle snap_help
 *
 * IMPORTANT: Returns plain text ONLY (no wire format).
 * This is intentional - snap_help is the escape hatch for when wire format is confusing.
 */
export const handleSnapHelp: ToolHandler = async (args, _context) => {
	const params = args as unknown as SnapHelpParams;

	// Normalize topic (support both 'topic' and legacy 'q')
	const topic = params.topic || params.q || "all";

	switch (topic) {
		case "tools":
			return { content: [{ type: "text", text: getToolsHelp() }] };

		case "status":
			return { content: [{ type: "text", text: getStatusHelp() }] };

		case "wire":
			return { content: [{ type: "text", text: getWireHelp() }] };

		case "modes":
			return { content: [{ type: "text", text: getModesHelp() }] };

		case "thresholds":
			return { content: [{ type: "text", text: getThresholdsHelp() }] };

		case "decision":
			return { content: [{ type: "text", text: getDecisionTreeHelp() }] };
		default: {
			// Concise help - lists tools and response format
			const allHelp = `${BRAND_PREFIX} Quick Reference

CORE COMMANDS: advise | guide | vreko | check | snap_learn | snap_end
SUPPORTING: snap_violation | snap_fix | learning_gc | snap_help | pulse

WORKFLOW:
  vreko({ mode: "start", task: "description" })  → Begin task
  advise({ files: ["path"] })                   → Get recommendations
  check({ mode: "quick" })                      → Validate code
  snap_learn({ trigger, action })               → Capture insight
  snap_end({ outcome: "completed" })            → Complete task

Response format: [wire line] --- [human summary]
TYPE CODES: 🧠=Advise, S=Start, C=Check, X=Context, E=End, R=Restore, L=Learn, V=Violation, GC=Learning GC

TOPICS: snap_help({ topic: "tools|wire|modes|thresholds|decision" })`;

			return { content: [{ type: "text", text: allHelp }] };
		}
	}
};

// =============================================================================
// Tool Definition
// =============================================================================

export const snapHelpTool: VrekoTool = {
	name: "vreko_help",
	description: `[DEPRECATED] Tool documentation and wire format reference. Returns plain text (not wire format).
Use when you need mode details, wire format grammar, or a tool selection decision tree.
Do NOT use to check code or session state (that's check or vreko).
Topics: tools, status, wire, modes, thresholds, decision, all (default).`,
	inputSchema: {
		type: "object",
		properties: {
			topic: {
				type: "string",
				enum: ["tools", "status", "wire", "modes", "thresholds", "decision", "all"],
				description: "Help topic: tools, status, wire, modes, thresholds, decision, or all (default)",
			},
		},
	},
	annotations: {
		title: "🦎 Vreko Help",
		readOnlyHint: true,
		destructiveHint: false,
		idempotentHint: true,
	},
	tier: "free",
};
