/**
 * V2 Tools - Black-Box Intelligence Surface
 *
 * These 4 tools replace the 12-tool SOPR surface with a simpler, more intelligent
 * interface that hides daemon internals from the LLM.
 *
 * Tools:
 * - vreko: Intelligence briefing (call FIRST before code changes)
 * - vreko_learn: Capture discovery mid-session
 * - vreko_end: Session closure + ceremony
 * - vreko_pulse: Mid-session intelligence check (read-only)
 *
 * @module tools/v2
 */

import type { ToolHandler, VrekoTool } from "../../types/tool-types.js";
import { handleVreko, vrekoTool } from "./vreko.js";
