import { handleVrekoPulse, vrekoPulseTool } from "./vreko-pulse.js";

// =============================================================================
// Tool Definitions
// =============================================================================

/**
 * V2 tools for registration with MCP server
 * These are added alongside existing SOPR tools (not replacing them yet)
 */
export const V2_TOOLS: VrekoTool[] = [vrekoTool, vrekoLearnTool, vrekoEndTool, vrekoPulseTool];

/**
 * Minimal surface tools (3-tool public MCP surface)
 * Excludes vreko_pulse which is available in full surface
 * Order: vreko → vreko_learn → vreko_end
 */
export const V2_MINIMAL_TOOLS: VrekoTool[] = [vrekoTool, vrekoLearnTool, vrekoEndTool];

