// =============================================================================
// Architecture Rules Runner
// =============================================================================

/**
 * Run architecture rules check
 *
 * Uses static analysis to verify import relationships without
 * requiring ts-arch as a runtime dependency.
 *
 * @example
 * ```typescript
 * const result = await runArchCheck({
 *   workspaceRoot: process.cwd(),
 *   customRules: [{
 *     id: "my-rule",
 *     description: "Custom rule",
 *     source: "src/api",
 *     target: "src/ui",
 *     type: "no-dependency",
 *     severity: "error"
 *   }]
 * });
 *
 * if (!result.passed) {
 *   console.error("Architecture violations:", result.violations);
 * }
 * ```
 */
export async function runArchCheck(config: ArchRunnerConfig): Promise<ArchCheckResult> {
	const startTime = Date.now();

	// Combine rules
	const rules = config.overrideDefaultRules
		? config.customRules || []
		: [...SNAPBACK_LAYER_RULES, ...(config.customRules || [])];

	const violations: ArchViolation[] = [];
	const ruleResults: ArchCheckResult["ruleResults"] = [];

	// Check each rule
	for (const rule of rules) {
		const ruleViolations = await checkRule(rule, config);
		ruleResults.push({
			ruleId: rule.id,
			passed: ruleViolations.length === 0,
			violations: ruleViolations,
		});
		violations.push(...ruleViolations);
	}

	const errorCount = violations.filter((v) => v.severity === "error").length;

	return {
		passed: errorCount === 0,
		rulesChecked: rules.length,
		rulesPassed: ruleResults.filter((r) => r.passed).length,
		violations,
		durationMs: Date.now() - startTime,
		ruleResults,
	};
}

/**
 * Check a single architecture rule
 */
async function checkRule(rule: ArchRule, config: ArchRunnerConfig): Promise<ArchViolation[]> {
	const violations: ArchViolation[] = [];

	switch (rule.type) {
		case "no-dependency":
			violations.push(...(await checkNoDependency(rule, config)));
			break;
		case "cycle-free":
			violations.push(...(await checkCycleFree(rule, config)));
			break;
		case "layer-dependency":
			// Future: validate layer hierarchy
			break;
	}

	return violations;
}

/**
 * Check no-dependency rule using AST-based ImportGraphAnalyzer (Task #11g)
 * Replaces legacy grep-based approach with proper AST parsing
 */
async function checkNoDependency(rule: ArchRule, config: ArchRunnerConfig): Promise<ArchViolation[]> {
	const violations: ArchViolation[] = [];
	const { join, relative } = await import("node:path");
	const { readdir, readFile } = await import("node:fs/promises");
	const { existsSync } = await import("node:fs");

	const sources = Array.isArray(rule.source) ? rule.source : [rule.source];
	const targets = Array.isArray(rule.target) ? rule.target : [rule.target];

	for (const source of sources) {
		const sourceDir = join(config.workspaceRoot, source);

		if (!existsSync(sourceDir)) {
			continue;
		}

		// Collect all source files recursively
		const sourceFiles: string[] = [];
		const collectFiles = async (dir: string) => {
			const entries = await readdir(dir, { withFileTypes: true });
			for (const entry of entries) {
				const fullPath = join(dir, entry.name);
				if (entry.isDirectory()) {
					// Skip node_modules, dist, .next, test dirs
					if (
						!["node_modules", "dist", ".next", "__tests__", "__mocks__"].includes(entry.name) &&
						!config.globalExclude?.some((ex) => fullPath.includes(ex))
					) {
						await collectFiles(fullPath);
					}
				} else if (
					/\.(ts|tsx|js|jsx)$/.test(entry.name) &&
					!/\.(test|spec)\.(ts|tsx|js|jsx)$/.test(entry.name)
				) {
					sourceFiles.push(fullPath);
				}
			}
		};

		try {
			await collectFiles(sourceDir);
		} catch {
			continue;
		}

		// Try to use AST-based import extraction (requires @vreko/core)
		// Falls back to regex if not available (OSS SDK standalone mode)
		let extractImports:
			| ((
					content: string,
					filePath: string,
			  ) => { imports: Array<{ source: string; line?: number }>; parseSuccess: boolean })
			| null = null;

		try {
			// Optional dependency on @vreko/core for enhanced AST analysis
			// @ts-expect-error  -  optional peer, may not be installed
			const coreAnalysis = await import("@vreko/core/analysis");
			extractImports = coreAnalysis.extractImports;
		} catch {
			// @vreko/core not available - use simple regex fallback
			extractImports = null;
		}

		for (const filePath of sourceFiles) {
			// Skip excluded files
			if (rule.exclude?.some((ex) => filePath.includes(ex))) {
				continue;
			}

			try {
				const content = await readFile(filePath, "utf-8");

				// Extract imports (AST-based or regex fallback)
				const imports: Array<{ source: string; line?: number }> = [];
				if (extractImports) {
					const extraction = extractImports(content, filePath);
					if (extraction.parseSuccess) {
						imports.push(...extraction.imports);
					}
				} else {
					// Regex fallback: match import/export from statements
					const importRegex = /(?:import|export)\s+.*?\s+from\s+['"]([^'"]+)['"]/g;
					let match: RegExpExecArray | null;
					while ((match = importRegex.exec(content)) !== null) {
						imports.push({ source: match[1] });
					}
				}

				// Check each import against target patterns
				for (const imp of imports) {
					for (const target of targets) {
						const matchesTarget =
							imp.source === target ||
							imp.source.startsWith(`${target}/`) ||
							imp.source.includes(`/${target}`) ||
							imp.source.includes(target.replace(/^packages\//, ""));

						if (matchesTarget) {
							violations.push({
								ruleId: rule.id,
								ruleDescription: rule.description,
								severity: rule.severity,
								sourceFile: relative(config.workspaceRoot, filePath),
								targetFile: target,
								importPath: imp.source,
								line: imp.line,
							});
						}
					}
				}
			} catch {
				// Skip files that can't be read or parsed
			}
		}
	}

	return violations;
}

/**
 * Check cycle-free rule.
 *
 * Previously used madge, which was removed in phase 260423-79c as part of the
 * madge → dependency-cruiser migration. Cycle detection now lives in the
 * daemon topology scanner (apps/local-service) which exposes cycles through
 * the topology API  -  callers that need cycle detection should consume that
 * API rather than calling into this SDK helper.
 *
 * This function is preserved as a no-op stub so the `cycle-free` rule type
 * and the public `shouldBeCycleFree()` fluent builder remain part of the
 * SDK's published API surface. It returns no violations, matching the old
 * behavior when madge failed (the previous implementation silently swallowed
 * errors and returned an empty array).
 */
async function checkCycleFree(_rule: ArchRule, _config: ArchRunnerConfig): Promise<ArchViolation[]> {
	return [];
}

