import type { CreditJobType } from "@vreko/core/services/billing";
import { getCreditRange } from "@vreko/core/services/billing";

const TOOL_CREDIT_JOB_MAP: Partial<Record<string, CreditJobType>> = {
	vreko_pulse: "synthesis",
	vreko_learn: "memory_sync",
};

export type CreditEstimateMetadata = {
	jobType: string;
	min: number;
	max: number;
	typical: number;
	note: string;
};

const TOOL_CREDIT_NOTES: Partial<Record<string, string>> = {
	vreko_pulse: "Credits consumed when intelligence synthesis runs on the API tier.",
	vreko_learn: "Credits consumed when intelligence is persisted to the remote knowledge base.",
};

export function getToolCreditEstimate(toolName: string): CreditEstimateMetadata | undefined {
	const jobType = TOOL_CREDIT_JOB_MAP[toolName];
	if (!jobType) return undefined;
	const range = getCreditRange(jobType);
	return {
		jobType,
		min: range.min,
		max: range.max,
		typical: range.typical,
		note: TOOL_CREDIT_NOTES[toolName] ?? "",
	};
}
