/**
 * Cleanup Handler
 *
 * Workspace cleanup tool for snapshots, learnings, sessions, and blobs.
 *
 * @module facades/handlers/cleanup-handler
 */

import { join } from "node:path";
import { createDaemonClient, listSnapshotsViaDaemon } from "../../daemon/local-service-adapter.js";
import type { ToolHandler } from "../../types/tool-types.js";
import {
	type CleanupResult,
	cleanupArchivedSessions,
	cleanupStaleLearnings,
	formatBytes,
	getArchitectureVersion,
} from "../response-utils.js";
import { jsonResult } from "./utils.js";

/**
 * cleanup - Clean up stale workspace artifacts
 *
 * Cleans up:
 * - Old snapshots beyond retention policy
 * - Stale learnings (age or architecture mismatch)
 * - Archived sessions
 * - Orphaned blobs (not referenced by any snapshot)
 */
export const handleCleanup: ToolHandler = async (args, context) => {
	const {
		target = "all",
		dryRun = true,
		maxAge,
		keepCount,
	} = args as {
		target?: "snapshots" | "learnings" | "sessions" | "blobs" | "all";
		dryRun?: boolean;
		maxAge?: number;
		keepCount?: number;
	};

	const learningsPath = join(context.workspaceRoot, ".vreko", "learnings", "learnings.jsonl");
	const sessionArchiveDir = join(context.workspaceRoot, ".vreko", "session", "archive");

	const results: CleanupResult = {
		snapshots: { found: 0, stale: 0, deleted: 0 },
		learnings: { found: 0, stale: 0, deleted: 0 },
		sessions: { found: 0, stale: 0, deleted: 0 },
		blobs: { found: 0, stale: 0, deleted: 0, orphaned: 0 },
		totalBytesReclaimed: 0,
	};

	// Clean snapshots  -  route through daemon IPC (list + delete)
	if (target === "snapshots" || target === "all") {
		try {
			const allSnapshots = await listSnapshotsViaDaemon(context.workspaceRoot);
			const maxAgeDays = maxAge || 30;
			const keepCountN = keepCount || 10;
			const maxAgeMs = maxAgeDays * 24 * 60 * 60 * 1000;
			const cutoffTime = Date.now() - maxAgeMs;

			// Sort newest-first, then find stale candidates beyond keepCount that are also old
			const sorted = [...allSnapshots].sort(
				(a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
			);
			const stale = sorted.slice(keepCountN).filter((s) => new Date(s.createdAt).getTime() < cutoffTime);

			let deletedCount = 0;
			if (!dryRun) {
				const daemon = createDaemonClient(context.workspaceRoot);
				for (const vreko of stale) {
					try {
						await daemon.request("snapshot/delete", {
							workspace: context.workspaceRoot,
							snapshotId: vreko.id,
						});
						deletedCount++;
					} catch {
						// Best-effort deletion  -  continue on individual failures
					}
				}
			}

			results.snapshots = {
				found: allSnapshots.length,
				stale: stale.length,
				deleted: deletedCount,
			};
		} catch (_err) {
			// Intentionally ignored: snapshot cleanup is best-effort, other cleanups should proceed
		}
	}

	// Clean learnings
	if (target === "learnings" || target === "all") {
		const archVersion = getArchitectureVersion(context.workspaceRoot);
		results.learnings = cleanupStaleLearnings(learningsPath, {
			maxAgeDays: maxAge || 90,
			archVersion,
			dryRun,
		});
	}

	// Clean sessions
	if (target === "sessions" || target === "all") {
		results.sessions = cleanupArchivedSessions(sessionArchiveDir, {
			maxAgeDays: maxAge || 30,
			dryRun,
		});
	}

	// Clean blobs  -  no daemon equivalent; blob GC is managed by the daemon internally.
	// Returns zeros: callers should not depend on MCP-side blob GC.
	if (target === "blobs" || target === "all") {
		results.blobs = {
			found: 0,
			stale: 0,
			deleted: 0,
			orphaned: 0,
			bytesReclaimed: 0,
		};
	}

	const totalStale =
		results.snapshots.stale + results.learnings.stale + results.sessions.stale + results.blobs.orphaned;
	const totalDeleted =
		results.snapshots.deleted + results.learnings.deleted + results.sessions.deleted + results.blobs.deleted;

	return jsonResult(
		{
			status: "success",
			dryRun,
			target,
			results,
			summary: {
				totalStale,
				totalDeleted,
				bytesReclaimed: results.totalBytesReclaimed,
				bytesReclaimedFormatted: formatBytes(results.totalBytesReclaimed),
			},
			message: dryRun
				? `Would remove ${totalStale} stale item(s) and reclaim ${formatBytes(results.totalBytesReclaimed)}`
				: `Removed ${totalDeleted} item(s) and reclaimed ${formatBytes(results.totalBytesReclaimed)}`,
			_hint: dryRun
				? "This was a dry run. Call with dryRun: false to execute cleanup."
				: "Cleanup complete. Run prepare_workspace to verify workspace health.",
			next_actions: dryRun
				? totalStale > 0
					? [
							{
								tool: "cleanup",
								priority: 1,
								reason: "Execute cleanup",
								args: { target, dryRun: false },
							},
						]
					: []
				: [{ tool: "prepare_workspace", priority: 2, reason: "Verify workspace health" }],
		},
		{ context },
	);
};
