/**
 * File Selector
 *
 * Git-based file selection for validation operations.
 *
 * @module services/validation/file-selector
 */

import { spawn } from "node:child_process";
import type { DiffScope } from "./types.js";

/**
 * Get files from git based on diff scope.
 */
export async function getGitDiffFiles(workspacePath: string, scope: DiffScope = "staged"): Promise<string[]> {
	return new Promise((resolve) => {
		let args: string[];
		switch (scope) {
			case "staged":
				args = ["diff", "--cached", "--name-only", "--diff-filter=ACMR"];
				break;
			case "changed":
				args = ["diff", "--name-only", "--diff-filter=ACMR"];
				break;
			case "uncommitted":
				args = ["diff", "HEAD", "--name-only", "--diff-filter=ACMR"];
				break;
			case "all":
				args = ["ls-files"];
				break;
		}

		const proc = spawn("git", args, {
			cwd: workspacePath,
			stdio: ["pipe", "pipe", "pipe"],
		});

		let stdout = "";
		proc.stdout?.on("data", (data) => {
			stdout += data.toString();
		});

		proc.on("close", (code) => {
			if (code !== 0) {
				resolve([]);
				return;
			}

			const files = stdout
				.split("\n")
				.map((f) => f.trim())
				.filter((f) => f.length > 0)
				.filter((f) => /\.(ts|tsx|js|jsx)$/.test(f));

			resolve(files);
		});

		proc.on("error", () => {
			resolve([]);
		});
	});
}

/**
 * Auto-detect files to check if none specified.
 * Prioritizes staged files, then uncommitted changes.
 */
export async function autoDetectFiles(workspacePath: string): Promise<{ files: string[]; source: string }> {
	const staged = await getGitDiffFiles(workspacePath, "staged");
	if (staged.length > 0) {
		return { files: staged, source: "staged" };
	}

	const uncommitted = await getGitDiffFiles(workspacePath, "uncommitted");
	if (uncommitted.length > 0) {
		return { files: uncommitted, source: "uncommitted" };
	}

	return { files: [], source: "none" };
}
