/**
 * Composite Tool: review_work
 *
 * Comprehensive pre-commit review that combines:
 * - Pattern checking (7-layer validation)
 * - Change summary
 * - Learning suggestions
 * - Suggested commit message
 *
 * @see pair_programmer.md Section 2.4
 * @module facades/review-work
 */

import { execSync } from "node:child_process";
import {
	getBaselineFileSetAsync,
	getCurrentTaskAsync,
	getSessionStateAsync,
	pushObservationAsync,
} from "../adapters/session-adapter.js";
import { formatDuration } from "../session/utils.js";
import type { ToolHandler, ToolResult } from "../types/tool-types.js";
import { getFacades } from "./intelligence.js";

// =============================================================================
// TYPES
// =============================================================================

interface ReviewWorkInput {
	/** Skip pattern validation (default: false) */
	skipPatterns?: boolean;
	/** Include suggested commit message (default: true) */
	includeCommitMessage?: boolean;
	/** Specific files to review (default: all changed files) */
	files?: string[];
}

interface ReviewWorkOutput {
	taskId: string | null;
	taskDescription: string | null;
	duration: string;
	readyToCommit: boolean;
	validation: {
		passed: boolean;
		issues: Array<{
			layer: string;
			severity: "error" | "warning" | "info";
			message: string;
			file?: string;
			line?: number;
		}>;
		layerSummary: Array<{
			layer: string;
			passed: boolean;
			issueCount: number;
		}>;
	};
	changes: {
		fileCount: number;
		linesAdded: number;
		linesRemoved: number;
		files: Array<{
			file: string;
			status: "A" | "M" | "D";
			linesChanged: number;
		}>;
	};
	suggestedCommitMessage?: string;
	suggestedLearnings: Array<{
		type: "pattern" | "pitfall" | "efficiency";
		trigger: string;
		action: string;
	}>;
	nextActions: Array<{
		tool: string;
		priority: number;
		reason: string;
	}>;
}

// =============================================================================
// BASELINE FILE FILTERING (MCP surface concern  -  task-scoped review)
// =============================================================================

/**
 * Get git diff stats with timeout and task-scoped baseline filtering.
 *
 * Baseline filtering is a surface concern: the MCP tracks which files
 * were modified BEFORE the current task started, so review_work only
 * shows changes from the active task.
 *
 * Core git diff logic is also in ValidationServiceImpl.reviewWork(),
 * but without baseline awareness (intelligence layer has no session state).
 */
function getGitDiffStats(
	workspaceRoot: string,
	baselineFiles?: Set<string>,
): {
	files: Array<{ file: string; status: "A" | "M" | "D"; linesChanged: number }>;
	linesAdded: number;
	linesRemoved: number;
} {
	const files: Array<{ file: string; status: "A" | "M" | "D"; linesChanged: number }> = [];
	let linesAdded = 0;
	let linesRemoved = 0;

	try {
		const numstat = execSync("git diff --numstat HEAD", {
			cwd: workspaceRoot,
			encoding: "utf8",
			timeout: 5000,
		});

		for (const line of numstat.split("\n")) {
			if (!line.trim()) {
				continue;
			}
			const [added, removed, file] = line.split("\t");
			if (file) {
				if (baselineFiles?.has(file)) {
					continue;
				}
				const a = added === "-" ? 0 : Number.parseInt(added, 10);
				const r = removed === "-" ? 0 : Number.parseInt(removed, 10);
				linesAdded += a;
				linesRemoved += r;
				files.push({ file, status: "M", linesChanged: a + r });
			}
		}

		const status = execSync("git status --porcelain", {
			cwd: workspaceRoot,
			encoding: "utf8",
			timeout: 5000,
		});

		for (const line of status.split("\n")) {
			if (!line.trim()) {
				continue;
			}
			const statusCode = line.substring(0, 2);
			const file = line.substring(3).trim();
			if (baselineFiles?.has(file)) {
				continue;
			}

			const existing = files.find((f) => f.file === file);
			if (existing) {
				if (statusCode.includes("A") || statusCode === "??") {
					existing.status = "A";
				} else if (statusCode.includes("D")) {
					existing.status = "D";
				}
			} else if (statusCode === "??" || statusCode.includes("A")) {
				files.push({ file, status: "A", linesChanged: 0 });
			}
		}
	} catch {
		// Git not available, timeout, or not a git repo
	}

	return { files, linesAdded, linesRemoved };
}

// =============================================================================
// HANDLER
// =============================================================================

function result(text: string, isError = false): ToolResult {
	return {
		content: [{ type: "text", text }],
		isError,
	};
}

/**
 * review_work - Comprehensive pre-commit review
 *
 * Thin-client pattern: delegates core logic (validation, commit message,
 * learning suggestions) to ValidationServiceImpl.reviewWork() from
 * @vreko/intelligence, then overlays MCP-specific session state,
 * observations, and next-action recommendations.
 *
 * MCP surface retains baseline file filtering (task-scoped review)
 * because session state is a surface concern the intelligence layer
 * doesn't manage.
 */
export const handleReviewWork: ToolHandler = async (args, context): Promise<ToolResult> => {
	const { files: filterFiles } = args as ReviewWorkInput;

	const workspaceRoot = context.workspaceRoot;
	const state = await getSessionStateAsync(workspaceRoot);
	const task = await getCurrentTaskAsync(workspaceRoot);

	// ── Surface concern: task-scoped baseline filtering ──────────────────
	// Excludes files modified before the current task started.
	// Intelligence facades don't track session state, so this stays here.
	const baselineFiles = await getBaselineFileSetAsync(workspaceRoot);
	const { files, linesAdded, linesRemoved } = getGitDiffStats(workspaceRoot, baselineFiles);

	// Apply user-specified file filter on top of baseline filtering
	const filteredFileNames =
		filterFiles && filterFiles.length > 0
			? files
					.filter((f) => filterFiles.some((filter) => f.file.includes(filter) || filter.includes(f.file)))
					.map((f) => f.file)
			: files.map((f) => f.file);

	// ── Delegate core logic to intelligence facade ──────────────────────
	const reviewResult = await getFacades().validation.reviewWork({
		workspaceRoot,
	});

	// ── Surface concern: session state overlay ───────────────────────────
	const duration = task ? formatDuration(Date.now() - task.startedAt) : "No active task";

	// Save suggested learnings to session for later acceptance
	// Note: async state is a daemon snapshot; local mutation is best-effort (daemon owns truth)
	if (state && reviewResult.suggestedLearnings && reviewResult.suggestedLearnings.length > 0) {
		state.pendingSuggestedLearnings = reviewResult.suggestedLearnings;
	}

	// ── Surface concern: next-action recommendations ────────────────────
	const nextActions: Array<{ tool: string; priority: number; reason: string }> = [];

	if (reviewResult.validation && !reviewResult.validation.overall.passed) {
		nextActions.push({
			tool: "validate",
			priority: 1,
			reason: "Fix validation issues before committing",
		});
	}

	if (reviewResult.readyToCommit) {
		nextActions.push({
			tool: "complete_task",
			priority: 1,
			reason: "Finalize task and optionally capture learnings",
		});
	}

	if (reviewResult.suggestedLearnings && reviewResult.suggestedLearnings.length > 0) {
		nextActions.push({
			tool: "learn",
			priority: 3,
			reason: `${reviewResult.suggestedLearnings.length} learning(s) suggested from this work`,
		});
	}

	// Push observation about review completion
	await pushObservationAsync(workspaceRoot, {
		type: reviewResult.readyToCommit ? "progress" : "warning",
		message: reviewResult.readyToCommit
			? `Review complete: ${files.length} file(s) ready to commit`
			: `Review found ${reviewResult.validation?.issues?.length || 0} issue(s) to address`,
		timestamp: Date.now(),
	});

	// ── Assemble final output ────────────────────────────────────────────
	// Use facade results for validation, commit message, and learnings.
	// Use MCP's baseline-filtered change data for accurate task-scoped counts.
	const output: ReviewWorkOutput = {
		taskId: task?.id ?? null,
		taskDescription: task?.description ?? null,
		duration,
		readyToCommit: reviewResult.readyToCommit,
		validation: {
			passed: reviewResult.validation?.overall?.passed ?? true,
			issues: (reviewResult.validation?.issues || []).map((i) => ({
				layer: i.rule || "unknown",
				severity: "warning" as const,
				message: i.message,
				file: i.file,
				line: i.line,
			})),
			layerSummary: (reviewResult.validation?.layers || []).map((l) => ({
				layer: l.name || l.layer || "unknown",
				passed: l.passed,
				issueCount: (l.issues || []).length,
			})),
		},
		changes: {
			fileCount: filteredFileNames.length,
			linesAdded,
			linesRemoved,
			files: files.filter((f) => filteredFileNames.includes(f.file)).slice(0, 20),
		},
		suggestedCommitMessage: reviewResult.suggestedCommitMessage,
		suggestedLearnings: (reviewResult.suggestedLearnings || []).map((l) => ({
			type:
				l.type === "pattern" || l.type === "pitfall" || l.type === "efficiency" ? l.type : ("pattern" as const),
			trigger: l.trigger,
			action: l.action,
		})),
		nextActions,
	};

	return result(
		JSON.stringify(
			{
				...output,
				_hint: reviewResult.readyToCommit
					? `Ready to commit! Suggested: ${reviewResult.suggestedCommitMessage}`
					: `${reviewResult.validation?.issues?.length || 0} issue(s) found. Fix them before committing.`,
			},
			null,
			2,
		),
	);
};
