/**
 * TieredLearningService - Tiered learning storage for token efficiency
 *
 * Implements three-tier architecture:
 * - Hot: Always loaded (~10-15 entries, critical patterns)
 * - Warm: Loaded based on intent/domain match (~20-30 per domain)
 * - Cold: Query-only, never auto-loaded (archived learnings)
 *
 * Fixes 97% token waste in learning retrieval by loading only relevant
 * learnings based on task intent instead of loading all ~100+ entries.
 *
 * Storage:
 * - .vreko/learnings/hot.jsonl (always loaded)
 * - .vreko/learnings/architecture-patterns.jsonl (intent: implement)
 * - .vreko/learnings/domain-testing.jsonl (intent: debug, review)
 * - .vreko/learnings/anti-patterns.jsonl (intent: debug, review)
 * - .vreko/learnings/workflow-patterns.jsonl (intent: refactor)
 * - .vreko/learnings/learnings.jsonl (cold tier - query only)
 *
 * @module services/tiered-learning-service
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { Learning, LearningTier } from "@vreko/intelligence/types";
import { observePatternViaDaemon, trackAppliedViaDaemon } from "../daemon/local-service-adapter.js";

// =============================================================================
// Usage Tracking Types
// =============================================================================

/**
 * Learning with usage tracking metadata
 *
 * Phase 3 additions: confidence, sourceRollbackId, captureMethod, synced, syncedAt.
 */
export interface TrackedLearning extends Learning {
	/** Number of times this learning was loaded */
	accessCount?: number;
	/** Number of times this learning was applied/useful */
	appliedCount?: number;
	/** Last time this learning was accessed */
	lastAccessed?: string;
	/** When this learning was promoted to hot tier */
	promotedAt?: string;

	// === Phase 3 Additions ===

	/** Confidence score (0-1). Default 0.3 for new learnings. */
	confidence?: number;
	/** Snapshot ID that was restored to generate this learning */
	sourceRollbackId?: string | null;
	/** How this learning was captured */
	captureMethod?: "passive-watcher" | "mcp-callback" | "user-feedback";
	/** Has been sent to API layer (for L3 equivalent  -  cold tier) */
	synced?: boolean;
	/** When this learning was synced to API */
	syncedAt?: number | null;
}

/**
 * Usage stats file format
 */
interface UsageStats {
	[learningId: string]: {
		accessCount: number;
		appliedCount: number;
		lastAccessed: string;
	};
}

