/** Directory name for auto-promoted invariant JSON files (relative to workspaceRoot) */
export const INVARIANTS_DIR_NAME = ".vreko/invariants" as const;

/**
 * Allowlist regex for verification.command in auto-promoted invariant JSON files.
 * INVAR-T-06: Prevents RCE if check.ts later executes the command.
 */
const VERIFICATION_COMMAND_ALLOWLIST =
	/^pnpm\s+vitest\s+run\s+tests\/architecture\/[A-Za-z0-9._\-/]+\.test\.ts(\s+--grep\s+"[^"]+")?$/;

interface PromotionInput {
	patternId: string;
	workspaceRoot: string;
	confirmingInstances: number;
	counterExamples: number;
	description?: string;
	verificationCommand?: string;
}

/**
 * INVAR-04: Promote a learning to an enforced invariant by writing
 * .vreko/invariants/{patternId}.json. Guarded by INVAR-03 (counterExamples must be 0).
 * INVAR-T-02: writeFileSync is gated by existsSync to avoid double-creation races.
 * INVAR-T-06: verificationCommand is allowlist-validated before writing.
 */
export async function emitInvariantIfQualified(input: PromotionInput): Promise<boolean> {
	const { patternId, workspaceRoot, confirmingInstances, counterExamples, description, verificationCommand } = input;

	// INVAR-03: Require at least 3 confirming instances (minObservations threshold)
	// Note: literal >= 3 guard required for static analysis (INVAR-03/04 tests assert this pattern)
	if (!(confirmingInstances >= 3)) {
		return false;
	}
	// Counter-example gate: any counter-example blocks promotion (INVAR-03)
	if (counterExamples !== 0) {
		return false;
	}
	// Validate patternId is safe for use as a filename
	if (!/^[a-z0-9][a-z0-9.-]*$/i.test(patternId)) {
		return false;
	}

	const cmd = verificationCommand ?? `pnpm vitest run tests/architecture/invariants.test.ts --grep "${patternId}"`;
	// INVAR-T-06: Reject verification commands that don't match the allowlist
	if (!VERIFICATION_COMMAND_ALLOWLIST.test(cmd)) {
		process.stderr.write(`[invariant-emission] WARN: rejected invalid verification.command for ${patternId}\n`);
		return false;
	}

	const { join: pathJoin } = await import("node:path");
	const dir = pathJoin(workspaceRoot, ".vreko", "invariants");
	const target = pathJoin(dir, `${patternId}.json`);

	// INVAR-T-02: Race guard  -  do not overwrite if file already exists
	if (existsSync(target)) {
		return false;
	}
	if (!existsSync(dir)) {
		mkdirSync(dir, { recursive: true });
	}

	const invariant = {
		invariant_id: patternId,
		version: "1.0",
		description: description ?? `Auto-promoted learning: ${patternId}`,
		category: "learned-invariant",
		severity: "error",
		phase: "Phase 10 (INVAR-04 auto-promotion)",
		mode: "enforced",
		confirmingInstances,
		counterExamples,
		overrideCount: 0,
		verification: {
			method: "command",
			command: cmd,
			threshold: 0,
		},
		rationale: description ?? "Auto-promoted from observed pattern",
		_note: "Mode changes require code review  -  auto-set to advisory by check.ts on overrideCount >= 2 only",
	};

	writeFileSync(target, `${JSON.stringify(invariant, null, 2)}\n`, "utf-8");
	return true;
}

/**
 * Intelligence Layer v0.3.0: Pattern Observation Record
 *
 * Tracks observations of a potential pattern across sessions.
 */
export interface PatternObservation {
	/** Pattern identifier (hash of trigger/signature) */
	patternId: string;
	/** Pattern signature (normalized trigger) */
	signature: string;
	/** Observation count */
	observationCount: number;
	/** Timestamps of each observation */
	observedAt: number[];
	/** Sessions where this pattern was observed */
	sessionIds: string[];
	/** Workspaces where this pattern was observed */
	workspaceIds: string[];
	/** Last observation timestamp */
	lastObservedAt: number;
	/** Confidence score (increases with more observations) */
	confidence: number;
	/** Pattern type classification */
	patternType: "pitfall" | "efficiency" | "discovery" | "workflow";
	/** Whether this pattern has been promoted to a learning */
	promoted: boolean;
	/** When this pattern was promoted (if applicable) */
	promotedAt?: number;
	/** Learning ID after promotion */
	learningId?: string;
	/**
	 * Number of counter-examples observed (observations that contradict the pattern).
	 * INVAR-03/04: If counterExampleCount > 0, invariant promotion is blocked.
	 * Field is optional (defaults to 0) for backward compat with existing observation records.
	 */
	counterExampleCount?: number;
}

/** Priority score boost for hot tier - exported for test visibility */
export const HOT_TIER_BOOST = 100;

/** Priority score boost for critical priority */
const CRITICAL_PRIORITY_BOOST = 50;

/** Priority score boost for high priority */
const HIGH_PRIORITY_BOOST = 25;

// =============================================================================
// Utility Functions
// =============================================================================

/**
 * Load JSONL file, skipping malformed lines
 */
function loadJsonlSafe<T>(filepath: string): T[] {
	if (!existsSync(filepath)) {
		return [];
	}

	try {
		const content = readFileSync(filepath, "utf8");
		const lines = content.split("\n").filter(Boolean);
		const items: T[] = [];

		for (const line of lines) {
			try {
				items.push(JSON.parse(line));
			} catch (_error) {
				// Skip malformed lines - log in debug mode for diagnostics
				if (process.env.DEBUG) {
					// Intentionally empty: placeholder for future debug logging of malformed JSONL lines
				}
			}
		}

		return items;
	} catch (_error) {
		// File read failed - could be missing or corrupted
		if (process.env.DEBUG) {
			// Intentionally empty: placeholder for future debug logging of file read failures
		}
		return [];
	}
}

/**
 * Score a learning based on keyword relevance
 */
function scoreLearning(learning: Learning, keywords: string[]): number {
	if (keywords.length === 0) {
		return 0;
	}

	const triggerText = Array.isArray(learning.trigger) ? learning.trigger.join(" ") : learning.trigger || "";

	const searchText = `${triggerText} ${learning.action || ""} ${learning.context || ""}`.toLowerCase();

	let matches = 0;
	for (const keyword of keywords) {
		if (searchText.includes(keyword.toLowerCase())) {
			matches++;
		}
	}

	return matches / keywords.length;
}

/**
 * Get priority boost based on learning priority
 */
function getPriorityBoost(learning: Learning): number {
	if (learning.priority === "critical") {
		return CRITICAL_PRIORITY_BOOST;
	}
	if (learning.priority === "high") {
		return HIGH_PRIORITY_BOOST;
	}
	return 0;
}

