// TieredLearningService
// =============================================================================

/**
 * TieredLearningService - Tiered learning storage for token efficiency
 *
 * Provides hot/warm/cold tiered learning retrieval optimized for LLM context windows.
 * Hot tier learnings are always loaded; warm tier loaded based on intent/keywords;
 * cold tier queried on-demand from archive.
 *
 * MIGRATION STATUS (2026-03):
 * - Hot/Warm/Cold loading: STABLE - core functionality
 * - trackApplied(): ACTIVE - used by vreko-end for usage tracking
 * - observePattern(): ACTIVE - pattern promotion system
 * - saveUsageStats(): DEPRECATED - to be migrated to daemon IPC
 * - savePatternObservations(): DEPRECATED - to be migrated to daemon IPC
 *
 * Direct file writes (saveUsageStats, savePatternObservations) should be
 * migrated to daemon IPC for consistency with learning.ts architecture.
 *
 * @see apps/local-service/src/services/learning.ts for daemon-side handlers
 */
export class TieredLearningService {
	private learningsDir: string;
	private workspaceId?: string;
	private workspaceRoot?: string;

	constructor(workspaceRoot: string, workspaceId?: string) {
		this.learningsDir = join(workspaceRoot, ".vreko", "learnings");
		this.workspaceId = workspaceId;
		this.workspaceRoot = workspaceRoot;
	}

	/**
	 * Check if a learning is visible to the current workspace.
	 *
	 * - Learnings without a workspaceId field are "global" (visible to all workspaces)
	 * - Learnings with a workspaceId are only visible to that specific workspace
	 * - If no workspaceId is set on this service, all learnings are visible (backward compat)
	 */
	private isVisibleToWorkspace(learning: Learning): boolean {
		const learningWsId = (learning as unknown as Record<string, unknown>).workspaceId as string | undefined;

		// No workspaceId on learning → global, always visible
		if (!learningWsId) {
			return true;
		}

		// No workspaceId on service → show everything (backward compat)
		if (!this.workspaceId) {
			return true;
		}

		// Both have workspaceId → must match
		return learningWsId === this.workspaceId;
	}

	/**
	 * Load learnings from tiered storage based on intent
	 *
	 * @param options - Loading options (intent, keywords, maxLearnings)
	 * @returns Scored and ranked learnings
	 */
	async loadTieredLearnings(options: LoadTieredLearningsOptions): Promise<ScoredLearning[]> {
		const { intent, keywords, filePaths = [], maxLearnings = DEFAULT_MAX_LEARNINGS } = options;

		// Track loaded learnings by ID for deduplication
		const loadedIds = new Set<string>();
		const allLearnings: ScoredLearning[] = [];

		// 1. ALWAYS load hot tier (filtered by workspaceId)
		const hotLearnings = this.loadHotTier();
		for (const learning of hotLearnings) {
			if (!this.isVisibleToWorkspace(learning)) {
				continue;
			}
			const id = learning.id || this.generateId(learning);
			if (!loadedIds.has(id)) {
				loadedIds.add(id);
				allLearnings.push({
					...learning,
					score: scoreLearning(learning, keywords) + HOT_TIER_BOOST + getPriorityBoost(learning),
					loadedFrom: "hot",
				});
			}
		}

		// 2. Load warm tier based on intent
		const intentFiles = INTENT_LEARNING_FILES[intent as TaskIntent] || DEFAULT_DOMAIN_FILES;

		// 3. Detect additional domain files from keywords (NEW)
		const keywordDomainFiles = detectDomainFilesFromKeywords(keywords);

		// 4. Detect additional domain files from file paths (NEW)
		const pathDomainFiles = detectDomainFilesFromPaths(filePaths);

		// 5. Combine all warm tier files (dedupe)
		const allWarmFiles = [...new Set([...intentFiles, ...keywordDomainFiles, ...pathDomainFiles])];

		// 6. Load learnings from all warm tier files (filtered by workspaceId)
		for (const filename of allWarmFiles) {
			const filepath = join(this.learningsDir, filename);
			const domainLearnings = loadJsonlSafe<Learning>(filepath);

			// Extract domain from filename
			const domain = filename.replace(/^domain-/, "").replace(/\.jsonl$/, "");

			for (const learning of domainLearnings) {
				if (!this.isVisibleToWorkspace(learning)) {
					continue;
				}
				const id = learning.id || this.generateId(learning);
				if (!loadedIds.has(id)) {
					loadedIds.add(id);
					allLearnings.push({
						...learning,
						score: scoreLearning(learning, keywords) + getPriorityBoost(learning),
						loadedFrom: "warm",
						tier: "warm" as LearningTier,
						domain,
					});
				}
			}
		}

		// 7. DO NOT auto-load cold tier (learnings.jsonl)
		// Cold tier is only accessible via explicit query

		// 8. Filter by relevance threshold, sort by score (descending), return top N
		// This reduces noise by only returning learnings that actually match the task
		return allLearnings
			.filter((l) => {
				// Hot tier learnings have lower threshold (pre-vetted critical patterns)
				const threshold = l.loadedFrom === "hot" ? MIN_HOT_RELEVANCE_SCORE : MIN_RELEVANCE_SCORE;
				// Normalize score by removing tier/priority boosts to compare raw relevance
				const rawScore =
					l.score - (l.loadedFrom === "hot" ? HOT_TIER_BOOST : 0) - getPriorityBoost(l as Learning);
				return rawScore >= threshold;
			})
			.sort((a, b) => b.score - a.score)
			.slice(0, maxLearnings);
	}

	/**
	 * Load hot tier learnings (always loaded)
	 */
	private loadHotTier(): Learning[] {
		const hotPath = join(this.learningsDir, HOT_TIER_FILE);
		const learnings = loadJsonlSafe<Learning>(hotPath);

		// Mark as hot tier
		return learnings.map((l) => ({ ...l, tier: "hot" as LearningTier }));
	}

	/**
	 * Query cold tier for specific keywords (on-demand only)
	 *
	 * This method is NOT called by loadTieredLearnings.
	 * Use it explicitly when searching archived learnings.
	 */
	async queryColdTier(keywords: string[], maxResults = 10): Promise<ScoredLearning[]> {
		const coldPath = join(this.learningsDir, COLD_TIER_FILE);
		const learnings = loadJsonlSafe<Learning>(coldPath);

		const scored: ScoredLearning[] = learnings
			.filter((l) => this.isVisibleToWorkspace(l))
			.filter((l) => l.tier === "cold" || !l.tier)
			.map((l) => ({
				...l,
				score: scoreLearning(l, keywords),
				loadedFrom: "cold" as const,
				tier: "cold" as LearningTier,
			}));

		return scored
			.filter((l) => l.score > 0)
			.sort((a, b) => b.score - a.score)
			.slice(0, maxResults);
	}

	/**
	 * Generate a deterministic ID for learnings without one
	 */
	private generateId(learning: Learning): string {
		const trigger = Array.isArray(learning.trigger) ? learning.trigger.join("-") : learning.trigger || "";
		return `${learning.type}-${trigger.slice(0, 20)}`.replace(/\s+/g, "-").toLowerCase();
	}

	// =========================================================================
	// Usage Tracking Methods
	// =========================================================================

	/**
	 * Load usage stats from disk
	 */
	private loadUsageStats(): UsageStats {
		const statsPath = join(this.learningsDir, USAGE_STATS_FILE);
		if (!existsSync(statsPath)) {
			return {};
		}
		try {
			return JSON.parse(readFileSync(statsPath, "utf8"));
		} catch (_error) {
			if (process.env.DEBUG) {
				// Intentionally empty: placeholder for future debug logging of stats read failures
			}
			return {};
		}
	}

	/**
	 * Save usage stats to disk
	 * @deprecated Direct file write. Will be migrated to daemon IPC in future version.
	 * @internal
	 */
	private saveUsageStats(stats: UsageStats): void {
		const statsPath = join(this.learningsDir, USAGE_STATS_FILE);
		try {
			mkdirSync(this.learningsDir, { recursive: true });
			writeFileSync(statsPath, JSON.stringify(stats, null, 2));
		} catch (_error) {
			// Best effort - don't fail if can't write, but log for visibility
			if (process.env.DEBUG) {
				// Intentionally empty: placeholder for future debug logging of stats write failures
			}
		}
	}

	/**
	 * Track that a learning was applied (marked as useful by user/agent).
	 * Routes to daemon IPC for centralized state management.
	 */
	trackApplied(learningId: string): void {
		// Route to daemon for centralized tracking (fire-and-forget)
		if (this.workspaceId) {
			trackAppliedViaDaemon(this.workspaceId, learningId, "medium").catch(() => {
				// Daemon unavailable - fall through to local tracking
			});
		}

		// Keep local state for backward compatibility and offline operation
		const stats = this.loadUsageStats();
		const now = new Date().toISOString();

		if (!stats[learningId]) {
			stats[learningId] = { accessCount: 1, appliedCount: 0, lastAccessed: now };
		}
		stats[learningId].appliedCount++;
		stats[learningId].lastAccessed = now;

		this.saveUsageStats(stats);
	}

	/**
	 * Calculate promotion score for a learning
	 * Higher score = more likely to be promoted to hot tier
	 */
	private calculatePromotionScore(learning: TrackedLearning, stats: UsageStats): number {
		const id = learning.id || this.generateId(learning);
		const usageData = stats[id];

		if (!usageData) {
			return 0;
		}

		// Base score from counts (applied counts weight 3x more than access)
		let score = usageData.accessCount + usageData.appliedCount * 3;

		// Recency boost - more recent = higher score
		const lastAccessed = new Date(usageData.lastAccessed);
		const daysSinceAccess = (Date.now() - lastAccessed.getTime()) / (1000 * 60 * 60 * 24);
		if (daysSinceAccess < HOT_TIER_PROMOTION_THRESHOLD.recencyDays) {
			score *= 1 + (1 - daysSinceAccess / HOT_TIER_PROMOTION_THRESHOLD.recencyDays);
		}

		// Priority boost
		if (learning.priority === "critical") {
			score *= 2;
		} else if (learning.priority === "high") {
			score *= 1.5;
		}

		return score;
	}

	/**
	 * Regenerate hot.jsonl based on usage patterns
	 *
	 * Algorithm:
	 * 1. Load all learnings from cold + warm tiers
	 * 2. Score each by usage patterns (access, applied, recency)
	 * 3. Preserve existing hot tier entries with priority: critical
	 * 4. Fill remaining slots with highest-scoring learnings
	 * 5. Write new hot.jsonl
	 *
	 * @returns Statistics about the regeneration
	 */
	async regenerateHotTier(): Promise<{
		preserved: number;
		promoted: number;
		demoted: number;
		totalHot: number;
	}> {
		const stats = this.loadUsageStats();

		// Load current hot tier
		const currentHot = this.loadHotTier();
		const criticalHot = currentHot.filter((l) => l.priority === "critical");

		// Load all learnings from cold tier
		const coldPath = join(this.learningsDir, COLD_TIER_FILE);
		const allLearnings = loadJsonlSafe<TrackedLearning>(coldPath);

		// Also load from warm tier files
		const warmFiles = Object.values(INTENT_LEARNING_FILES).flat();
		const seenIds = new Set<string>();
		const warmLearnings: TrackedLearning[] = [];

		for (const filename of [...new Set(warmFiles)]) {
			const filepath = join(this.learningsDir, filename);
			const learnings = loadJsonlSafe<TrackedLearning>(filepath);
			for (const l of learnings) {
				const id = l.id || this.generateId(l as Learning);
				if (!seenIds.has(id)) {
					seenIds.add(id);
					warmLearnings.push(l);
				}
			}
		}

		// Combine and dedupe
		const allCandidates = [...allLearnings, ...warmLearnings];
		const candidateMap = new Map<string, TrackedLearning>();
		for (const l of allCandidates) {
			const id = l.id || this.generateId(l as Learning);
			if (!candidateMap.has(id)) {
				candidateMap.set(id, l);
			}
		}

		// Score all candidates
		const scored = Array.from(candidateMap.entries())
			.map(([id, learning]) => ({
				id,
				learning,
				score: this.calculatePromotionScore(learning, stats),
			}))
			.filter((item) => {
				// Only consider learnings that meet minimum thresholds
				const usageData = stats[item.id];
				if (!usageData) {
					return false;
				}
				return (
					usageData.accessCount >= HOT_TIER_PROMOTION_THRESHOLD.minAccessCount ||
					usageData.appliedCount >= HOT_TIER_PROMOTION_THRESHOLD.minAppliedCount
				);
			})
			.sort((a, b) => b.score - a.score);

		// Build new hot tier
		const newHot: TrackedLearning[] = [];
		const criticalIds = new Set(criticalHot.map((l) => l.id || this.generateId(l)));

		// 1. Always preserve critical entries
		for (const l of criticalHot) {
			newHot.push({
				...l,
				tier: "hot" as LearningTier,
			});
		}

		// 2. Fill remaining slots with highest-scoring
		const _remainingSlots = HOT_TIER_PROMOTION_THRESHOLD.maxHotTierSize - newHot.length;
		let promoted = 0;

		for (const item of scored) {
			if (newHot.length >= HOT_TIER_PROMOTION_THRESHOLD.maxHotTierSize) {
				break;
			}
			if (criticalIds.has(item.id)) {
				continue; // Already added
			}

			newHot.push({
				...item.learning,
				tier: "hot" as LearningTier,
				promotedAt: new Date().toISOString(),
			});
			promoted++;
		}

		// Calculate demoted count
		const newHotIds = new Set(newHot.map((l) => l.id || this.generateId(l as Learning)));
		const demoted = currentHot.filter((l) => {
			const id = l.id || this.generateId(l);
			return !newHotIds.has(id);
		}).length;

		// Hot tier persistence via daemon IPC not yet implemented  -  see Deferred Backlog

		return {
			preserved: criticalHot.length,
			promoted,
			demoted,
			totalHot: newHot.length,
		};
	}

	/**
	 * Get usage statistics for analysis
	 */
	getUsageStats(): UsageStats {
		return this.loadUsageStats();
	}

	// =========================================================================
	// Intelligence Layer v0.3.0: Pattern Observation Methods
	// =========================================================================

	/** Pattern observations file */
	private get patternObservationsPath(): string {
		return join(this.learningsDir, "pattern-observations.json");
	}

	/**
	 * Load pattern observations from disk
	 */
	private loadPatternObservations(): Map<string, PatternObservation> {
		if (!existsSync(this.patternObservationsPath)) {
			return new Map();
		}
		try {
			const content = readFileSync(this.patternObservationsPath, "utf8");
			const records = JSON.parse(content) as PatternObservation[];
			return new Map(records.map((r) => [r.patternId, r]));
		} catch {
			return new Map();
		}
	}

	/**
	 * Save pattern observations to disk
	 * @deprecated Direct file write. Will be migrated to daemon IPC in future version.
	 * @internal
	 */
	private savePatternObservations(observations: Map<string, PatternObservation>): void {
		try {
			mkdirSync(this.learningsDir, { recursive: true });
			const records = Array.from(observations.values());
			writeFileSync(this.patternObservationsPath, JSON.stringify(records, null, 2));
		} catch (_error) {
			if (process.env.DEBUG) {
				// Intentionally empty: placeholder for future debug logging of pattern observation save failures
			}
		}
	}

	/**
	 * Generate a pattern ID from a signature
	 */
	private generatePatternId(signature: string): string {
		let hash = 0;
		for (let i = 0; i < signature.length; i++) {
			const char = signature.charCodeAt(i);
			hash = (hash << 5) - hash + char;
			hash |= 0;
		}
		return `pat_${Math.abs(hash).toString(36)}`;
	}

	/**
	 * Observe a potential pattern.
	 *
	 * Call this when a pattern is detected during a session.
	 * After 3 observations, the pattern is automatically promoted to a learning.
	 *
	 * Routes to daemon IPC for centralized tracking.
	 * @param signature - Normalized pattern signature (e.g., "rapid-write:file.ts")
	 * @param patternType - Type of pattern
	 * @param sessionId - Current session ID
	 * @param confidence - Initial confidence (0-1)
	 * @returns Whether the pattern was promoted to a learning
	 */
	async observePattern(
		signature: string,
		patternType: PatternObservation["patternType"],
		sessionId: string,
		confidence = 0.5,
	): Promise<{ promoted: boolean; observationCount: number; patternId: string }> {
		const observations = this.loadPatternObservations();
		// Route to daemon for centralized tracking (fire-and-forget)
		if (this.workspaceId) {
			observePatternViaDaemon(this.workspaceId, signature, patternType, sessionId, confidence).catch(() => {
				// Daemon unavailable - continue with local tracking
			});
		}

		// Local tracking for sophisticated promotion logic
		const patternId = this.generatePatternId(signature);
		const now = Date.now();

		let observation = observations.get(patternId);
		if (!observation) {
			observation = {
				patternId,
				signature,
				observationCount: 0,
				observedAt: [],
				sessionIds: [],
				workspaceIds: [],
				lastObservedAt: now,
				confidence: 0,
				patternType,
				promoted: false,
			};
			observations.set(patternId, observation);
		}

		// Check if already promoted
		if (observation.promoted) {
			return { promoted: true, observationCount: observation.observationCount, patternId };
		}

		// Check if this session already observed this pattern
		if (!observation.sessionIds.includes(sessionId)) {
			observation.observationCount++;
			observation.observedAt.push(now);
			observation.sessionIds.push(sessionId);
			if (this.workspaceId && !observation.workspaceIds.includes(this.workspaceId)) {
				observation.workspaceIds.push(this.workspaceId);
			}

			// Update confidence (increases with more observations, max 1.0)
			observation.confidence = Math.min(1.0, observation.confidence + confidence * 0.3);
		}
		observation.lastObservedAt = now;

		// Check for promotion (3x threshold)
		const shouldPromote =
			observation.observationCount >= PATTERN_OBSERVATION_THRESHOLD.minObservations &&
			observation.confidence >= PATTERN_OBSERVATION_THRESHOLD.minConfidence &&
			!observation.promoted;

		if (shouldPromote) {
			observation.promoted = true;
			observation.promotedAt = now;

			// Save observations before creating learning
			this.savePatternObservations(observations);

			// Create a learning from the pattern (async via daemon IPC)
			const learningId = await this.createLearningFromPattern(observation);
			observation.learningId = learningId;
			this.savePatternObservations(observations);

			// INVAR-04: After learning promotion, attempt invariant emission.
			// counterExampleCount defaults to 0 for backward compat with existing records.
			const counterExamples = observation.counterExampleCount ?? 0;
			if (
				observation.observationCount >= PATTERN_OBSERVATION_THRESHOLD.minObservations &&
				counterExamples === 0
			) {
				await emitInvariantIfQualified({
					patternId: observation.patternId,
					// Issue: LIN-INVAR-04  -  inject workspaceRoot via constructor instead of process.cwd() fallback
					workspaceRoot: this.workspaceRoot ?? process.cwd(),
					confirmingInstances: observation.observationCount,
					counterExamples,
					description: observation.signature,
				});
			}

			return { promoted: true, observationCount: observation.observationCount, patternId };
		}

		this.savePatternObservations(observations);
		return { promoted: false, observationCount: observation.observationCount, patternId };
	}

	/**
	 * Create a learning from a promoted pattern observation.
	 */
	private async createLearningFromPattern(observation: PatternObservation): Promise<string> {
		const learning: TrackedLearning = {
			id: `learn_${observation.patternId}`,
			type: observation.patternType,
			trigger: observation.signature,
			action: `Pattern observed ${observation.observationCount} times across ${observation.sessionIds.length} sessions`,
			solution: `Apply pattern from ${observation.observationCount} observations`,
			source: "pattern-promotion",
			timestamp: new Date().toISOString(),
			tier: "warm",
			priority: observation.confidence >= 0.9 ? "high" : "medium",
			confidence: observation.confidence,
		};

		// Warm tier persistence via daemon IPC not yet implemented  -  see Deferred Backlog
		return learning.id;
	}

	/**
	 * Get all pattern observations.
	 */
	getPatternObservations(): PatternObservation[] {
		const observations = this.loadPatternObservations();
		return Array.from(observations.values());
	}

	/**
	 * Get patterns ready for promotion (observed 2+ times, not yet promoted).
	 */
	getPatternsPendingPromotion(): PatternObservation[] {
		const observations = this.loadPatternObservations();
		return Array.from(observations.values()).filter(
			(o) => !o.promoted && o.observationCount >= PATTERN_OBSERVATION_THRESHOLD.minObservations - 1,
		);
	}

	/**
	 * Get promoted patterns.
	 */
	getPromotedPatterns(): PatternObservation[] {
		const observations = this.loadPatternObservations();
		return Array.from(observations.values()).filter((o) => o.promoted);
	}
}

