export const validateChangeTool: VrekoTool = {
	name: "vreko_validate_change",
	description: `[DEPRECATED  -  use vreko_begin/vreko_learn/vreko_end/vreko_pulse] 🔍 Validate a proposed code change against historical context, documentation, and production error data.

**When to use:**
- Before applying a significant code change
- When modifying critical files (auth, payments, config)
- To get risk assessment with specific factors

**Wire Response:**
🔍|V|score:45|level:medium|rec:warn|conf:75|factors:3

**Parameters:**
- filePath: Path to the file being changed (required)
- content: New file content (required)
- previousContent: Previous file content for diff analysis
- language: Programming language (auto-detected if not provided)

**Returns:** Risk assessment with score, level, factors, and recommendation`,
	inputSchema: {
		type: "object",
		properties: {
			filePath: {
				type: "string",
				description: "Path to the file being changed",
			},
			content: {
				type: "string",
				description: "New file content",
			},
			previousContent: {
				type: "string",
				description: "Previous file content for diff analysis",
			},
			language: {
				type: "string",
				description: "Programming language (auto-detected if not provided)",
			},
		},
		required: ["filePath", "content"],
	},
	annotations: {
		title: "🔍 Validate Change",
		readOnlyHint: true,
		destructiveHint: false,
		idempotentHint: true,
	},
};

export async function handleValidateChange(args: Record<string, unknown>, context: ToolContext): Promise<ToolResult> {
	// Security: Validate and sanitize all user inputs
	const validation = validateValidateChangeParams(args);
	if (!validation.success) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Input validation failed:\n${validation.errors?.join("\n") ?? "Unknown validation error"}`,
				},
			],
			isError: true,
		};
	}

	const input = validation.data as ValidateChangeArgs;
	const workspaceRoot = getWorkspaceRoot(context);
	const language = input.language ?? detectLanguage(input.filePath);

	// Get integration orchestrator
	const integrations = context.services?.integrations ?? getIntegrationOrchestratorService();

	// Gather context from all integrations
	const enriched = await integrations.enrichContext({
		files: [{ path: input.filePath, content: input.content, language }],
		intent: "implement",
		skipCache: false,
	});

	// Build aggregated context
	const aggregatedContext = enrichedToAggregated(input.filePath, enriched);

	// Assess risk via daemon IPC
	const result = await assessRiskViaDaemon(
		workspaceRoot,
		input.filePath,
		input.content,
		input.previousContent,
		aggregatedContext,
	);

	if (!result.success || !result.assessment) {
		return {
			content: [{ type: "text", text: `🔍|V|error:${result.error}|path:${input.filePath}` }],
			isError: true,
		};
	}

	const assessment = result.assessment;

	// Index patterns for future queries
	await indexPatternsViaDaemon(workspaceRoot, assessment.factors);

	// Build wire format
	const wire = [
		"🔍",
		"V",
		`score:${assessment.score}`,
		`level:${assessment.level}`,
		`rec:${assessment.recommendation}`,
		`conf:${assessment.confidence}`,
		`factors:${assessment.factors.length}`,
	].join("|");

	// Build human-readable summary
	const summary = formatRiskAssessmentViaDaemon(assessment);

	// Build structured content
	const structuredContent: Record<string, unknown> = {
		score: assessment.score,
		level: assessment.level,
		recommendation: assessment.recommendation,
		confidence: assessment.confidence,
		factors: (assessment.factors || []).map((f) => ({
			name: f.name,
			score: f.score,
			source: f.source,
			description: f.description,
			suggestion: f.suggestion,
		})),
		explanation: assessment.explanation,
		sources: enriched?.sources ?? [],
	};

	return {
		content: [{ type: "text", text: `${wire}\n---\n${summary}` }],
		structuredContent,
	};
}

