export const getRiskScoreTool: VrekoTool = {
	name: "vreko_get_risk_score",
	description: `[DEPRECATED] 📊 Get the current risk score for a file based on all available context.

**When to use:**
- Quick risk check before modifying a file
- To understand a file's current health status
- Before deciding whether to proceed with changes

**Wire Response:**
📊|R|score:35|level:medium|rec:warn

**Parameters:**
- filePath: Path to the file (required)
- content: File content (reads from disk if not provided)

**Returns:** Score 0-100 with breakdown of contributing factors`,
	inputSchema: {
		type: "object",
		properties: {
			filePath: {
				type: "string",
				description: "Path to the file",
			},
			content: {
				type: "string",
				description: "File content (reads from disk if not provided)",
			},
		},
		required: ["filePath"],
	},
	annotations: {
		title: "📊 Get Risk Score",
		readOnlyHint: true,
		destructiveHint: false,
		idempotentHint: true,
	},
};

export async function handleGetRiskScore(args: Record<string, unknown>, context: ToolContext): Promise<ToolResult> {
	// Security: Validate and sanitize all user inputs
	const validation = validateGetRiskScoreParams(args);
	if (!validation.success) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Input validation failed:\n${validation.errors?.join("\n") ?? "Unknown validation error"}`,
				},
			],
			isError: true,
		};
	}

	const input = validation.data as GetRiskScoreArgs;
	const workspaceRoot = getWorkspaceRoot(context);

	// Get content from disk if not provided
	const content = input.content ?? readFileContent(input.filePath, workspaceRoot);
	if (!content) {
		return {
			content: [{ type: "text", text: `📊|R|error:file_not_found|path:${input.filePath}` }],
			isError: true,
		};
	}

	const language = detectLanguage(input.filePath);

	// Get integration orchestrator
	const integrations = context.services?.integrations ?? getIntegrationOrchestratorService();

	// Gather context
	const enriched = await integrations.enrichContext({
		files: [{ path: input.filePath, content, language }],
		intent: "review",
		skipCache: false,
	});

	// Build aggregated context and get quick assessment
	const aggregatedContext = enrichedToAggregated(input.filePath, enriched);
	const quickResult = await quickAssessRiskViaDaemon(workspaceRoot, aggregatedContext.riskFactors || []);

	if (!quickResult.success || !quickResult.assessment) {
		return {
			content: [{ type: "text", text: `📊|R|error:${quickResult.error}|path:${input.filePath}` }],
			isError: true,
		};
	}

	const quickAssessment = quickResult.assessment;

	// Build wire format
	const wire = [
		"📊",
		"R",
		`score:${quickAssessment.score}`,
		`level:${quickAssessment.level}`,
		`rec:${quickAssessment.recommendation}`,
	].join("|");

	// Build factor summary
	let factorSummary = "";
	if ((aggregatedContext.riskFactors || []).length > 0) {
		factorSummary = "\n\nRisk Factors:\n";
		for (const factor of (aggregatedContext.riskFactors || []).slice(0, 5)) {
			const sign = factor.score >= 0 ? "+" : "";
			factorSummary += `  • [${factor.source}] ${factor.description} (${sign}${factor.score})\n`;
		}
	}

	const summary = `Score: ${quickAssessment.score}/100 (${quickAssessment.level})
Recommendation: ${quickAssessment.recommendation}
Sources: ${enriched?.sources.join(", ") ?? "local only"}${factorSummary}`;

	// Build structured content
	const structuredContent: Record<string, unknown> = {
		score: quickAssessment.score,
		level: quickAssessment.level,
		recommendation: quickAssessment.recommendation,
		factors: (aggregatedContext.riskFactors || []).map((f) => ({
			name: f.name,
			score: f.score,
			source: f.source,
			description: f.description,
		})),
		sources: enriched?.sources ?? [],
	};

	return {
		content: [{ type: "text", text: `${wire}\n---\n${summary}` }],
		structuredContent,
	};
}

