export const queryPatternsTool: VrekoTool = {
	name: "vreko_query_patterns",
	description: `[DEPRECATED] 🔎 Query behavioral patterns from Vreko's learning system.

**When to use:**
- To find common mistakes in a file or area
- To understand what patterns lead to rollbacks
- To get recommendations based on historical data

**Wire Response:**
🔎|P|results:5|top:high_churn_file|score:15

**Parameters:**
- query: Natural language query about patterns (required)
- filePath: Scope query to specific file
- timeRange: Time range for analysis (7d, 30d, 90d)
- limit: Maximum results to return (default: 10)

**Returns:** Matching patterns with relevance scores`,
	inputSchema: {
		type: "object",
		properties: {
			query: {
				type: "string",
				description: "Natural language query about code patterns",
			},
			filePath: {
				type: "string",
				description: "Scope query to specific file",
			},
			timeRange: {
				type: "string",
				enum: ["7d", "30d", "90d"],
				description: "Time range for pattern analysis",
			},
			limit: {
				type: "number",
				description: "Maximum results to return (default: 10)",
			},
		},
		required: ["query"],
	},
	annotations: {
		title: "🔎 Query Patterns",
		readOnlyHint: true,
		destructiveHint: false,
		idempotentHint: true,
	},
};

export async function handleQueryPatterns(args: Record<string, unknown>, context: ToolContext): Promise<ToolResult> {
	// Security: Validate and sanitize all user inputs
	const validation = validateQueryPatternsParams(args);
	if (!validation.success) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Input validation failed:\n${validation.errors?.join("\n") ?? "Unknown validation error"}`,
				},
			],
			isError: true,
		};
	}

	const input = validation.data as QueryPatternsArgs;
	const workspaceRoot = getWorkspaceRoot(context);
	const timeRange = input.timeRange ?? "30d";
	const limit = input.limit ?? 10;

	// Build query
	const query: PatternQueryViaDaemon = {
		search: input.query,
		filePath: input.filePath,
		limit,
		sortBy: "relevance",
		sortOrder: "desc",
	};

	// Add time range filter
	const timeRangeMs = getTimeRangeMs(timeRange);
	query.dateFrom = Date.now() - timeRangeMs;

	// Execute search via daemon IPC
	const queryResult = await queryPatternsViaDaemon(workspaceRoot, query);

	if (!queryResult.success || !queryResult.results) {
		return {
			content: [{ type: "text", text: `🔎|P|error:${queryResult.error}|query:${input.query}` }],
			isError: true,
		};
	}

	const results = queryResult.results;

	// Get recommendations based on context
	const recResult = await recommendPatternsViaDaemon(workspaceRoot, {
		filePath: input.filePath,
		keywords: input.query
			.toLowerCase()
			.split(/\s+/)
			.filter((w) => w.length > 3),
	});

	const recommendations = recResult.success ? (recResult.recommendations ?? []) : [];

	// Get violation stats from query result
	const violationStats = queryResult.violationStats ?? { total: 0, topViolations: [] };

	// Build wire format
	const topResult = results[0];
	const wire = [
		"🔎",
		"P",
		`results:${results.length}`,
		topResult ? `top:${topResult.pattern.name}` : "top:none",
		topResult ? `score:${topResult.pattern.score}` : "score:0",
	].join("|");

	// Build summary
	let summary = `Found ${results.length} pattern(s) matching "${input.query}"\n`;
	summary += `Time range: ${timeRange}\n\n`;

	if (results.length > 0) {
		summary += "**Matching Patterns:**\n";
		for (const result of results.slice(0, 5)) {
			summary += `  • [${result.pattern.source}] ${result.pattern.name}: ${result.pattern.description} (score: ${result.pattern.score}, seen: ${result.usageCount}x)\n`;
		}
	}

	if (recommendations.length > 0) {
		summary += "\n**Recommendations:**\n";
		for (const rec of recommendations.slice(0, 3)) {
			summary += `  • ${rec.pattern.name}: ${rec.reason} (confidence: ${Math.round(rec.confidence * 100)}%)\n`;
		}
	}

	if (violationStats.total > 0) {
		summary += `\n**Violation Stats:** ${violationStats.total} total violations tracked\n`;
	}

	// Build structured content
	const structuredContent: Record<string, unknown> = {
		results: results.map((r) => ({
			pattern: {
				name: r.pattern.name,
				score: r.pattern.score,
				source: r.pattern.source,
				description: r.pattern.description,
			},
			relevance: r.relevance,
			usageCount: r.usageCount,
		})),
		recommendations: recommendations.map((r) => ({
			pattern: r.pattern.name,
			reason: r.reason,
			confidence: r.confidence,
		})),
		violationStats: {
			total: violationStats.total,
			topViolations: violationStats.topViolations.slice(0, 5),
		},
	};

	return {
		content: [{ type: "text", text: `${wire}\n---\n${summary}` }],
		structuredContent,
	};
}

