export const getContextTool: VrekoTool = {
	name: "vreko_get_context",
	description: `[DEPRECATED] 📋 Get aggregated context for a file from all available sources.

**When to use:**
- To understand full context before making changes
- To check what external data is available for a file
- To see GitHub history, docs validation, and error data

**Wire Response:**
📋|C|sources:github,sentry|factors:4|duration:234ms

**Parameters:**
- filePath: Path to the file (required)
- sources: Which sources to include (github, context7, sentry)

**Returns:** Context from GitHub, Context7, and Sentry with risk factors`,
	inputSchema: {
		type: "object",
		properties: {
			filePath: {
				type: "string",
				description: "Path to the file",
			},
			sources: {
				type: "array",
				items: { type: "string", enum: ["github", "context7", "sentry"] },
				description: "Which context sources to include",
			},
		},
		required: ["filePath"],
	},
	annotations: {
		title: "📋 Get Context",
		readOnlyHint: true,
		destructiveHint: false,
		idempotentHint: true,
	},
};

export async function handleGetContext(args: Record<string, unknown>, context: ToolContext): Promise<ToolResult> {
	// Security: Validate and sanitize all user inputs
	const validation = validateGetContextParams(args);
	if (!validation.success) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Input validation failed:\n${validation.errors?.join("\n") ?? "Unknown validation error"}`,
				},
			],
			isError: true,
		};
	}

	const input = validation.data as GetContextArgs;
	const workspaceRoot = getWorkspaceRoot(context);

	// Read file content for Context7 validation
	const content = readFileContent(input.filePath, workspaceRoot);
	const language = detectLanguage(input.filePath);

	// Get integration orchestrator
	const integrations = context.services?.integrations ?? getIntegrationOrchestratorService();

	// Check health
	const health = integrations.getHealth();

	// Gather context
	const startTime = Date.now();
	const enriched = await integrations.enrichContext({
		files: content ? [{ path: input.filePath, content, language }] : [input.filePath],
		intent: "explore",
		skipCache: false,
	});
	const duration = Date.now() - startTime;

	// Filter sources if specified
	let filteredSources = enriched?.sources ?? [];
	if (input.sources && input.sources.length > 0) {
		filteredSources = filteredSources.filter((s) => input.sources?.includes(s as "github" | "context7" | "sentry"));
	}

	// Build wire format
	const wire = [
		"📋",
		"C",
		`sources:${filteredSources.length > 0 ? filteredSources.join(",") : "none"}`,
		`factors:${enriched?.riskFactors.length ?? 0}`,
		`duration:${duration}ms`,
	].join("|");

	// Build summary
	let summary = `Context for: ${input.filePath}\n`;
	summary += `Duration: ${duration}ms\n`;
	summary += `Health: ${health.status}\n\n`;

	summary += "**Integration Status:**\n";
	for (const [name, status] of Object.entries(health.integrations)) {
		const icon = status.connected && !status.circuitOpen ? "✓" : status.enabled ? "○" : "✗";
		summary += `  ${icon} ${name}: ${status.connected ? "connected" : status.enabled ? "not connected" : "disabled"}`;
		if (status.circuitOpen) {
			summary += " (circuit open)";
		}
		summary += "\n";
	}

	if (enriched) {
		const fileContext = enriched.contexts.get(input.filePath);
		if (fileContext) {
			summary += "\n**Sources Contributing:**\n";
			if (fileContext.sources.github) {
				const gh = fileContext.sources.github;
				summary += `  • GitHub: ${gh.recentCommits?.length ?? 0} commits, ${gh.changeFrequency ?? "unknown"} frequency\n`;
			}
			if (fileContext.sources.context7) {
				const c7 = fileContext.sources.context7;
				summary += `  • Context7: ${c7.imports?.length ?? 0} imports validated\n`;
			}
			if (fileContext.sources.sentry) {
				const sn = fileContext.sources.sentry;
				summary += `  • Sentry: ${sn.errors?.length ?? 0} errors, trend: ${sn.errorTrend ?? "unknown"}\n`;
			}
		}

		if ((enriched.riskFactors || []).length > 0) {
			summary += "\n**Risk Factors:**\n";
			for (const factor of (enriched.riskFactors || []).slice(0, 5)) {
				summary += `  • [${factor.source}] ${factor.description}\n`;
			}
		}
	}

	// Build structured content
	const structuredContent: Record<string, unknown> = {
		file: input.filePath,
		duration,
		health,
		sources: filteredSources,
		riskScore: enriched?.riskScore ?? 50,
		riskFactors: enriched?.riskFactors ?? [],
		contexts: enriched
			? Object.fromEntries(enriched.contexts)
			: {
					/* intentionally empty */
				},
	};

	return {
		content: [{ type: "text", text: `${wire}\n---\n${summary}` }],
		structuredContent,
	};
}

