/**
 * Proactive Alert Types
 *
 * Schema for proactive alerts in enriched tool responses.
 * Implements PROACTIVE_VREKO_SPEC.md specifications.
 *
 * @module types/alerts
 */

// =============================================================================
// Alert Category Types
// =============================================================================

/**
 * Alert categories for proactive notifications
 *
 * Each category maps to specific detection logic and suggested actions
 */
export type AlertCategory =
	| "high_risk_file" // Entering file with history of issues
	| "pressure_threshold" // Unsnapshot changes accumulating
	| "velocity_alert" // Development velocity insights (vibe-coding aware)
	| "violation_recurrence" // Same mistake as before
	| "critical_file_touch" // Editing .env, secrets, core auth
	| "stale_snapshot" // Coverage degrading
	| "ai_temperature" // High AI activity percentage
	| "phantom_dependency" // Undeclared import detected
	| "architecture_violation"; // Cross-layer import

/**
 * Alert severity levels
 */
export type AlertSeverity = "info" | "warning" | "critical";

// =============================================================================
// Velocity Monitoring (Vibe-Coding Aware)
// =============================================================================

/**
 * Edit velocity classification
 *
 * Instead of "loop detection," we classify edit patterns to distinguish
 * legitimate iterative development ("vibe coding") from stuck patterns.
 */
export type VelocityClassification = "iteration" | "exploration" | "refinement" | "stuck" | "testing";

/**
 * Velocity monitoring result
 */
export interface VelocityMonitoringResult {
	/** Classification of current edit pattern */
	classification: VelocityClassification;
	/** Confidence in classification (0-100) */
	confidence: number;
	/** Indicators that led to this classification */
	indicators: string[];
	/** Context-aware message (only for 'stuck' with high confidence) */
	message?: string;
}

// =============================================================================
// Pressure Calculation
// =============================================================================

/**
 * Session metrics for pressure calculation
 */
export interface SessionMetrics {
	/** Lines changed since last snapshot */
	linesChanged: number;
	/** Minutes since last snapshot */
	minutesSinceSnapshot: number;
	/** Percentage of changes made by AI */
	aiGeneratedPercentage: number;
	/** Average violation history of touched files (0-100) */
	averageFileRiskScore: number;
}

/**
 * Pressure calculation result
 */
export interface PressureResult {
	/** Calculated pressure value (0-100) */
	value: number;
	/** Pressure level classification */
	level: "low" | "moderate" | "elevated" | "critical";
	/** Whether snapshot is recommended */
	snapshotRecommended: boolean;
	/** Breakdown of contributing factors */
	breakdown: {
		changes: number;
		time: number;
		aiActivity: number;
		fileRisk: number;
	};
}

/**
 * Calculate pressure from session metrics
 *
 * Formula: weighted sum of risk factors
 * - 40% unsnapshotted changes
 * - 20% time since snapshot
 * - 20% AI activity rate
 * - 20% file risk score
 */
export function calculatePressure(metrics: SessionMetrics): PressureResult {
	const weights = { changes: 0.4, time: 0.2, aiActivity: 0.2, fileRisk: 0.2 };

	// Unsnapshotted changes: 0-100 based on lines changed (500 lines = 100%)
	const changeScore = Math.min(100, (metrics.linesChanged / 500) * 100);

	// Time decay: increases 10 points per 10 minutes without snapshot
	const timeScore = Math.min(100, (metrics.minutesSinceSnapshot / 10) * 10);

	// AI activity: percentage of changes made by AI
	const aiScore = metrics.aiGeneratedPercentage;

	// File risk: average violation history of touched files
	const riskScore = metrics.averageFileRiskScore;

	const value = Math.round(
		changeScore * weights.changes +
			timeScore * weights.time +
			aiScore * weights.aiActivity +
			riskScore * weights.fileRisk,
	);

	// Determine level from value
	let level: PressureResult["level"];
	if (value <= 40) {
		level = "low";
	} else if (value <= 70) {
		level = "moderate";
	} else if (value <= 85) {
		level = "elevated";
	} else {
		level = "critical";
	}

	return {
		value,
		level,
		snapshotRecommended: value > 70,
		breakdown: {
			changes: Math.round(changeScore * weights.changes),
			time: Math.round(timeScore * weights.time),
			aiActivity: Math.round(aiScore * weights.aiActivity),
			fileRisk: Math.round(riskScore * weights.fileRisk),
		},
	};
}

// =============================================================================
// Proactive Alert Schema
// =============================================================================

/**
 * Proactive alert structure
 *
 * Alerts are included in tool responses to provide context-aware
 * guidance without explicit tool calls.
 */
export interface ProactiveAlert {
	/** Unique alert identifier */
	id: string;
	/** When the alert was generated */
	timestamp: number;
	/** Alert severity level */
	severity: AlertSeverity;
	/** Alert category for grouping/filtering */
	category: AlertCategory;
	/** One-line summary (always shown) */
	summary: string;
	/** Expanded details (shown on request) */
	details?: string;
	/** Recommended action */
	suggested_action?: string;
	/** Related learning ID (if applicable) */
	learning_id?: string;
	/** Confidence in alert (0-100), only show if > 80 */
	confidence: number;
	/** Whether user can dismiss this alert type */
	dismissible: boolean;
	/** Auto-dismiss timestamp (optional) */
	expires_at?: number;
}

// =============================================================================
// Enhanced Response Types
// =============================================================================

/**
 * Session health summary for tool responses
 */
export interface SessionHealth {
	/** Current pulse level */
	pulse: "resting" | "elevated" | "racing" | "critical";
	/** Pressure value (0-100) */
	pressure: number;
	/** Session trajectory */
	trajectory: "stable" | "escalating" | "critical" | "recovering";
	/** Whether snapshot is recommended */
	snapshotRecommended: boolean;
	/** Number of dirty (uncommitted) files */
	dirtyFiles: number;
	/** Optional hint based on state */
	hint?: string;
}

/**
 * Check-back trigger for proactive follow-up
 */
export type CheckBackTrigger = "before_file_edit" | "after_test_run" | "after_save" | "in_5_minutes";

/**
 * Related learning reference
 */
export interface RelatedLearning {
	/** Learning ID */
	id: string;
	/** Learning trigger (when to apply) */
	trigger: string;
	/** Learning action (what to do) */
	action: string;
	/** Learning type */
	type: "pattern" | "pitfall" | "efficiency" | "discovery" | "workflow";
	/** Relevance score (0-100) */
	relevance: number;
}

/**
 * Enhanced tool response with proactive fields
 *
 * All MCP tool responses should include these fields for AI agent context.
 */
export interface EnhancedToolResponse<T = unknown> {
	/** Standard response status */
	status: "ok" | "error";
	/** Response data (varies by tool) */
	data: T;

	// === Proactive Fields ===

	/** Proactive alerts queued from daemon */
	proactive_alerts?: ProactiveAlert[];
	/** Suggested next action */
	next_action?: string;
	/** When to check back for updates */
	check_back_trigger?: CheckBackTrigger;
	/** Relevant learnings for current context */
	relevant_learnings?: RelatedLearning[];

	// === Session Context (always included) ===

	/**
	 * Current session health snapshot
	 * @internal For MCP internal use only - not part of public API
	 */
	_sessionHealth?: SessionHealth;
}

// =============================================================================
// Alert Queue Types (for daemon)
// =============================================================================

/**
 * Alert queue entry (stored in .vreko/alerts.jsonl)
 */
export interface AlertQueueEntry extends ProactiveAlert {
	/** Whether this alert has been delivered to MCP */
	delivered: boolean;
	/** Delivery timestamp (if delivered) */
	delivered_at?: number;
	/** Whether user acted on this alert */
	acted_upon?: boolean;
}

/**
 * Alert dismissal preferences (stored in .vreko/alerts-dismissed.json)
 */
export interface AlertDismissalPreferences {
	/** Categories the user has dismissed */
	dismissed_categories: AlertCategory[];
	/** Specific alert IDs dismissed */
	dismissed_ids: string[];
	/** Global dismissal timestamp (for backoff) */
	last_dismissal_at?: number;
	/** Number of dismissals in current session */
	dismissal_count: number;
}

/**
 * Alert rate limiting configuration
 */
export interface AlertRateLimiter {
	/** Maximum alerts per session */
	max_per_session: number;
	/** Minimum interval between alerts (ms) */
	min_interval_ms: number;
	/** Confidence threshold for showing alerts */
	confidence_threshold: number;
	/** Preferred natural breakpoints for alerts */
	natural_breakpoints: Array<"after_test_run" | "after_save" | "before_commit" | "after_long_pause">;
	/** Whether to increase interval after dismissals */
	backoff_on_dismiss: boolean;
}

/**
 * Default rate limiter configuration
 */
export const DEFAULT_RATE_LIMITER: AlertRateLimiter = {
	max_per_session: 3,
	min_interval_ms: 60000, // 1 minute
	confidence_threshold: 80,
	natural_breakpoints: ["after_test_run", "after_save", "before_commit", "after_long_pause"],
	backoff_on_dismiss: true,
};

// =============================================================================
// Telemetry Event Types
// =============================================================================

/**
 * Alert telemetry event: alert was shown to user/AI
 */
export interface AlertShownEvent {
	alert_id: string;
	category: AlertCategory;
	severity: AlertSeverity;
	confidence: number;
	delivery_method: "enriched_response" | "notification" | "sampling";
}

/**
 * Alert telemetry event: user/AI acted on alert
 */
export interface AlertActedEvent {
	alert_id: string;
	category: AlertCategory;
	action_taken: "snapshot_created" | "rollback" | "learning_captured" | "file_fixed" | "dismissed" | "ignored";
	time_to_action_ms: number;
}

/**
 * Alert telemetry event: alert was dismissed
 */
export interface AlertDismissedEvent {
	alert_id: string;
	category: AlertCategory;
	dismiss_type: "single" | "category" | "session";
}
