export type QueryComplexity = "low" | "medium" | "high";

export interface RetrievalStrategy {
	semanticWeight: number;
	keywordWeight: number;
	method: string;
	topK?: number;
	shouldRetrieve?: boolean;
	useExpansion?: boolean;
	useReranking?: boolean;
}

export interface QueryClassification {
	type: string;
	complexity: QueryComplexity;
	confidence: number;
	weights: { semantic: number; keyword: number };
	reason: string;
}

export interface ChunkInfo {
	id: string;
	chunk_text: string;
	source_id: string;
	source_type?: "pattern" | "violation" | "learning" | "adr";
	authority?: string;
	status?: string;
	created_at?: string;
	updated_at?: string;
	metadata?: Record<string, unknown>;
}

export interface RetrievalResult {
	id: string;
	text: string;
	source: string;
	score: number;
	chunk: ChunkInfo;
	confidence: number;
	sources: string[];
	metadata?: Record<string, unknown>;
}

export interface HistoricalSignals {
	successRate?: number;
	avgLatency?: number;
	usageCount?: number;
}

// Local implementations of query classification (previously from @vreko/intelligence)
function classifyQueryLocal(query: string): QueryClassification {
	const _length = query.length;
	const hasSpecialChars = /[<>{}[\]()]/.test(query);
	const hasMultipleTerms = query.split(/\s+/).length > 3;

	if (hasSpecialChars) {
		return {
			type: "factual",
			complexity: "high",
			confidence: 0.8,
			weights: { semantic: 0.3, keyword: 0.7 },
			reason: "Special characters detected, likely factual lookup",
		};
	}
	if (hasMultipleTerms) {
		return {
			type: "conceptual",
			complexity: "medium",
			confidence: 0.7,
			weights: { semantic: 0.7, keyword: 0.3 },
			reason: "Multiple terms, likely conceptual query",
		};
	}
	return {
		type: "exploratory",
		complexity: "low",
		confidence: 0.6,
		weights: { semantic: 0.5, keyword: 0.5 },
		reason: "Simple query, using balanced weights",
	};
}

function getRetrievalStrategyLocal(classification: { type: string; confidence: number }): RetrievalStrategy {
	if (classification.type === "factual") {
		return { semanticWeight: 0.3, keywordWeight: 0.7, method: "keyword-biased" };
	}
	if (classification.type === "conceptual") {
		return { semanticWeight: 0.7, keywordWeight: 0.3, method: "semantic-biased" };
	}
	return { semanticWeight: 0.5, keywordWeight: 0.5, method: "balanced" };
}

function getConfidenceLevelLocal(confidence: number): "high" | "medium" | "low" {
	if (confidence >= 0.8) {
		return "high";
	}
	if (confidence >= 0.5) {
		return "medium";
	}
	return "low";
}

function expandQueryLocal(query: string): string[] {
	// Simple query expansion
	const terms = query.split(/\s+/);
	return [query, ...terms.map((t) => t.toLowerCase())];
}

function calculateMetadataBoostLocal(metadata: Record<string, unknown>): number {
	return metadata?.priority === "high" ? 0.1 : 0;
}

function calculateRerankingScoreLocal(result: { score: number; metadata?: Record<string, unknown> }): number {
	const metadataBoost = calculateMetadataBoostLocal(result.metadata || {});
	return result.score + metadataBoost;
}

function cosineSimilarityLocal(a: number[], b: number[]): number {
	if (a.length !== b.length) {
		return 0;
	}
	let dot = 0;
	let normA = 0;
	let normB = 0;
	for (let i = 0; i < a.length; i++) {
		dot += a[i] * b[i];
		normA += a[i] * a[i];
		normB += b[i] * b[i];
	}
	return dot / (Math.sqrt(normA) * Math.sqrt(normB) || 1);
}

// Export with expected names
const classifyQuery = classifyQueryLocal;
const _getRetrievalStrategy = getRetrievalStrategyLocal;
const getConfidenceLevel = getConfidenceLevelLocal;
const _expandQuery = expandQueryLocal;
const calculateMetadataBoost = calculateMetadataBoostLocal;
const calculateRerankingScore = calculateRerankingScoreLocal;
const cosineSimilarity = cosineSimilarityLocal;

