/**
 * Minimum classification confidence to use adaptive weights
 * Below this, fall back to balanced weights (0.5/0.5)
 */
const MIN_CLASSIFICATION_CONFIDENCE = 0.5;

/**
 * Cache TTL in milliseconds (5 minutes)
 * After this, retriever will be recreated on next use
 */
const CACHE_TTL_MS = 5 * 60 * 1000;

/**
 * Maximum candidates to consider for reranking
 * Reranking is expensive, so we limit candidates
 */
const RERANK_CANDIDATE_LIMIT = 15;

/**
 * Intent-based boost factors for domain matching
 * P1: Makes retrieval intent-aware
 */
const INTENT_BOOST_FACTOR = 0.2; // 20% boost for domain match

/**
 * Intent → domain keywords for boost matching
 */
const INTENT_DOMAIN_KEYWORDS: Record<TaskIntent, string[]> = {
	implement: ["architecture", "pattern", "structure", "design", "implementation", "feature"],
	debug: ["error", "bug", "fix", "issue", "problem", "anti-pattern", "pitfall", "test"],
	refactor: ["workflow", "refactor", "clean", "extract", "move", "rename", "consolidate"],
	review: ["review", "check", "audit", "verify", "pattern", "test"],
	explore: ["context", "workflow", "understand", "how", "where", "what"],
};

