interface CachedRetriever {
	workspaceRoot: string;
	createdAt: number;
	indexed: boolean;
}

// Cache of retriever state per workspace (daemon manages actual retrievers)
const retrievers = new Map<string, CachedRetriever>();

// Track whether workspace has been indexed
const indexedWorkspaces = new Set<string>();

// =============================================================================
// PUBLIC API
// =============================================================================

/**
 * Get or create a HybridRetriever for a workspace
 *
 * @param workspaceRoot - Absolute path to workspace root
 * @returns HybridRetriever instance configured for the workspace
 *
 * DEPRECATED (Day 4): Returns a proxy that delegates to daemon IPC.
 */
export function getHybridRetriever(workspaceRoot: string): {
	retrieve: (
		query: string,
		options?: { intent?: string; keywords?: string[]; limit?: number },
	) => Promise<RetrievalResult[]>;
	retrieveAdaptive: (
		query: string,
		options?: { intent?: string; keywords?: string[]; limit?: number },
	) => Promise<{ results: RetrievalResult[]; classification: QueryClassification; stats: Record<string, unknown> }>;
	close: () => void;
} {
	const cached = retrievers.get(workspaceRoot);

	// Check if cache is still valid
	if (cached && Date.now() - cached.createdAt < CACHE_TTL_MS) {
		// Return proxy that delegates to daemon
		return createRetrieverProxy(workspaceRoot);
	}

	// Update cache
	retrievers.set(workspaceRoot, {
		workspaceRoot,
		createdAt: Date.now(),
		indexed: indexedWorkspaces.has(workspaceRoot),
	});

	return createRetrieverProxy(workspaceRoot);
}

/**
 * Create a retriever proxy that delegates to daemon IPC
 */
function createRetrieverProxy(workspaceRoot: string): {
	retrieve: (
		query: string,
		options?: { intent?: string; keywords?: string[]; limit?: number },
	) => Promise<RetrievalResult[]>;
	retrieveAdaptive: (
		query: string,
		options?: { intent?: string; keywords?: string[]; limit?: number },
	) => Promise<{ results: RetrievalResult[]; classification: QueryClassification; stats: Record<string, unknown> }>;
	close: () => void;
} {
	return {
		retrieve: async (query: string, options?: { intent?: string; keywords?: string[]; limit?: number }) => {
			const result = await hybridRetrieveViaDaemon(workspaceRoot, query, options);
			if (!result.success || !result.results) {
				return [];
			}
			return result.results.map((r) => ({
				id: r.id,
				text: r.text,
				source: r.source,
				score: r.score,
				chunk: { id: r.id, chunk_text: r.text, source_id: r.source, metadata: r.metadata },
				confidence: r.score,
				sources: [r.source],
				metadata: r.metadata,
			}));
		},
		retrieveAdaptive: async (query: string, options?: { intent?: string; keywords?: string[]; limit?: number }) => {
			const classification = classifyQueryLocal(query);
			const result = await hybridRetrieveViaDaemon(workspaceRoot, query, {
				...options,
				semanticWeight: classification.weights.semantic,
				keywordWeight: classification.weights.keyword,
			});
			const results: RetrievalResult[] = [];
			if (result.success && result.results) {
				for (const r of result.results) {
					results.push({
						id: r.id,
						text: r.text,
						source: r.source,
						score: r.score,
						chunk: { id: r.id, chunk_text: r.text, source_id: r.source, metadata: r.metadata },
						confidence: r.score,
						sources: [r.source],
						metadata: r.metadata,
					});
				}
			}
			return {
				results,
				classification,
				stats: result.metrics || {},
			};
		},
		close: () => {
			// Daemon manages resources
		},
	};
}

/**
 * Retrieve learnings using adaptive hybrid search
 *
 * Classifies the query to determine optimal semantic vs keyword weights:
 * - Factual queries (specific lookups): keyword=0.7, semantic=0.3
 * - Conceptual queries (understanding): semantic=0.7, keyword=0.3
 * - Exploratory queries (browsing): balanced 0.5/0.5
 *
 * P1 ENHANCEMENT: Now accepts optional intent parameter for domain boosting.
 *
 * Includes fallback behaviors:
 * - Low confidence classification → balanced weights
 * - Embeddings unavailable → keyword-only search
 * - Empty KnowledgeStore → auto-index learnings first
 *
 * @param workspaceRoot - Workspace root path
 * @param query - Search query (task description or keywords)
 * @param options - Optional retrieval options including intent
 * @returns Retrieval results with classification metadata
 */
export async function retrieveAdaptive(
	workspaceRoot: string,
	query: string,
	options?: {
		/** P1: Task intent for domain-specific boosting */
		intent?: TaskIntent;
		/** Packages context for cache key generation */
		packages?: string[];
	},
): Promise<{
	results: RetrievalResult[];
	classification: QueryClassification;
	stats: {
		semanticCandidates: number;
		keywordCandidates: number;
		fusedCount: number;
		latencyMs: number;
		fallbackUsed?: "keyword-only" | "balanced-weights";
		indexingPerformed?: boolean;
		/** P1: Intent used for boosting */
		intentUsed?: TaskIntent;
		intentBoostedCount?: number;
		/** NEW: Cache hit indicator */
		cacheHit?: boolean;
	};
}> {
	// DOGFOODING: Wrap entire retrieval in pattern cache
	return withPatternCache(
		{
			query,
			intent: options?.intent,
			packages: options?.packages,
		},
		async (): Promise<{
			results: RetrievalResult[];
			classification: QueryClassification;
			stats: {
				semanticCandidates: number;
				keywordCandidates: number;
				fusedCount: number;
				latencyMs: number;
				fallbackUsed?: "keyword-only" | "balanced-weights";
				indexingPerformed?: boolean;
				intentUsed?: TaskIntent;
				intentBoostedCount?: number;
			};
		}> => {
			const startTime = performance.now();

			// Step 0: Auto-index learnings if not done yet
			let indexingPerformed = false;
			if (!indexedWorkspaces.has(workspaceRoot)) {
				try {
					const indexResult = await indexAllLearnings(workspaceRoot, {
						skipEmbeddings: !isEmbeddingsAvailable(),
					});
					indexedWorkspaces.add(workspaceRoot);
					indexingPerformed = indexResult.indexed > 0;

					if (indexingPerformed) {
						// Intentionally empty: indexing success noted, no further action needed
					}
				} catch (_error) {
					// Intentionally ignored: learning indexing failure is non-fatal for retrieval
				}
			}

			// Step 1: Classify the query
			const classification = classifyQuery(query);

			// Step 2: Determine if we should use adaptive weights
			let fallbackUsed: "keyword-only" | "balanced-weights" | undefined;

			// Check if embeddings are available for semantic search
			const embeddingsAvailable = isEmbeddingsAvailable();

			if (!embeddingsAvailable) {
				// Fallback to keyword-only search
				fallbackUsed = "keyword-only";
				return keywordOnlySearch(workspaceRoot, query, classification, startTime, {
					fallbackUsed,
					indexingPerformed,
				});
			}

			// Check classification confidence
			if (classification.confidence < MIN_CLASSIFICATION_CONFIDENCE) {
				// Low confidence - use balanced weights instead of adaptive
				fallbackUsed = "balanced-weights";
				// Override weights to balanced
				classification.weights = { semantic: 0.5, keyword: 0.5 };
			}

			// Step 3: Run adaptive retrieval
			try {
				const retriever = getHybridRetriever(workspaceRoot);
				const result = await retriever.retrieveAdaptive(query);

				// P1: Apply intent-based boosting
				let boostedResults = result.results;
				let intentBoostedCount = 0;
				const intent = options?.intent;

				if (intent) {
					const { results: boosted, boostedCount } = applyIntentBoost(result.results, intent);
					boostedResults = boosted;
					intentBoostedCount = boostedCount;
				}

				return {
					results: boostedResults,
					classification:
						fallbackUsed === "balanced-weights"
							? { ...result.classification, weights: { semantic: 0.5, keyword: 0.5 } }
							: result.classification,
					stats: {
						semanticCandidates: (result.stats as { semanticCandidates?: number }).semanticCandidates || 0,
						keywordCandidates: (result.stats as { keywordCandidates?: number }).keywordCandidates || 0,
						fusedCount: boostedResults.length,
						latencyMs: performance.now() - startTime,
						fallbackUsed,
						indexingPerformed,
						intentUsed: intent,
						intentBoostedCount,
					},
				};
			} catch (_error) {
				return keywordOnlySearch(workspaceRoot, query, classification, startTime, {
					fallbackUsed: "keyword-only",
					indexingPerformed,
					intent: options?.intent,
				});
			}
		},
	);
}

/**
 * Keyword-only search fallback
 *
 * Used when:
 * - Embeddings model is not loaded
 * - Hybrid retrieval fails
 * - Explicit request for keyword search
 */
async function keywordOnlySearch(
	workspaceRoot: string,
	query: string,
	classification: QueryClassification,
	startTime: number,
	metadata: {
		fallbackUsed: "keyword-only" | "balanced-weights";
		indexingPerformed: boolean;
		intent?: TaskIntent;
	},
): Promise<{
	results: RetrievalResult[];
	classification: QueryClassification;
	stats: {
		semanticCandidates: number;
		keywordCandidates: number;
		fusedCount: number;
		latencyMs: number;
		fallbackUsed?: "keyword-only" | "balanced-weights";
		indexingPerformed?: boolean;
		intentUsed?: TaskIntent;
		intentBoostedCount?: number;
	};
}> {
	// Use daemon IPC for keyword search (Day 4: daemon-first)
	const daemonResult = await searchKnowledgeViaDaemon(workspaceRoot, query, 10);
	const elapsed = performance.now() - startTime;

	// Convert to RetrievalResult format
	let results: RetrievalResult[] = [];
	if (daemonResult.success && daemonResult.chunks) {
		results = daemonResult.chunks.map((chunk, index) => ({
			id: chunk.id,
			text: chunk.chunk_text,
			source: chunk.source_id,
			chunk: {
				id: chunk.id,
				chunk_text: chunk.chunk_text,
				source_id: chunk.source_id,
				metadata: chunk.metadata,
			},
			score: 1 / (60 + index + 1), // RRF-style score
			confidence: 0.5 + 0.3 * (1 - index / (daemonResult.chunks?.length || 1)), // Decreasing confidence
			sources: [chunk.source_id],
			metadata: chunk.metadata,
		}));
	}

	// P1: Apply intent-based boosting
	let intentBoostedCount = 0;
	if (metadata.intent) {
		const { results: boosted, boostedCount } = applyIntentBoost(results, metadata.intent);
		results = boosted;
		intentBoostedCount = boostedCount;
	}

	return {
		results,
		classification: {
			...classification,
			weights: { semantic: 0, keyword: 1 }, // Keyword-only
			reason: "Fallback to keyword-only via daemon",
		},
		stats: {
			semanticCandidates: 0,
			keywordCandidates: results.length,
			fusedCount: results.length,
			latencyMs: elapsed,
			fallbackUsed: metadata.fallbackUsed,
			indexingPerformed: metadata.indexingPerformed,
			intentUsed: metadata.intent,
			intentBoostedCount,
		},
	};
}

/**
 * Pre-classify a query without retrieving
 * Useful for understanding what retrieval strategy will be used
 *
 * @param query - Query to classify
 * @returns Classification with type, confidence, and weights
 */
export function classifyQueryType(query: string): QueryClassification {
	return classifyQuery(query);
}

/**
 * Initialize hybrid retrieval for a workspace
 *
 * Call during server startup for optimal first-query performance:
 * 1. Preloads embeddings model (unless fast mode is enabled)
 * 2. Indexes existing learnings (unless fast mode is enabled)
 * 3. Warms up the retriever cache
 *
 * Fast Mode (VREKO_MCP_FAST_MODE=true):
 * - Skips embeddings preloading (loads lazily on first query)
 * - Skips learnings indexing (done on first retrieval)
 * - Defers all heavy work until actually needed
 * - Use when MCP client timeout is a concern
 *
 * @param workspaceRoot - Workspace root path
 */
export async function initializeHybridRetrieval(workspaceRoot: string): Promise<{
	embeddingsReady: boolean;
	indexingResult: IngestionResult;
}> {
	// Check for fast mode - skip all heavy initialization
	const fastModeEnv = process.env.VREKO_MCP_FAST_MODE;
	const fastMode = fastModeEnv === "true";

	if (fastMode) {
		return {
			embeddingsReady: false,
			indexingResult: { indexed: 0, skipped: 0, success: true, errors: [], embeddingsGenerated: 0 },
		};
	}

	// Step 1: Preload embeddings model
	const embeddingsReady = await ensureEmbeddingsReady();

	// Step 2: Index existing learnings
	const indexingResult = await indexAllLearnings(workspaceRoot, {
		skipEmbeddings: !embeddingsReady,
	});
	indexedWorkspaces.add(workspaceRoot);

	// Step 3: Warm up retriever cache
	getHybridRetriever(workspaceRoot);

	return { embeddingsReady, indexingResult };
}

/**
 * Invalidate cache for a workspace
 * Call when learnings are added/updated
 */
export function invalidateRetrieverCache(workspaceRoot: string): void {
	const cached = retrievers.get(workspaceRoot);
	if (cached) {
		// Daemon manages resources, just remove from cache
		retrievers.delete(workspaceRoot);
	}
	indexedWorkspaces.delete(workspaceRoot);
}

/**
 * Dispose all retrievers
 * Call on server shutdown
 */
export function disposeAllRetrievers(): void {
	// Daemon manages resources, just clear cache
	retrievers.clear();
	indexedWorkspaces.clear();
}

// =============================================================================
// P1: INTENT-BASED BOOSTING
// =============================================================================

/**
 * Apply intent-based boosting to retrieval results.
 *
 * Boosts learnings whose content matches the intent's domain keywords.
 * For example, "debug" intent boosts learnings containing "error", "bug", "fix", etc.
 *
 * @param results - Original retrieval results
 * @param intent - Task intent
 * @returns Results with boosted scores and count of boosted items
 */
function applyIntentBoost(
	results: RetrievalResult[],
	intent: TaskIntent,
): { results: RetrievalResult[]; boostedCount: number } {
	const domainKeywords = INTENT_DOMAIN_KEYWORDS[intent] || [];
	const intentFiles = INTENT_LEARNING_FILES[intent] || [];

	let boostedCount = 0;

	const boosted = results.map((result) => {
		const chunkText = result.chunk.chunk_text?.toLowerCase() || "";
		const sourceId = result.chunk.source_id?.toLowerCase() || "";
		const metadata = result.chunk.metadata as Record<string, string> | undefined;
		const domain = metadata?.domain?.toLowerCase() || "";

		// Check if chunk matches intent
		let shouldBoost = false;

		// Method 1: Domain keywords in chunk text
		const keywordMatches = domainKeywords.filter((kw) => chunkText.includes(kw)).length;
		if (keywordMatches >= 2) {
			shouldBoost = true;
		}

		// Method 2: Source ID matches intent files
		if (intentFiles.some((f) => sourceId.includes(f.replace(".jsonl", "")))) {
			shouldBoost = true;
		}

		// Method 3: Domain metadata matches intent
		if (domain && INTENT_DOMAIN_KEYWORDS[intent]?.some((kw) => domain.includes(kw))) {
			shouldBoost = true;
		}

		if (shouldBoost) {
			boostedCount++;
			return {
				...result,
				score: result.score * (1 + INTENT_BOOST_FACTOR),
				confidence: Math.min(result.confidence * (1 + INTENT_BOOST_FACTOR), 1),
				sources: {
					...result.sources,
					intentBoost: { intent, factor: INTENT_BOOST_FACTOR },
				},
			};
		}

		return result;
	});

	// Re-sort by boosted scores
	boosted.sort((a, b) => b.score - a.score);

	return { results: boosted, boostedCount };
}

/**
 * Get retrieval statistics for monitoring
 */
export function getRetrievalStats(workspaceRoot: string): {
	cacheHit: boolean;
	cacheAgeMs: number;
	indexed: boolean;
	embeddingsAvailable: boolean;
} {
	const cached = retrievers.get(workspaceRoot);
	return {
		cacheHit: !!cached,
		cacheAgeMs: cached ? Date.now() - cached.createdAt : 0,
		indexed: indexedWorkspaces.has(workspaceRoot),
		embeddingsAvailable: isEmbeddingsAvailable(),
	};
}

// =============================================================================
// ENHANCED RETRIEVAL (V2) - 2025 Best Practices
// =============================================================================

/**
 * Enhanced adaptive retrieval with 2025 best practices:
 * - Query complexity classification for retrieval strategy
 * - Query expansion for factual queries
 * - Post-RRF reranking for improved relevance
 * - Comprehensive metrics for observability
 *
 * @see https://arxiv.org/abs/2501.07391 - RAG best practices
 * @see https://www.meilisearch.com/blog/adaptive-rag
 * @see https://www.elastic.co/search-labs/blog/weighted-reciprocal-rank-fusion-rrf
 */
export async function retrieveAdaptiveV2(
	workspaceRoot: string,
	query: string,
	options?: {
		/** P1: Task intent for domain-specific boosting */
		intent?: TaskIntent;
	},
): Promise<{
	results: RetrievalResult[];
	classification: QueryClassification;
	strategy: RetrievalStrategy;
	metrics: RetrievalMetrics;
}> {
	const startTime = performance.now();

	// Initialize metrics
	const metrics: RetrievalMetrics = {
		queryLength: query.length,
		classificationType: "unknown",
		classificationComplexity: "medium",
		classificationConfidence: 0,
		embeddingsAvailable: isEmbeddingsAvailable(),
		strategy: {
			semanticWeight: 0.5,
			keywordWeight: 0.5,
			method: "balanced",
			shouldRetrieve: true,
			topK: 10,
			useReranking: false,
			useExpansion: false,
		},
		retrievalSkipped: false,
		queryExpansionUsed: false,
		expandedQueries: 1,
		rerankingApplied: false,
		semanticCandidates: 0,
		keywordCandidates: 0,
		fusedCount: 0,
		rerankedCount: 0,
		finalResultCount: 0,
		latencyMs: 0,
		indexingPerformed: false,
	};

	// Step 0: Auto-index learnings if not done yet
	if (!indexedWorkspaces.has(workspaceRoot)) {
		try {
			const indexResult = await indexAllLearnings(workspaceRoot, {
				skipEmbeddings: !metrics.embeddingsAvailable,
			});
			indexedWorkspaces.add(workspaceRoot);
			metrics.indexingPerformed = indexResult.indexed > 0;

			if (metrics.indexingPerformed) {
				// Intentionally empty: indexing success noted for metrics, no further action needed
			}
		} catch (_error) {
			// Intentionally ignored: learning indexing failure is non-fatal for retrieval
		}
	}

	// Step 1: Classify the query (type + complexity)
	const classification = classifyQuery(query);
	metrics.classificationType = classification.type;
	metrics.classificationComplexity = classification.complexity;
	metrics.classificationConfidence = classification.confidence;

	// Step 2: Determine retrieval strategy based on complexity
	const strategy = getRetrievalStrategyLocal(classification);
	metrics.strategy = strategy;

	// Step 3: Check if retrieval should be skipped (simple queries)
	if (!strategy.shouldRetrieve) {
		metrics.retrievalSkipped = true;
		metrics.fallbackUsed = "skipped";
		metrics.latencyMs = performance.now() - startTime;

		return {
			results: [],
			classification,
			strategy,
			metrics,
		};
	}

	// Step 4: Check embeddings availability
	if (!metrics.embeddingsAvailable) {
		metrics.fallbackUsed = "keyword-only";
		const result = await keywordOnlySearchV2(workspaceRoot, query, classification, strategy, metrics, startTime);
		return result;
	}

	// Step 5: Check classification confidence
	if (classification.confidence < MIN_CLASSIFICATION_CONFIDENCE) {
		metrics.fallbackUsed = "balanced-weights";
		classification.weights = { semantic: 0.5, keyword: 0.5 };
	}

	// Step 6: Query expansion (for factual queries)
	let queries = [query];
	if (strategy.useExpansion) {
		queries = expandQueryLocal(query);
		metrics.queryExpansionUsed = queries.length > 1;
		metrics.expandedQueries = queries.length;
	}

	// Step 7: Run adaptive retrieval
	try {
		const retriever = getHybridRetriever(workspaceRoot);

		// Run retrieval (potentially with multiple queries)
		let allResults: RetrievalResult[] = [];

		for (const q of queries) {
			const result = await retriever.retrieveAdaptive(q, { limit: strategy.topK || 10 });
			const stats = result.stats as {
				semanticCandidates?: number;
				keywordCandidates?: number;
			};
			metrics.semanticCandidates += stats.semanticCandidates || 0;
			metrics.keywordCandidates += stats.keywordCandidates || 0;
			allResults = allResults.concat(result.results);
		}

		// Deduplicate results by chunk ID
		const seen = new Set<string>();
		const dedupedResults = allResults.filter((r) => {
			if (seen.has(r.chunk.id)) {
				return false;
			}
			seen.add(r.chunk.id);
			return true;
		});

		metrics.fusedCount = dedupedResults.length;

		// Step 8: Apply reranking if enabled (with three-layer confidence model)
		let finalResults = dedupedResults;
		if (strategy.useReranking && dedupedResults.length > 1) {
			finalResults = await rerankResults(query, dedupedResults);
			metrics.rerankingApplied = true;
			metrics.rerankedCount = finalResults.length;
		}

		// Limit to topK
		finalResults = finalResults.slice(0, strategy.topK);

		// P1: Apply intent-based boosting
		const intent = options?.intent;
		if (intent) {
			const { results: boosted, boostedCount } = applyIntentBoost(finalResults, intent);
			finalResults = boosted;
			metrics.intentUsed = intent;
			metrics.intentBoostedCount = boostedCount;
		}

		metrics.finalResultCount = finalResults.length;
		metrics.latencyMs = performance.now() - startTime;

		return {
			results: finalResults,
			classification:
				metrics.fallbackUsed === "balanced-weights"
					? { ...classification, weights: { semantic: 0.5, keyword: 0.5 } }
					: classification,
			strategy,
			metrics,
		};
	} catch (_error) {
		metrics.fallbackUsed = "keyword-only";
		return keywordOnlySearchV2(workspaceRoot, query, classification, strategy, metrics, startTime);
	}
}

/**
 * Rerank results using three-layer confidence model
 *
 * Layers:
 * - Layer 1: Semantic similarity (query-chunk embedding similarity)
 * - Layer 2: Historical signals (past success rate, latency)
 * - Layer 3: Metadata signals (authority, status, recency)
 *
 * @see https://www.dbi-services.com/blog/rag-series-hybrid-search-with-re-ranking/
 */
async function rerankResults(
	query: string,
	results: RetrievalResult[],
	_store?: unknown, // Day 4: No longer used, daemon manages store
): Promise<RetrievalResult[]> {
	// Only rerank top candidates
	const candidates = results.slice(0, RERANK_CANDIDATE_LIMIT);

	try {
		// Get query embedding via daemon
		const queryEmbeddingResult = await generateEmbeddingViaDaemon(query);
		const queryEmbedding = queryEmbeddingResult.embedding || [];

		// Score each result using three-layer confidence model
		const scored = await Promise.all(
			candidates.map(async (result) => {
				// Layer 1: Get semantic similarity (retrieval score)
				let semanticScore = result.score;

				// If we have embeddings, compute similarity
				if (queryEmbedding.length > 0 && result.text) {
					try {
						const chunkEmbeddingResult = await generateEmbeddingViaDaemon(result.text);
						if (chunkEmbeddingResult.embedding) {
							semanticScore = cosineSimilarity(queryEmbedding, chunkEmbeddingResult.embedding);
						}
					} catch {
						// Keep original score on embedding failure
					}
				}

				// Layer 2: Historical signals (not available in daemon mode)
				const historicalSignals: HistoricalSignals = {};

				// Layer 3: Calculate metadata boost (authority, status, recency)
				const metadataBoost = calculateMetadataBoost(result.metadata || {});

				// Combined score using three-layer model
				const rerankScore =
					calculateRerankingScore({
						score: semanticScore,
						metadata: result.metadata,
					}) + metadataBoost;

				// Confidence level for display
				const confidenceLevel = getConfidenceLevel(rerankScore);

				return {
					...result,
					rerankedScore: rerankScore,
					metadataBoost,
					confidenceLevel,
					historicalSignals,
				};
			}),
		);

		// Sort by reranked score
		scored.sort((a, b) => b.rerankedScore - a.rerankedScore);

		// Return with updated scores and confidence
		return scored.map(({ rerankedScore, metadataBoost, confidenceLevel, historicalSignals, ...result }) => ({
			...result,
			score: rerankedScore,
			confidence: rerankedScore,
			// Add metadata to sources for observability
			sources: {
				...result.sources,
				reranking: {
					metadataBoost,
					confidenceLevel,
					hasHistoricalSignals: !!historicalSignals,
				},
			},
		}));
	} catch (_error) {
		return candidates;
	}
}

/**
 * Keyword-only search fallback for V2
 */
async function keywordOnlySearchV2(
	workspaceRoot: string,
	query: string,
	classification: QueryClassification,
	strategy: RetrievalStrategy,
	metrics: RetrievalMetrics,
	startTime: number,
): Promise<{
	results: RetrievalResult[];
	classification: QueryClassification;
	strategy: RetrievalStrategy;
	metrics: RetrievalMetrics;
}> {
	// Use daemon IPC for keyword search (Day 4: daemon-first)
	const daemonResult = await searchKnowledgeViaDaemon(workspaceRoot, query, strategy.topK || 10);
	metrics.keywordCandidates = daemonResult.chunks?.length || 0;
	metrics.fusedCount = daemonResult.chunks?.length || 0;
	metrics.finalResultCount = daemonResult.chunks?.length || 0;
	metrics.latencyMs = performance.now() - startTime;

	// Convert to RetrievalResult format
	const results: RetrievalResult[] = (daemonResult.chunks || []).map((chunk, index) => ({
		id: chunk.id,
		text: chunk.chunk_text,
		source: chunk.source_id,
		chunk: {
			id: chunk.id,
			chunk_text: chunk.chunk_text,
			source_id: chunk.source_id,
			metadata: chunk.metadata,
		},
		score: 1 / (60 + index + 1), // RRF-style score
		confidence: 0.5 + 0.3 * (1 - index / Math.max(daemonResult.chunks?.length || 1, 1)),
		sources: [chunk.source_id],
		metadata: chunk.metadata,
	}));

	return {
		results,
		classification: {
			...classification,
			weights: { semantic: 0, keyword: 1 },
			reason: "Keyword-only V2 via daemon",
		},
		strategy,
		metrics,
	};
}
