/**
 * Handler Utilities
 *
 * Shared utility functions for facade tool handlers.
 *
 * @module facades/handlers/utils
 */

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { ToolResult } from "../../types/tool-types.js";
import { type CoachingContext, compressResponse, getResponseConfig } from "../response-utils.js";

/**
 * Helper to create a tool result
 */
export function result(text: string, isError = false): ToolResult {
	return {
		content: [{ type: "text", text }],
		isError,
	};
}

/**
 * Helper to create JSON result with optional compression and coaching
 */
export function jsonResult(
	data: unknown,
	options?: {
		context?: { tier?: string };
		coaching?: CoachingContext;
		compress?: boolean;
	},
): ToolResult {
	let finalData = data as Record<string, unknown>;

	// Add coaching hint if context provided
	if (options?.coaching) {
		const hint = generateCoachingHint(options.coaching);
		if (hint) {
			finalData = { ...finalData, _hint: hint };
		}
	}

	// Compress if requested or if context tier requires it
	if (options?.compress !== false && options?.context) {
		const config = getResponseConfig(options.context.tier || "local");
		finalData = compressResponse(finalData, config);
	}

	return result(JSON.stringify(finalData, null, 2));
}

/**
 * Helper to create JSON error result (sets isError: true)
 */
export function errorJsonResult(data: unknown): ToolResult {
	return result(JSON.stringify(data, null, 2), true);
}

/**
 * Helper to safely list snapshots without creating directories
 * For readonly/remote mode, reads snapshots without triggering directory creation
 */
export function listSnapshotsReadonly(
	workspaceRoot: string,
): Array<{ id: string; createdAt: number; files: Array<{ path: string }> }> {
	const snapshotDir = join(workspaceRoot, ".vreko", "snapshots");

	if (!existsSync(snapshotDir)) {
		return [];
	}

	try {
		const files = require("node:fs")
			.readdirSync(snapshotDir)
			.filter((f: string) => f.endsWith(".json"));

		return files
			.map((file: string) => {
				try {
					const content = readFileSync(join(snapshotDir, file), "utf8");
					const parsed = JSON.parse(content);
					return {
						id: parsed.id,
						createdAt: parsed.createdAt,
						files: parsed.files || [],
					};
				} catch {
					return null;
				}
			})
			.filter((m: unknown): m is { id: string; createdAt: number; files: Array<{ path: string }> } => m !== null)
			.sort((a: { createdAt: number }, b: { createdAt: number }) => b.createdAt - a.createdAt);
	} catch {
		return [];
	}
}

/**
 * Detect if workspace path is local or remote
 * Remote workspaces (sent by client over network) won't have write permissions
 */
export function isLocalWorkspace(workspacePath: string): boolean {
	// Check if path looks like an absolute local path
	// Windows: C:\path or local UNC paths
	// Unix/Mac: /path or ~/path
	if (workspacePath.startsWith("/") || workspacePath.startsWith("~") || /^[A-Za-z]:/.test(workspacePath)) {
		// Still might not be writable, but worth trying
		return true;
	}
	// Relative paths or network paths are likely remote
	return false;
}

/**
 * Generate coaching hint for response
 * Re-exported from response-utils for convenience
 */
function generateCoachingHint(coaching: CoachingContext): string | null {
	// Simple coaching hint generation - can be enhanced
	if (coaching.lastAction) {
		const hints: Record<string, string> = {
			snapshot_created: "Snapshot created successfully. Continue with your task.",
			snapshot_skipped: "No changes detected. Previous snapshot still valid.",
			snapshot_restored: "Files restored. Review changes before proceeding.",
			validation_passed: "All checks passed. Ready to commit.",
			validation_failed: "Issues found. Review and fix before committing.",
		};
		return hints[coaching.lastAction] || null;
	}
	return null;
}

/**
 * Enhanced MCP Response Format
 * Provides user-friendly messages with technical details
 */
export interface EnhancedMCPResponse {
	// Status
	status: "success" | "error" | "warning";
	icon?: string; // Emoji for quick visual scanning

	// User-facing (required for good UX)
	userMessage: string; // Clear, friendly explanation
	details?: string; // Additional context if needed

	// Actionable guidance
	whatToDoNext?: string; // Clear next steps
	nextActions?: Array<{
		icon?: string;
		label: string;
		tool: string;
		priority: number;
		reason: string; // Why this action matters
	}>;

	// Technical (for debugging/support)
	technicalError?: string; // Error codes for support

	// Original data (preserve for compatibility)
	[key: string]: unknown;
}

/**
 * Create an enhanced JSON result with user-friendly messaging
 * Use this for improved UX over raw jsonResult
 */
export function enhancedJsonResult(
	data: Partial<EnhancedMCPResponse> & Record<string, unknown>,
	options?: {
		context?: { tier?: string };
		coaching?: CoachingContext;
		compress?: boolean;
	},
): ToolResult {
	// Add default icon based on status if not provided
	if (!data.icon && data.status) {
		data.icon = getStatusIcon(data.status);
	}

	return jsonResult(data, options);
}

/**
 * Create an enhanced error result with user-friendly messaging
 */
export function enhancedErrorResult(
	userMessage: string,
	details?: string,
	technicalError?: string,
	whatToDoNext?: string,
): ToolResult {
	const errorResponse: Partial<EnhancedMCPResponse> = {
		status: "error",
		icon: "⚠️",
		userMessage,
		details,
		technicalError,
		whatToDoNext,
	};

	return {
		content: [
			{
				type: "text",
				text: JSON.stringify(errorResponse, null, 2),
			},
		],
		isError: true,
	};
}

/**
 * Get status icon based on status type
 */
function getStatusIcon(status: "success" | "error" | "warning"): string {
	switch (status) {
		case "success":
			return "✅";
		case "error":
			return "⚠️";
		case "warning":
			return "⚡";
		default:
			return "ℹ️";
	}
}
