/**
 * Vector Context Module
 *
 * Provides vector-based context retrieval for MCP tools.
 * Bridges the VectorRetrieval service from @vreko/intelligence
 * with MCP facades (begin-task, complete-task).
 *
 * Key Features:
 * - Graceful degradation when vector search is disabled
 * - Lazy initialization of embedding pipeline
 * - Workspace isolation via workspaceId filtering
 * - Non-blocking operations (never blocks MCP)
 *
 * @module context/vector-context
 */

import type { VectorResult, VectorRetrieval } from "@vreko/intelligence";

// =============================================================================
// TYPES
// =============================================================================

/**
 * Options for vector context retrieval
 */
export interface VectorContextOptions {
	/** VectorRetrieval service instance (null if disabled) */
	retrieval: VectorRetrieval | null;
	/** Workspace ID for isolation */
	workspaceId: string;
}

/**
 * Options for file-based context retrieval
 */
export interface FileContextSearchOptions extends VectorContextOptions {
	/** File path being worked on */
	filePath: string;
	/** Task description for context */
	taskDescription: string;
	/** Maximum results to return */
	limit?: number;
	/** Similarity threshold (0-1) */
	threshold?: number;
}

/**
 * Options for session-based context retrieval
 */
export interface SessionContextSearchOptions extends VectorContextOptions {
	/** Session summary text */
	summary: string;
	/** List of changed file paths */
	changedFiles?: string[];
	/** Maximum results to return */
	limit?: number;
}

/**
 * Result of vector context retrieval
 */
export interface VectorContextResult {
	/** Retrieved learnings from vector search */
	learnings: VectorResult[];
	/** Source of results */
	source: "vector" | "fallback" | "disabled";
	/** Error message if fallback was used */
	error?: string;
}

/**
 * Learning formatted for MCP output
 */
export interface FormattedVectorLearning {
	/** Unique ID */
	id: string;
	/** Content/snippet */
	content: string;
	/** Similarity score (0-1) */
	score: number;
	/** Source type (pattern, pitfall, etc.) */
	type: string;
	/** Source of retrieval */
	source: "vector";
	/** Additional metadata */
	metadata?: Record<string, unknown>;
}

// =============================================================================
// MAIN FUNCTIONS
// =============================================================================

/**
 * Get vector-based context for MCP tools
 *
 * Provides graceful degradation:
 * 1. If retrieval is null → disabled
 * 2. If embedding pipeline not ready → try preload, then fallback
 * 3. If search fails → fallback
 *
 * @param options - Context options including retrieval service
 * @returns Vector context result with learnings and source info
 */
export async function getVectorContext(options: VectorContextOptions): Promise<VectorContextResult> {
	const { retrieval } = options;

	// No retrieval service configured
	if (!retrieval) {
		return { learnings: [], source: "disabled" };
	}

	// Check if embedding pipeline is ready
	if (!retrieval.isReady()) {
		// Try to preload (non-blocking with timeout)
		try {
			// Use a timeout to prevent blocking
			const preloadPromise = retrieval.preload();
			const timeoutPromise = new Promise<void>((_, reject) =>
				setTimeout(() => reject(new Error("Preload timeout")), 5000),
			);

			await Promise.race([preloadPromise, timeoutPromise]);
		} catch (error) {
			return {
				learnings: [],
				source: "fallback",
				error: error instanceof Error ? error.message : "Embedding pipeline not ready",
			};
		}
	}

	// Return empty result - actual search is done by specific functions
	return { learnings: [], source: "vector" };
}

/**
 * Search for learnings relevant to a file and task
 *
 * Used by begin_task to provide file-based context.
 * Falls back gracefully if vector search fails.
 *
 * @param options - File context search options
 * @returns Vector context result with relevant learnings
 */
export async function searchFileContext(options: FileContextSearchOptions): Promise<VectorContextResult> {
	const { retrieval, workspaceId, filePath, taskDescription, limit = 5, threshold = 0.7 } = options;

	// Check if retrieval is available
	if (!retrieval) {
		return { learnings: [], source: "disabled" };
	}

	// Ensure pipeline is ready
	try {
		if (!retrieval.isReady()) {
			const preloadPromise = retrieval.preload();
			const timeoutPromise = new Promise<void>((_, reject) =>
				setTimeout(() => reject(new Error("Preload timeout")), 3000),
			);
			await Promise.race([preloadPromise, timeoutPromise]);
		}
	} catch (error) {
		return {
			learnings: [],
			source: "fallback",
			error: error instanceof Error ? error.message : "Embedding pipeline not ready",
		};
	}

	// Perform search
	try {
		const learnings = await retrieval.searchByFile({
			filePath,
			taskDescription,
			workspaceId,
			limit,
			threshold,
		});

		return { learnings, source: "vector" };
	} catch (error) {
		return {
			learnings: [],
			source: "fallback",
			error: error instanceof Error ? error.message : "Vector search failed",
		};
	}
}

/**
 * Search for learnings relevant to a session summary
 *
 * Used by complete_task to surface related learnings during closing ceremony.
 * Falls back gracefully if vector search fails.
 *
 * @param options - Session context search options
 * @returns Vector context result with relevant learnings
 */
export async function searchSessionContext(options: SessionContextSearchOptions): Promise<VectorContextResult> {
	const { retrieval, workspaceId, summary, changedFiles, limit = 10 } = options;

	// Check if retrieval is available
	if (!retrieval) {
		return { learnings: [], source: "disabled" };
	}

	// Ensure pipeline is ready
	try {
		if (!retrieval.isReady()) {
			const preloadPromise = retrieval.preload();
			const timeoutPromise = new Promise<void>((_, reject) =>
				setTimeout(() => reject(new Error("Preload timeout")), 3000),
			);
			await Promise.race([preloadPromise, timeoutPromise]);
		}
	} catch (error) {
		return {
			learnings: [],
			source: "fallback",
			error: error instanceof Error ? error.message : "Embedding pipeline not ready",
		};
	}

	// Perform search
	try {
		const learnings = await retrieval.searchBySession({
			summary,
			changedFiles,
			workspaceId,
			limit,
		});

		return { learnings, source: "vector" };
	} catch (error) {
		return {
			learnings: [],
			source: "fallback",
			error: error instanceof Error ? error.message : "Vector search failed",
		};
	}
}

/**
 * Format vector results for MCP output
 *
 * Converts VectorResult to a format suitable for begin_task/complete_task output.
 *
 * @param results - Vector search results
 * @returns Formatted learnings for MCP output
 */
export function formatVectorLearnings(results: VectorResult[]): FormattedVectorLearning[] {
	return results.map((result) => ({
		id: result.id,
		content: result.content,
		score: result.score,
		type: (result.metadata?.type as string) || "discovery",
		source: "vector" as const,
		metadata: result.metadata,
	}));
}

/**
 * Check if vector search is available and ready
 *
 * @param retrieval - VectorRetrieval instance (may be null)
 * @returns true if vector search can be used
 */
export function isVectorSearchReady(retrieval: VectorRetrieval | null): boolean {
	return retrieval?.isReady() ?? false;
}

/**
 * Merge vector learnings with existing learnings
 *
 * Deduplicates by ID and prioritizes higher scores.
 *
 * @param existing - Existing learnings (may be from keyword search)
 * @param vector - Vector search results
 * @returns Merged and deduplicated learnings
 */
export function mergeLearnings(
	existing: Array<{ id?: string; content: string; score?: number; relevanceScore?: number }>,
	vector: FormattedVectorLearning[],
): Array<{ id?: string; content: string; score: number; source: string }> {
	const merged = new Map<string, { id?: string; content: string; score: number; source: string }>();

	// Add existing learnings
	for (const learning of existing) {
		const id = learning.id || `existing_${learning.content.slice(0, 20)}`;
		const score = learning.score ?? learning.relevanceScore ?? 0;
		merged.set(id, {
			id,
			content: learning.content,
			score,
			source: "keyword",
		});
	}

	// Add or update with vector learnings
	for (const learning of vector) {
		const existing = merged.get(learning.id);
		if (existing) {
			// Take higher score
			if (learning.score > existing.score) {
				merged.set(learning.id, {
					id: learning.id,
					content: learning.content,
					score: learning.score,
					source: "vector",
				});
			}
		} else {
			merged.set(learning.id, {
				id: learning.id,
				content: learning.content,
				score: learning.score,
				source: "vector",
			});
		}
	}

	// Sort by score descending
	return Array.from(merged.values()).sort((a, b) => b.score - a.score);
}
