/**
 * Result Type for Type-Safe Error Handling
 *
 * Re-exports from neverthrow for backward compatibility.
 * This file provides the SDK's Result pattern utilities.
 *
 * @module result
 */

import type { LegacyResult as ContractsLegacyResult } from "@vreko-oss/contracts";

// Re-export neverthrow factory functions and types
export {
	err,
	errAsync,
	fromPromise,
	fromThrowable,
	ok,
	okAsync,
	type Result,
	ResultAsync,
} from "neverthrow";

// Re-export LegacyResult type from contracts
export type LegacyResult<T, E = Error> = ContractsLegacyResult<T, E>;

// Legacy result factory functions (for code using { success, value/error } pattern)
export function legacyOk<T>(value: T): LegacyResult<T, never> {
	return { success: true, value };
}

export function legacyErr<E>(error: E): LegacyResult<never, E> {
	return { success: false, error };
}

// Type guards for LegacyResult
export function isLegacyOk<T, E>(result: LegacyResult<T, E>): result is { success: true; value: T } {
	return result.success === true;
}

export function isLegacyErr<T, E>(result: LegacyResult<T, E>): result is { success: false; error: E } {
	return result.success === false;
}
