/**
 * Handler Registry
 *
 * Central registry mapping tool names to their handlers.
 *
 * @module facades/handlers/registry
 */

import type { ToolHandler } from "../../types/tool-types.js";

// Import composite tool handlers (delegated to other modules)
import { handleBeginTask } from "../begin-task.js";
import { handleCompleteTask } from "../complete-task.js";
import { generatePairingProtocol, getContextSummary } from "../pairing-protocol.js";
import { handleQuickCheck } from "../quick-check.js";
import { handleReviewWork } from "../review-work.js";
import { handleWhatChanged } from "../what-changed.js";

// Import extracted handlers
import { handleAnalyze } from "./analyze-handler.js";
import { handleCleanup } from "./cleanup-handler.js";
import { handleContext } from "./context-handler.js";
import { handleGetLearnings, handleLearn } from "./learning-handlers.js";
import { handleLookupExports } from "./lookup-exports-handler.js";
import { handleMeta } from "./meta-handlers.js";
import { handleAcknowledgeRisk, handleReportViolation } from "./risk-handlers.js";
import { handleSession } from "./session-handler.js";
import {
	handleCompareSnapshots,
	handleSnapshotCreate,
	handleSnapshotList,
	handleSnapshotRestore,
	handleSuggestSnapshot,
} from "./snapshot-handlers.js";
import { handleCheckPatterns, handleValidate } from "./validation-handlers.js";
import { handlePrepareWorkspace } from "./workspace-handler.js";

/**
 * Get pairing protocol handler
 */
const handleGetPairingProtocol: ToolHandler = async (_args, context) => {
	const protocol = generatePairingProtocol(context.workspaceRoot);
	return {
		content: [{ type: "text", text: JSON.stringify(protocol, null, 2) }],
		isError: false,
	};
};

/**
 * Get context handler
 */
export const handleGetContext: ToolHandler = async (_args, context) => {
	const summary = await getContextSummary(context.workspaceRoot);
	return {
		content: [{ type: "text", text: JSON.stringify(summary, null, 2) }],
		isError: false,
	};
};

/**
 * Registry mapping tool names to their handlers
 */
export const facadeHandlers: Record<string, ToolHandler> = {
	// Core handlers
	analyze: handleAnalyze,
	prepare_workspace: handlePrepareWorkspace,

	// Snapshot handlers
	snapshot_create: handleSnapshotCreate,
	snapshot_list: handleSnapshotList,
	snapshot_restore: handleSnapshotRestore,
	suggest_snapshot: handleSuggestSnapshot,
	compare_snapshots: handleCompareSnapshots,

	// Validation handlers
	validate: handleValidate,
	check_patterns: handleCheckPatterns,

	// Context and session handlers
	context: handleContext,
	session: handleSession,
	get_context: handleGetContext,

	// Learning handlers
	learn: handleLearn,
	get_learnings: handleGetLearnings,

	// Risk handlers
	acknowledge_risk: handleAcknowledgeRisk,
	report_violation: handleReportViolation,

	// Meta handlers
	meta: handleMeta,
	cleanup: handleCleanup,

	// Pair programmer composite tools
	begin_task: handleBeginTask,
	quick_check: handleQuickCheck,
	what_changed: handleWhatChanged,
	review_work: handleReviewWork,
	complete_task: handleCompleteTask,
	get_pairing_protocol: handleGetPairingProtocol,

	// Discovery handlers
	lookup_exports: handleLookupExports,
};

/**
 * Get a handler by tool name
 */
export function getHandler(toolName: string): ToolHandler | undefined {
	return facadeHandlers[toolName];
}

/**
 * Check if a handler exists for a tool name
 */
export function hasHandler(toolName: string): boolean {
	return toolName in facadeHandlers;
}

/**
 * Get all registered tool names
 */
export function getRegisteredTools(): string[] {
	return Object.keys(facadeHandlers);
}
