/**
 * Integration Orchestrator Service
 *
 * Unified interface for GitHub, Context7, and Sentry MCP integrations.
 * Manages lifecycle, caching, circuit breakers, and graceful degradation.
 *
 * Key Features:
 * - Single entry point for all external integrations
 * - Per-integration circuit breakers (3 failures → 60s cooldown)
 * - LRU cache with TTL (5min GitHub/Sentry, 30min Context7)
 * - Graceful degradation (never throws, always returns null on failure)
 * - Health monitoring for integration status
 * - MCP config detection from .mcp.json and .claude.json files
 *
 * @module services/integration-orchestrator-service
 *
 * DEPRECATED (Day 4): Direct @vreko/intelligence imports replaced with daemon IPC.
 * Integration context now routes through the daemon.
 */

import { existsSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import type {
	AggregatedContext,
	DocsValidation,
	GitHubContext,
	RiskFactor,
	SentryContext,
} from "@vreko/intelligence/types";
import { getIntegrationContextViaDaemon } from "../daemon/local-service-adapter.js";

// =============================================================================
// TYPES
// =============================================================================

export type IntegrationName = "github" | "context7" | "sentry";

export interface IntegrationHealth {
	/** Overall health status */
	status: "healthy" | "degraded" | "unavailable";
	/** Per-integration status */
	integrations: {
		github: IntegrationStatus;
		context7: IntegrationStatus;
		sentry: IntegrationStatus;
	};
	/** Cache statistics */
	cache: {
		hits: number;
		misses: number;
		size: number;
	};
}

export interface IntegrationStatus {
	/** Whether this integration is enabled in config */
	enabled: boolean;
	/** Whether this integration is connected */
	connected: boolean;
	/** Whether circuit breaker is open (disabled due to failures) */
	circuitOpen: boolean;
	/** Number of consecutive failures */
	failureCount: number;
	/** Last error message if any */
	lastError?: string;
	/** Last successful call timestamp */
	lastSuccess?: string;
}

export interface FileInfo {
	/** File path */
	path: string;
	/** File content (required for Context7 validation) */
	content?: string;
	/** Language identifier (e.g., "typescript", "javascript") */
	language?: string;
}

export interface EnrichmentParams {
	/** Files to get context for (simple paths for GitHub/Sentry, with content for Context7) */
	files: Array<string | FileInfo>;
	/** Intent for prioritization */
	intent?: "implement" | "debug" | "refactor" | "review" | "explore";
	/** Skip cache and fetch fresh data */
	skipCache?: boolean;
}

export interface EnrichedContext {
	/** Aggregated contexts per file */
	contexts: Map<string, AggregatedContext>;
	/** Combined risk factors from all sources */
	riskFactors: RiskFactor[];
	/** Overall risk score (0-100) */
	riskScore: number;
	/** Which integrations contributed */
	sources: IntegrationName[];
	/** Time taken to gather context */
	durationMs: number;
}

export interface OrchestratorConfig {
	/** Enable/disable the orchestrator */
	enabled: boolean;
	/** Per-integration configuration */
	github: {
		enabled: boolean;
		token?: string;
		owner?: string;
		repo?: string;
		timeoutMs: number;
	};
	context7: {
		enabled: boolean;
		apiKey?: string;
		timeoutMs: number;
	};
	sentry: {
		enabled: boolean;
		authToken?: string;
		organization?: string;
		project?: string;
		timeoutMs: number;
	};
	/** Cache configuration */
	cache: {
		enabled: boolean;
		githubTtlMs: number;
		context7TtlMs: number;
		sentryTtlMs: number;
		maxEntries: number;
	};
	/** Circuit breaker configuration */
	circuitBreaker: {
		failureThreshold: number;
		recoveryTimeMs: number;
	};
}

interface CacheEntry<T> {
	data: T;
	expiresAt: number;
}

interface CircuitState {
	failures: number;
	lastFailure: number;
	isOpen: boolean;
}

// =============================================================================
// DEFAULT CONFIGURATION
// =============================================================================

const DEFAULT_CONFIG: OrchestratorConfig = {
	enabled: true,
	github: {
		enabled: false,
		timeoutMs: 5000,
	},
	context7: {
		enabled: false,
		timeoutMs: 5000,
	},
	sentry: {
		enabled: false,
		timeoutMs: 5000,
	},
	cache: {
		enabled: true,
		githubTtlMs: 5 * 60 * 1000, // 5 minutes
		context7TtlMs: 30 * 60 * 1000, // 30 minutes (docs change less frequently)
		sentryTtlMs: 5 * 60 * 1000, // 5 minutes
		maxEntries: 100,
	},
	circuitBreaker: {
		failureThreshold: 3,
		recoveryTimeMs: 60 * 1000, // 60 seconds
	},
};

// =============================================================================
// INTEGRATION ORCHESTRATOR SERVICE
// =============================================================================

/**
 * Integration Orchestrator Service
 *
 * Manages GitHub, Context7, and Sentry MCP client lifecycle with
 * caching, circuit breakers, and graceful degradation.
 *
 * @example
 * ```typescript
 * const orchestrator = new IntegrationOrchestratorService({
 *   enabled: true,
 *   github: { enabled: true, token: 'xxx' },
 * });
 *
 * await orchestrator.initialize();
 *
 * const enriched = await orchestrator.enrichContext({
 *   files: ['src/auth.ts'],
 *   imports: ['react', 'next'],
 * });
 *
 * if (enriched) {
 *   logger.debug(...);
 * }
 * ```
 */
export class IntegrationOrchestratorService {
	private readonly config: OrchestratorConfig;
	private readonly logger: OrchestratorLogger;
	private readonly workspaceRoot?: string;

	// Circuit breaker state per integration
	private circuits: Map<IntegrationName, CircuitState> = new Map();

	// LRU Cache per integration (key → CacheEntry)
	private githubCache: Map<string, CacheEntry<GitHubContext>> = new Map();
	private context7Cache: Map<string, CacheEntry<DocsValidation>> = new Map();
	private sentryCache: Map<string, CacheEntry<SentryContext>> = new Map();

	// Cache statistics
	private cacheHits = 0;
	private cacheMisses = 0;

	// Connection state
	private initialized = false;

	constructor(config?: Partial<OrchestratorConfig> & { workspaceRoot?: string }, logger?: OrchestratorLogger) {
		this.config = this.mergeConfig(config);
		this.logger = logger ?? defaultLogger;
		this.workspaceRoot = config?.workspaceRoot;

		// Initialize circuit breaker state
		this.circuits.set("github", { failures: 0, lastFailure: 0, isOpen: false });
		this.circuits.set("context7", { failures: 0, lastFailure: 0, isOpen: false });
		this.circuits.set("sentry", { failures: 0, lastFailure: 0, isOpen: false });
	}

	// ===========================================================================
	// LIFECYCLE
	// ===========================================================================

	/**
	 * Initialize all enabled integrations
	 *
	 * Day 4: Integration clients are now managed by the daemon.
	 * This method validates configuration and sets up circuit breakers.
	 */
	async initialize(): Promise<void> {
		if (this.initialized) {
			return;
		}

		if (!this.config.enabled) {
			this.logger.info("Integration orchestrator disabled");
			this.initialized = true;
			return;
		}

		// Day 4: Daemon manages integration clients
		// We just validate configuration here
		const enabledIntegrations: IntegrationName[] = [];
		if (this.config.github.enabled) {
			enabledIntegrations.push("github");
		}
		if (this.config.context7.enabled) {
			enabledIntegrations.push("context7");
		}
		if (this.config.sentry.enabled) {
			enabledIntegrations.push("sentry");
		}

		this.logger.info(
			`Integration orchestrator initialized: ${enabledIntegrations.length} integrations configured (daemon-managed)`,
		);

		this.initialized = true;
	}

	/**
	 * Shutdown all integrations and clear caches
	 * Day 4: Daemon manages client lifecycle, we just clear caches.
	 */
	async shutdown(): Promise<void> {
		// Clear caches
		this.githubCache.clear();
		this.context7Cache.clear();
		this.sentryCache.clear();

		// Reset state
		this.initialized = false;

		this.logger.info("Integration orchestrator shutdown complete");
	}

	// ===========================================================================
	// HEALTH
	// ===========================================================================

	/**
	 * Get health status of all integrations
	 */
	getHealth(): IntegrationHealth {
		const github = this.getIntegrationStatus("github");
		const context7 = this.getIntegrationStatus("context7");
		const sentry = this.getIntegrationStatus("sentry");

		// Determine overall status
		const connectedCount = [github, context7, sentry].filter((s) => s.connected && !s.circuitOpen).length;
		const enabledCount = [github, context7, sentry].filter((s) => s.enabled).length;

		let status: IntegrationHealth["status"];
		if (enabledCount === 0 || connectedCount === enabledCount) {
			status = "healthy";
		} else if (connectedCount > 0) {
			status = "degraded";
		} else {
			status = "unavailable";
		}

		return {
			status,
			integrations: { github, context7, sentry },
			cache: {
				hits: this.cacheHits,
				misses: this.cacheMisses,
				size: this.githubCache.size + this.context7Cache.size + this.sentryCache.size,
			},
		};
	}

	private getIntegrationStatus(name: IntegrationName): IntegrationStatus {
		const circuit = this.circuits.get(name);
		if (!circuit) {
			throw new Error(`Circuit for ${name} not initialized`);
		}
		const config = this.config[name];

		// Day 4: Daemon manages connections, so we check if enabled
		const connected = config.enabled && !circuit.isOpen;

		return {
			enabled: config.enabled,
			connected,
			circuitOpen: circuit.isOpen,
			failureCount: circuit.failures,
			lastError: circuit.failures > 0 ? `${circuit.failures} consecutive failures` : undefined,
		};
	}

	// ===========================================================================
	// ENRICHMENT
	// ===========================================================================

	/**
	 * Enrich context with data from all available integrations
	 *
	 * Day 4: Uses daemon IPC for integration context.
	 * Returns null if no integrations are available. Never throws.
	 *
	 * @param params - Enrichment parameters
	 * @returns Enriched context or null if unavailable
	 */
	async enrichContext(params: EnrichmentParams): Promise<EnrichedContext | null> {
		if (!this.config.enabled || !this.initialized) {
			return null;
		}

		if (!this.workspaceRoot) {
			this.logger.warn("Cannot enrich context: workspaceRoot not set");
			return null;
		}

		const startTime = Date.now();

		try {
			// Day 4: Use daemon IPC for integration context
			const daemonResult = await getIntegrationContextViaDaemon(this.workspaceRoot, {
				files: params.files,
				intent: params.intent,
				skipCache: params.skipCache,
			});

			if (!daemonResult.success || !daemonResult.context) {
				return null;
			}

			const daemonContext = daemonResult.context;
			const contexts = new Map<string, AggregatedContext>();

			// Convert daemon context to AggregatedContext format
			const contextsMap = daemonContext.contexts;
			if (contextsMap && typeof contextsMap === "object") {
				for (const [filePath, ctx] of Object.entries(contextsMap)) {
					const aggregated: AggregatedContext = {
						file: filePath,
						gatheredAt: new Date().toISOString(),
						durationMs: Date.now() - startTime,
						sources: ((ctx as Record<string, unknown>).sources || []) as AggregatedContext["sources"],
						riskFactors: (daemonContext.riskFactors || []) as RiskFactor[],
					};
					contexts.set(filePath, aggregated);
				}
			}

			// Map daemon risk factors to RiskFactor type
			const riskFactors: RiskFactor[] = (daemonContext.riskFactors || []).map((f) => ({
				name: f.name,
				score: f.score,
				description: f.description,
				source: f.source as RiskFactor["source"],
				suggestion: f.suggestion,
				docsUrl: f.docsUrl,
			}));

			return {
				contexts,
				riskFactors,
				riskScore: daemonContext.riskScore || 0,
				sources: (daemonContext.sources || []) as IntegrationName[],
				durationMs: Date.now() - startTime,
			};
		} catch (error) {
			this.logger.warn("Failed to enrich context via daemon", {
				error: error instanceof Error ? error.message : "Unknown",
			});
			return null;
		}
	}

	// ===========================================================================
	// INDIVIDUAL CONTEXT GETTERS
	// ===========================================================================

	/**
	 * Get GitHub context for a file
	 *
	 * Day 4: Uses daemon IPC for integration context.
	 * Returns null if GitHub integration is unavailable or circuit is open.
	 */
	async getGitHubContext(filePath: string, _skipCache = false): Promise<GitHubContext | null> {
		if (!this.canUseIntegration("github") || !this.workspaceRoot) {
			return null;
		}

		// Check cache
		if (!_skipCache && this.config.cache.enabled) {
			const cached = this.getFromCache(this.githubCache, filePath, this.config.cache.githubTtlMs);
			if (cached) {
				this.cacheHits++;
				return cached;
			}
			this.cacheMisses++;
		}

		try {
			// Day 4: Use daemon IPC for GitHub context
			const daemonResult = await getIntegrationContextViaDaemon(this.workspaceRoot, {
				files: [{ path: filePath }],
				intent: "github",
			});

			if (daemonResult.success && daemonResult.context) {
				const githubCtx = daemonResult.context.githubContext as GitHubContext | undefined;
				if (githubCtx) {
					this.recordSuccess("github");
					this.setCache(this.githubCache, filePath, githubCtx);
					return githubCtx;
				}
			}

			return null;
		} catch (error) {
			const msg = error instanceof Error ? error.message : "Unknown error";
			this.recordFailure("github", msg);
			return null;
		}
	}

	/**
	 * Get Context7 documentation validation for a file
	 *
	 * Day 4: Uses daemon IPC for integration context.
	 * Validates imports, API usage, and patterns against current documentation.
	 * Returns null if Context7 integration is unavailable or circuit is open.
	 *
	 * @param filePath - Path to the file being validated
	 * @param content - File content to analyze
	 * @param language - Language identifier (e.g., "typescript", "javascript")
	 * @param skipCache - Skip cache and fetch fresh data
	 */
	async getDocsValidation(
		filePath: string,
		content: string,
		language: string,
		skipCache = false,
	): Promise<DocsValidation | null> {
		if (!this.canUseIntegration("context7") || !this.workspaceRoot) {
			return null;
		}

		// Cache key includes content hash to ensure fresh validation when content changes
		const contentHash = this.hashContent(content);
		const cacheKey = `${filePath}:${language}:${contentHash}`;

		// Check cache
		if (!skipCache && this.config.cache.enabled) {
			const cached = this.getFromCache(this.context7Cache, cacheKey, this.config.cache.context7TtlMs);
			if (cached) {
				this.cacheHits++;
				return cached;
			}
			this.cacheMisses++;
		}

		try {
			// Day 4: Use daemon IPC for Context7 validation
			const daemonResult = await getIntegrationContextViaDaemon(this.workspaceRoot, {
				files: [{ path: filePath, content, language }],
				intent: "context7",
			});

			if (daemonResult.success && daemonResult.context) {
				const docsCtx = daemonResult.context.docsValidation as DocsValidation | undefined;
				if (docsCtx) {
					this.recordSuccess("context7");
					this.setCache(this.context7Cache, cacheKey, docsCtx);
					return docsCtx;
				}
			}

			return null;
		} catch (error) {
			const msg = error instanceof Error ? error.message : "Unknown error";
			this.recordFailure("context7", msg);
			return null;
		}
	}

	/**
	 * Simple content hash for cache key generation
	 */
	private hashContent(content: string): string {
		// Simple hash using first 100 chars + length
		// Good enough for cache invalidation without crypto overhead
		const prefix = content.slice(0, 100).replace(/\s/g, "");
		return `${prefix.length}_${content.length}`;
	}

	/**
	 * Get Sentry error context for a file
	 *
	 * Day 4: Uses daemon IPC for integration context.
	 * Returns null if Sentry integration is unavailable or circuit is open.
	 */
	async getSentryContext(filePath: string, skipCache = false): Promise<SentryContext | null> {
		if (!this.canUseIntegration("sentry") || !this.workspaceRoot) {
			return null;
		}

		// Check cache
		if (!skipCache && this.config.cache.enabled) {
			const cached = this.getFromCache(this.sentryCache, filePath, this.config.cache.sentryTtlMs);
			if (cached) {
				this.cacheHits++;
				return cached;
			}
			this.cacheMisses++;
		}

		try {
			// Day 4: Use daemon IPC for Sentry context
			const daemonResult = await getIntegrationContextViaDaemon(this.workspaceRoot, {
				files: [{ path: filePath }],
				intent: "sentry",
			});

			if (daemonResult.success && daemonResult.context) {
				const sentryCtx = daemonResult.context.sentryContext as SentryContext | undefined;
				if (sentryCtx) {
					this.recordSuccess("sentry");
					this.setCache(this.sentryCache, filePath, sentryCtx);
					return sentryCtx;
				}
			}

			return null;
		} catch (error) {
			const msg = error instanceof Error ? error.message : "Unknown error";
			this.recordFailure("sentry", msg);
			return null;
		}
	}

	// ===========================================================================
	// CIRCUIT BREAKER
	// ===========================================================================

	/**
	 * Check if an integration can be used (enabled, connected, circuit closed)
	 */
	private canUseIntegration(name: IntegrationName): boolean {
		const config = this.config[name];
		if (!config.enabled) {
			return false;
		}

		const circuit = this.circuits.get(name);
		if (!circuit) {
			throw new Error(`Circuit for ${name} not initialized`);
		}

		// Check if circuit should be reset (recovery time passed)
		if (circuit.isOpen) {
			const timeSinceFailure = Date.now() - circuit.lastFailure;
			if (timeSinceFailure >= this.config.circuitBreaker.recoveryTimeMs) {
				// Reset circuit to half-open state (allow one attempt)
				circuit.isOpen = false;
				circuit.failures = 0;
				this.logger.info(`Circuit breaker reset for ${name} (recovery time passed)`);
			} else {
				return false;
			}
		}

		return true;
	}

	/**
	 * Record a successful call (resets failure count)
	 */
	private recordSuccess(name: IntegrationName): void {
		const circuit = this.circuits.get(name);
		if (!circuit) {
			throw new Error(`Circuit for ${name} not initialized`);
		}
		circuit.failures = 0;
		circuit.isOpen = false;
	}

	/**
	 * Record a failed call (may open circuit)
	 */
	private recordFailure(name: IntegrationName, error: string): void {
		const circuit = this.circuits.get(name);
		if (!circuit) {
			throw new Error(`Circuit for ${name} not initialized`);
		}
		circuit.failures++;
		circuit.lastFailure = Date.now();

		if (circuit.failures >= this.config.circuitBreaker.failureThreshold) {
			circuit.isOpen = true;
			this.logger.warn(`Circuit breaker opened for ${name} after ${circuit.failures} failures`, { error });
		}
	}

	// ===========================================================================
	// CACHE
	// ===========================================================================

	private getFromCache<T>(cache: Map<string, CacheEntry<T>>, key: string, _ttlMs: number): T | null {
		const entry = cache.get(key);
		if (!entry) {
			return null;
		}

		// Check if expired
		if (Date.now() > entry.expiresAt) {
			cache.delete(key);
			return null;
		}

		return entry.data;
	}

	private setCache<T>(cache: Map<string, CacheEntry<T>>, key: string, data: T): void {
		// Enforce max entries (LRU eviction)
		if (cache.size >= this.config.cache.maxEntries) {
			// Delete oldest entry (first in map iteration order)
			const firstKey = cache.keys().next().value;
			if (firstKey) {
				cache.delete(firstKey);
			}
		}

		// Determine TTL based on cache type
		let ttlMs = this.config.cache.githubTtlMs;
		if (cache === this.context7Cache) {
			ttlMs = this.config.cache.context7TtlMs;
		}
		if (cache === this.sentryCache) {
			ttlMs = this.config.cache.sentryTtlMs;
		}

		cache.set(key, {
			data,
			expiresAt: Date.now() + ttlMs,
		});
	}

	/**
	 * Clear all caches
	 */
	clearCache(): void {
		this.githubCache.clear();
		this.context7Cache.clear();
		this.sentryCache.clear();
		this.cacheHits = 0;
		this.cacheMisses = 0;
	}

	private mergeConfig(partial?: Partial<OrchestratorConfig>): OrchestratorConfig {
		if (!partial) {
			return { ...DEFAULT_CONFIG };
		}

		return {
			enabled: partial.enabled ?? DEFAULT_CONFIG.enabled,
			github: { ...DEFAULT_CONFIG.github, ...partial.github },
			context7: { ...DEFAULT_CONFIG.context7, ...partial.context7 },
			sentry: { ...DEFAULT_CONFIG.sentry, ...partial.sentry },
			cache: { ...DEFAULT_CONFIG.cache, ...partial.cache },
			circuitBreaker: { ...DEFAULT_CONFIG.circuitBreaker, ...partial.circuitBreaker },
		};
	}
}

// =============================================================================
// LOGGER INTERFACE
// =============================================================================

export interface OrchestratorLogger {
	debug(msg: string, data?: unknown): void;
	info(msg: string, data?: unknown): void;
	warn(msg: string, data?: unknown): void;
	error(msg: string, data?: unknown): void;
}

const defaultLogger: OrchestratorLogger = {
	debug: (_msg, _data) => {
		// no-op: default logger discards messages until a real logger is injected
	},
	info: (_msg, _data) => {
		// no-op: default logger discards messages until a real logger is injected
	},
	warn: (_msg, _data) => {
		// no-op: default logger discards messages until a real logger is injected
	},
	error: (_msg, _data) => {
		// no-op: default logger discards messages until a real logger is injected
	},
};

// =============================================================================
// SINGLETON FACTORY
// =============================================================================

let instance: IntegrationOrchestratorService | null = null;

/**
 * Get or create the singleton orchestrator instance
 *
 * @param config - Configuration (only used on first call)
 * @param logger - Optional logger
 */
export function getIntegrationOrchestratorService(
	config?: Partial<OrchestratorConfig>,
	logger?: OrchestratorLogger,
): IntegrationOrchestratorService {
	if (!instance) {
		instance = new IntegrationOrchestratorService(config, logger);
	}
	return instance;
}

/**
 * Create a new orchestrator instance (for testing)
 */
export function createIntegrationOrchestratorService(
	config?: Partial<OrchestratorConfig>,
	logger?: OrchestratorLogger,
): IntegrationOrchestratorService {
	return new IntegrationOrchestratorService(config, logger);
}

/**
 * Reset the singleton instance (for testing)
 */
export function resetIntegrationOrchestratorService(): void {
	if (instance) {
		instance.shutdown().catch(() => {
			// Intentionally ignored: shutdown during reset is best-effort
		});
		instance = null;
	}
}

/**
 * Create orchestrator config from environment variables
 */
export function createOrchestratorConfigFromEnv(): Partial<OrchestratorConfig> {
	return {
		enabled: process.env.VREKO_INTEGRATIONS_ENABLED !== "false",
		github: {
			enabled: !!process.env.GITHUB_PERSONAL_ACCESS_TOKEN || !!process.env.GITHUB_TOKEN,
			token: process.env.GITHUB_PERSONAL_ACCESS_TOKEN ?? process.env.GITHUB_TOKEN,
			owner: process.env.VREKO_GITHUB_OWNER,
			repo: process.env.VREKO_GITHUB_REPO,
			timeoutMs: Number.parseInt(process.env.VREKO_GITHUB_TIMEOUT_MS ?? "5000", 10),
		},
		context7: {
			enabled: !!process.env.CONTEXT7_API_KEY,
			apiKey: process.env.CONTEXT7_API_KEY,
			timeoutMs: Number.parseInt(process.env.VREKO_CONTEXT7_TIMEOUT_MS ?? "5000", 10),
		},
		sentry: {
			enabled: !!process.env.SENTRY_AUTH_TOKEN,
			authToken: process.env.SENTRY_AUTH_TOKEN,
			organization: process.env.SENTRY_ORGANIZATION,
			project: process.env.SENTRY_PROJECT,
			timeoutMs: Number.parseInt(process.env.VREKO_SENTRY_TIMEOUT_MS ?? "5000", 10),
		},
	};
}

// =============================================================================
// MCP CONFIG DETECTION
// =============================================================================

/**
 * Detected MCP server configuration from user's config files
 */
export interface DetectedMCPServer {
	/** Server name as configured */
	name: string;
	/** Command to run the server */
	command: string;
	/** Arguments passed to the command */
	args: string[];
	/** Environment variables */
	env?: Record<string, string>;
	/** Source config file path */
	source: string;
}

/**
 * Result of MCP config detection
 */
export interface MCPConfigDetectionResult {
	/** All detected MCP servers */
	servers: DetectedMCPServer[];
	/** Specifically detected integration servers */
	detected: {
		github: DetectedMCPServer | null;
		context7: DetectedMCPServer | null;
		sentry: DetectedMCPServer | null;
	};
	/** Installation recommendations for missing servers */
	recommendations: MCPInstallRecommendation[];
	/** Config files that were checked */
	configFilesChecked: string[];
}

/**
 * Recommendation for installing an MCP server
 */
export interface MCPInstallRecommendation {
	/** Integration name */
	integration: IntegrationName;
	/** Why it's recommended */
	reason: string;
	/** Command to add to .mcp.json */
	mcpConfig: {
		command: string;
		args: string[];
	};
	/** Documentation URL */
	docsUrl: string;
}

/**
 * Known MCP server patterns for detection
 */
const KNOWN_MCP_PATTERNS: Record<IntegrationName, RegExp[]> = {
	github: [/github/i, /gh-mcp/i, /@modelcontextprotocol\/server-github/i],
	context7: [/context7/i, /@upstash\/context7-mcp/i, /c7-mcp/i],
	sentry: [/sentry/i, /@sentry\/mcp/i, /sentry-mcp/i],
};

/**
 * Installation recommendations for each integration
 */
const INSTALL_RECOMMENDATIONS: Record<IntegrationName, Omit<MCPInstallRecommendation, "integration">> = {
	github: {
		reason: "Enables PR context, file blame, and change frequency analysis",
		mcpConfig: {
			command: "npx",
			args: ["-y", "@modelcontextprotocol/server-github"],
		},
		docsUrl: "https://github.com/modelcontextprotocol/servers/tree/main/src/github",
	},
	context7: {
		reason: "Validates imports against official documentation, detects deprecated APIs",
		mcpConfig: {
			command: "npx",
			args: ["-y", "@upstash/context7-mcp@latest"],
		},
		docsUrl: "https://context7.dev/docs",
	},
	sentry: {
		reason: "Provides production error context for files being modified",
		mcpConfig: {
			command: "npx",
			args: ["-y", "@sentry/mcp-server"],
		},
		docsUrl: "https://docs.sentry.io/platforms/javascript/guides/node/",
	},
};

/**
 * Get paths to check for MCP configuration files
 */
function getMCPConfigPaths(workspaceRoot?: string): string[] {
	const paths: string[] = [];
	const home = homedir();

	// Project-scope configs (highest priority)
	if (workspaceRoot) {
		paths.push(join(workspaceRoot, ".mcp.json"));
		paths.push(join(workspaceRoot, ".claude", "mcp.json"));
	}

	// User-scope configs
	paths.push(join(home, ".claude.json"));
	paths.push(join(home, ".claude", "mcp.json"));

	// Claude Desktop config (for reference)
	if (process.platform === "darwin") {
		paths.push(join(home, "Library", "Application Support", "Claude", "claude_desktop_config.json"));
	} else if (process.platform === "win32") {
		const appData = process.env.APPDATA ?? join(home, "AppData", "Roaming");
		paths.push(join(appData, "Claude", "claude_desktop_config.json"));
	}

	return paths;
}

/**
 * Parse MCP config file and extract servers
 */
function parseMCPConfigFile(filePath: string): DetectedMCPServer[] {
	try {
		if (!existsSync(filePath)) {
			return [];
		}

		const content = readFileSync(filePath, "utf-8");
		const config = JSON.parse(content) as { mcpServers?: Record<string, unknown> };

		if (!config.mcpServers || typeof config.mcpServers !== "object") {
			return [];
		}

		const servers: DetectedMCPServer[] = [];

		for (const [name, serverConfig] of Object.entries(config.mcpServers)) {
			if (typeof serverConfig === "object" && serverConfig !== null) {
				const cfg = serverConfig as Record<string, unknown>;
				servers.push({
					name,
					command: String(cfg.command ?? ""),
					args: Array.isArray(cfg.args) ? cfg.args.map(String) : [],
					env:
						typeof cfg.env === "object" && cfg.env !== null
							? Object.fromEntries(
									Object.entries(cfg.env as Record<string, unknown>).map(([k, v]) => [k, String(v)]),
								)
							: undefined,
					source: filePath,
				});
			}
		}

		return servers;
	} catch {
		// Invalid JSON or read error - skip this file
		return [];
	}
}

/**
 * Match a server to a known integration
 */
function matchServerToIntegration(server: DetectedMCPServer): IntegrationName | null {
	const searchText = `${server.name} ${server.command} ${server.args.join(" ")}`.toLowerCase();

	for (const [integration, patterns] of Object.entries(KNOWN_MCP_PATTERNS)) {
		for (const pattern of patterns) {
			if (pattern.test(searchText)) {
				return integration as IntegrationName;
			}
		}
	}

	return null;
}

/**
 * Detect MCP server configurations from user's config files
 *
 * Checks multiple config file locations:
 * - Project: .mcp.json, .claude/mcp.json
 * - User: ~/.claude.json, ~/.claude/mcp.json
 * - Claude Desktop: platform-specific paths
 *
 * @param workspaceRoot - Optional workspace root for project-scope configs
 * @returns Detection result with servers, recommendations, and checked paths
 *
 * @example
 * ```typescript
 * const detection = detectMCPConfig("/path/to/project");
 *
 * if (detection.detected.context7) {
 *   logger.debug(...);
 * } else {
 *   logger.debug(...);
 * }
 * ```
 */
export function detectMCPConfig(workspaceRoot?: string): MCPConfigDetectionResult {
	const configPaths = getMCPConfigPaths(workspaceRoot);
	const allServers: DetectedMCPServer[] = [];
	const checkedPaths: string[] = [];

	// Parse all config files
	for (const configPath of configPaths) {
		checkedPaths.push(configPath);
		const servers = parseMCPConfigFile(configPath);
		allServers.push(...servers);
	}

	// Match servers to known integrations
	const detected: MCPConfigDetectionResult["detected"] = {
		github: null,
		context7: null,
		sentry: null,
	};

	for (const server of allServers) {
		const integration = matchServerToIntegration(server);
		if (integration && !detected[integration]) {
			detected[integration] = server;
		}
	}

	// Generate recommendations for missing integrations
	const recommendations: MCPInstallRecommendation[] = [];

	for (const integration of ["github", "context7", "sentry"] as IntegrationName[]) {
		if (!detected[integration]) {
			recommendations.push({
				integration,
				...INSTALL_RECOMMENDATIONS[integration],
			});
		}
	}

	return {
		servers: allServers,
		detected,
		recommendations,
		configFilesChecked: checkedPaths,
	};
}

/**
 * Get a human-readable summary of MCP config detection
 */
export function getMCPConfigSummary(detection: MCPConfigDetectionResult): string {
	const lines: string[] = [];

	// Detected servers
	const detectedCount = Object.values(detection.detected).filter(Boolean).length;
	lines.push(`MCP Integrations: ${detectedCount}/3 detected`);

	for (const [name, server] of Object.entries(detection.detected)) {
		if (server) {
			lines.push(`  ✓ ${name}: ${server.source}`);
		} else {
			lines.push(`  ○ ${name}: not configured`);
		}
	}

	// Recommendations
	if (detection.recommendations.length > 0) {
		lines.push("");
		lines.push("Recommendations:");
		for (const rec of detection.recommendations) {
			lines.push(
				`  Add to .mcp.json: "${rec.integration}": { "command": "${rec.mcpConfig.command}", "args": ${JSON.stringify(rec.mcpConfig.args)} }`,
			);
		}
	}

	return lines.join("\n");
}
