/**
 * @deprecated Use vreko_begin / vreko_learn / vreko_end / vreko_pulse instead.
 * This tool will be removed after telemetry confirms zero usage (target: 30 days post-Pioneer).
 * See: daemon-mcp-cli-integration-v1 spec, WS-1.2
 */

/**
 * Snap Session Tool
 *
 * Query daemon for current development session state.
 * Returns: files touched, edit velocity, AI attribution, snapshot activity.
 *
 * This tool queries the daemon's session state (not local MCP state).
 * Use snap_status for MCP-level session status.
 *
 * @module tools/consolidated/vreko-session
 */

import { getSessionChangesViaDaemon, getSessionStatusViaService } from "../../daemon/local-service-adapter.js";
import type { ToolContext, ToolHandler, VrekoTool } from "../../types/tool-types.js";

// =============================================================================
// Types
// =============================================================================

/**
 * Snap session parameters (no params needed - queries current workspace)
 */
export interface SnapSessionParams {
	/** Include AI attribution details */
	includeAIAttribution?: boolean;
}

/**
 * Session state returned from daemon
 */
interface SessionState {
	active: boolean;
	taskId?: string;
	task?: string;
	startedAt?: string;
	filesModified: number;
	snapshotCount: number;
	durationMin?: number;
	editVelocity?: number;
	aiAttributedChanges?: number;
}

// =============================================================================
// Tool Implementation
// =============================================================================

const handler: ToolHandler = async (args: Record<string, unknown>, context: ToolContext) => {
	const params = args as SnapSessionParams;
	const { workspaceRoot } = context;

	// Query daemon for session state
	const sessionState = await getSessionStatusViaService(workspaceRoot);

	if (!sessionState) {
		return {
			content: [
				{
					type: "text",
					text: JSON.stringify({
						active: false,
						message: "No active session or daemon unavailable",
					}),
				},
			],
		};
	}

	// Calculate derived metrics
	const durationMin = sessionState.startedAt
		? Math.floor((Date.now() - new Date(sessionState.startedAt).getTime()) / 60000)
		: 0;

	const result: SessionState = {
		active: sessionState.active,
		taskId: sessionState.taskId,
		task: sessionState.task,
		startedAt: sessionState.startedAt,
		filesModified: sessionState.filesModified,
		snapshotCount: sessionState.snapshotCount,
		durationMin,
	};

	// Include AI attribution if requested
	if (params.includeAIAttribution) {
		// Fetch session file changes from daemon and count AI-attributed files
		const sessionChanges = await getSessionChangesViaDaemon(workspaceRoot, { includeAIAttribution: true });
		result.aiAttributedChanges = sessionChanges
			? sessionChanges.files.filter((f) => f.aiAttributed === true).length
			: 0;
	}

	// Build human-readable summary
	const statusEmoji = sessionState.active ? "🟢" : "⚪";
	const taskText = sessionState.task ? `\n📋 **Task:** ${sessionState.task}` : "";
	const durationText = durationMin > 0 ? `\n⏱️ **Duration:** ${durationMin} min` : "";
	const filesText = `\n📁 **Files Modified:** ${sessionState.filesModified}`;
	const snapshotsText = `\n📸 **Snapshots:** ${sessionState.snapshotCount}`;

	const humanText =
		`## Session Status ${statusEmoji}\n` +
		`**Active:** ${sessionState.active ? "Yes" : "No"}` +
		taskText +
		durationText +
		filesText +
		snapshotsText;

	return {
		content: [
			{
				type: "text",
				text: `${JSON.stringify(result)}\n\n${humanText}`,
			},
		],
	};
};

// =============================================================================
// Tool Definition
// =============================================================================

export const snapSessionTool: VrekoTool = {
	name: "vreko_session",
	description:
		"[DEPRECATED  -  use vreko_begin/vreko_learn/vreko_end/vreko_pulse] 📊 Get current development session state from daemon: files touched, duration, snapshots. " +
		"Query the daemon's session tracking for real-time state.",
	inputSchema: {
		type: "object",
		properties: {
			includeAIAttribution: {
				type: "boolean",
				description: "Include AI attribution details (default: false)",
			},
		},
	},
	annotations: {
		title: "📊 Session State",
		readOnlyHint: true,
		destructiveHint: false,
		idempotentHint: true,
	},
};

/**
 * Handler export for registry
 */
export const handleSnapSession = handler;
