/**
 * Workspace Resolution Utility
 *
 * Delegates to the existing workspace resolution mechanism.
 * The workspace root is typically provided via ToolContext.
 *
 * Bug 2 Fix: Normalizes workspace paths to prevent lookup failures
 * due to trailing slashes, symlinks, or case differences.
 *
 * @module tools/v2/utils/workspace
 */

import { resolve } from "node:path";
import type { ToolContext } from "../../../types/tool-types.js";

/**
 * Normalize a workspace path for consistent Map lookups.
 *
 * MCP, CLI, and extension may resolve paths differently:
 * - Trailing slashes: "/workspace/" vs "/workspace"
 * - Symlinks: resolved vs original path
 * - Relative vs absolute: "./workspace" vs "/full/path/workspace"
 *
 * This function normalizes at the boundary to prevent "same workspace, different string" bugs
 * that cause session lookup failures between vreko and vreko_end.
 */
function normalizeWorkspacePath(p: string): string {
	return resolve(p).replace(/\/+$/, "");
}

/**
 * Resolve the workspace root from the tool context.
 *
 * The workspace root is always available in the ToolContext
 * passed to tool handlers by the MCP server.
 *
 * Bug 2 Fix: Normalizes the path before returning to ensure
 * consistent lookups across all V2 tools.
 */
export function resolveWorkspace(context: ToolContext): string {
	const workspaceRoot = context.workspaceRoot;

	if (!workspaceRoot) {
		throw new Error("Workspace root not available in tool context");
	}

	// Bug 2 Fix: Normalize path to prevent lookup failures
	return normalizeWorkspacePath(workspaceRoot);
}
