export interface SnapshotSuggestion {
	id: string;
	score: number;
	confidence: number;
	reasoning: string;
	files: string[];
}

export interface WorkspaceVitalsSnapshot {
	pressure: number;
	snapshotCount: number;
	trajectory: "improving" | "stable" | "degrading" | "critical";
}

/**
 * snapshot_create - Create snapshot with auto-retry, diagnosis, and duplicate detection
 */
export const handleSnapshotCreate: ToolHandler = async (args, context) => {
	const { files, reason, trigger } = args as {
		files?: string[];
		reason?: string;
		trigger?: string;
	};

	if (!files || files.length === 0) {
		return errorJsonResult(CommonErrors.missingParam("files"));
	}

	// P0-004: Validate file paths for traversal attacks
	const pathValidation = validateFilePaths(files, context.workspaceRoot);
	if (!pathValidation.valid) {
		return errorJsonResult(CommonErrors.pathTraversalBlocked(pathValidation.invalidPath, pathValidation.error));
	}

	// Check if readonly mode - if so, reject write operations with helpful guidance
	if (context.storageMode === "readonly" || context.storageMode === "remote") {
		return errorJsonResult({
			status: "error",
			error: "E503_SNAPSHOT_SETUP_NEEDED",
			message: "Enable snapshots with quick local setup",
			action: {
				type: "cli_install",
				command: "npm install -g @vreko/cli && vreko tools configure",
				description: "One command enables full snapshot capabilities",
				time_estimate: "~30 seconds",
			},
			help_url: "https://docs.vreko.dev/cli/setup",
			_llm: {
				suggest: "I can enable snapshots for you with a quick CLI install. Want me to help?",
				auto_offer: true,
			},
		});
	}

	// Enhancement #1: Duplicate snapshot prevention (best-effort)
	// Daemon list returns fileCount only (not blobId per file), so full dedup
	// is delegated to the daemon. MCP-side hash check is skipped.
	const daemonSnapshots = await listSnapshotsViaDaemon(context.workspaceRoot, 20);
	void daemonSnapshots; // reserved for future daemon-supported dedup

	// Route snapshot creation through daemon IPC  -  daemon reads file content from workspace
	try {
		const daemonResult = await createSnapshotViaDaemon(context.workspaceRoot, files, {
			reason,
			trigger: (trigger as "manual" | "auto" | "ai-detection") || "manual",
		});

		if (!daemonResult.success || !daemonResult.snapshotId) {
			return errorJsonResult({
				status: "error",
				error: "E106_SNAPSHOT_CREATION_FAILED",
				message: daemonResult.error || "Daemon failed to create snapshot",
				next_actions: [],
			});
		}

		return jsonResult(
			{
				status: "success",
				snapshotId: daemonResult.snapshotId,
				fileCount: daemonResult.fileCount ?? files.length,
				totalSize: daemonResult.totalSize ?? 0,
				createdAt: daemonResult.createdAt ?? new Date().toISOString(),
				message: `Snapshot created with ${daemonResult.fileCount ?? files.length} file(s)`,
				attempts: 1,
				autoFixed: false,
				next_actions: buildSmartActions([{ tool: "snapshot_list", reason: "Verify snapshot", priority: 2 }], {
					hasUnsavedChanges: false,
					lastSnapshotMinutes: 0,
				}),
			},
			{ context, coaching: { lastAction: "snapshot_create", taskPhase: "working" } },
		);
	} catch (error) {
		const lastError = error instanceof Error ? error : new Error(String(error));
		const diagnosis = diagnoseSnapshotFailure(lastError, files, context.workspaceRoot);
		const formattedDiagnosis = formatDiagnosis(diagnosis);

		return errorJsonResult({
			status: "error",
			error: "E106_SNAPSHOT_CREATION_FAILED",
			message: lastError.message,
			diagnosis: {
				type: diagnosis.type,
				message: diagnosis.message,
				cause: diagnosis.cause,
				suggestedFix: diagnosis.suggestedFix,
				userAction: diagnosis.userAction,
				confidence: diagnosis.confidence,
				affectedFiles: diagnosis.affectedFiles,
			},
			formatted: formattedDiagnosis,
			next_actions: diagnosis.canAutoFix
				? [{ tool: "snapshot_create", priority: 1, reason: "Retry with manual fix" }]
				: [],
		});
	}
};

/**
 * snapshot_list - List snapshots
 */
export const handleSnapshotList: ToolHandler = async (args, context) => {
	const { limit = 20, since } = args as { limit?: number; since?: string };

	let snapshots = await listSnapshotsViaDaemon(context.workspaceRoot, limit);

	// Filter by since if provided
	if (since) {
		const sinceTime = new Date(since).getTime();
		snapshots = snapshots.filter((s) => new Date(s.createdAt).getTime() >= sinceTime);
	}

	// Limit results
	snapshots = snapshots.slice(0, limit);

	return jsonResult({
		status: "success",
		count: snapshots.length,
		snapshots: snapshots.map((s) => ({
			id: s.id,
			createdAt: new Date(s.createdAt).toISOString(),
			fileCount: s.fileCount,
			totalSize: 0,
			description: s.reason,
			trigger: undefined,
			files: [],
		})),
		next_actions:
			snapshots.length > 0
				? [
						{
							tool: "snapshot_restore",
							priority: 2,
							reason: "Restore if needed",
							args: { snapshotId: snapshots[0].id },
						},
					]
				: [{ tool: "snapshot_create", priority: 1, reason: "No snapshots yet" }],
	});
};

/**
 * snapshot_restore - Restore snapshot
 */
export const handleSnapshotRestore: ToolHandler = async (args, context) => {
	const {
		snapshotId,
		files: filterFiles,
		dryRun,
	} = args as {
		snapshotId?: string;
		files?: string[];
		dryRun?: boolean;
	};

	if (!snapshotId) {
		return errorJsonResult(CommonErrors.missingParam("snapshotId"));
	}

	// P0-004: Validate filter file paths if provided
	if (filterFiles && filterFiles.length > 0) {
		const pathValidation = validateFilePaths(filterFiles, context.workspaceRoot);
		if (!pathValidation.valid) {
			return errorJsonResult(CommonErrors.pathTraversalBlocked(pathValidation.invalidPath, pathValidation.error));
		}
	}

	const daemon = createDaemonClient(context.workspaceRoot);

	try {
		// Get snapshot metadata via daemon  -  validates existence and provides file list
		const snapInfo = await daemon.request<{
			snapshot?: { files: Array<{ path: string }> };
		}>("snapshot/get", { workspace: context.workspaceRoot, snapshotId });

		if (!snapInfo?.snapshot) {
			return errorJsonResult(CommonErrors.snapshotNotFound(snapshotId));
		}

		const allSnapshotFiles = snapInfo.snapshot.files.map((f) => f.path);
		const filesToRestorePaths = filterFiles
			? allSnapshotFiles.filter((p) => filterFiles.includes(p))
			: allSnapshotFiles;

		if (dryRun) {
			return jsonResult({
				status: "dry_run",
				snapshotId,
				wouldRestore: filesToRestorePaths.map((p) => ({ path: p, size: 0 })),
				message: `Would restore ${filesToRestorePaths.length} file(s)`,
			});
		}

		// P0-005: Create backup snapshot of current files BEFORE overwriting
		// Daemon reads current disk content when creating the backup snapshot
		const existingFilePaths = filesToRestorePaths.filter((p) => existsSync(join(context.workspaceRoot, p)));
		let backupSnapshotId: string | null = null;
		if (existingFilePaths.length > 0) {
			const backup = await createSnapshotViaDaemon(context.workspaceRoot, existingFilePaths, {
				reason: `Auto-backup before restore from ${snapshotId}`,
				trigger: "auto",
			});
			if (backup.success && backup.snapshotId) {
				backupSnapshotId = backup.snapshotId;
			}
		}

		// Restore via daemon  -  daemon writes files to disk
		const restoreResult = await restoreSnapshotViaDaemon(context.workspaceRoot, snapshotId, {
			files: filterFiles,
			dryRun: false,
		});

		if (!restoreResult.success) {
			return result(`Snapshot restore failed: ${restoreResult.errors?.[0] ?? "unknown error"}`, true);
		}

		return jsonResult({
			status: "success",
			snapshotId,
			backupSnapshotId,
			restoredFiles: restoreResult.restoredFiles ?? [],
			message: `Restored ${(restoreResult.restoredFiles ?? []).length} file(s) from snapshot${backupSnapshotId ? ` (backup: ${backupSnapshotId})` : ""}`,
			next_actions: [{ tool: "prepare_workspace", priority: 1, reason: "Verify workspace state" }],
		});
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		return result(`Snapshot restore failed: ${message}`, true);
	}
};

/**
 * suggest_snapshot - Proactive snapshot suggestion via daemon IPC
 * @see Archaeological Feedback Synthesis - P0: Proactive Snapshot Suggestion
 */
export const handleSuggestSnapshot: ToolHandler = async (args, context) => {
	const { files } = args as { files?: string[] };

	try {
		// Day 4: Get vitals from daemon
		const vitalsResult = await getVitalsViaDaemon(context.workspaceRoot);
		const vitals =
			vitalsResult.success && vitalsResult.vitals ? vitalsResult.vitals : { pressure: 0, snapshotCount: 0 };

		// Get recent snapshots to assess snapshot frequency
		const snapshots = await listSnapshotsViaDaemon(context.workspaceRoot, 5);

		// Simple heuristic-based suggestion (daemon-first architecture)
		const pressure = vitals.pressure ?? 0;
		const snapshotCount = vitals.snapshotCount ?? snapshots.length;

		// Determine recommendation based on pressure and snapshot frequency
		let recommendation: "now" | "soon" | "continue" = "continue";
		let reason = "Workspace is stable";
		let urgency = "low";

		if (pressure >= 60) {
			recommendation = "now";
			reason = "High pressure detected - immediate snapshot recommended";
			urgency = "high";
		} else if (pressure >= 40) {
			recommendation = "soon";
			reason = "Moderate pressure - consider creating a snapshot";
			urgency = "medium";
		} else if (snapshotCount === 0) {
			recommendation = "soon";
			reason = "No snapshots in this session - consider creating one";
			urgency = "medium";
		}

		// Enhance with file-specific context if provided
		let criticalFilesTouched = 0;
		if (files && files.length > 0) {
			const sensitiveTouched = files.filter((f) => SENSITIVE_PATTERNS.some((p) => p.test(f)));
			criticalFilesTouched = sensitiveTouched.length;

			if (criticalFilesTouched > 0 && recommendation === "continue") {
				recommendation = "soon";
				reason = "Sensitive files modified - consider creating a snapshot";
				urgency = "medium";
			}
		}

		// Build actionable response
		const nextActions =
			recommendation === "now"
				? [{ tool: "snapshot_create", priority: 1, reason, args: { files } }]
				: recommendation === "soon"
					? [{ tool: "snapshot_create", priority: 2, reason, args: { files } }]
					: [];

		return jsonResult({
			status: "success",
			urgency,
			recommendation,
			reason,
			metrics: {
				pressureRate: pressure / 100,
				aiActivityBurst: false,
				criticalFilesTouched,
				trajectoryConfidence: 0.7,
			},
			vitals: {
				pressure,
				snapshotCount,
				trajectory: pressure >= 60 ? "critical" : pressure >= 40 ? "degrading" : "stable",
			},
			message:
				recommendation === "now"
					? `⚠️ Snapshot recommended NOW: ${reason}`
					: recommendation === "soon"
						? `🕔 Snapshot recommended soon: ${reason}`
						: `✅ Continue working: ${reason}`,
			next_actions: nextActions,
		});
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		return result(`Snapshot suggestion failed: ${message}`, true);
	}
};

/**
 * compare_snapshots - Compare two snapshots or snapshot to current state
 * @see Archaeological Feedback Synthesis - P1: Snapshot Comparison Tool
 */
export const handleCompareSnapshots: ToolHandler = async (args, context) => {
	const {
		snapshotId,
		targetId,
		files: filterFiles,
	} = args as {
		snapshotId?: string;
		targetId?: string;
		files?: string[];
	};

	if (!snapshotId) {
		return errorJsonResult(CommonErrors.missingParam("snapshotId"));
	}

	try {
		const daemon = createDaemonClient(context.workspaceRoot);
		const diffCalculator = new DiffCalculator();

		// Get source snapshot via daemon (content is optional in response)
		const sourceData = await daemon.request<{
			snapshot?: { files: Array<{ path: string; content?: string }> };
		}>("snapshot/get", { workspace: context.workspaceRoot, snapshotId });

		if (!sourceData?.snapshot) {
			return errorJsonResult(CommonErrors.snapshotNotFound(snapshotId));
		}

		const sourceFileMap: Map<string, string | null> = new Map(
			sourceData.snapshot.files.map((f) => [f.path, f.content ?? null]),
		);

		// Get target content (another snapshot or current filesystem)
		let targetFileMap: Map<string, string | null>;
		let targetLabel: string;

		if (targetId) {
			const targetData = await daemon.request<{
				snapshot?: { files: Array<{ path: string; content?: string }> };
			}>("snapshot/get", { workspace: context.workspaceRoot, snapshotId: targetId });

			if (!targetData?.snapshot) {
				return errorJsonResult(CommonErrors.snapshotNotFound(targetId));
			}
			targetFileMap = new Map(targetData.snapshot.files.map((f) => [f.path, f.content ?? null]));
			targetLabel = `snapshot ${targetId}`;
		} else {
			// Compare to current filesystem
			targetFileMap = new Map();
			for (const [path] of sourceFileMap) {
				const fullPath = join(context.workspaceRoot, path as string);
				if (existsSync(fullPath)) {
					targetFileMap.set(path as string, readFileSync(fullPath, "utf8"));
				}
			}
			targetLabel = "current filesystem";
		}

		// Determine files to compare
		const allPaths = new Set([...sourceFileMap.keys(), ...targetFileMap.keys()]);
		let pathsToCompare: string[] = Array.from(allPaths);

		if (filterFiles && filterFiles.length > 0) {
			pathsToCompare = pathsToCompare.filter((p) => filterFiles.includes(p));
		}

		// Calculate diffs  -  content may be null if daemon didn't return it
		const diffs = pathsToCompare.map((path) => {
			const sourceContent = sourceFileMap.get(path) ?? null;
			const targetContent = targetFileMap.get(path) ?? null;
			return diffCalculator.calculateFileDiff(path, sourceContent, targetContent);
		});

		const preview = diffCalculator.generateDiffPreview(diffs);

		return jsonResult({
			status: "success",
			sourceSnapshot: snapshotId,
			target: targetId ?? "current",
			stats: {
				totalFiles: preview.totalFiles,
				filesCreated: preview.filesCreated,
				filesModified: preview.filesModified,
				filesDeleted: preview.filesDeleted,
				linesAdded: preview.totalLinesAdded,
				linesRemoved: preview.totalLinesRemoved,
			},
			files: diffs.map((d) => ({
				path: d.path,
				operation: d.operation,
				linesAdded: d.linesAdded,
				linesRemoved: d.linesRemoved,
				preview: d.preview,
			})),
			message: `Compared snapshot ${snapshotId} to ${targetLabel}: ${preview.filesModified} modified, +${preview.totalLinesAdded}/-${preview.totalLinesRemoved} lines`,
			next_actions:
				preview.filesModified > 0
					? [
							{
								tool: "snapshot_restore",
								priority: 2,
								reason: "Restore if changes unwanted",
								args: { snapshotId },
							},
						]
					: [],
		});
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		return result(`Snapshot comparison failed: ${message}`, true);
	}
};
