/**
 * Vreko MCP Error Codes
 *
 * Standardized error codes for consistent error handling across all MCP tools.
 * Aligned with JSON-RPC 2.0 standards and industry best practices.
 *
 * @module errors
 */

// =============================================================================
// Error Code Categories
// =============================================================================

/**
 * Error Code Ranges:
 * - 0xx: Protocol/System errors (JSON-RPC alignment)
 * - 1xx: Request/Parameter errors (Client errors)
 * - 2xx: File/Resource errors
 * - 3xx: Snapshot/State errors
 * - 4xx: Validation/Check errors
 * - 5xx: Internal/Server errors
 */

// =============================================================================
// 0xx: Protocol/System Errors
// =============================================================================

/** Invalid JSON-RPC request format */
export const E001_INVALID_REQUEST = "E001_INVALID_REQUEST";

/** MCP tool method not found */
export const E002_METHOD_NOT_FOUND = "E002_METHOD_NOT_FOUND";

/** MCP server not initialized */
export const E003_NOT_INITIALIZED = "E003_NOT_INITIALIZED";

/** Connection to daemon/service lost */
export const E004_CONNECTION_LOST = "E004_CONNECTION_LOST";

/** Request timeout exceeded */
export const E005_TIMEOUT = "E005_TIMEOUT";

/** Protocol version mismatch */
export const E006_VERSION_MISMATCH = "E006_VERSION_MISMATCH";

// =============================================================================
// 1xx: Request/Parameter Errors
// =============================================================================

/** Required parameter missing */
export const E101_MISSING_PARAM = "E101_MISSING_PARAM";

/** Parameter validation failed */
export const E102_INVALID_PARAM = "E102_INVALID_PARAM";

/** Parameter type mismatch */
export const E103_TYPE_MISMATCH = "E103_TYPE_MISMATCH";

/** Invalid workspace path */
export const E104_INVALID_WORKSPACE = "E104_INVALID_WORKSPACE";

/** Invalid session ID */
export const E105_INVALID_SESSION_ID = "E105_INVALID_SESSION_ID";

/** Invalid snapshot ID */
export const E106_INVALID_SNAPSHOT_ID = "E106_INVALID_SNAPSHOT_ID";

/** Invalid mode or option specified */
export const E107_INVALID_MODE = "E107_INVALID_MODE";

// =============================================================================
// 2xx: File/Resource Errors
// =============================================================================

/** File not found in workspace */
export const E201_FILE_NOT_FOUND = "E201_FILE_NOT_FOUND";

/** File already exists (conflict) */
export const E202_FILE_ALREADY_EXISTS = "E202_FILE_ALREADY_EXISTS";

/** Permission denied for file operation */
export const E203_FILE_PERMISSION_DENIED = "E203_FILE_PERMISSION_DENIED";

/** File is currently locked by another operation */
export const E204_FILE_LOCKED = "E204_FILE_LOCKED";

/** File has unsaved changes */
export const E205_FILE_DIRTY = "E205_FILE_DIRTY";

/** Workspace not initialized (.vreko/ missing) */
export const E206_WORKSPACE_NOT_INIT = "E206_WORKSPACE_NOT_INIT";

/** Resource quota exceeded (storage, snapshots, etc.) */
export const E207_QUOTA_EXCEEDED = "E207_QUOTA_EXCEEDED";

// =============================================================================
// 3xx: Snapshot/State Errors
// =============================================================================

/** Snapshot not found */
export const E301_SNAPSHOT_NOT_FOUND = "E301_SNAPSHOT_NOT_FOUND";

/** Cannot create snapshot (workspace dirty) */
export const E302_SNAPSHOT_CREATE_FAILED = "E302_SNAPSHOT_CREATE_FAILED";

/** Cannot restore snapshot (conflicts or errors) */
export const E303_SNAPSHOT_RESTORE_FAILED = "E303_SNAPSHOT_RESTORE_FAILED";

/** Snapshot is corrupted or invalid */
export const E304_SNAPSHOT_CORRUPTED = "E304_SNAPSHOT_CORRUPTED";

/** No session currently active */
export const E305_NO_ACTIVE_SESSION = "E305_NO_ACTIVE_SESSION";

/** Session already exists (cannot start new) */
export const E306_SESSION_ALREADY_ACTIVE = "E306_SESSION_ALREADY_ACTIVE";

/** Cannot end session (operations pending) */
export const E307_SESSION_END_FAILED = "E307_SESSION_END_FAILED";

/** Snapshot is protected (cannot delete/modify) */
export const E308_SNAPSHOT_PROTECTED = "E308_SNAPSHOT_PROTECTED";

// =============================================================================
// 4xx: Validation/Check Errors
// =============================================================================

/** Validation check failed */
export const E401_VALIDATION_FAILED = "E401_VALIDATION_FAILED";

/** TypeScript compilation errors found */
export const E402_TYPESCRIPT_ERRORS = "E402_TYPESCRIPT_ERRORS";

/** Linter errors found */
export const E403_LINT_ERRORS = "E403_LINT_ERRORS";

/** Test failures detected */
export const E404_TEST_FAILURES = "E404_TEST_FAILURES";

/** Pattern violation detected */
export const E405_PATTERN_VIOLATION = "E405_PATTERN_VIOLATION";

/** Security scan failed (secrets, threats) */
export const E406_SECURITY_SCAN_FAILED = "E406_SECURITY_SCAN_FAILED";

/** Circular dependency detected */
export const E407_CIRCULAR_DEPENDENCY = "E407_CIRCULAR_DEPENDENCY";

/** Build failed */
export const E408_BUILD_FAILED = "E408_BUILD_FAILED";

// =============================================================================
// 5xx: Internal/Server Errors
// =============================================================================

/** Internal server/daemon error */
export const E501_INTERNAL_ERROR = "E501_INTERNAL_ERROR";

/** Database/storage error */
export const E502_STORAGE_ERROR = "E502_STORAGE_ERROR";

/** Service unavailable (daemon not running) */
export const E503_SERVICE_UNAVAILABLE = "E503_SERVICE_UNAVAILABLE";

/** Operation timeout on server side */
export const E504_OPERATION_TIMEOUT = "E504_OPERATION_TIMEOUT";

/** Configuration error */
export const E505_CONFIG_ERROR = "E505_CONFIG_ERROR";

/** Dependency not available */
export const E506_DEPENDENCY_ERROR = "E506_DEPENDENCY_ERROR";

/** Rate limit exceeded */
export const E507_RATE_LIMIT_EXCEEDED = "E507_RATE_LIMIT_EXCEEDED";

// =============================================================================
// Error Code Type
// =============================================================================

/**
 * Union type of all error codes for type safety
 */
export type ErrorCode =
	// Protocol errors
	| typeof E001_INVALID_REQUEST
	| typeof E002_METHOD_NOT_FOUND
	| typeof E003_NOT_INITIALIZED
	| typeof E004_CONNECTION_LOST
	| typeof E005_TIMEOUT
	| typeof E006_VERSION_MISMATCH
	// Request errors
	| typeof E101_MISSING_PARAM
	| typeof E102_INVALID_PARAM
	| typeof E103_TYPE_MISMATCH
	| typeof E104_INVALID_WORKSPACE
	| typeof E105_INVALID_SESSION_ID
	| typeof E106_INVALID_SNAPSHOT_ID
	| typeof E107_INVALID_MODE
	// File errors
	| typeof E201_FILE_NOT_FOUND
	| typeof E202_FILE_ALREADY_EXISTS
	| typeof E203_FILE_PERMISSION_DENIED
	| typeof E204_FILE_LOCKED
	| typeof E205_FILE_DIRTY
	| typeof E206_WORKSPACE_NOT_INIT
	| typeof E207_QUOTA_EXCEEDED
	// Snapshot errors
	| typeof E301_SNAPSHOT_NOT_FOUND
	| typeof E302_SNAPSHOT_CREATE_FAILED
	| typeof E303_SNAPSHOT_RESTORE_FAILED
	| typeof E304_SNAPSHOT_CORRUPTED
	| typeof E305_NO_ACTIVE_SESSION
	| typeof E306_SESSION_ALREADY_ACTIVE
	| typeof E307_SESSION_END_FAILED
	| typeof E308_SNAPSHOT_PROTECTED
	// Validation errors
	| typeof E401_VALIDATION_FAILED
	| typeof E402_TYPESCRIPT_ERRORS
	| typeof E403_LINT_ERRORS
	| typeof E404_TEST_FAILURES
	| typeof E405_PATTERN_VIOLATION
	| typeof E406_SECURITY_SCAN_FAILED
	| typeof E407_CIRCULAR_DEPENDENCY
	| typeof E408_BUILD_FAILED
	// Internal errors
	| typeof E501_INTERNAL_ERROR
	| typeof E502_STORAGE_ERROR
	| typeof E503_SERVICE_UNAVAILABLE
	| typeof E504_OPERATION_TIMEOUT
	| typeof E505_CONFIG_ERROR
	| typeof E506_DEPENDENCY_ERROR
	| typeof E507_RATE_LIMIT_EXCEEDED;

