// =============================================================================
// Helper Functions
// =============================================================================

/**
 * Get error message for a code
 */
export function getErrorMessage(code: ErrorCode): string {
	return ERROR_MESSAGES[code];
}

/**
 * Check if an error code is in a specific category
 */
export function getErrorCategory(
	code: ErrorCode,
): "protocol" | "request" | "file" | "snapshot" | "validation" | "internal" {
	const codeNum = Number.parseInt(code.slice(1, 4), 10);
	if (codeNum < 100) {
		return "protocol";
	}
	if (codeNum < 200) {
		return "request";
	}
	if (codeNum < 300) {
		return "file";
	}
	if (codeNum < 400) {
		return "snapshot";
	}
	if (codeNum < 500) {
		return "validation";
	}
	return "internal";
}

/**
 * Check if error is recoverable (client can retry)
 */
export function isRecoverableError(code: ErrorCode): boolean {
	const category = getErrorCategory(code);
	// Protocol, request, and file errors are often recoverable
	// Internal errors usually are not
	return category !== "internal";
}
