/**
 * Guide Tool - Intent-to-Plan Router
 *
 * Provides complete workflow plans based on intent. This is the "I don't know
 * where to start" tool that converts intent into a concrete sequence of steps.
 *
 * Key differences from nextActions:
 * - nextActions: "What's the ONE next thing?" (reactive, in vreko response)
 * - guide: "What's the WHOLE plan?" (proactive, standalone tool)
 *
 * Based on MCP ergonomics research showing agents with 20+ tools suffer
 * decision paralysis. Guide removes this by providing explicit sequences.
 *
 * @module tools/consolidated/guide
 */

import { getSessionStateAsync } from "../../adapters/session-adapter.js";
import { formatWireLabeled, INTERNAL_SEPARATOR } from "../../branding/index.js";
import { validateGuideParams } from "../../security/input-sanitization.js";
import type { ToolHandler, VrekoTool } from "../../types/tool-types.js";

// =============================================================================
// Types
// =============================================================================

/**
 * Supported intents for workflow planning
 */
export type WorkflowIntent = "debug" | "implement" | "refactor" | "review" | "explore";

/**
 * Guide tool parameters
 */
export interface GuideParams {
	/** What the agent is trying to accomplish */
	intent: WorkflowIntent;
	/** Description of the task */
	task: string;
	/** Files that will be touched (helps with risk assessment) */
	files?: string[];
	/** Keywords for pattern matching */
	keywords?: string[];
	/** Use compact wire format */
	compact?: boolean;
}

/**
 * A single step in a workflow
 */
export interface WorkflowStep {
	/** Step order (1-indexed) */
	order: number;
	/** Tool to call */
	tool: string;
	/** Parameters for the tool */
	params?: Record<string, unknown>;
	/** Why this step is included */
	reason: string;
	/** True for steps where agent does work (not tool calls) */
	isAgentAction?: boolean;
	/** Conditional execution (e.g., "if tests fail") */
	conditional?: string;
}

/**
 * Template modification applied based on context
 */
export interface WorkflowModification {
	/** What was changed */
	change: string;
	/** Why it was changed */
	reason: string;
}

/**
 * Complete guide response
 */
export interface GuideResponse {
	/** The intent this plan is for */
	intent: WorkflowIntent;
	/** Complete workflow steps */
	plan: WorkflowStep[];
	/** Human-readable explanation */
	explanation: string;
	/** Modifications made to base template */
	modifications: WorkflowModification[];
	/** Risk level detected */
	risk: "L" | "M" | "H";
}

