// =============================================================================
// Template Modifiers
// =============================================================================

/**
 * Context for applying modifications
 */
interface ModificationContext {
	risk: "L" | "M" | "H";
	dirtyFiles: number;
	files?: string[];
	hasActiveSession: boolean;
}

/**
 * Apply risk-based modifications to a workflow template
 */
function applyRiskModifications(
	steps: WorkflowStep[],
	context: ModificationContext,
): { steps: WorkflowStep[]; modifications: WorkflowModification[] } {
	const modifications: WorkflowModification[] = [];
	let modifiedSteps = [...steps];

	// High risk: Add security check early in workflow
	if (context.risk === "H") {
		// Find the first agent action step
		const agentActionIndex = modifiedSteps.findIndex((s) => s.isAgentAction);
		if (agentActionIndex > 0) {
			// Insert security check before agent action
			const securityStep: WorkflowStep = {
				order: 0, // Will be renumbered
				tool: "check",
				params: { mode: "security" },
				reason: "High risk detected - security validation required",
			};

			modifiedSteps.splice(agentActionIndex, 0, securityStep);
			modifications.push({
				change: "Added security check before implementation",
				reason: "High risk level detected",
			});
		}

		// Upgrade final check to full if not already
		const lastCheckIndex =
			modifiedSteps
				.map((s, idx) => ({ s, idx }))
				.reverse()
				.find(({ s }) => s.tool === "check" && !s.isAgentAction)?.idx ?? -1;
		if (lastCheckIndex >= 0 && modifiedSteps[lastCheckIndex].params?.mode !== "full") {
			modifiedSteps[lastCheckIndex] = {
				...modifiedSteps[lastCheckIndex],
				params: { ...modifiedSteps[lastCheckIndex].params, mode: "full" },
				reason: "Upgraded to full validation due to high risk",
			};
			modifications.push({
				change: "Upgraded final check to full mode",
				reason: "High risk requires comprehensive validation",
			});
		}
	}

	// Medium risk: Add architecture check if not present
	if (context.risk === "M" || context.risk === "H") {
		const hasArchCheck = modifiedSteps.some((s) => s.tool === "check" && s.params?.mode === "architecture");
		if (!hasArchCheck) {
			// Find position after advise or before agent action
			const insertIndex = modifiedSteps.findIndex((s) => s.isAgentAction);
			if (insertIndex > 0) {
				const archStep: WorkflowStep = {
					order: 0,
					tool: "check",
					params: { mode: "architecture" },
					reason: "Verify architecture boundaries",
				};
				modifiedSteps.splice(insertIndex, 0, archStep);
				modifications.push({
					change: "Added architecture check",
					reason: `${context.risk === "H" ? "High" : "Medium"} risk - verify boundaries before changes`,
				});
			}
		}
	}

	// Files touching auth/security areas
	if (context.files?.some((f) => /auth|security|password|token|secret/i.test(f))) {
		const hasSecurityCheck = modifiedSteps.some((s) => s.tool === "check" && s.params?.mode === "security");
		if (!hasSecurityCheck) {
			const agentActionIndex = modifiedSteps.findIndex((s) => s.isAgentAction);
			if (agentActionIndex > 0) {
				const securityStep: WorkflowStep = {
					order: 0,
					tool: "check",
					params: { mode: "security" },
					reason: "Security-sensitive files detected",
				};
				modifiedSteps.splice(agentActionIndex, 0, securityStep);
				modifications.push({
					change: "Added security check",
					reason: "Touching security-sensitive files",
				});
			}
		}
	}

	// Many files: recommend architecture check
	if (context.files && context.files.length > 5) {
		const hasArchCheck = modifiedSteps.some((s) => s.tool === "check" && s.params?.mode === "architecture");
		if (!hasArchCheck) {
			const insertIndex = modifiedSteps.findIndex((s) => s.isAgentAction);
			if (insertIndex > 0) {
				const archStep: WorkflowStep = {
					order: 0,
					tool: "check",
					params: { mode: "architecture" },
					reason: "Large changeset - verify architecture",
				};
				modifiedSteps.splice(insertIndex, 0, archStep);
				modifications.push({
					change: "Added architecture check",
					reason: `Touching ${context.files.length} files - verify boundaries`,
				});
			}
		}
	}

	// Renumber steps
	modifiedSteps = modifiedSteps.map((step, index) => ({
		...step,
		order: index + 1,
	}));

	return { steps: modifiedSteps, modifications };
}

// =============================================================================
// Formatting
// =============================================================================

/**
 * Format workflow for wire protocol
 */
function formatWireWorkflow(response: GuideResponse, compact: boolean): string {
	const planStr = response.plan
		.filter((s) => !s.isAgentAction)
		.slice(0, 5) // Max 5 tool calls in wire format
		.map((s) => {
			const mode = s.params?.mode;
			return mode ? `${s.tool}→${mode}` : s.tool;
		})
		.join(",");

	return formatWireLabeled(
		"G",
		{
			intent: response.intent,
			risk: response.risk,
			steps: response.plan.length,
			mods: response.modifications.length,
			plan: planStr,
		},
		{ compact },
	);
}

/**
 * Format workflow for human-readable output
 */
function formatHumanWorkflow(response: GuideResponse): string {
	const lines: string[] = [];

	lines.push(`\n📋 WORKFLOW PLAN (${response.intent}):\n`);

	for (const step of response.plan) {
		if (step.isAgentAction) {
			lines.push(`${step.order}. [YOU: ${step.reason}]`);
		} else {
			const paramsStr = step.params
				? `({ ${Object.entries(step.params)
						.map(([k, v]) => `${k}: "${v}"`)
						.join(", ")} })`
				: "()";
			lines.push(`${step.order}. ${step.tool}${paramsStr}`);
			lines.push(`   → ${step.reason}`);
		}

		if (step.conditional) {
			lines.push(`   ⚠️ ${step.conditional}`);
		}

		lines.push(""); // Empty line between steps
	}

	if (response.modifications.length > 0) {
		lines.push("MODIFICATIONS (based on context):");
		for (const mod of response.modifications) {
			lines.push(`- ${mod.change}`);
			lines.push(`  Reason: ${mod.reason}`);
		}
	}

	return lines.join("\n");
}

// =============================================================================
// Handler
// =============================================================================

/**
 * Handle guide request
 */
export const handleGuide: ToolHandler = async (args, context) => {
	// Security: Validate and sanitize all user inputs
	const validation = validateGuideParams(args);
	if (!validation.success) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Input validation failed:\n${validation.errors?.join("\n") ?? "Unknown validation error"}`,
				},
			],
			isError: true,
		};
	}

	const params = validation.data as GuideParams;
	const { intent, task, files, compact = false } = params;

	// Validate intent (also checked by Zod but kept for clear error message)
	if (!intent || !BASE_TEMPLATES[intent]) {
		return {
			content: [
				{
					type: "text",
					text: `Invalid intent: ${intent}. Must be one of: debug, implement, refactor, review, explore`,
				},
			],
			isError: true,
		};
	}

	// Get current session state for context
	let risk: "L" | "M" | "H" = "L";
	let dirtyFiles = 0;
	let hasActiveSession = false;

	if (context.workspaceRoot) {
		try {
			const sessionState = await getSessionStateAsync(context.workspaceRoot);
			if (sessionState) {
				hasActiveSession = !!sessionState.currentTask;
				dirtyFiles = sessionState.changesSinceTaskStart?.length || 0;

				// Determine risk from various signals
				const hasRiskAreas = sessionState.riskAreasTouched?.some((area) =>
					["auth", "payment", "security", "database"].includes(area),
				);
				// TD-04: Use riskAreasTouched as proxy for violations instead of hardcoding false.
				// This ensures guide elevates risk for files with known violation history.
				const hasViolations = (sessionState.riskAreasTouched?.length ?? 0) > 0;

				if (hasRiskAreas || hasViolations) {
					risk = "H";
				} else if (dirtyFiles > 5 || (files && files.length > 5)) {
					risk = "M";
				}
			}
		} catch {
			// Session state not available, use defaults
		}
	}

	// Check if files suggest high risk
	if (files?.some((f) => /auth|security|password|token|secret|payment/i.test(f))) {
		risk = "H";
	}

	// Get base template
	const baseSteps = JSON.parse(JSON.stringify(BASE_TEMPLATES[intent])) as WorkflowStep[];

	// Apply modifications based on context
	const modificationContext: ModificationContext = {
		risk,
		dirtyFiles,
		files,
		hasActiveSession,
	};

	const { steps: modifiedSteps, modifications } = applyRiskModifications(baseSteps, modificationContext);

	// Inject task into advise step if present
	const adviseStep = modifiedSteps.find((s) => s.tool === "advise");
	if (adviseStep && task) {
		adviseStep.params = { ...adviseStep.params, task };
	}

	// Build response
	const response: GuideResponse = {
		intent,
		plan: modifiedSteps,
		explanation: getExplanation(intent, modifications.length),
		modifications,
		risk,
	};

	// Format output
	const wire = formatWireWorkflow(response, compact);
	const human = formatHumanWorkflow(response);
	const brandedMessage = `🦎 Vreko: Here's your ${intent} workflow plan.`;

	// Build structuredContent for programmatic parsing
	const structuredContent: Record<string, unknown> = {
		intent,
		risk,
		stepCount: modifiedSteps.length,
		modifications: modifications.length,
		plan: modifiedSteps,
		hasActiveSession,
	};

	return {
		content: [
			{
				type: "text",
				text: `${wire}${INTERNAL_SEPARATOR}${brandedMessage}${human}`,
			},
		],
		structuredContent,
	};
};

/**
 * Get explanation for an intent
 */
function getExplanation(intent: WorkflowIntent, modCount: number): string {
	const base: Record<WorkflowIntent, string> = {
		debug: "Debug workflow: Start session, validate state, get advice, fix, validate, and capture learnings.",
		implement: "Implementation workflow: Start session, get architecture guidance, implement, validate, and close.",
		refactor: "Refactoring workflow: Start session, check architecture, refactor, full validation with ceremony.",
		review: "Review workflow: Start session, check health, security scan, architecture validation, document findings.",
		explore: "Exploration workflow: Lightweight context load, explore, capture discoveries.",
	};

	const modNote = modCount > 0 ? ` (${modCount} modifications applied based on your context)` : "";
	return base[intent] + modNote;
}

