/**
 * Format diagnostic error message with actionable fix suggestions
 * P0-2: Error Diagnostics - helps agents quickly understand and fix errors
 */
export function formatDiagnosticError(
	error: Error | unknown,
	context: { tool?: string; workspace?: string; config?: string },
): { error: string; code: string; message: string; diagnostics: string[]; fix?: string } {
	const errorMsg = error instanceof Error ? error.message : String(error);
	const errorName = error instanceof Error ? error.name : "Error";

	// Detect error type and provide specific diagnostics
	if (errorMsg.includes("ENOENT")) {
		const pathMatch = errorMsg.match(/['"]([^'"]+)['"]/);
		const path = pathMatch ? pathMatch[1] : "unknown";
		return {
			error: "E201_FILE_NOT_FOUND",
			code: "ENOENT",
			message: `File or directory not found: ${path}`,
			diagnostics: [
				`Path: ${path}`,
				context.config ? `Config: ${context.config}` : "",
				"Issue: Path does not exist or is inaccessible",
			].filter(Boolean),
			fix: context.config
				? "Update config file to use valid path. Check .qoder-mcp-config.json or similar."
				: "Verify path exists and has correct permissions.",
		};
	}

	if (errorMsg.includes("ECONNREFUSED") || errorMsg.includes("Connection refused")) {
		return {
			error: "E503_SERVICE_UNAVAILABLE",
			code: "ECONNREFUSED",
			message: "Cannot connect to service",
			diagnostics: [
				context.workspace ? `Workspace: ${context.workspace}` : "",
				"Issue: Service not running or not accepting connections",
			].filter(Boolean),
			fix: "Start the Vreko daemon: vreko daemon start",
		};
	}

	if (errorMsg.includes("timeout") || errorMsg.includes("ETIMEDOUT")) {
		return {
			error: "E504_TIMEOUT",
			code: "TIMEOUT",
			message: "Request timed out",
			diagnostics: [
				context.tool ? `Tool: ${context.tool}` : "",
				"Issue: Operation took too long to complete",
			].filter(Boolean),
			fix: "Check network connectivity or increase timeout. Review server logs for hung processes.",
		};
	}

	if (errorMsg.includes("EACCES") || errorMsg.includes("permission denied")) {
		const pathMatch = errorMsg.match(/['"]([^'"]+)['"]/);
		const path = pathMatch ? pathMatch[1] : "unknown";
		return {
			error: "E303_PERMISSION_DENIED",
			code: "EACCES",
			message: `Permission denied: ${path}`,
			diagnostics: [`Path: ${path}`, "Issue: Insufficient permissions to access file/directory"].filter(Boolean),
			fix: "Check file permissions: chmod or chown the path, or run with appropriate user.",
		};
	}

	// Generic error - provide basic diagnostics
	return {
		error: "E500_INTERNAL_ERROR",
		code: errorName,
		message: errorMsg,
		diagnostics: [
			context.tool ? `Tool: ${context.tool}` : "",
			context.workspace ? `Workspace: ${context.workspace}` : "",
			`Error: ${errorName}`,
		].filter(Boolean),
	};
}
