/**
 * Transport Manager - Daemon Lifecycle Integration
 *
 * Manages transport lifecycle and provides daemon integration points
 * for SSE and future transport types.
 *
 * @module daemon/transport-manager
 */

import { EventEmitter } from "node:events";
import {
	type ApiKeyValidator,
	type DigestServiceProvider,
	type SessionServiceProvider,
	SSELocalTransport,
	type SSELogger,
} from "../transport/sse-local.js";

// =============================================================================
// Types
// =============================================================================

export interface TransportManagerConfig {
	/** SSE port (default: 8765) */
	ssePort?: number;
	/** Max SSE clients (default: 10) */
	maxClients?: number;
	/** Idle timeout in ms (default: 15 minutes) */
	idleTimeoutMs?: number;
	/** Logger instance */
	logger?: SSELogger;
	/** API key validator for unified auth (enables API key authentication) */
	apiKeyValidator?: ApiKeyValidator;
	/** Digest service for Pioneer Dashboard (enables /digest endpoint) */
	digestService?: DigestServiceProvider;
	/** Session service for web dashboard (enables /session/list endpoint) */
	sessionService?: SessionServiceProvider;
}

interface ClientEvent {
	transport: "sse";
	clientId: string;
}

// =============================================================================
// Transport Manager
// =============================================================================

export class TransportManager extends EventEmitter {
	private sseTransport: SSELocalTransport | null = null;
	private config: TransportManagerConfig;

	constructor(config?: TransportManagerConfig) {
		super();
		this.config = {
			ssePort: 8765,
			maxClients: 10,
			idleTimeoutMs: 15 * 60 * 1000,
			...config,
		};
	}

	/**
	 * Set the digest service for Pioneer Dashboard
	 * Can be called after construction but before start()
	 */
	setDigestService(digestService: DigestServiceProvider): void {
		this.config.digestService = digestService;
	}

	/**
	 * Set the session service for web dashboard /session/list endpoint
	 * Can be called after construction but before start()
	 */
	setSessionService(sessionService: SessionServiceProvider): void {
		this.config.sessionService = sessionService;
	}

	/**
	 * Start all transports
	 */
	async start(): Promise<void> {
		// Start SSE transport with unified auth support
		this.sseTransport = new SSELocalTransport({
			port: this.config.ssePort,
			maxClients: this.config.maxClients,
			idleTimeoutMs: this.config.idleTimeoutMs,
			logger: this.config.logger,
			apiKeyValidator: this.config.apiKeyValidator,
			digestService: this.config.digestService,
			sessionService: this.config.sessionService,
		});

		// Forward events
		this.sseTransport.on("client:connected", (clientId: string) => {
			const event: ClientEvent = { transport: "sse", clientId };
			this.emit("client:connected", event);
		});

		this.sseTransport.on("client:disconnected", (clientId: string) => {
			const event: ClientEvent = { transport: "sse", clientId };
			this.emit("client:disconnected", event);
		});

		await this.sseTransport.start();
	}

	/**
	 * Stop all transports
	 */
	async stop(): Promise<void> {
		if (this.sseTransport) {
			await this.sseTransport.stop();
			this.sseTransport = null;
		}
	}

	/**
	 * Broadcast an event to all connected clients
	 */
	broadcast(event: string, data: unknown): void {
		if (this.sseTransport) {
			this.sseTransport.broadcast(event, data);
		}
	}

	/**
	 * Check if any transport has active clients
	 * Used by daemon to suppress idle shutdown
	 */
	shouldSuppressIdleShutdown(): boolean {
		return this.sseTransport?.shouldSuppressIdleShutdown() ?? false;
	}

	/**
	 * Get transport statistics
	 */
	getStats() {
		return {
			sse: {
				clientCount: this.sseTransport?.clientCount ?? 0,
			},
		};
	}
}
