/** Compress string for wire format */
const compressStr = (s: string, max: number): string => {
	const clean = s.replace(/\s+/g, "→");
	return clean.length > max ? `${clean.slice(0, max - 1)}…` : clean;
};

/**
 * Normalize a free-text or enum outcome to one of the known internal enum values.
 * The MCP inputSchema accepts free text; the task state machine needs an enum.
 * Examples: "Completed auth refactor" → "completed", "gave up on this" → "abandoned"
 *
 * Exported for unit testing.
 */
export function normalizeOutcome(
	outcome: string | undefined,
	ok: 0 | 1 | boolean | undefined,
): "completed" | "abandoned" | "blocked" {
	if (!outcome) {
		return ok === 0 || ok === false ? "abandoned" : "completed";
	}
	const lower = outcome.toLowerCase().trim();
	// Exact enum shorthand first
	if (lower === "completed" || lower === "success") {
		return "completed";
	}
	if (lower === "abandoned" || lower === "cancelled" || lower === "canceled") {
		return "abandoned";
	}
	if (lower === "blocked" || lower === "failed" || lower === "failure" || lower === "error") {
		return "blocked";
	}
	// Substring match for free-text paragraphs
	if (/\bcomplet|\bfinish|\bdone|\bsuccess/.test(lower)) {
		return "completed";
	}
	if (/\babandon|\bcancel|\bgave up|\bgive up|\bscrapped/.test(lower)) {
		return "abandoned";
	}
	if (/\bblock|\bfail|\bstuck|\bbroken|\berror/.test(lower)) {
		return "blocked";
	}
	// Free text doesn't match any pattern  -  derive from ok flag
	return ok === 0 || ok === false ? "abandoned" : "completed";
}

