/**
 * Handle snap_end
 *
 * Enhanced to provide:
 * 1. 🦎 Vreko branded output for visual distinctiveness
 * 2. User-facing efficiency stats (tokens saved, mistakes prevented)
 * 3. Internal improvement tracking for agent learning loop
 */
export const handleSnapEnd: ToolHandler = async (args, context) => {
	// Security: Validate and sanitize all user inputs
	const validation = validateSnapEndParams(args);
	if (!validation.success) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Input validation failed:\n${validation.errors?.join("\n") ?? "Unknown validation error"}`,
				},
			],
			isError: true,
		};
	}

	const params = validation.data as SnapEndParams;
	const options: WireFormatOptions = { compact: params.compact ?? false };

	// Update workflow stage to 'closing' (2026 session hygiene)
	if (context.workspaceRoot) {
		await updateWorkflowStageAsync(context.workspaceRoot, "closing");
	}

	// Normalize learnings (prefer 'learnings', fall back to legacy 'l')
	const learningStrings = params.learnings ?? params.l ?? [];

	// ==========================================================================
	// AUTO-CEREMONY SUGGESTION: Recommend ceremony based on session context
	// ==========================================================================
	let suggestedCeremony: CeremonyLevel | null = null;
	let ceremonySuggestionReason = "";
	let ceremonySuggestionConfidence = 0;

	// Only suggest ceremony if:
	// 1. Ceremony not explicitly requested
	// 2. Task is NOT completing successfully (abandoned/blocked need validation)
	// Clean completions don't need ceremony nag - user already finished the work
	const isCleanCompletion = normalizeOutcome(params.outcome, params.ok) === "completed" || params.ok === 1;
	if (!params.ceremony && context.workspaceRoot && !isCleanCompletion) {
		const sessionState = await getSessionStateAsync(context.workspaceRoot);
		if (sessionState) {
			// Calculate suggestion based on session metrics
			const filesModified = sessionState.changesSinceTaskStart?.length || 0;
			const hasHighRiskAreas = sessionState.riskAreasTouched?.some((area) =>
				["auth", "payment", "security", "database"].includes(area),
			);
			const taskStartTime = sessionState.currentTask?.startedAt;
			const taskDurationMs = taskStartTime ? Date.now() - taskStartTime : 0;
			const taskDurationMins = taskDurationMs / 60000;

			if (hasHighRiskAreas) {
				suggestedCeremony = "comprehensive";
				ceremonySuggestionReason = `High-risk areas touched (${sessionState.riskAreasTouched?.join(", ")}) - comprehensive validation recommended`;
				ceremonySuggestionConfidence = 95;
			} else if (filesModified > 10 || taskDurationMins > 30) {
				suggestedCeremony = "standard";
				ceremonySuggestionReason = `Significant session (${filesModified} files, ${Math.round(taskDurationMins)}min) - standard validation recommended`;
				ceremonySuggestionConfidence = 90;
			} else if (filesModified > 3) {
				suggestedCeremony = "quick";
				ceremonySuggestionReason = `${filesModified} files modified - quick validation recommended`;
				ceremonySuggestionConfidence = 80;
			}
		}
	}

	// ==========================================================================
	// FOLLOW-THROUGH RATE: Track how well agent follows suggested nextActions
	// ==========================================================================
	let followThroughInfo = "";
	let followThroughData: {
		rate: number;
		suggested: number;
		followed: number;
		altEvents: number;
		altSuccess: number;
		altRate: number;
		combinedRate: number;
	} | null = null;

	if (context.workspaceRoot) {
		const ftResult = await computeFollowThroughRateAsync(context.workspaceRoot);
		if (ftResult.suggested > 0 || ftResult.altEvents > 0) {
			followThroughData = ftResult;
			const directPct = Math.round(ftResult.rate * 100);
			const altPct = Math.round(ftResult.altRate * 100);
			const totalPct = Math.round(ftResult.combinedRate * 100);
			if (altPct > 0) {
				followThroughInfo =
					`\n📊 Follow-through: ${totalPct}% total` +
					`\n   • ${directPct}% direct (${ftResult.followed}/${ftResult.suggested} suggested actions)` +
					`\n   • ${altPct}% alternative (${ftResult.altSuccess} external validations)`;
			} else if (ftResult.suggested > 0) {
				followThroughInfo = `\n📊 Follow-through: ${directPct}% (${ftResult.followed}/${ftResult.suggested} suggested actions taken)`;
			}
		}
	}

	// ==========================================================================
	// CEREMONY MODE: Maximum confidence validation before session close
	// ==========================================================================
	let ceremonyResult: CeremonyResult | undefined;

	if (params.ceremony) {
		ceremonyResult = await runCeremony(params, context);

		// If ceremony failed and not forcing, return early with ceremony results
		if (!ceremonyResult.passed && !params.force) {
			const ceremonyOutput = formatCeremonyResult(ceremonyResult);
			const ceremonyWire = buildCeremonyWireFields(ceremonyResult);

			const wire = formatWireLabeled(
				"E",
				{
					status: "CEREMONY_BLOCKED",
					...ceremonyWire,
				},
				options,
			);

			return {
				content: [
					{
						type: "text",
						text: `${wire}${INTERNAL_SEPARATOR}🚫 Session close blocked by ceremony validation\n${ceremonyOutput}\n\n💡 Fix the issues above, then re-run snap_end({ ceremony: "${getCeremonyLevel(params.ceremony)}" })\n   Or use force: true to bypass (not recommended)`,
					},
				],
				structuredContent: {
					status: "CEREMONY_BLOCKED",
					ceremonyPassed: false,
					blockers: ceremonyResult.blockers,
					warnings: ceremonyResult.warnings,
				},
				isError: true,
			};
		}
	}

	// Check if task has a goal that needs validation
	const goalCheck = await checkTaskGoal(context.workspaceRoot);
	if (goalCheck && !goalCheck.met) {
		// Goal not met - return warning but don't block completion
		const wire = formatWireLabeled(
			"E",
			{
				status: "GOAL_NOT_MET",
				metric: goalCheck.metric,
				current: `${goalCheck.current}${goalCheck.unit}`,
				target: `${goalCheck.target}${goalCheck.unit}`,
			},
			options,
		);
		return {
			content: [
				{
					type: "text",
					text: `${wire}\n\n⚠️ Goal not achieved: ${goalCheck.metric} is ${goalCheck.current}${goalCheck.unit}, target was ${goalCheck.target}${goalCheck.unit}. Task marked incomplete.`,
				},
			],
			isError: false, // Warning, not error
		};
	}

	// Convert quick learnings to customLearning format if provided
	const customLearnings = learningStrings.map((learning) => ({
		type: "pattern" as const,
		trigger: "Task completion",
		action: learning,
	}));

	// P1-3: Track learnings as applied for auto-promotion
	const learningService = createTieredLearningService(context.workspaceRoot);
	let promotionResult: { promoted: number; totalHot: number } | undefined;
	let surveyAttributionCount = 0;
	let totalTrackedLearnings = 0;

	const usageStats = learningService.getUsageStats();
	totalTrackedLearnings = Object.keys(usageStats).length;

	// FEEDBACK LOOP: Use survey data to attribute applied learnings
	if (params.survey) {
		const sessionState = await getSessionStateAsync(context.workspaceRoot);
		const shownLearnings = sessionState?.currentTask?.shownLearnings;

		// Gate on helpfulness - if LLM rated Vreko unhelpful, don't boost learnings
		const helpfulness = params.survey.helpfulness ?? 3;
		if (shownLearnings && helpfulness >= 3) {
			// Attribute patterns: first N patterns shown = first N applied
			const patternsUsed = params.survey.patterns_used ?? 0;
			for (let i = 0; i < Math.min(patternsUsed, shownLearnings.patterns.length); i++) {
				learningService.trackApplied(shownLearnings.patterns[i]);
				surveyAttributionCount++;
			}

			// Attribute pitfalls: first N pitfalls shown = first N avoided
			const pitfallsAvoided = params.survey.pitfalls_avoided ?? 0;
			for (let i = 0; i < Math.min(pitfallsAvoided, shownLearnings.pitfalls.length); i++) {
				learningService.trackApplied(shownLearnings.pitfalls[i]);
				surveyAttributionCount++;
			}
		}
	}

	if (customLearnings.length > 0) {
		// Generate IDs for the learnings we're capturing
		for (const learning of customLearnings) {
			const learningId = `vreko-end-${learning.action.slice(0, 30).replace(/\s+/g, "-").toLowerCase()}`;
			learningService.trackApplied(learningId);
		}

		// Check if we should trigger auto-regeneration
		const stats = usageStats;
		const hasReachedThreshold = Object.values(stats).some(
			(s) => s.appliedCount >= HOT_TIER_PROMOTION_THRESHOLD.minAccessCount,
		);

		if (hasReachedThreshold) {
			try {
				promotionResult = await learningService.regenerateHotTier();
			} catch {
				// Best effort - don't fail snap_end if promotion fails
			}
		}
	}

	// TD-02: Persist ALL custom learnings to disk
	let directLearningsPersisted = 0;
	if (customLearnings.length > 0) {
		for (const learning of customLearnings) {
			const result = await addLearningViaDaemon(context.workspaceRoot, learning);
			if (result.success) {
				directLearningsPersisted++;
			}
		}
	}

	// Map to complete_task parameters  -  normalize free-text outcome to enum
	const completeArgs: Record<string, unknown> = {
		outcome: normalizeOutcome(params.outcome, params.ok),
		createSnapshot: true,
		notes: params.notes ?? params.outcome, // preserve full text as notes for ceremony context
	};

	completeArgs.learningsCaptured = directLearningsPersisted;

	const result = await handleCompleteTask(completeArgs, context);

	// TD-09: Clean up SessionFileTracker after task completion
	try {
		const tracker = getSessionFileTracker(context.workspaceRoot);
		if (tracker.hasActiveTask()) {
			tracker.endTask();
		}
	} catch {
		// Best effort cleanup
	}

	// Parse and format as 🦎 Vreko branded wire response
	try {
		const content = result.content[0]?.text || "";
		const data = JSON.parse(content) as Record<string, unknown>;

		// Get efficiency metrics from agent-reported values
		const metrics = getEfficiencyMetrics(params, customLearnings.length);

		// Identify improvements for agent learning
		const improvements = identifyImprovements(data, params);

		// Build wire format with 🦎 Vreko branding
		const success = data.success !== false;
		const wireFields: Record<string, string | number | undefined> = {
			status: success ? "OK" : "FAIL",
			learn: `${data.learningsGenerated || customLearnings.length}L`,
			files: `${data.filesModified || 0}F`,
			lines: `+${data.linesAdded || 0}-${data.linesRemoved || 0}`,
		};

		// Add learnings summary
		if (learningStrings.length > 0) {
			wireFields.summary = learningStrings
				.slice(0, 2)
				.map((l) => compressStr(l, 80))
				.join(",");
		}

		// Add survey data
		if (params.survey) {
			const surveyJson = JSON.stringify({
				patterns_used: params.survey.patterns_used ?? 0,
				pitfalls_avoided: params.survey.pitfalls_avoided ?? 0,
				helpfulness: params.survey.helpfulness ?? 0,
				unhelpful_count: params.survey.unhelpful_count ?? 0,
			});
			wireFields.survey = surveyJson;
		}

		const wire = formatWireLabeled("E", wireFields, options);

		// Build full response
		const userStats = formatUserStats(metrics);
		const improvementNotes = formatImprovements(improvements);

		// Add promotion info
		const promotionInfo =
			promotionResult && promotionResult.promoted > 0
				? ` | 🔥 ${promotionResult.promoted} learning(s) promoted to hot tier`
				: "";

		// Add feedback loop attribution
		const feedbackInfo =
			surveyAttributionCount > 0 ? ` | 🔄 ${surveyAttributionCount} learning(s) marked as applied` : "";

		// Add ceremony results
		const ceremonyInfo = ceremonyResult
			? `\n${formatCeremonyResult(ceremonyResult)}${ceremonyResult.passed ? "" : " (forced)"}`
			: "";

		// Add ceremony suggestion
		const ceremonySuggestionInfo =
			!ceremonyResult && suggestedCeremony
				? `\n💡 SUGGESTION: Vreko recommends ceremony: "${suggestedCeremony}"` +
					(ceremonySuggestionConfidence ? ` (${ceremonySuggestionConfidence}% confidence)` : "") +
					`\n   Why: ${ceremonySuggestionReason}\n   Run: snap_end({ ceremony: "${suggestedCeremony}" })`
				: "";

		// If ceremony was run, add ceremony fields to wire format
		if (ceremonyResult) {
			const ceremonyFields = buildCeremonyWireFields(ceremonyResult);
			Object.assign(wireFields, ceremonyFields);
		}

		// Add suggested ceremony to wire format
		if (suggestedCeremony && !ceremonyResult) {
			wireFields.suggest = suggestedCeremony;
		}

		// Generate messages
		const celebrationMessage = generateCelebrationMessage(metrics, ceremonyResult, params, {
			totalTracked: totalTrackedLearnings,
			hotTier: promotionResult?.totalHot,
		});
		const sessionNarrative = generateSessionNarrative(data, metrics, params);
		const nextSteps = suggestNextSteps(params, ceremonyResult, data);
		const nextStepsBlock =
			nextSteps.length > 0 ? `\n\n💡 Next steps:\n${nextSteps.map((s) => `   • ${s}`).join("\n")}` : "";

		const baseMessage = celebrationMessage || "🦎 Vreko Session Complete:\n   ✨ Session ended successfully";

		// Combined output
		const fullResponse = [
			`${wire}${improvementNotes}`,
			INTERNAL_SEPARATOR,
			baseMessage,
			"",
			userStats,
			promotionInfo,
			feedbackInfo,
			followThroughInfo,
			ceremonySuggestionInfo,
			ceremonyInfo,
			sessionNarrative,
			nextStepsBlock,
		].join("");

		// Build structuredContent
		const structuredContent: Record<string, unknown> = {
			status: success ? "OK" : "FAIL",
			learningsCount: data.learningsGenerated || customLearnings.length,
			filesModified: data.filesModified || 0,
			linesAdded: data.linesAdded || 0,
			linesRemoved: data.linesRemoved || 0,
			promoted: promotionResult?.promoted || 0,
		};

		if (suggestedCeremony && !ceremonyResult) {
			structuredContent.suggestedCeremony = {
				level: suggestedCeremony,
				reason: ceremonySuggestionReason,
			};
		}

		if (followThroughData) {
			structuredContent.followThrough = {
				rate: followThroughData.rate,
				suggested: followThroughData.suggested,
				followed: followThroughData.followed,
				altRate: followThroughData.altRate,
				altEvents: followThroughData.altEvents,
				altSuccess: followThroughData.altSuccess,
				combinedRate: followThroughData.combinedRate,
			};
		}

		return {
			content: [{ type: "text", text: fullResponse }],
			structuredContent,
		};
	} catch {
		return result;
	}
};

