export const snapEndTool: VrekoTool = {
	name: "vreko_end",
	description: `[DEPRECATED] Close a task session and capture learnings. MUST call at task end  -  even if abandoned.
Use when the task is done (completed, abandoned, or blocked).
Do NOT use mid-task to capture a single insight (use vreko_learn instead).
Params: outcome (required), learnings (string[]), ceremony (optional validation cascade).
Fill efficiency/survey fields silently from your own experience. NEVER ask the user. Omit if unsure.`,
	inputSchema: {
		type: "object",
		properties: {
			outcome: {
				type: "string",
				description:
					"How the task ended and what was accomplished. Free text is accepted (e.g. 'Refactored auth module, all tests passing'). Short enum values also work: 'completed', 'abandoned', 'blocked'.",
			},
			learnings: {
				type: "array",
				items: { type: "string" },
				description: "Key learnings from this task as strings",
			},
			notes: {
				type: "string",
				description: "Additional completion notes",
			},
			efficiency: {
				type: "object",
				description: "Your estimate of session efficiency (optional, shown to user as stats)",
				properties: {
					saved: { type: "string", description: "Your estimate of tokens saved (e.g. '~15K')" },
					prevented: { type: "string", description: "Mistakes you avoided (e.g. '2 - wrong layer')" },
					helped: { type: "string", description: "What context helped you most (e.g. 'auth patterns')" },
				},
			},
			survey: {
				type: "object",
				description: "Optional self-assessment (helps improve Vreko). Fill silently, NEVER ask user.",
				properties: {
					patterns_used: { type: "number", description: "How many patterns did you apply? (0 if none)" },
					pitfalls_avoided: { type: "number", description: "How many mistakes did you avoid? (0 if none)" },
					helpfulness: { type: "number", description: "Your rating of Vreko helpfulness 1-5" },
					unhelpful_count: { type: "number", description: "How many suggestions were NOT useful?" },
				},
			},
			compact: { type: "boolean", default: false, description: "Use compact wire format" },
			ceremony: {
				type: "string",
				enum: ["true", "false", "quick", "standard", "comprehensive"],
				description:
					"Enable ceremony mode with validation before close. Use 'true'/'false' for on/off, or 'quick'/'standard'/'comprehensive' for specific depth.",
			},
			verifyScript: { type: "string", description: "Path to YOUR project's verify script" },
			scopes: {
				type: "array",
				items: {
					type: "string",
					enum: ["typescript", "lint", "tests", "architecture", "security", "coverage"],
				},
				description: "Specific validation scopes (cherry-pick validations)",
			},
			diffScope: {
				type: "string",
				enum: ["staged", "uncommitted", "all"],
				default: "uncommitted",
				description: "Diff scope for ceremony validation",
			},
			force: { type: "boolean", default: false, description: "Force close even if ceremony fails" },
		},
	},
	outputSchema: {
		type: "object",
		properties: {
			status: { type: "string", enum: ["OK", "FAIL"], description: "Completion status" },
			learningsCount: { type: "number", description: "Number of learnings captured" },
			filesModified: { type: "number", description: "Files modified in session" },
		},
	},
	annotations: {
		title: "🦎 Vreko End",
		readOnlyHint: false,
		destructiveHint: false,
		idempotentHint: false,
	},
	tier: "free",
};

// Helper function imported from efficiency-metrics
function formatUserStats(metrics: { saved: string; prevented: string; helped: string; newLearnings: number }): string {
	const parts: string[] = [];
	if (metrics.saved !== "not reported") {
		parts.push(`💰 ${metrics.saved} tokens saved`);
	}
	if (metrics.prevented !== "none reported") {
		parts.push(`🛡️ Prevented: ${metrics.prevented}`);
	}
	if (metrics.helped !== "general context") {
		parts.push(`📚 Context: ${metrics.helped}`);
	}
	if (metrics.newLearnings > 0) {
		parts.push(`✨ ${metrics.newLearnings} new learning(s)`);
	}
	return parts.length > 0 ? `\n${parts.join(" | ")}` : "";
}
