/**
 * Daemon Contract Builders
 *
 * Centralizes parameter shapes for daemon IPC methods used by V2 tools.
 * These builders encode the authoritative field names so tool call sites
 * do not drift from the local-service schemas.
 *
 * @module tools/v2/utils/daemon-contracts
 */

export function buildSessionCurrentParams(workspace: string): { workspacePath: string } {
	return { workspacePath: workspace };
}

export function buildSessionStartParams(
	workspace: string,
	input: { task?: string; files?: string[]; keywords?: string[] },
): { workspacePath: string; task?: string; files?: string[]; keywords?: string[] } {
	return {
		workspacePath: workspace,
		...(input.task ? { task: input.task } : {}),
		...(input.files ? { files: input.files } : {}),
		...(input.keywords ? { keywords: input.keywords } : {}),
	};
}

export function buildSessionReviewParams(
	workspace: string,
	input: { sessionId?: string; files?: string[] },
): { workspacePath: string; sessionId?: string; files?: string[] } {
	return {
		workspacePath: workspace,
		...(input.sessionId ? { sessionId: input.sessionId } : {}),
		...(input.files ? { files: input.files } : {}),
	};
}

export function buildSessionEndDaemonParams(
	workspace: string,
	input: { sessionId?: string; outcome?: string; notes?: string; createSnapshot?: boolean },
): {
	workspacePath: string;
	sessionId?: string;
	outcome?: string;
	notes?: string;
	createSnapshot?: boolean;
} {
	return {
		workspacePath: workspace,
		...(input.sessionId ? { sessionId: input.sessionId } : {}),
		...(input.outcome ? { outcome: input.outcome } : {}),
		...(input.notes ? { notes: input.notes } : {}),
		...(input.createSnapshot !== undefined ? { createSnapshot: input.createSnapshot } : {}),
	};
}

export function buildLearningSearchParams(
	workspace: string,
	query: string,
	limit?: number,
): { workspace: string; keywords: string[]; limit?: number } {
	return {
		workspace,
		keywords: tokenizeSearchQuery(query),
		...(limit !== undefined ? { limit } : {}),
	};
}

export function tokenizeSearchQuery(query: string): string[] {
	return query
		.toLowerCase()
		.replace(/[^a-z0-9\s]/g, " ")
		.split(/\s+/)
		.map((part) => part.trim())
		.filter((part, index, all) => part.length > 1 && all.indexOf(part) === index)
		.slice(0, 10);
}
