/**
 * Calculate confidence based on warnings and learnings
 */
function calculateConfidence(warningCount: number, learningCount: number, violationCount: number): number {
	let confidence = 85; // Base confidence

	// Reduce for warnings
	confidence -= warningCount * 10;

	// Reduce for recent violations in this area
	confidence -= violationCount * 15;

	// Increase slightly for applicable learnings (they help)
	confidence += Math.min(learningCount * 5, 15);

	return Math.max(10, Math.min(100, confidence));
}

/**
 * Get recommendation based on confidence
 */
function getRecommendation(confidence: number): string {
	if (confidence >= 80) {
		return "proceed";
	}
	if (confidence >= 60) {
		return "review";
	}
	if (confidence >= 40) {
		return "caution";
	}
	return "stop";
}

