/**
 * TD-07: Load recent violations from disk for advisory context.
 * Reads .vreko/violations.jsonl and filters to violations relevant to target files.
 */
function _loadRecentViolations(
	workspaceRoot: string,
	targetFiles: string[],
	limit = 10,
): Array<{ type: string; file: string }> {
	try {
		const violationsPath = join(workspaceRoot, ".vreko", "violations.jsonl");
		if (!existsSync(violationsPath)) {
			return [];
		}

		const content = readFileSync(violationsPath, "utf-8");
		const lines = content.trim().split("\n").filter(Boolean);

		const violations: Array<{ type: string; file: string }> = [];
		for (const line of lines.slice(-50)) {
			// Read last 50 entries max
			try {
				const entry = JSON.parse(line) as { type?: string; file?: string };
				if (entry.type && entry.file) {
					violations.push({ type: entry.type, file: entry.file });
				}
			} catch {
				// Skip malformed lines
			}
		}

		// If target files specified, prioritize violations for those files
		if (targetFiles.length > 0) {
			const relevant = violations.filter((v) =>
				targetFiles.some((f) => v.file.includes(basename(f)) || f.includes(v.file)),
			);
			if (relevant.length > 0) {
				return relevant.slice(-limit);
			}
		}

		// Return most recent violations as general context
		return violations.slice(-limit);
	} catch {
		return [];
	}
}

/**
 * Find files with similar patterns to the target files.
 * Uses daemon IPC for structural similarity analysis.
 * Returns empty array if daemon unavailable (graceful fallback).
 */
async function findSimilarPatterns(
	targetFiles: string[],
	workspaceRoot: string,
	limit = 5,
): Promise<SimilarPatternMatch[]> {
	// Delegate to daemon IPC - replaces direct PatternReuseService instantiation
	return findSimilarPatternsViaDaemon(workspaceRoot, targetFiles, limit);
}

/**
 * Find TypeScript files in a directory (recursive, limited)
 */
function _findTypeScriptFiles(dir: string, limit: number): string[] {
	const results: string[] = [];
	const stack = [dir];

	while (stack.length > 0 && results.length < limit) {
		const current = stack.pop();
		if (!current) {
			continue;
		}
		try {
			const entries = readdirSync(current, { withFileTypes: true });
			for (const entry of entries) {
				if (results.length >= limit) {
					break;
				}

				const fullPath = join(current, entry.name);
				if (entry.isDirectory()) {
					// Skip node_modules, dist, etc.
					if (!entry.name.startsWith(".") && entry.name !== "node_modules" && entry.name !== "dist") {
						stack.push(fullPath);
					}
				} else if (entry.name.endsWith(".ts") && !entry.name.endsWith(".d.ts")) {
					results.push(fullPath);
				}
			}
		} catch {
			// Skip directories that can't be read
		}
	}

	return results;
}

/**
 * Build study_first recommendations based on intent and violations.
 */
function buildStudyRecommendations(
	_task: string,
	files: string[],
	intent: string,
	workspaceRoot: string,
	violations: Array<{ type: string; file: string; message: string }>,
	learnings: Array<{ trigger: string; action: string; type: string }>,
): StudyRecommendation[] {
	const recommendations: StudyRecommendation[] = [];
	const addedFiles = new Set<string>();

	// 1. From violations - study files with past issues
	for (const violation of violations.slice(0, 2)) {
		if (!addedFiles.has(violation.file)) {
			addedFiles.add(violation.file);
			recommendations.push({
				file: violation.file,
				reason: `Past violation: ${violation.type}`,
				priority: "high",
			});
		}
	}

	// 2. From learnings - extract file mentions
	for (const learning of learnings.slice(0, 3)) {
		const fileMatch = learning.action.match(/([\w-]+\.(?:ts|tsx|js|jsx))/gi);
		if (fileMatch) {
			for (const mentioned of fileMatch) {
				// Try to find the actual file
				const found = findFileInWorkspace(mentioned, workspaceRoot);
				if (found && !addedFiles.has(found)) {
					addedFiles.add(found);
					recommendations.push({
						file: found,
						reason: `From learning: ${learning.trigger.slice(0, 40)}`,
						priority: "medium",
					});
				}
			}
		}
	}

	// 3. Intent-based recommendations
	const intentFiles = getIntentBasedFiles(intent, workspaceRoot);
	for (const { file, reason } of intentFiles) {
		if (!addedFiles.has(file)) {
			addedFiles.add(file);
			recommendations.push({
				file,
				reason,
				priority: "low",
			});
		}
	}

	// 4. From target files - recommend parent/related files
	for (const file of files.slice(0, 2)) {
		const related = findRelatedFiles(file, workspaceRoot);
		for (const relFile of related) {
			if (!addedFiles.has(relFile)) {
				addedFiles.add(relFile);
				recommendations.push({
					file: relFile,
					reason: `Related to ${basename(file)}`,
					priority: "medium",
				});
			}
		}
	}

	return recommendations.slice(0, 5);
}

/**
 * Find a file in the workspace by name
 */
function findFileInWorkspace(filename: string, workspaceRoot: string): string | null {
	const searchDirs = ["src", "packages", "apps", "lib"];

	for (const dir of searchDirs) {
		const dirPath = join(workspaceRoot, dir);
		if (!existsSync(dirPath)) {
			continue;
		}

		try {
			const found = findFileRecursive(dirPath, filename);
			if (found) {
				return relative(workspaceRoot, found);
			}
		} catch {
			// Continue searching
		}
	}

	return null;
}

function findFileRecursive(dir: string, filename: string, depth = 0): string | null {
	if (depth > 5) {
		return null;
	}

	try {
		const entries = readdirSync(dir, { withFileTypes: true });
		for (const entry of entries) {
			const fullPath = join(dir, entry.name);
			if (entry.isDirectory() && !entry.name.startsWith(".") && entry.name !== "node_modules") {
				const found = findFileRecursive(fullPath, filename, depth + 1);
				if (found) {
					return found;
				}
			} else if (entry.name === filename) {
				return fullPath;
			}
		}
	} catch {
		// Skip directories that can't be read
	}

	return null;
}

/**
 * Get intent-based file recommendations
 */
function getIntentBasedFiles(intent: string, workspaceRoot: string): Array<{ file: string; reason: string }> {
	const results: Array<{ file: string; reason: string }> = [];

	const intentPatterns: Record<string, Array<{ pattern: string; reason: string }>> = {
		implement: [
			{ pattern: "types", reason: "Review type definitions" },
			{ pattern: "interfaces", reason: "Check existing interfaces" },
		],
		refactor: [
			{ pattern: "test", reason: "Ensure tests pass" },
			{ pattern: "spec", reason: "Check test coverage" },
		],
		debug: [
			{ pattern: "utils", reason: "Review utility functions" },
			{ pattern: "helpers", reason: "Check helper functions" },
		],
		test: [
			{ pattern: "fixtures", reason: "Review test fixtures" },
			{ pattern: "mock", reason: "Check existing mocks" },
		],
		deploy: [
			{ pattern: "config", reason: "Review configuration" },
			{ pattern: "env", reason: "Check environment setup" },
		],
	};

	const patterns = intentPatterns[intent] || [];
	for (const { pattern, reason } of patterns) {
		// Find first matching directory
		const searchDirs = ["src", "packages", "apps"];
		for (const dir of searchDirs) {
			const dirPath = join(workspaceRoot, dir, pattern);
			if (existsSync(dirPath)) {
				results.push({ file: join(dir, pattern), reason });
				break;
			}
		}
	}

	return results.slice(0, 2);
}

/**
 * Find related files (same directory, index files, etc.)
 */
function findRelatedFiles(file: string, workspaceRoot: string): string[] {
	const results: string[] = [];
	const fullPath = file.startsWith("/") ? file : join(workspaceRoot, file);
	const dir = dirname(fullPath);

	try {
		// Look for index.ts in same directory
		const indexPath = join(dir, "index.ts");
		if (existsSync(indexPath) && indexPath !== fullPath) {
			results.push(relative(workspaceRoot, indexPath));
		}

		// Look for types file
		const typesPath = join(dir, "types.ts");
		if (existsSync(typesPath) && typesPath !== fullPath) {
			results.push(relative(workspaceRoot, typesPath));
		}

		// Look for related test file
		const baseName = basename(file, ".ts");
		const testPath = join(dir, `${baseName}.test.ts`);
		if (existsSync(testPath)) {
			results.push(relative(workspaceRoot, testPath));
		}
	} catch {
		// Skip errors
	}

	return results;
}

/**
 * Build confidence reason explaining why the confidence is what it is
 */
function buildConfidenceReason(
	confidence: number,
	warnings: AdvisoryWarning[],
	learnings: Array<{ trigger: string; action: string; type: string }>,
	violations: Array<{ type: string; file: string; message: string }>,
	loopDetected: boolean,
): string {
	const parts: string[] = [];

	if (loopDetected) {
		parts.push("Agent loop detected - confidence reduced");
	}

	if (violations.length > 0) {
		parts.push(`${violations.length} past violation(s) in this area`);
	}

	if (warnings.length > 0) {
		parts.push(`${warnings.length} warning(s): ${warnings[0]?.message?.slice(0, 50) || "see details"}`);
	}

	if (learnings.length > 0) {
		parts.push(`${learnings.length} relevant learning(s) available`);
	}

	if (parts.length === 0) {
		if (confidence >= 80) {
			return "No issues detected - safe to proceed";
		}
		return "Standard confidence level for this task type";
	}

	return parts.join("; ");
}

