// Integration Enrichment Logic
// =============================================================================

/**
 * Get confidence adjustments from external integrations (GitHub, Sentry, Context7).
 * Adjustments based on:
 * - High Sentry errors: -15% confidence
 * - File highly volatile (frequent commits): -10% confidence
 * - Deprecated APIs detected: -5% confidence
 * - Clean production (no errors): +5% confidence
 */
async function getIntegrationConfidenceAdjustment(
	files: string[],
	context: ToolContext,
): Promise<IntegrationConfidenceAdjustment> {
	const result: IntegrationConfidenceAdjustment = {
		adjustment: 0,
		reasons: [],
		ext: {},
		enrichment: null,
	};

	// Try to get integration service from context or singleton
	const integrations = context.services?.integrations ?? getIntegrationOrchestratorService();
	if (!integrations) {
		return result;
	}

	// Check health first
	const health = integrations.getHealth();
	if (health.status === "unavailable") {
		return result;
	}

	// Get enriched context for the files
	try {
		const enrichment = await integrations.enrichContext({
			files: files.map((f) => ({ path: f })),
			skipCache: false,
		});

		if (!enrichment) {
			return result;
		}

		result.enrichment = enrichment;

		// Track aggregated data across all files
		let hasActivePR = false;
		let prNumber: number | undefined;
		let volatileFiles = 0;
		let totalErrors = 0;
		let deprecationCount = 0;
		let hasGitHub = false;
		let hasSentry = false;
		let hasContext7 = false;

		// Process each file's context from the enrichment
		for (const [, fileContext] of enrichment.contexts) {
			const { sources } = fileContext;

			// Process GitHub context
			if (sources.github) {
				hasGitHub = true;
				const github = sources.github;

				// Check for active PR
				if (github.activePR && !hasActivePR) {
					hasActivePR = true;
					prNumber = github.activePR.number;
				}

				// Check file volatility using changeFrequency
				if (github.changeFrequency === "volatile") {
					volatileFiles++;
				}
			}

			// Process Sentry context
			if (sources.sentry) {
				hasSentry = true;
				totalErrors += sources.sentry.errors?.length ?? 0;
			}

			// Process Context7 context
			if (sources.context7) {
				hasContext7 = true;
				// Count deprecated imports
				const deprecated = sources.context7.imports?.filter((i) => i.isDeprecated) ?? [];
				deprecationCount += deprecated.length;
			}
		}

		// Apply GitHub adjustments
		if (hasGitHub) {
			if (hasActivePR) {
				result.ext.github = `pr:${prNumber}`;
				result.adjustment += 3;
				result.reasons.push("Code under PR review (+3%)");
			} else if (volatileFiles > 0) {
				result.ext.github = `volatile:${volatileFiles}`;
				result.adjustment -= 10;
				result.reasons.push(`High file volatility (${volatileFiles} volatile file(s)) (-10%)`);
			} else {
				result.ext.github = "ok";
			}
		}

		// Apply Sentry adjustments
		if (hasSentry) {
			if (totalErrors >= 5) {
				result.adjustment -= 15;
				result.reasons.push(`High Sentry errors (${totalErrors}) - production issues (-15%)`);
				result.ext.sentry = `${totalErrors}err`;
			} else if (totalErrors >= 2) {
				result.adjustment -= 10;
				result.reasons.push(`Sentry errors (${totalErrors}) - some production issues (-10%)`);
				result.ext.sentry = `${totalErrors}err`;
			} else if (totalErrors > 0) {
				result.adjustment -= 5;
				result.reasons.push(`Minor Sentry errors (${totalErrors}) (-5%)`);
				result.ext.sentry = `${totalErrors}err`;
			} else {
				// Clean production - confidence boost
				result.adjustment += 5;
				result.reasons.push("Clean production - no Sentry errors (+5%)");
				result.ext.sentry = "ok";
			}
		}

		// Apply Context7 adjustments
		if (hasContext7) {
			if (deprecationCount > 0) {
				result.adjustment -= 5;
				result.reasons.push(`Deprecated APIs detected (${deprecationCount}) (-5%)`);
				result.ext.context7 = `${deprecationCount}dep`;
			} else {
				result.ext.context7 = "ok";
			}
		}
	} catch {
		// Integration enrichment failed - continue without it
	}

	return result;
}

