// Trust Builder UX - Formatting Functions
// =============================================================================

/**
 * Extract dominant approach from similar patterns.
 * Returns pattern name if it appears in >50% of matches.
 * Guards against analysis cost by capping text scan and pattern count.
 */
function extractDominantApproach(
	similarPatterns: SimilarPatternMatch[],
	learnings: Array<{ trigger: string; action: string; type: string }>,
): string | null {
	if (similarPatterns.length === 0 && learnings.length === 0) {
		return null;
	}

	// Common pattern names to search for
	const patternRegex =
		/\b(middleware|factory|singleton|observer|strategy|adapter|decorator|proxy|builder|facade|repository|service|controller|handler)\b/gi;
	const patternCounts = new Map<string, number>();

	// Scan similar patterns (max 10, first 50 chars of relevance)
	const maxPatterns = Math.min(similarPatterns.length, 10);
	for (let i = 0; i < maxPatterns; i++) {
		const relevance = similarPatterns[i].relevance.slice(0, 50).toLowerCase();
		const matches = relevance.match(patternRegex);
		if (matches) {
			for (const match of matches) {
				const normalized = match.toLowerCase();
				patternCounts.set(normalized, (patternCounts.get(normalized) || 0) + 1);
			}
		}
	}

	// Scan learnings (max 10, first 50 chars of action)
	const maxLearnings = Math.min(learnings.length, 10);
	for (let i = 0; i < maxLearnings; i++) {
		const action = learnings[i].action.slice(0, 50).toLowerCase();
		const matches = action.match(patternRegex);
		if (matches) {
			for (const match of matches) {
				const normalized = match.toLowerCase();
				patternCounts.set(normalized, (patternCounts.get(normalized) || 0) + 1);
			}
		}
	}

	if (patternCounts.size === 0) {
		return null;
	}

	// Find dominant pattern (>50% prevalence)
	const totalSources = maxPatterns + maxLearnings;
	const threshold = totalSources * 0.5;

	let maxCount = 0;
	let dominantPattern: string | null = null;

	for (const [pattern, count] of patternCounts.entries()) {
		if (count > maxCount && count >= threshold) {
			maxCount = count;
			dominantPattern = pattern;
		}
	}

	return dominantPattern;
}

/**
 * Build "WHAT I KNOW ABOUT THIS" section with authority framing.
 */
function buildWhatIKnow(
	learnings: Array<{ trigger: string; action: string; type: string }>,
	warnings: AdvisoryWarning[],
	violations: Array<{ type: string; file: string; message: string }>,
	learningTypes: string[],
): string {
	const lines: string[] = ["WHAT I KNOW ABOUT THIS:"];

	// Learning types with emoji
	if (learnings.length > 0) {
		const typeNames = learningTypes.slice(0, 3).join(", ");
		lines.push(`  📚 ${learnings.length} relevant patterns loaded (${typeNames})`);
	}

	// Warnings with urgency
	if (warnings.length > 0) {
		const zone = warnings.length >= 3 ? "high fragility zone" : "elevated risk area";
		lines.push(`  ⚠️ ${warnings.length} warning${warnings.length > 1 ? "s" : ""} in this area  -  ${zone}`);
	}

	// Violations with severity
	if (violations.length > 0) {
		lines.push(`  🔥 ${violations.length} past violation${violations.length > 1 ? "s" : ""}  -  handle with care`);
	}

	return lines.join("\n");
}

/**
 * Build "RECOMMENDED APPROACH" section with opinionated voice.
 * Includes "why not" signal when multiple approaches exist.
 */
function buildRecommendedApproach(
	dominantApproach: string | null,
	similarPatterns: SimilarPatternMatch[],
	learnings: Array<{ trigger: string; action: string; type: string }>,
): string {
	const lines: string[] = ["RECOMMENDED APPROACH:"];

	// Dominant approach with prevalence
	if (dominantApproach && similarPatterns.length > 0) {
		const dominantCount = similarPatterns.filter((p) =>
			p.relevance.toLowerCase().includes(dominantApproach),
		).length;
		lines.push(`  → Use ${dominantApproach} pattern (seen in ${dominantCount} similar implementations)`);

		// Check for alternative approach ("why not" signal)
		const altPattern = similarPatterns.find(
			(p) => !p.relevance.toLowerCase().includes(dominantApproach) && p.score >= 0.6,
		);
		if (altPattern && dominantCount - 1 >= 2) {
			// Only show if dominant is significantly more common
			const altMatch = altPattern.relevance.match(
				/\b(middleware|factory|singleton|observer|strategy|adapter|decorator|proxy|builder|facade)\b/gi,
			);
			if (altMatch && altMatch[0].toLowerCase() !== dominantApproach) {
				const altName = altMatch[0].toLowerCase();
				lines.push(`  ⚠️ Alternative: ${altName} exists but less common (${dominantCount} vs 1 use)`);
			}
		}
	}

	// Extract top 2 actionable learnings (opinionated language)
	const actionable = learnings.filter((l) => l.type === "pattern" || l.type === "workflow").slice(0, 2);
	for (const learning of actionable) {
		const action = truncate(learning.action, 60);
		// Convert to directive: "always do X" → "Do X", "use Y" → "Use Y"
		const directive = action.replace(/^(always |you should |consider |try to )/i, "");
		const capitalized = directive.charAt(0).toUpperCase() + directive.slice(1);
		lines.push(`  → ${capitalized}`);
	}

	return lines.join("\n");
}

/**
 * Build "START HERE" section with numbered directive steps.
 */
function buildStartHere(studyFirst: StudyRecommendation[]): string {
	if (studyFirst.length === 0) {
		return "";
	}

	const lines: string[] = ["START HERE (do these first):"];

	for (let i = 0; i < Math.min(studyFirst.length, 5); i++) {
		const study = studyFirst[i];
		const icon = study.priority === "high" ? "🔴" : study.priority === "medium" ? "🟡" : "🟢";
		const num = i + 1;

		// Directive framing: "Past violation: X" → "Review this  -  it has past violations"
		let directiveReason = study.reason;
		if (study.reason.startsWith("Past violation:")) {
			directiveReason = `Review this  -  ${study.reason.toLowerCase()}`;
		} else if (study.reason.startsWith("From learning:")) {
			directiveReason = `Study this pattern  -  ${study.reason.replace("From learning:", "").trim()}`;
		} else if (study.reason.startsWith("Related to")) {
			directiveReason = `Check dependencies  -  ${study.reason.toLowerCase()}`;
		}

		lines.push(`  ${num}. ${icon} Read \`${study.file}\`  -  ${directiveReason}`);
	}

	return lines.join("\n");
}

/**
 * Build "WATCH OUT FOR" section with trajectory signals.
 */
function buildWatchOutFor(
	warnings: AdvisoryWarning[],
	violations: Array<{ type: string; file: string; message: string }>,
	integrationAdjustment: IntegrationConfidenceAdjustment,
): string {
	const lines: string[] = ["WATCH OUT FOR:"];
	let hasContent = false;

	// Integration adjustment reasons (churn, errors, deprecations)
	for (const reason of integrationAdjustment.reasons.slice(0, 2)) {
		lines.push(`  ⚠️ ${reason}`);
		hasContent = true;
	}

	// Top warnings
	for (const warning of warnings.slice(0, 2)) {
		lines.push(`  ⚠️ ${warning.message}`);
		hasContent = true;
	}

	// Past violations
	for (const violation of violations.slice(0, 2)) {
		lines.push(`  ❌ Past violation: ${violation.type}  -  don't repeat this`);
		hasContent = true;
	}

	return hasContent ? lines.join("\n") : "";
}

/**
 * Build LLM_HINT block with confidence-based guidance.
 * Max 3 bullets to keep terse.
 */
function buildAdviseHint(
	confidence: number,
	_recommendation: string,
	studyCount: number,
	dominantApproach: string | null,
): string {
	const hints: string[] = [];

	// Priority 1: Follow approach (if exists)
	if (dominantApproach) {
		hints.push("Follow RECOMMENDED APPROACH above  -  it's battle-tested in this codebase");
	}

	// Priority 2: Study first (if exists)
	if (studyCount > 0 && hints.length < 3) {
		hints.push("Complete START HERE steps before implementation");
	}

	// Priority 3: Confidence-based validation
	if (hints.length < 3) {
		if (confidence < 40) {
			hints.push("STOP and investigate warnings before proceeding");
		} else if (confidence < 60) {
			hints.push("Call check(mode:'architecture') to validate approach");
		} else if (confidence >= 80) {
			hints.push("High confidence  -  proceed with implementation");
		}
	}

	// Enforce max 3 bullets
	const capped = hints.slice(0, 3);
	return `LLM_HINT:\n${capped.map((h) => `- ${h}`).join("\n")}`;
}

