export const adviseTool: VrekoTool = {
	name: "advise",
	description: `[DEPRECATED  -  use vreko_begin/vreko_learn/vreko_end/vreko_pulse] Get pre-action recommendations: confidence score, warnings, applicable learnings.
Use when vreko(start) returned low confidence, before risky changes, or when uncertain about approach.
Do NOT use if vreko(start) already provided sufficient context  -  avoid redundant calls.
Params: task, files, intent ("implement"|"refactor"|"debug"|"test"|"deploy").`,
	inputSchema: {
		type: "object",
		properties: {
			task: {
				type: "string",
				description: "What you're about to do",
			},
			files: {
				type: "array",
				items: { type: "string" },
				description: "Files you plan to modify",
			},
			intent: {
				type: "string",
				enum: ["implement", "refactor", "debug", "test", "deploy"],
				description: "Type of work",
			},
		},
		required: [],
	},
	annotations: {
		title: "🦎 Vreko Advise",
		readOnlyHint: true,
		destructiveHint: false,
		idempotentHint: true,
	},
};

// =============================================================================
// Handler
// =============================================================================

export async function handleAdvise(args: Record<string, unknown>, context: ToolContext): Promise<ToolResult> {
	const { task = "general task", files = [], intent = "implement" } = args as AdviseArgs;
	const filesArray = files as string[];

	// Get workspace root
	const workspaceRoot = getWorkspaceRoot(context);

	// =========================================================================
	// LOOP DETECTION - Check if agent is stuck in a cycle
	// =========================================================================
	let loopDetected = false;
	let loopConfidence = 0;
	let loopType: string | undefined;
	let loopEvidence: string[] = [];
	if (context.sessionId && context.services?.sessionManager) {
		try {
			const loopResult = context.services.sessionManager.detectLoop(context.sessionId);
			loopDetected = loopResult.detected;
			loopConfidence = loopResult.confidence;
			loopType = loopResult.type;
			loopEvidence = loopResult.evidence;
		} catch {
			// Loop detection failed, continue without it
		}
	}

	// =========================================================================
	// TOOL AVAILABILITY - Query for helper tools (sequential-thinking, etc.)
	// =========================================================================
	let availableHelpers: string[] = [];
	if (context.services?.mcp) {
		try {
			const tools = await context.services.mcp.listTools();
			availableHelpers = tools
				.filter((t) => ["sequential-thinking", "search_web", "context7"].includes(t.name))
				.map((t) => t.name);
		} catch {
			// MCP query failed, continue without suggestions
		}
	}

	const warnings: AdvisoryWarning[] = [];
	const learnings: Array<{ trigger: string; action: string; type: string }> = [];
	const violations: Array<{ type: string; file: string; message: string }> = [];
	let hint = "";

	// Calculate confidence (reduced drastically if loop detected)
	let confidence = calculateConfidence(warnings.length, learnings.length, violations.length);
	if (loopDetected) {
		// Loop detected - drastically reduce confidence based on loop severity
		if (loopConfidence >= 0.8) {
			// HALT threshold - force very low confidence
			confidence = Math.min(confidence, 25);
		} else if (loopConfidence >= 0.5) {
			// WARN threshold - reduce confidence significantly
			confidence = Math.min(confidence, 45);
		}
	}

	// =========================================================================
	// INTEGRATION ENRICHMENT - Adjust confidence based on external data
	// =========================================================================
	const integrationAdjustment = await getIntegrationConfidenceAdjustment(filesArray, context);
	confidence = Math.max(10, Math.min(100, confidence + integrationAdjustment.adjustment));

	const recommendation = getRecommendation(confidence);

	// Generate hint if loop detected and helpers available
	if (loopDetected && availableHelpers.length > 0 && !hint) {
		hint = `Agent loop detected - try ${availableHelpers[0].replace(/-/g, "_")} to break pattern`;
	} else if (loopDetected && !hint) {
		hint = "Agent loop detected - consider alternative approach or bail out";
	}

	// =========================================================================
	// P1: BUILD CONCRETE RECOMMENDATIONS
	// =========================================================================

	let studyFirst: StudyRecommendation[] = [];
	let similarPatterns: SimilarPatternMatch[] = [];
	let dominantApproach: string | null = null;

	try {
		// Find similar patterns in workspace
		if (filesArray.length > 0) {
			similarPatterns = await findSimilarPatterns(filesArray, workspaceRoot, 3);
		}

		// Build study recommendations
		studyFirst = buildStudyRecommendations(task, filesArray, intent, workspaceRoot, violations, learnings);

		// Extract dominant approach for opinionated guidance
		dominantApproach = extractDominantApproach(similarPatterns, learnings);
	} catch {
		// Concrete recommendations failed - continue with basic advice
	}

	// Build confidence reason including integration adjustments
	let confidenceReason = buildConfidenceReason(confidence, warnings, learnings, violations, loopDetected);
	if (integrationAdjustment.reasons.length > 0) {
		confidenceReason = `${confidenceReason}; ${integrationAdjustment.reasons.join("; ")}`;
	}

	// Build wire format response with loop detection
	const wireParts = [
		"🧠",
		`conf:${confidence}`,
		`rec:${recommendation}`,
		`warn:${warnings.length}`,
		`learn:${learnings.length}`,
		`viol:${violations.length}`,
	];

	// Add study count if any
	if (studyFirst.length > 0) {
		wireParts.push(`study:${studyFirst.length}`);
	}

	// Add similar patterns count if any
	if (similarPatterns.length > 0) {
		wireParts.push(`sim:${similarPatterns.length}`);
	}

	// Add dominant approach if found
	if (dominantApproach) {
		wireParts.push(`approach:${dominantApproach}`);
	}

	// Add loop detection fields if detected
	if (loopDetected) {
		wireParts.push("loop:Y");
		wireParts.push(`lc:${Math.round(loopConfidence * 100)}`); // loop_conf → lc (save 7 chars)
		if (loopType) {
			// Abbreviate: structural→s, semantic→m, both→b (save ~8 chars)
			const typeAbbr = loopType === "structural" ? "s" : loopType === "semantic" ? "m" : "b";
			wireParts.push(`lt:${typeAbbr}`); // loop_type → lt (save 5 chars)
		}
		if (loopEvidence.length > 0) {
			// Reduce evidence from 40→25 chars (save 15 chars)
			const evidence = loopEvidence[0].replace(/\s+/g, "_").slice(0, 25);
			wireParts.push(`ev:${evidence}`); // evidence → ev (save 5 chars)
		}
	}

	// Add hint (reduce from 40→30 chars to save 10 chars when present)
	if (hint) {
		wireParts.push(`hint:${hint.slice(0, 30).replace(/\s+/g, "_")}`); // 40→30 (save 10)
	}

	// Add integration status if available
	const extParts: string[] = [];
	if (integrationAdjustment.ext.github) {
		extParts.push(`gh:${integrationAdjustment.ext.github}`);
	}
	if (integrationAdjustment.ext.sentry) {
		extParts.push(`sn:${integrationAdjustment.ext.sentry}`);
	}
	if (integrationAdjustment.ext.context7) {
		extParts.push(`c7:${integrationAdjustment.ext.context7}`);
	}
	if (extParts.length > 0) {
		wireParts.push(`ext:${extParts.join(",")}`);
	}

	const wire = wireParts.filter(Boolean).join("|");

	// =========================================================================
	// TRUST BUILDER UX - Build senior-dev mentor output
	// =========================================================================

	// Extract unique learning types for WHAT I KNOW
	const learningTypes = Array.from(new Set(learnings.map((l) => l.type)));

	// Build Trust Builder sections
	const whatIKnow = buildWhatIKnow(learnings, warnings, violations, learningTypes);

	const recommendedApproach =
		dominantApproach || learnings.length > 0
			? buildRecommendedApproach(dominantApproach, similarPatterns, learnings)
			: "";

	const startHere = studyFirst.length > 0 ? buildStartHere(studyFirst) : "";

	const watchOutFor =
		warnings.length > 0 || violations.length > 0 || integrationAdjustment.reasons.length > 0
			? buildWatchOutFor(warnings, violations, integrationAdjustment)
			: "";

	const llmHint = buildAdviseHint(confidence, recommendation, studyFirst.length, dominantApproach);

	// Build senior-dev greeting with trajectory context
	const learningTrajectory = getLearningTrajectory(workspaceRoot);
	const trajectoryContext = learningTrajectory
		? `Based on ${learningTrajectory.totalTracked} learnings and ${similarPatterns.length} similar patterns`
		: `Based on ${learnings.length} relevant learnings`;

	const confidenceLabel =
		confidence >= 80
			? "PROCEED"
			: confidence >= 60
				? "REVIEW CAREFULLY"
				: confidence >= 40
					? "CAUTION"
					: "STOP AND INVESTIGATE";

	// Assemble output
	const sections = [whatIKnow, recommendedApproach, startHere, watchOutFor, llmHint].filter(Boolean).join("\n\n");

	const summary = `${sections}
---
🧠 Vreko Advisory: ${trajectoryContext}
  Confidence: ${confidence}% (${confidenceLabel})  -  ${confidenceReason}
  Intent: ${intent} | Files: ${filesArray.length > 0 ? filesArray.join(", ") : "none"}`;

	// Build structuredContent for programmatic parsing
	const structuredContent: Record<string, unknown> = {
		confidence,
		recommendation,
		warnings: warnings.map((w) => ({ level: w.level, code: w.code, message: w.message })),
		learnings: learnings.slice(0, 5),
		violations: violations.slice(0, 3),
		studyFirst,
		similarPatterns,
		loopDetection: loopDetected
			? { detected: true, confidence: loopConfidence, type: loopType, evidence: loopEvidence }
			: { detected: false },
	};

	// Add integration data if available
	if (integrationAdjustment.enrichment) {
		structuredContent.integrations = {
			adjustment: integrationAdjustment.adjustment,
			reasons: integrationAdjustment.reasons,
			status: integrationAdjustment.ext,
			riskScore: integrationAdjustment.enrichment.riskScore,
			riskFactors: integrationAdjustment.enrichment.riskFactors,
			sources: integrationAdjustment.enrichment.sources,
		};
	}

	return {
		content: [
			{
				type: "text",
				text: `${wire}\n${summary}`,
			},
		],
		structuredContent,
	};
}
