/**
 * Ceremony validation for vreko-end module
 *
 * Maximum confidence validation cascade before session close.
 *
 * @module tools/consolidated/vreko-end/ceremony-validator
 */

import { exec } from "node:child_process";
import { existsSync } from "node:fs";
import { join } from "node:path";
import { promisify } from "node:util";
import { recordValidationEventAsync, trackActualToolCallAsync } from "../../../adapters/session-adapter.js";
import type { ToolContext } from "../../../types/tool-types.js";
import type { CeremonyLevel, CeremonyResult, SnapEndParams, ValidationStepResult } from "./types.js";

const execAsync = promisify(exec);

// =============================================================================
// CEREMONY LEVEL UTILITIES
// =============================================================================

/**
 * Determine ceremony level from params
 */
export function getCeremonyLevel(ceremony: boolean | CeremonyLevel | undefined): CeremonyLevel | null {
	if (!ceremony) {
		return null;
	}
	if (ceremony === true) {
		return "standard";
	}
	return ceremony;
}

/**
 * Get validation scopes for ceremony level
 */
export function getScopesForLevel(
	level: CeremonyLevel,
	customScopes?: SnapEndParams["scopes"],
): Array<"typescript" | "lint" | "tests" | "architecture" | "security" | "coverage"> {
	if (customScopes && customScopes.length > 0) {
		return customScopes;
	}

	switch (level) {
		case "quick":
			return ["typescript", "lint"];
		case "standard":
			return ["typescript", "lint", "tests", "architecture"];
		case "comprehensive":
			return ["typescript", "lint", "tests", "architecture", "security", "coverage"];
	}
}

// =============================================================================
// VALIDATION STEPS
// =============================================================================

/**
 * Run a single validation step using the check tool
 */
export async function runValidationStep(
	scope: string,
	context: ToolContext,
	diffScope: "staged" | "uncommitted" | "all" = "uncommitted",
): Promise<ValidationStepResult> {
	const start = Date.now();
	const INTERNAL_SEPARATOR = "---";

	try {
		// Import the check handler dynamically to avoid circular deps
		const { handleCheck } = await import("../check.js");

		// Map scope to check mode
		const modeMap: Record<string, string> = {
			typescript: "quick", // quick mode includes TS
			lint: "quick", // quick mode includes lint
			tests: "full", // full mode runs tests
			architecture: "architecture",
			security: "security",
			coverage: "coverage",
		};

		const mode = modeMap[scope] || "quick";
		// Map diffScope to check's diff param (all = no diff filtering)
		const diff = diffScope === "all" ? undefined : diffScope;
		const result = await handleCheck({ mode, diff }, context);
		const content = result.content[0]?.text || "";

		// Parse result to extract pass/fail
		// Require positive confirmation of success (status:✓), not just absence of failure
		const hasSuccessMarker = content.includes("status:✓") || content.includes("status:OK");
		const hasFailureMarker = content.includes("status:✗");

		// If we have a wire format response, trust the status marker
		// If no wire format is present, treat as failure (malformed response)
		const hasWireFormat = content.includes("err:") && content.includes("warn:");
		const passed = hasWireFormat && hasSuccessMarker && !hasFailureMarker;

		const errorMatch = content.match(/err:(\d+)E/);
		const warnMatch = content.match(/warn:(\d+)W/);

		// Extract error/warning counts, but if validation failed without a wire format,
		// indicate this clearly in the error count
		const errors = errorMatch ? Number.parseInt(errorMatch[1], 10) : passed ? 0 : 1;
		const warnings = warnMatch ? Number.parseInt(warnMatch[1], 10) : 0;

		return {
			step: scope,
			passed,
			errors,
			warnings,
			duration: Date.now() - start,
			details: passed ? undefined : content.split(INTERNAL_SEPARATOR)[0],
		};
	} catch (error) {
		return {
			step: scope,
			passed: false,
			errors: 1,
			warnings: 0,
			duration: Date.now() - start,
			details: error instanceof Error ? error.message : "Validation failed",
		};
	}
}

/**
 * Run verify script (for comprehensive mode)
 */
export async function runVerifyScript(workspaceRoot: string, scriptPath?: string): Promise<ValidationStepResult> {
	const start = Date.now();
	const script = scriptPath || "./verify.sh";

	try {
		// Check if script exists
		const fullPath = join(workspaceRoot, script);
		if (!existsSync(fullPath) && !scriptPath) {
			// No default verify.sh, try common alternatives
			const alternatives = ["pnpm verify", "npm run verify", "pnpm test && pnpm lint", "pnpm build"]; // NOGUARD:unregistered-scripts  -  dynamic fallback commands for user projects
			for (const alt of alternatives) {
				try {
					await execAsync(alt, { cwd: workspaceRoot, timeout: 120000 });
					return {
						step: "verify-script",
						passed: true,
						errors: 0,
						warnings: 0,
						duration: Date.now() - start,
						details: `Ran: ${alt}`,
					};
				} catch {
					// Try next alternative
				}
			}
			// No verify script found, skip
			return {
				step: "verify-script",
				passed: true,
				errors: 0,
				warnings: 0,
				duration: Date.now() - start,
				details: "No verify script found, skipped",
			};
		}

		// Run the script
		const { stdout, stderr } = await execAsync(script, {
			cwd: workspaceRoot,
			timeout: 300000, // 5 minute timeout
		});

		return {
			step: "verify-script",
			passed: true,
			errors: 0,
			warnings: stderr ? 1 : 0,
			duration: Date.now() - start,
			details: stdout ? stdout.slice(0, 500) : undefined,
		};
	} catch (error) {
		const errMsg = error instanceof Error ? error.message : String(error);
		return {
			step: "verify-script",
			passed: false,
			errors: 1,
			warnings: 0,
			duration: Date.now() - start,
			details: errMsg.slice(0, 500),
		};
	}
}

// =============================================================================
// CEREMONY CASCADE
// =============================================================================

/**
 * Run ceremony validation cascade
 *
 * Implements the maximum confidence workflow:
 * 1. Quick diff gate (types + lint on staged/uncommitted)
 * 2. Deep system validation (full mode)
 * 3. Architecture integrity pass
 * 4. Extended audits (security, coverage) for comprehensive
 * 5. Verify script for comprehensive
 */
export async function runCeremony(params: SnapEndParams, context: ToolContext): Promise<CeremonyResult> {
	const level = getCeremonyLevel(params.ceremony) ?? "standard";
	const scopes = getScopesForLevel(level, params.scopes);
	const diffScope = params.diffScope ?? "uncommitted";
	const steps: ValidationStepResult[] = [];
	const blockers: string[] = [];
	const warnings: string[] = [];
	const totalStart = Date.now();

	// Phase 1: Quick validation (always first)
	if (scopes.includes("typescript") || scopes.includes("lint")) {
		const quickResult = await runValidationStep("quick", context, diffScope);
		steps.push({ ...quickResult, step: "quick (types+lint)" });
		// TD-10: Track ceremony check for follow-through
		await trackActualToolCallAsync(context.workspaceRoot, "check", "quick");
		// Record validation event for quick (types + lint) pass/fail
		await recordValidationEventAsync(context.workspaceRoot, {
			source: "ceremony",
			category: "typescript",
			tool: "check",
			mode: "quick",
			success: quickResult.passed,
			details: quickResult.details,
		});

		if (!quickResult.passed) {
			blockers.push(`Quick validation failed: ${quickResult.errors} error(s)`);
			if (level === "quick") {
				// Quick mode stops on first failure
				return {
					passed: false,
					level,
					steps,
					totalDuration: Date.now() - totalStart,
					blockers,
					warnings,
				};
			}
		}
	}

	// Phase 2: Tests (standard and comprehensive)
	if (scopes.includes("tests")) {
		const testResult = await runValidationStep("tests", context, diffScope);
		steps.push(testResult);
		await trackActualToolCallAsync(context.workspaceRoot, "check", "tests");
		await recordValidationEventAsync(context.workspaceRoot, {
			source: "ceremony",
			category: "tests",
			tool: "check",
			mode: "tests",
			success: testResult.passed,
			details: testResult.details,
		});

		if (!testResult.passed) {
			blockers.push(`Tests failed: ${testResult.errors} error(s)`);
		}
	}

	// Phase 3: Architecture check (standard and comprehensive)
	if (scopes.includes("architecture")) {
		const archResult = await runValidationStep("architecture", context, diffScope);
		steps.push(archResult);
		await trackActualToolCallAsync(context.workspaceRoot, "check", "architecture");
		await recordValidationEventAsync(context.workspaceRoot, {
			source: "ceremony",
			category: "architecture",
			tool: "check",
			mode: "architecture",
			success: archResult.passed,
			details: archResult.details,
		});

		if (!archResult.passed) {
			blockers.push(`Architecture violations: ${archResult.errors} issue(s)`);
		}
	}

	// Phase 4: Security (comprehensive only by default, or via scopes)
	if (scopes.includes("security")) {
		const secResult = await runValidationStep("security", context, diffScope);
		steps.push(secResult);
		await trackActualToolCallAsync(context.workspaceRoot, "check", "security");
		await recordValidationEventAsync(context.workspaceRoot, {
			source: "ceremony",
			category: "security",
			tool: "check",
			mode: "security",
			success: secResult.passed,
			details: secResult.details,
		});

		if (!secResult.passed) {
			// Security failures are blockers
			blockers.push(`Security issues: ${secResult.errors} finding(s)`);
		}
	}

	// Phase 5: Coverage (comprehensive only by default, or via scopes)
	if (scopes.includes("coverage")) {
		const covResult = await runValidationStep("coverage", context, diffScope);
		steps.push(covResult);
		await trackActualToolCallAsync(context.workspaceRoot, "check", "coverage");
		await recordValidationEventAsync(context.workspaceRoot, {
			source: "ceremony",
			category: "coverage",
			tool: "check",
			mode: "coverage",
			success: covResult.passed,
			details: covResult.details,
		});

		if (!covResult.passed) {
			// Coverage warnings, not blockers
			warnings.push(`Coverage gaps: ${covResult.errors} issue(s)`);
		}
	}

	// Phase 6: Verify script (runs at ANY level when specified, or comprehensive by default)
	if (params.verifyScript || level === "comprehensive") {
		const verifyResult = await runVerifyScript(context.workspaceRoot, params.verifyScript);
		steps.push(verifyResult);
		// Treat verify script (or its fallbacks) as a build-level validation signal
		await recordValidationEventAsync(context.workspaceRoot, {
			source: "ceremony",
			category: "build",
			tool: "snap_end",
			mode: "verify-script",
			success: verifyResult.passed,
			details: verifyResult.details,
		});

		if (!verifyResult.passed) {
			blockers.push(`Verify script failed: ${verifyResult.details}`);
		}
	}

	return {
		passed: blockers.length === 0,
		level,
		steps,
		totalDuration: Date.now() - totalStart,
		blockers,
		warnings,
	};
}

// =============================================================================
// FORMATTING
// =============================================================================

/**
 * Build a visual progress bar for ceremony steps
 */
export function buildProgressBar(passed: number, total: number): string {
	const filled = "█";
	const empty = "░";
	const barLength = total;
	const bar = filled.repeat(passed) + empty.repeat(Math.max(0, barLength - passed));
	const pct = total > 0 ? Math.round((passed / total) * 100) : 0;
	return `[${bar}] ${pct}%`;
}

/**
 * Format ceremony result for output with visual progress indicators
 */
export function formatCeremonyResult(result: CeremonyResult): string {
	const statusIcon = result.passed ? "✅" : "❌";
	const levelIcon = result.level === "comprehensive" ? "🎯" : result.level === "standard" ? "🔍" : "⚡";

	let output = `\n${levelIcon} CEREMONY [${result.level.toUpperCase()}] ${statusIcon}\n`;

	// Visual step-by-step progress
	for (let i = 0; i < result.steps.length; i++) {
		const step = result.steps[i];
		const icon = step.passed ? "✅" : "❌";
		const timing = step.duration < 1000 ? `${step.duration}ms` : `${(step.duration / 1000).toFixed(1)}s`;
		const detail =
			step.errors > 0 ? ` (${step.errors}E ${step.warnings}W)` : step.warnings > 0 ? ` (${step.warnings}W)` : "";
		output += `  ${icon} ${step.step}${detail} ${timing}\n`;
	}

	// Progress summary bar
	const totalSteps = result.steps.length;
	const passedSteps = result.steps.filter((s) => s.passed).length;
	output += `\n  ${buildProgressBar(passedSteps, totalSteps)} ${passedSteps}/${totalSteps} checks passed`;

	// Blockers
	if (result.blockers.length > 0) {
		output += `\n\n🚫 BLOCKERS (${result.blockers.length}):\n`;
		for (const blocker of result.blockers) {
			output += `  - ${blocker}\n`;
		}
	}

	// Warnings
	if (result.warnings.length > 0) {
		output += `\n⚠️ WARNINGS (${result.warnings.length}):\n`;
		for (const warning of result.warnings) {
			output += `  - ${warning}\n`;
		}
	}

	// Duration
	const totalTime =
		result.totalDuration < 1000 ? `${result.totalDuration}ms` : `${(result.totalDuration / 1000).toFixed(1)}s`;
	output += `\n⏱️ Total: ${totalTime}`;

	return output;
}

/**
 * Build ceremony wire format fields
 */
export function buildCeremonyWireFields(result: CeremonyResult): Record<string, string | number> {
	return {
		ceremony: result.level,
		ceremony_passed: result.passed ? 1 : 0,
		ceremony_steps: result.steps.length,
		ceremony_errors: result.steps.reduce((sum, s) => sum + s.errors, 0),
		ceremony_warnings: result.steps.reduce((sum, s) => sum + s.warnings, 0),
		ceremony_duration: `${result.totalDuration}ms`,
	};
}
