/**
 * Wire format options
 *
 * P2 ENHANCEMENT: Added `humanReadable` option (default: true) for better UX.
 * Wire format is now opt-in via `compact: true` for programmatic use.
 */
export interface WireFormatOptions {
	/**
	 * Use compact wire format for programmatic consumption.
	 * When false (default), outputs human-readable format.
	 * When true, outputs wire format for token efficiency.
	 */
	compact?: boolean;
}

/**
 * P2: Human-readable output templates for better UX
 */
const HUMAN_READABLE_TEMPLATES = {
	S: {
		created: (data: Record<string, unknown>) =>
			`✓ Snapshot created (${riskLabel(data.risk as string)} risk, ${data.dirty} uncommitted file${data.dirty !== 1 ? "s" : ""})\n  Protected at ${data.prot}% confidence`,
		reused: (data: Record<string, unknown>) =>
			`✓ Task started (reusing existing snapshot, ${riskLabel(data.risk as string)} risk)\n  Protection: ${data.prot}%`,
		skipped: (data: Record<string, unknown>) =>
			`✓ Task started (${riskLabel(data.risk as string)} risk, no snapshot needed)\n  Protection: ${data.prot}%`,
	},
	C: {
		passed: (data: Record<string, unknown>) =>
			`✓ All checks passed (${data.warn || 0} warning${(data.warn || 0) !== 1 ? "s" : ""})`,
		failed: (data: Record<string, unknown>) =>
			`✗ Check failed: ${data.err} error${data.err !== 1 ? "s" : ""}, ${data.warn || 0} warning${(data.warn || 0) !== 1 ? "s" : ""}`,
	},
	E: {
		ok: (data: Record<string, unknown>) =>
			`✓ Task complete! Captured ${data.learn || 0} learning${data.learn !== 1 ? "s" : ""}, modified ${data.files || 0} file${data.files !== 1 ? "s" : ""}`,
		fail: (data: Record<string, unknown>) => `Task ended with issues. Files modified: ${data.files || 0}`,
	},
	L: {
		ok: (data: Record<string, unknown>) => `✓ Learning captured: ${data.type || "pattern"}`,
	},
	V: {
		ok: (data: Record<string, unknown>) =>
			`⚠ Violation recorded: ${data.type} (occurrence #${data.count})${data.promote ? " - PROMOTED to pattern" : ""}`,
	},
	R: {
		list: (data: Record<string, unknown>) => `Found ${data.count} snapshot${data.count !== 1 ? "s" : ""}`,
		restore: () => "✓ Restore complete",
	},
	"!": {
		error: (data: Record<string, unknown>) =>
			`✗ Error [${data.code}]: ${String(data.reason || "").replace(/→/g, " ")}`,
	},
};

/**
 * Convert risk code to human-readable label
 */
function riskLabel(risk: string): string {
	switch (risk?.toUpperCase()) {
		case "L":
			return "low";
		case "M":
			return "medium";
		case "H":
			return "high";
		default:
			return "unknown";
	}
}

/**
 * Format a response in wire format with 🦎 brand prefix
 *
 * P2 ENHANCEMENT: Now supports human-readable output by default.
 *
 * Default (labeled): Self-documenting fields
 *   🦎|S|id:task_1|vreko:snap_a|risk:M|prot:85
 *
 * Compact (opt-in via compact: true): For programmatic use
 *   🦎|S|task_1|snap_a|M|85
 *
 * @param type - Wire type code (S, C, X, E, R, L, V, !)
 * @param fields - Named fields as key-value pairs
 * @param options - Format options (compact mode)
 */
export function formatWireLabeled(
	type: string,
	fields: Record<string, string | number | undefined>,
	options?: WireFormatOptions,
): string {
	const parts = [WIRE_PREFIX, type];
	const entries = Object.entries(fields).filter(([, v]) => v !== undefined);

	if (options?.compact) {
		// Compact: positional values only
		parts.push(...entries.map(([, v]) => String(v)));
	} else {
		// Labeled: key:value pairs (default for LLM comprehension)
		parts.push(...entries.map(([k, v]) => `${k}:${v}`));
	}

	return parts.join("|");
}

/**
 * P2: Format response with human-readable output by default.
 *
 * When compact=false (default): Returns human-readable message
 *   "✓ Snapshot created (medium risk, 2 uncommitted files)"
 *
 * When compact=true: Returns wire format for programmatic use
 *   "🦎|S|id:task_1|vreko:snap_a|risk:M|prot:85|dirty:2"
 *
 * @param type - Wire type code (S, C, E, etc.)
 * @param fields - Named fields as key-value pairs
 * @param options - Format options
 * @returns Human-readable or wire format string
 */
export function formatResponse(
	type: string,
	fields: Record<string, string | number | undefined>,
	options?: WireFormatOptions,
): string {
	// If compact mode, return wire format
	if (options?.compact) {
		return formatWireLabeled(type, fields, options);
	}

	// Try to generate human-readable output
	const humanReadable = generateHumanReadable(type, fields);
	if (humanReadable) {
		return humanReadable;
	}

	// Fallback to wire format if no template available
	return formatWireLabeled(type, fields, options);
}

/**
 * Generate human-readable output from type and fields
 */
function generateHumanReadable(type: string, fields: Record<string, string | number | undefined>): string | null {
	const templates = HUMAN_READABLE_TEMPLATES[type as keyof typeof HUMAN_READABLE_TEMPLATES];
	if (!templates) {
		return null;
	}

	// Convert fields to data object with proper typing
	const data: Record<string, unknown> = { ...fields };

	switch (type) {
		case "S": {
			const statusKey = (fields.status as string) || "created";
			const template = (templates as typeof HUMAN_READABLE_TEMPLATES.S)[
				statusKey as keyof typeof HUMAN_READABLE_TEMPLATES.S
			];
			return template ? template(data) : null;
		}
		case "C": {
			const statusKey = fields.status === "✓" || fields.status === "OK" ? "passed" : "failed";
			const template = (templates as typeof HUMAN_READABLE_TEMPLATES.C)[
				statusKey as keyof typeof HUMAN_READABLE_TEMPLATES.C
			];
			return template ? template(data) : null;
		}
		case "E": {
			const statusKey = fields.status === "OK" ? "ok" : "fail";
			const template = (templates as typeof HUMAN_READABLE_TEMPLATES.E)[
				statusKey as keyof typeof HUMAN_READABLE_TEMPLATES.E
			];
			return template ? template(data) : null;
		}
		case "L": {
			const template = (templates as typeof HUMAN_READABLE_TEMPLATES.L).ok;
			return template(data);
		}
		case "V": {
			const template = (templates as typeof HUMAN_READABLE_TEMPLATES.V).ok;
			return template(data);
		}
		case "R": {
			const statusKey = fields.count !== undefined ? "list" : "restore";
			const template = (templates as typeof HUMAN_READABLE_TEMPLATES.R)[
				statusKey as keyof typeof HUMAN_READABLE_TEMPLATES.R
			];
			return template ? template(data) : null;
		}
		case "!": {
			const template = (templates as (typeof HUMAN_READABLE_TEMPLATES)["!"]).error;
			return template(data);
		}
		default:
			return null;
	}
}

/**
 * Legacy: Format a response in compact wire format with 🦎 brand prefix
 * Format: 🦎|TYPE|field1|field2|...
 *
 * @deprecated Use formatWireLabeled with compact: true instead
 */
export function formatWire(type: string, ...fields: (string | number)[]): string {
	return [WIRE_PREFIX, type, ...fields.map(String)].join("|");
}

/**
 * Format a human-readable branded message
 */
export function formatMessage(message: string): string {
	// If message already has brand prefix, return as-is
	if (message.startsWith(BRAND_PREFIX) || message.startsWith(WIRE_PREFIX)) {
		return message;
	}
	return `${BRAND_PREFIX} ${message}`;
}

/**
 * Compress a string for wire format (replace spaces, truncate)
 */
export function compress(s: string, maxLength: number): string {
	const clean = s.replace(/\s+/g, "→");
	return clean.length > maxLength ? `${clean.slice(0, maxLength - 1)}…` : clean;
}

/**
 * Get relative time string (e.g., "2m", "1h", "3d")
 */
export function getRelativeTime(timestamp: number): string {
	const diff = Date.now() - timestamp;
	const minutes = Math.floor(diff / 60000);
	const hours = Math.floor(minutes / 60);
	const days = Math.floor(hours / 24);

	if (days > 0) {
		return `${days}d`;
	}
	if (hours > 0) {
		return `${hours}h`;
	}
	if (minutes > 0) {
		return `${minutes}m`;
	}
	return "just now";
}

/**
 * Get human-readable relative time (e.g., "2 minutes ago")
 */
export function getRelativeTimeHuman(timestamp: number): string {
	const diff = Date.now() - timestamp;
	const minutes = Math.floor(diff / 60000);
	const hours = Math.floor(minutes / 60);
	const days = Math.floor(hours / 24);

	if (days > 0) {
		return `${days} day${days !== 1 ? "s" : ""} ago`;
	}
	if (hours > 0) {
		return `${hours} hour${hours !== 1 ? "s" : ""} ago`;
	}
	if (minutes > 0) {
		return `${minutes} minute${minutes !== 1 ? "s" : ""} ago`;
	}
	return "just now";
}

