export interface WireResponse {
	/** The wire format string */
	wire: string;
	/** Optional human-readable message */
	message?: string;
}

/**
 * Build a start task response
 *
 * Wire format (labeled):
 *   🦎|S|id:<taskId>|vreko:<snapshotId>|risk:<L/M/H>|prot:<0-100>|dirty:<count>|status:<text>|learn:<compressed>
 *
 * Wire format (compact):
 *   🦎|S|<taskId>|<snapshotId>|<risk>|<prot>|<dirty>|<status>|<learnings>
 */
export function buildStartResponse(
	data: {
		taskId: string;
		snapshotId?: string;
		risk: "L" | "M" | "H";
		protection: number;
		dirty: number;
		snapshotStatus: "created" | "reused" | "skipped";
		learnings?: string[];
		hotspots?: string[];
		taskDescription?: string;
	},
	options?: WireFormatOptions,
): WireResponse {
	const learningsStr =
		data.learnings
			?.slice(0, 3)
			.map((l) => compress(l, 40))
			.join(",") || "";
	const hotspotsStr = data.hotspots?.slice(0, 2).join(",") || "";

	const wire = formatWireLabeled(
		"S",
		{
			id: data.taskId,
			vreko: data.snapshotId || "none",
			risk: data.risk,
			prot: data.protection,
			dirty: data.dirty,
			status: data.snapshotStatus,
			...(learningsStr && { learn: learningsStr }),
			...(hotspotsStr && { hotspots: hotspotsStr }),
		},
		options,
	);

	const message =
		data.snapshotStatus === "created"
			? messages.snapshot.created(data.taskDescription)
			: data.snapshotStatus === "reused"
				? messages.snapshot.reused()
				: undefined;

	return { wire, message };
}

/**
 * Build a check/validation response
 *
 * Wire format (labeled):
 *   🦎|C|status:<✓/✗>|err:<n>E|warn:<n>W|ts:<✓/✗/⏭️>|lint:<✓/✗/⏭️>|tests:<✓/✗/⏭️>|issues:<compressed>
 *
 * Wire format (compact):
 *   🦎|C|<status>|<errors>E|<warnings>W|<indicators>|<issues>
 */
export function buildCheckResponse(
	data: {
		mode: "S" | "C" | "Q" | "F" | "P";
		status: "OK" | "ERR";
		errors: number;
		warnings: number;
		checked?: { typescript: boolean; lint: boolean; tests: boolean | "skipped" };
		issues?: string[];
	},
	options?: WireFormatOptions,
): WireResponse {
	// Build status indicators
	const tsStatus = data.checked?.typescript ? "✓" : "✗";
	const lintStatus = data.checked?.lint ? "✓" : "✗";
	const testsStatus = data.checked?.tests === true ? "✓" : data.checked?.tests === "skipped" ? "⏭️" : "✗";
	const issuesStr =
		data.issues
			?.slice(0, 3)
			.map((i) => compress(i, 40))
			.join(",") || "";

	const wire = formatWireLabeled(
		data.mode,
		{
			status: data.status === "OK" ? "✓" : "✗",
			err: `${data.errors}E`,
			warn: `${data.warnings}W`,
			ts: tsStatus,
			lint: lintStatus,
			tests: testsStatus,
			...(issuesStr && { issues: issuesStr }),
		},
		options,
	);

	const message =
		data.status === "OK" ? messages.validation.passed() : messages.validation.issues(data.errors, data.warnings);

	return { wire, message };
}

/**
 * Build a restore response
 */
export function buildRestoreResponse(data: { files: string[]; snapshotTime: number; isDry?: boolean }): WireResponse {
	const timeAgo = getRelativeTimeHuman(data.snapshotTime);

	if (data.isDry) {
		const wire = formatWire("R", "DRY", `${(data.files || []).length}f`, ...(data.files || []).slice(0, 5));
		return { wire, message: messages.restore.preview((data.files || []).length) };
	}

	const wire = formatWire("R", "OK", `${(data.files || []).length}f`, ...(data.files || []).slice(0, 5));
	const message =
		(data.files || []).length === 1
			? messages.restore.single((data.files || [])[0], timeAgo)
			: messages.restore.multiple((data.files || []).length, timeAgo);

	return { wire, message };
}

/**
 * Build a list snapshots response
 */
export function buildListResponse(
	snapshots: Array<{ id: string; createdAt: number; fileCount: number }>,
): WireResponse {
	if (snapshots.length === 0) {
		return {
			wire: formatWire("R", "0", "No snapshots available"),
			message: messages.restore.notFound(),
		};
	}

	const parts = snapshots.slice(0, 5).map((vreko) => {
		const age = getRelativeTime(vreko.createdAt);
		return `${vreko.id.slice(0, 8)}:${age}:${vreko.fileCount}f`;
	});

	return {
		wire: formatWire("R", String(snapshots.length), ...parts),
	};
}

/**
 * Build an end task response
 *
 * Wire format (labeled):
 *   🦎|E|status:<OK/FAIL>|learn:<n>L|files:<n>F|lines:<+added-removed>|summary:<compressed>|<survey-json>
 *
 * Wire format (compact):
 *   🦎|E|<status>|<learnings>L|<files>F|<lines>|<summary>
 */
export function buildEndResponse(
	data: {
		success: boolean;
		learningsCount: number;
		filesModified: number;
		linesAdded: number;
		linesRemoved: number;
		learnings?: string[];
		tokensSaved?: number;
		savingsPercent?: number;
		mistakesPrevented?: number;
		survey?: Record<string, unknown>;
	},
	options?: WireFormatOptions,
): WireResponse {
	const learningsStr =
		data.learnings
			?.slice(0, 2)
			.map((l) => compress(l, 30))
			.join(",") || "";

	const wire = formatWireLabeled(
		"E",
		{
			status: data.success ? "OK" : "FAIL",
			learn: `${data.learningsCount}L`,
			files: `${data.filesModified}F`,
			lines: `+${data.linesAdded}-${data.linesRemoved}`,
			...(learningsStr && { summary: learningsStr }),
		},
		options,
	);

	// Append survey as JSON if present (not in wire format fields)
	const wireWithSurvey = data.survey ? `${wire}|${JSON.stringify(data.survey)}` : wire;

	// Build efficiency stats line
	const statsParts: string[] = [];
	if (data.tokensSaved && data.tokensSaved > 500) {
		statsParts.push(`💰 ~${data.tokensSaved.toLocaleString()} tokens saved (${data.savingsPercent}%)`);
	}
	if (data.mistakesPrevented && data.mistakesPrevented > 0) {
		statsParts.push(`🛡️ ${data.mistakesPrevented} ${data.mistakesPrevented === 1 ? "issue" : "issues"} prevented`);
	}
	if (data.learningsCount > 0) {
		statsParts.push(`📚 ${data.learningsCount} captured`);
	}

	const message = statsParts.length > 0 ? statsParts.join(" | ") : undefined;

	return { wire: wireWithSurvey, message };
}

/**
 * Learning type mapping from abbreviated to full words
 */
export const LEARNING_TYPE_MAP: Record<string, string> = {
	pat: "pattern",
	pattern: "pattern",
	pit: "pitfall",
	pitfall: "pitfall",
	eff: "efficiency",
	efficiency: "efficiency",
	disc: "discovery",
	discovery: "discovery",
	wf: "workflow",
	workflow: "workflow",
};

/**
 * Build a learning response
 *
 * Wire format (labeled):
 *   🦎|L|status:OK|id:<learningId>|type:<pattern/pitfall/efficiency/discovery/workflow>
 *
 * Wire format (compact):
 *   🦎|L|OK|<id>|<type>
 */
export function buildLearnResponse(data: { id: string; type: string }, options?: WireFormatOptions): WireResponse {
	const fullType = LEARNING_TYPE_MAP[data.type] || data.type;

	const wire = formatWireLabeled(
		"L",
		{
			status: "OK",
			id: data.id,
			type: fullType,
		},
		options,
	);

	return {
		wire,
		message: messages.learning.captured(fullType),
	};
}

/**
 * Build a violation response
 *
 * Wire format (labeled):
 *   🦎|V|status:OK|type:<violationType>|count:<n>|promote:<NO/PROMOTED>|auto:<NO/YES>
 *
 * Wire format (compact):
 *   🦎|V|OK|<type>|<count>|PROMOTE?|AUTOMATE?
 */
export function buildViolationResponse(
	data: {
		type: string;
		count: number;
		shouldPromote?: boolean;
		shouldAutomate?: boolean;
	},
	options?: WireFormatOptions,
): WireResponse {
	const wire = formatWireLabeled(
		"V",
		{
			status: "OK",
			type: data.type,
			count: data.count,
			promote: data.shouldPromote ? "PROMOTED" : "NO",
			auto: data.shouldAutomate ? "YES" : "NO",
		},
		options,
	);

	const message = data.shouldAutomate
		? messages.violation.automate(data.type)
		: data.shouldPromote
			? messages.violation.promoted(data.type)
			: messages.violation.recorded(data.type, data.count);

	return {
		wire,
		message,
	};
}

/**
 * Build an error response
 *
 * Wire format (labeled):
 *   🦎|!|code:<ERROR_CODE>|reason:<compressed>
 *
 * Wire format (compact):
 *   🦎|!|<code>|<reason>
 */
export function buildErrorResponse(reason: string, code?: string, options?: WireFormatOptions): WireResponse {
	const wire = formatWireLabeled(
		"!",
		{
			code: code || "ERR",
			reason: compress(reason, 60),
		},
		options,
	);

	return {
		wire,
		message: messages.error.generic(reason),
	};
}

/**
 * Format a standardized wire error with ErrorCode
 *
 * Wire format: 🦎|!|code:<ERROR_CODE>|reason:<compressed>
 *
 * @param code - ErrorCode from errors/index.ts (e.g., "FILE_NOT_FOUND", "SNAPSHOT_NOT_FOUND")
 * @param reason - Human-readable error reason
 * @param options - Wire format options
 * @returns Formatted wire error string
 *
 * @example
 * formatWireError("FILE_NOT_FOUND", "auth.ts not in snapshot")
 * // Returns: "🦎|!|code:FILE_NOT_FOUND|reason:auth.ts→not→in→snapshot"
 */
export function formatWireError(code: string, reason: string, options?: WireFormatOptions): string {
	return formatWireLabeled(
		"!",
		{
			code,
			reason: compress(reason, 60),
		},
		options,
	);
}

// =============================================================================
// Utility Functions
// =============================================================================

function capitalize(s: string): string {
	return s.charAt(0).toUpperCase() + s.slice(1);
}

/**
 * Format tool result with optional human message
 * When humanize=true, includes friendly message after wire format
 */
export function formatToolResult(response: WireResponse, humanize = false): string {
	if (humanize && response.message) {
		return `${response.wire}\n${response.message}`;
	}
	return response.wire;
}
