/**
 * MCP Intelligence Adapter
 *
 * Provides daemon IPC methods for intelligence operations.
 * Replaces direct @vreko/intelligence imports with daemon calls.
 *
 * Circuit Breaker Fixes (SB-190):
 * - Added circuit breaker state per workspace
 * - Added timeout protection for all daemon calls
 * - Added proper error logging (no more silent swallowing)
 * - Added error aggregation for fallback operations
 * - Export circuit status for monitoring
 *
 * @module daemon/intelligence-adapter
 */

import type { CircuitBreakerState as BaseCBState } from "@vreko/contracts";
import type { VrekoLocalClient } from "@vreko/local-service-client";

import { acquireClient, getAllConnectedClients, getPooledClient } from "./client-pool.js";

// =============================================================================
// CIRCUIT BREAKER STATE
// =============================================================================

/**
 * Runtime circuit breaker state  -  extends canonical BaseCBState from
 * @vreko/contracts with a pre-computed absolute retry timestamp.
 */
type CircuitBreakerState = BaseCBState & {
	/** Absolute timestamp (ms) after which a retry is permitted */
	nextRetryTime: number;
};

const circuitBreakers = new Map<string, CircuitBreakerState>();

const CIRCUIT_BREAKER_CONFIG = {
	failureThreshold: 5, // Open after 5 consecutive failures
	resetTimeout: 30000, // Try again after 30s
	halfOpenMaxAttempts: 2, // Allow 2 test requests in half-open
};

function getCircuitBreaker(workspaceRoot: string): CircuitBreakerState {
	let cb = circuitBreakers.get(workspaceRoot);
	if (!cb) {
		cb = {
			state: "closed",
			failures: 0,
			threshold: CIRCUIT_BREAKER_CONFIG.failureThreshold,
			lastFailure: 0,
			cooldownMs: CIRCUIT_BREAKER_CONFIG.resetTimeout,
			nextRetryTime: 0,
		};
		circuitBreakers.set(workspaceRoot, cb);
	}
	return cb;
}

function recordSuccess(workspaceRoot: string): void {
	const cb = getCircuitBreaker(workspaceRoot);
	cb.state = "closed";
	cb.failures = 0;
}

function recordFailure(workspaceRoot: string): void {
	const cb = getCircuitBreaker(workspaceRoot);
	cb.failures++;
	cb.lastFailure = Date.now();

	if (cb.failures >= CIRCUIT_BREAKER_CONFIG.failureThreshold) {
		cb.state = "open";
		cb.nextRetryTime = Date.now() + CIRCUIT_BREAKER_CONFIG.resetTimeout;
	}
}

function shouldAllowRequest(workspaceRoot: string): { allowed: boolean; reason?: string } {
	const cb = getCircuitBreaker(workspaceRoot);

	if (cb.state === "closed") {
		return { allowed: true };
	}

	if (cb.state === "open") {
		if (Date.now() >= cb.nextRetryTime) {
			cb.state = "half-open";
			return { allowed: true };
		}
		const retryIn = Math.ceil((cb.nextRetryTime - Date.now()) / 1000);
		return {
			allowed: false,
			reason: `Circuit open. Retry in ${retryIn}s`,
		};
	}

	// half-open: allow limited requests
	return { allowed: true };
}

/**
 * Get circuit breaker status for a workspace.
 * Useful for monitoring and debugging.
 */
export function getCircuitStatus(workspaceRoot: string): CircuitBreakerState {
	return getCircuitBreaker(workspaceRoot);
}

/**
 * Reset circuit breaker for a workspace.
 * Call this after daemon restart to clear stale state.
 */
export function resetCircuitBreaker(workspaceRoot: string): void {
	circuitBreakers.delete(workspaceRoot);
}

/**
 * Reset all circuit breakers.
 * Call this after daemon restart.
 */
export function resetAllCircuitBreakers(): void {
	circuitBreakers.clear();
}

// =============================================================================
// CONNECTION MANAGEMENT (shared pool  -  no private map)
// =============================================================================

/**
 * Get or create a connected, initialized client for a workspace.
 * Delegates to the shared client pool so intelligence and local-service
 * adapters share a single connection per workspace.
 *
 * Now with circuit breaker and proper error logging.
 */
async function getClient(workspaceRoot: string): Promise<VrekoLocalClient | null> {
	const circuitCheck = shouldAllowRequest(workspaceRoot);
	if (!circuitCheck.allowed) {
		return null;
	}

	try {
		const client = await acquireClient(workspaceRoot);

		// Verify connection is actually healthy
		if (!client.isConnected()) {
			recordFailure(workspaceRoot);
			return null;
		}

		return client;
	} catch (_error) {
		recordFailure(workspaceRoot);
		return null;
	}
}

/**
 * Protected call wrapper with timeout and circuit breaker.
 */
async function protectedCall<T>(
	workspaceRoot: string,
	_operation: string,
	call: () => Promise<T>,
	timeoutMs = 10000,
): Promise<{ success: true; result: T } | { success: false; error: string }> {
	const circuitCheck = shouldAllowRequest(workspaceRoot);
	if (!circuitCheck.allowed) {
		return { success: false, error: circuitCheck.reason ?? "Circuit breaker rejected request" };
	}

	try {
		const timeoutPromise = new Promise<never>((_, reject) => {
			setTimeout(() => reject(new Error(`Timeout after ${timeoutMs}ms`)), timeoutMs);
		});

		const result = await Promise.race([call(), timeoutPromise]);
		recordSuccess(workspaceRoot);
		return { success: true, result };
	} catch (error) {
		const errorMsg = error instanceof Error ? error.message : String(error);
		recordFailure(workspaceRoot);
		return { success: false, error: errorMsg };
	}
}

// =============================================================================
// VITALS OPERATIONS
// =============================================================================

export interface VitalsViaDaemonResult {
	success: boolean;
	vitals?: {
		pressure: number;
		threshold: number;
		agentGuidance?: unknown;
		snapshotCount: number;
		sessionDuration: number;
	};
	error?: string;
}

/**
 * Get workspace vitals via daemon IPC
 */
export async function getVitalsViaDaemon(workspaceRoot: string): Promise<VitalsViaDaemonResult> {
	const client = await getClient(workspaceRoot);
	if (!client) {
		const cb = getCircuitBreaker(workspaceRoot);
		return {
			success: false,
			error:
				cb.state === "open"
					? `Daemon unavailable (circuit open, retry in ${Math.ceil((cb.nextRetryTime - Date.now()) / 1000)}s)`
					: "Daemon unavailable",
		};
	}

	const result = await protectedCall(workspaceRoot, "intelligence/getVitals", () =>
		client.call<{
			pressure: number;
			threshold: number;
			agentGuidance?: unknown;
			snapshotCount: number;
			sessionDuration: number;
		}>("intelligence/getVitals", { workspace: workspaceRoot }),
	);

	if (!result.success) {
		return { success: false, error: result.error };
	}

	return { success: true, vitals: result.result };
}

