/**
 * Get context via daemon IPC
 */
export async function getContextViaDaemon(
	workspaceRoot: string,
	options?: { task?: string; keywords?: string[] },
): Promise<ContextViaDaemonResult> {
	const client = await getClient(workspaceRoot);
	if (!client) {
		const cb = getCircuitBreaker(workspaceRoot);
		return {
			success: false,
			error:
				cb.state === "open"
					? `Daemon unavailable (circuit open, retry in ${Math.ceil((cb.nextRetryTime - Date.now()) / 1000)}s)`
					: "Daemon unavailable",
		};
	}

	const result = await protectedCall(workspaceRoot, "context/get", () =>
		client.call<{
			patterns: string;
			constraints: Array<{ domain: string; name: string; value: string | number; description: string }>;
			learnings: Array<{ type: string; trigger: string; action: string }>;
		}>("context/get", {
			workspace: workspaceRoot,
			task: options?.task,
			keywords: options?.keywords ?? [],
		}),
	);

	if (!result.success) {
		return { success: false, error: result.error };
	}

	return {
		success: true,
		patterns: result.result.patterns,
		constraints: result.result.constraints,
		learnings: result.result.learnings,
		context: result.result,
	};
}

// =============================================================================
// EMBEDDING OPERATIONS
// =============================================================================

export interface EmbeddingViaDaemonResult {
	success: boolean;
	embedding?: number[];
	error?: string;
}

/**
 * Generate embedding via daemon IPC
 *
 * Now with error aggregation for better diagnostics.
 */
export async function generateEmbeddingViaDaemon(
	text: string,
	preferredWorkspace?: string,
): Promise<EmbeddingViaDaemonResult> {
	const errors: string[] = [];

	// Tier 1: try the preferred workspace client first
	if (preferredWorkspace) {
		const circuitCheck = shouldAllowRequest(preferredWorkspace);
		if (circuitCheck.allowed) {
			const preferred = getPooledClient(preferredWorkspace);
			if (preferred?.isConnected()) {
				try {
					const result = await preferred.call<{ embedding: number[] }>("intelligence/generateEmbedding", {
						text,
					});
					recordSuccess(preferredWorkspace);
					return { success: true, embedding: result.embedding };
				} catch (error) {
					recordFailure(preferredWorkspace);
					errors.push(`${preferredWorkspace}: ${error instanceof Error ? error.message : String(error)}`);
				}
			}
		} else {
			errors.push(`${preferredWorkspace}: ${circuitCheck.reason}`);
		}
	}

	// Tier 2: try any connected client  -  embedding generation is workspace-agnostic
	// (the model doesn't change per workspace), so any live connection works.
	for (const client of getAllConnectedClients()) {
		try {
			const result = await client.call<{ embedding: number[] }>("intelligence/generateEmbedding", { text });
			return { success: true, embedding: result.embedding };
		} catch (error) {
			errors.push(error instanceof Error ? error.message : String(error));
		}
	}

	// Tier 3: provide diagnostic info
	return {
		success: false,
		error:
			errors.length > 0
				? `All clients failed: ${errors.join("; ")}`
				: "No daemon connection available for embedding generation",
	};
}

