/**
 * Format risk assessment for display via daemon IPC
 */
export function formatRiskAssessmentViaDaemon(assessment: RiskAssessmentViaDaemon): string {
	const lines: string[] = [];

	lines.push(`Risk Assessment: ${assessment.score}/100 (${assessment.level})`);
	lines.push(`Recommendation: ${assessment.recommendation}`);
	lines.push(`Confidence: ${Math.round(assessment.confidence * 100)}%`);

	if (assessment.factors.length > 0) {
		lines.push("");
		lines.push("Risk Factors:");
		for (const factor of assessment.factors) {
			const sign = factor.score >= 0 ? "+" : "";
			lines.push(`  • [${factor.source}] ${factor.name}: ${factor.description} (${sign}${factor.score})`);
			if (factor.suggestion) {
				lines.push(`    Suggestion: ${factor.suggestion}`);
			}
		}
	}

	if (assessment.explanation) {
		lines.push("");
		lines.push(`Explanation: ${assessment.explanation}`);
	}

	return lines.join("\n");
}

// =============================================================================
// ROLLBACK SUGGESTIONS (replaces RiskEngine.suggestRollback)
// =============================================================================

export interface RollbackSuggestionViaDaemon {
	snapshotId: string;
	score: number;
	createdAt: Date;
	reasoning: string;
}

export interface RollbackSuggestionResult {
	success: boolean;
	suggestions?: RollbackSuggestionViaDaemon[];
	error?: string;
}

/**
 * Suggest rollback via daemon IPC (replaces RiskEngine.suggestRollback())
 */
export async function suggestRollbackViaDaemon(
	workspaceRoot: string,
	filePath: string,
	symptom?: string,
): Promise<RollbackSuggestionResult> {
	const client = await getClient(workspaceRoot);
	if (!client) {
		const cb = getCircuitBreaker(workspaceRoot);
		return {
			success: false,
			error:
				cb.state === "open"
					? `Daemon unavailable (circuit open, retry in ${Math.ceil((cb.nextRetryTime - Date.now()) / 1000)}s)`
					: "Daemon unavailable",
		};
	}

	const result = await protectedCall(workspaceRoot, "intelligence/suggestRollback", () =>
		client.call<{
			suggestions: Array<{
				snapshotId: string;
				score: number;
				createdAt: string;
				reasoning: string;
			}>;
		}>("intelligence/suggestRollback", {
			workspace: workspaceRoot,
			filePath,
			symptom,
		}),
	);

	if (!result.success) {
		return { success: false, error: result.error };
	}

	// Convert date strings to Date objects
	const suggestions = result.result.suggestions.map((s) => ({
		...s,
		createdAt: new Date(s.createdAt),
	}));

	return { success: true, suggestions };
}
