/**
 * ServiceError - Typed error class for service layer operations
 *
 * Used with neverthrow Result types to provide type-safe error handling
 * throughout the service layer.
 */

/**
 * Safely extract a string message from an unknown error.
 * Use in catch blocks: catch (e) { logger.error(errorMessage(e)) }
 */
export function errorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

export type ServiceErrorCode =
	| "WORKSPACE_NOT_FOUND"
	| "WORKSPACE_API_ERROR"
	| "ENGINE_NOT_INITIALIZED"
	| "THRESHOLD_FETCH_FAILED"
	| "VALIDATION_ERROR"
	| "NETWORK_ERROR"
	| "TIMEOUT_ERROR"
	| "PARSING_ERROR";

export class ServiceError extends Error {
	constructor(
		public readonly code: ServiceErrorCode,
		message: string,
		public readonly cause?: Error,
	) {
		super(message);
		this.name = "ServiceError";
	}

	/**
	 * Create a WORKSPACE_NOT_FOUND error
	 */
	static workspaceNotFound(workspaceId: string, cause?: Error): ServiceError {
		return new ServiceError("WORKSPACE_NOT_FOUND", `Workspace not found: ${workspaceId}`, cause);
	}

	/**
	 * Create a WORKSPACE_API_ERROR error
	 */
	static workspaceApiError(status: number, cause?: Error): ServiceError {
		return new ServiceError("WORKSPACE_API_ERROR", `API error: ${status}`, cause);
	}

	/**
	 * Create an ENGINE_NOT_INITIALIZED error
	 */
	static engineNotInitialized(cause?: Error): ServiceError {
		return new ServiceError("ENGINE_NOT_INITIALIZED", "Engine not initialized. Call initialize() first.", cause);
	}

	/**
	 * Create a THRESHOLD_FETCH_FAILED error
	 */
	static thresholdFetchFailed(cause?: Error): ServiceError {
		return new ServiceError("THRESHOLD_FETCH_FAILED", "Failed to fetch thresholds", cause);
	}

	/**
	 * Create a VALIDATION_ERROR error
	 */
	static validationError(message: string, cause?: Error): ServiceError {
		return new ServiceError("VALIDATION_ERROR", message, cause);
	}

	/**
	 * Create a NETWORK_ERROR error
	 */
	static networkError(message: string, cause?: Error): ServiceError {
		return new ServiceError("NETWORK_ERROR", message, cause);
	}

	/**
	 * Create a TIMEOUT_ERROR error
	 */
	static timeoutError(operation: string, cause?: Error): ServiceError {
		return new ServiceError("TIMEOUT_ERROR", `Operation timed out: ${operation}`, cause);
	}

	/**
	 * Create a PARSING_ERROR error
	 */
	static parsingError(message: string, cause?: Error): ServiceError {
		return new ServiceError("PARSING_ERROR", `Failed to parse: ${message}`, cause);
	}

	/**
	 * Convert to a plain object for logging/serialization
	 */
	toJSON(): Record<string, unknown> {
		return {
			name: this.name,
			code: this.code,
			message: this.message,
			cause: this.cause?.message,
		};
	}
}
