/**
 * Shared learning type metadata and utilities.
 *
 * Used by vreko-learn (reward signal) and vreko (curated learnings display).
 * Single source of truth for learning type emojis, verbs, and normalization.
 *
 * @module utils/learning-meta
 */

import { existsSync, readFileSync } from "node:fs";
import { createTieredLearningService } from "../services/tiered-learning-service.js";

// =============================================================================
// Learning Type Metadata
// =============================================================================

/** Valid learning types (whitelist for normalization) */
export const VALID_LEARNING_TYPES = new Set(["pattern", "pitfall", "efficiency", "discovery", "workflow"]);

/** Type-specific reward messages and emoji */
export const LEARNING_TYPE_META: Record<string, { emoji: string; verb: string; future: string }> = {
	pattern: { emoji: "🎯", verb: "Pattern captured", future: "will auto-surface in similar contexts" },
	pitfall: { emoji: "🛡️", verb: "Pitfall recorded", future: "will warn you before repeating this mistake" },
	efficiency: { emoji: "⚡", verb: "Efficiency insight saved", future: "will speed up future similar work" },
	discovery: { emoji: "📍", verb: "Discovery mapped", future: "builds your repo's mental model" },
	workflow: { emoji: "🔄", verb: "Workflow improvement noted", future: "will guide future task sequences" },
};

// =============================================================================
// Utilities
// =============================================================================

/** Normalize learning type to a valid value, defaulting to "pattern" */
export function normalizeLearningType(raw: string | undefined): string {
	const t = raw?.toLowerCase();
	if (t && VALID_LEARNING_TYPES.has(t)) {
		return t;
	}
	return "pattern";
}

/** Truncate string with ellipsis */
export function truncate(str: string, maxLen: number): string {
	if (str.length <= maxLen) {
		return str;
	}
	return `${str.slice(0, maxLen - 1)}…`;
}

// =============================================================================
// Trajectory
// =============================================================================

/** Learning trajectory data for progress display */
export interface LearningTrajectory {
	totalTracked: number;
	hotCount: number;
	maxHotSize: number;
}

/**
 * Build learning trajectory from tiered learning service.
 * Returns null if service unavailable (graceful degradation).
 */
export function getLearningTrajectory(workspaceRoot: string): LearningTrajectory | null {
	try {
		const service = createTieredLearningService(workspaceRoot);
		const usageStats = service.getUsageStats();
		const totalTracked = Object.keys(usageStats).length;

		// FIXED: hotCount should be actual hot tier size, not eligible count
		// Load hot tier to get real count
		const hotTierPath = `${workspaceRoot}/.vreko/learnings/hot.jsonl`;
		let hotCount = 0;
		try {
			if (existsSync(hotTierPath)) {
				const content = readFileSync(hotTierPath, "utf-8");
				hotCount = content.trim().split("\n").filter(Boolean).length;
			}
		} catch {
			// Fallback to eligible count if file read fails
			hotCount = Object.values(usageStats).filter((s) => s.accessCount >= 3 || s.appliedCount >= 1).length;
		}

		const maxHotSize = 20; // HOT_TIER_PROMOTION_THRESHOLD.maxHotTierSize
		return { totalTracked, hotCount, maxHotSize };
	} catch {
		return null;
	}
}
