/**
 * Learning Validation Service
 *
 * Security hardening for learning storage:
 * - Size limits (prevent memory exhaustion)
 * - Blocked patterns (prevent malicious content)
 * - Provenance tracking (source validation)
 * - Temporal decay (automatic expiration)
 *
 * @see docs/security/2-3-26-security_review_feedback.md Week 1 P0
 * @module services/learning-validation
 */

import type { Learning } from "@vreko/intelligence/types";

// =============================================================================
// Constants
// =============================================================================

/** Maximum learning content size (combined trigger + action + solution) */
export const MAX_LEARNING_SIZE = 5000; // 5KB per learning

/** Maximum trigger length */
export const MAX_TRIGGER_LENGTH = 500;

/** Maximum action length */
export const MAX_ACTION_LENGTH = 2000;

/** Maximum solution length */
export const MAX_SOLUTION_LENGTH = 2000;

/** Default expiration period (90 days per feedback) */
export const DEFAULT_EXPIRATION_DAYS = 90;

/** Blocked patterns that should never appear in learnings */
export const BLOCKED_PATTERNS = [
	/ignore\s+previous\s+instructions/i,
	/disregard\s+all\s+prior/i,
	/<\|im_start\|>/i,
	/<\|im_end\|>/i,
	/system\s*:\s*you\s+are\s+now/i,
	/\bDAN\b.*do\s+anything\s+now/i,
	// Add more prompt injection patterns as needed
];

/** Valid provenance sources */
export const VALID_SOURCES = [
	"user_explicit", // User manually created via snap_learn
	"auto_inferred", // Automatically extracted from violations
	"imported", // Imported from external source (ADR, docs)
	"mcp", // Legacy source (treated as user_explicit)
	"snap_learn", // Legacy source (treated as user_explicit)
];

// =============================================================================
// Types
// =============================================================================

/**
 * Validation result
 */
export interface ValidationResult {
	isValid: boolean;
	errors: string[];
	warnings: string[];
}

/**
 * Validated learning with security metadata
 */
export interface ValidatedLearning extends Learning {
	/** Provenance source (user_explicit, auto_inferred, imported) */
	source: "user_explicit" | "auto_inferred" | "imported";
	/** When the learning was created */
	created_at: string;
	/** When the learning expires (90 days default) */
	expires_at: string;
	/** Validation status for approval workflow */
	validation_status: "pending" | "approved" | "rejected";
}

// =============================================================================
// Validation Functions
// =============================================================================

/**
 * Validate learning size limits
 */
export function validateSize(learning: Partial<Learning>): ValidationResult {
	const errors: string[] = [];
	const warnings: string[] = [];

	// Check trigger length
	const trigger = Array.isArray(learning.trigger) ? learning.trigger.join(", ") : learning.trigger || "";

	// Check action length
	const action = learning.action || "";

	// Check solution length (if present)
	const solution = learning.solution || "";

	// Check combined size FIRST (most important check)
	const totalSize = trigger.length + action.length + solution.length;
	if (totalSize > MAX_LEARNING_SIZE) {
		errors.push(`Combined learning size exceeds maximum (${MAX_LEARNING_SIZE} chars): ${totalSize} chars`);
	}

	// Individual field checks (for more specific error messages)
	if (trigger.length > MAX_TRIGGER_LENGTH) {
		errors.push(`Trigger exceeds maximum length (${MAX_TRIGGER_LENGTH} chars): ${trigger.length} chars`);
	}

	if (action.length > MAX_ACTION_LENGTH) {
		errors.push(`Action exceeds maximum length (${MAX_ACTION_LENGTH} chars): ${action.length} chars`);
	}

	if (solution.length > MAX_SOLUTION_LENGTH) {
		errors.push(`Solution exceeds maximum length (${MAX_SOLUTION_LENGTH} chars): ${solution.length} chars`);
	}

	// Warnings for large but not invalid content
	if (totalSize > MAX_LEARNING_SIZE * 0.8 && totalSize <= MAX_LEARNING_SIZE) {
		warnings.push(`Learning size approaching limit: ${totalSize}/${MAX_LEARNING_SIZE} chars`);
	}

	return {
		isValid: errors.length === 0,
		errors,
		warnings,
	};
}

/**
 * Validate learning content for blocked patterns
 */
export function validateContent(learning: Partial<Learning>): ValidationResult {
	const errors: string[] = [];
	const warnings: string[] = [];

	// Combine all text fields for pattern checking
	const trigger = Array.isArray(learning.trigger) ? learning.trigger.join(" ") : learning.trigger || "";
	const action = learning.action || "";
	const solution = learning.solution || "";
	const context = learning.context || "";

	const combinedContent = `${trigger} ${action} ${solution} ${context}`;

	// Check for blocked patterns
	for (const pattern of BLOCKED_PATTERNS) {
		if (pattern.test(combinedContent)) {
			errors.push(`Blocked pattern detected: ${pattern.source}`);
		}
	}

	// Check for suspicious content
	if (combinedContent.includes("\\u") || combinedContent.includes("\\x")) {
		warnings.push("Contains escaped unicode/hex characters - verify legitimacy");
	}

	if (combinedContent.match(/\s{10,}/)) {
		warnings.push("Contains excessive whitespace - possible obfuscation");
	}

	return {
		isValid: errors.length === 0,
		errors,
		warnings,
	};
}

/**
 * Validate learning provenance
 */
export function validateProvenance(source: string): ValidationResult {
	const errors: string[] = [];
	const warnings: string[] = [];

	if (!VALID_SOURCES.includes(source)) {
		errors.push(`Invalid source: ${source}. Must be one of: ${VALID_SOURCES.join(", ")}`);
	}

	return {
		isValid: errors.length === 0,
		errors,
		warnings,
	};
}

/**
 * Normalize legacy source to new provenance model
 */
export function normalizeSource(source: string): "user_explicit" | "auto_inferred" | "imported" {
	// Map legacy sources
	if (source === "mcp" || source === "snap_learn" || source === "cli") {
		return "user_explicit";
	}

	if (source === "violation" || source === "auto") {
		return "auto_inferred";
	}

	if (source.startsWith("ADR-") || source === "import" || source === "external") {
		return "imported";
	}

	// Default to user_explicit if unknown
	return "user_explicit";
}

/**
 * Calculate expiration date (90 days from now)
 */
export function calculateExpirationDate(createdAt = new Date()): Date {
	const expiresAt = new Date(createdAt);
	expiresAt.setDate(expiresAt.getDate() + DEFAULT_EXPIRATION_DAYS);
	return expiresAt;
}

/**
 * Check if learning has expired
 */
export function isExpired(expiresAt: string | Date): boolean {
	const now = new Date();
	const expiry = typeof expiresAt === "string" ? new Date(expiresAt) : expiresAt;
	return now > expiry;
}

// =============================================================================
// Combined Validation
// =============================================================================

/**
 * Validate and enhance learning with security metadata
 *
 * @param learning - Raw learning data
 * @returns Validated learning or validation errors
 */
export function validateAndEnhanceLearning(
	learning: Partial<Learning>,
): { learning: ValidatedLearning; validation: ValidationResult } | { validation: ValidationResult } {
	const allErrors: string[] = [];
	const allWarnings: string[] = [];

	// 1. Size validation
	const sizeResult = validateSize(learning);
	allErrors.push(...sizeResult.errors);
	allWarnings.push(...sizeResult.warnings);

	// 2. Content validation (blocked patterns)
	const contentResult = validateContent(learning);
	allErrors.push(...contentResult.errors);
	allWarnings.push(...contentResult.warnings);

	// 3. Provenance validation
	const source = learning.source || "user_explicit";
	const provenanceResult = validateProvenance(source);
	allErrors.push(...provenanceResult.errors);
	allWarnings.push(...provenanceResult.warnings);

	// If validation failed, return errors
	if (allErrors.length > 0) {
		return {
			validation: {
				isValid: false,
				errors: allErrors,
				warnings: allWarnings,
			},
		};
	}

	// 4. Enhance with security metadata
	const now = new Date();
	const expiresAt = calculateExpirationDate(now);
	const normalizedSource = normalizeSource(source);

	const validatedLearning: ValidatedLearning = {
		// Existing fields
		id: learning.id || `learn_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`,
		type: learning.type || "pattern",
		trigger: learning.trigger || "",
		action: learning.action || "",
		solution: learning.solution || learning.action || "",
		context: learning.context,
		problem: learning.problem,
		related: learning.related,
		timestamp: learning.timestamp || now.toISOString(),

		// Security metadata
		source: normalizedSource,
		created_at: now.toISOString(),
		expires_at: expiresAt.toISOString(),
		validation_status: normalizedSource === "user_explicit" ? "approved" : "pending",

		// Tiering metadata (preserve if exists)
		tier: learning.tier,
		domain: learning.domain,
		priority: learning.priority,
		keywords: learning.keywords,

		// Usage tracking (preserve if exists)
		accessCount: learning.accessCount,
		lastAccessed: learning.lastAccessed,
		relevanceScore: learning.relevanceScore,
		appliedDate: learning.appliedDate,
	};

	return {
		learning: validatedLearning,
		validation: {
			isValid: true,
			errors: [],
			warnings: allWarnings,
		},
	};
}

/**
 * Bulk validate learnings (for migration/cleanup)
 */
export function validateLearningsBulk(learnings: Partial<Learning>[]): {
	valid: ValidatedLearning[];
	invalid: Array<{ learning: Partial<Learning>; errors: string[] }>;
	warnings: string[];
} {
	const valid: ValidatedLearning[] = [];
	const invalid: Array<{ learning: Partial<Learning>; errors: string[] }> = [];
	const allWarnings: string[] = [];

	for (const learning of learnings) {
		const result = validateAndEnhanceLearning(learning);

		if ("learning" in result && result.validation.isValid) {
			valid.push(result.learning);
			allWarnings.push(...result.validation.warnings);
		} else {
			invalid.push({
				learning,
				errors: result.validation.errors,
			});
		}
	}

	return { valid, invalid, warnings: allWarnings };
}

/**
 * Filter expired learnings for garbage collection
 */
export function filterExpiredLearnings(learnings: ValidatedLearning[]): {
	active: ValidatedLearning[];
	expired: ValidatedLearning[];
} {
	const active: ValidatedLearning[] = [];
	const expired: ValidatedLearning[] = [];

	for (const learning of learnings) {
		if (learning.expires_at && isExpired(learning.expires_at)) {
			expired.push(learning);
		} else {
			active.push(learning);
		}
	}

	return { active, expired };
}
