/**
 * Workspace Handler
 *
 * Pre-flight workspace check handler.
 *
 * @module facades/handlers/workspace-handler
 *
 * DEPRECATED (Day 4): Direct @vreko/intelligence imports replaced with daemon IPC.
 * Workspace vitals now route through the daemon.
 */

import { getVitalsViaDaemon, listSnapshotsViaDaemon } from "../../daemon/local-service-adapter.js";
import type { ToolHandler } from "../../types/tool-types.js";
import { jsonResult } from "./utils.js";

/**
 * prepare_workspace - Pre-flight workspace check
 * Day 4: Uses daemon IPC for vitals
 */
export const handlePrepareWorkspace: ToolHandler = async (_args, context) => {
	// Get snapshots via daemon IPC
	const snapshots = await listSnapshotsViaDaemon(context.workspaceRoot, 20);

	// Get vitals via daemon IPC (Day 4: daemon-first architecture)
	const vitalsResult = await getVitalsViaDaemon(context.workspaceRoot);
	const vitals =
		vitalsResult.success && vitalsResult.vitals ? vitalsResult.vitals : { pressure: 0, snapshotCount: 0 };

	const lastSnapshot = snapshots[0];
	const timeSinceLastSnapshot = lastSnapshot
		? Math.floor((Date.now() - new Date(lastSnapshot.createdAt).getTime()) / 60000)
		: null;

	// Protection score based on pressure (inverted - low pressure = high protection)
	const pressure = vitals.pressure ?? 0;
	const protectionScore = Math.max(0, 100 - pressure);

	// Determine recommendation based on pressure
	const shouldSnapshot = pressure >= 50 || snapshots.length === 0;
	const reason =
		pressure >= 50
			? "High pressure detected"
			: snapshots.length === 0
				? "No snapshots in this session"
				: "Workspace is healthy";
	const urgency = pressure >= 70 ? "high" : pressure >= 50 ? "medium" : "low";

	return jsonResult({
		vitals: {
			pressure,
			snapshotCount: vitals.snapshotCount ?? snapshots.length,
			trajectory: pressure >= 70 ? "critical" : pressure >= 50 ? "degrading" : "stable",
		},
		protectionScore,
		lastSnapshot: lastSnapshot
			? {
					id: lastSnapshot.id,
					createdAt: new Date(lastSnapshot.createdAt).toISOString(),
					fileCount: lastSnapshot.fileCount,
					minutesAgo: timeSinceLastSnapshot,
				}
			: null,
		totalSnapshots: snapshots.length,
		recommendation: {
			should: shouldSnapshot,
			reason,
			urgency,
		},
		safeOperations: [],
		blockedOperations: [],
		suggestion: shouldSnapshot ? reason : "Continue working",
		next_actions: shouldSnapshot ? [{ tool: "snapshot_create", priority: 1, reason }] : [],
	});
};
