/**
 * Vreko Tool (V2) - Intelligence Briefing
 *
 * Call this FIRST before making any code changes. Returns critical context
 * about the codebase  -  known fragile files, patterns that cause problems,
 * learnings from previous sessions, and files that frequently break together.
 *
 * This is a black-box formatting layer on top of the daemon intelligence engine.
 * The tool does NOT compute, store, or decide  -  it formats daemon responses
 * into LLM-consumable natural language payloads.
 *
 * @module tools/v2/vreko
 */

import { validateSnapStartParams } from "../../security/input-sanitization.js";
import type { ToolHandler, ToolResult, VrekoTool } from "../../types/tool-types.js";
import {
	buildSessionCurrentParams,
	buildSessionStartParams,
	checkDaemonHealth,
	classifyDaemonError,
	formatDaemonError,
	formatUnexpectedError,
	getDaemonClient,
	isActiveSession,
	isDaemonConnectionError,
	isDaemonNullResponse,
	resolveWorkspace,
} from "./utils/index.js";
import { drainPendingQueue } from "./utils/pending-queue.js";
import { logNonFatalError } from "./utils/telemetry.js";
import { formatBlindSpotsForBriefing } from "./utils/tool-blind-spots.js";

// =============================================================================
// Feature gate: recurrence surfacing
// =============================================================================

/**
 * RECUR-01: Controls whether recurrence candidates reach the MCP briefing.
 *
 * false = record-only (default). Findings are written to the store and returned
 * by the IPC handler, but no recurrence signal appears in the brief.
 *
 * Do not flip to true until Pioneer calibration data exists. Kept here (not in
 * env) so the gate and the injection block are always co-located.
 */
const RECURRENCE_SURFACING_ENABLED = false;

// =============================================================================
// Types (inline to avoid import issues during development)
// =============================================================================

interface SessionCurrentResult {
	/** Legacy field  -  may not be present in all daemon versions */
	active?: boolean;
	/** Actual field from daemon: "active" | "ended" | "idle" | "started" */
	state?: string;
	id?: string;
	taskId?: string;
	task?: string;
	startedAt?: string;
	filesModified?: number;
	snapshotCount?: number;
}

interface SessionBeginResult {
	id?: string;
	taskId?: string;
	workspacePath?: string;
	startedAt?: string;
	state?: string;
	metadata?: {
		task?: string;
		keywords?: string[];
		aiToolsDetected?: string[];
		highestRiskLevel?: string;
	};
	touchedFiles?: string[];
	context?: {
		fragileFilesInScope: Array<{ path: string; fragility: number; reason?: string }>;
		// Contract shape from results.ts CoChangeEntry: source/target pairs
		coChangePatternsInScope: Array<{ source: string; target: string; confidence: number }>;
		concurrentSessionWarning: { sessionId: string; workspacePath: string; touchedFiles: string[] } | null;
		// recurrenceCandidatesInScope intentionally absent: surface gate CLOSED pending RECUR-02/03/04 hardenings.
		// Phase 1 Intelligence Wiring: Query-aware enrichment
		queryAwareKnowledge?: Array<{ content: string; source: string; score: number }>;
		queryAwareLearnings?: Array<{ insight: string; severity: string; files: string[] }>;
	} | null;
	learnings?: Array<{ id?: string; type?: string; trigger: string; action: string; relevanceScore?: number }>;
}

interface ContextGetResult {
	compiled?: string;
	/** Raw learnings for natural language display */
	learnings?: Array<{
		type: string;
		trigger: string;
		action: string;
		relevanceScore: number;
	}>;
	/** Raw patterns for display */
	patterns?: Array<{ name: string; description: string }>;
	metadata?: {
		learningCount?: number;
		fragileFileCount?: number;
		coChangePatternCount?: number;
		tokenCount?: number;
		fromCache?: boolean;
	};
}

interface RiskAssessResult {
	score: number;
	action: "PROCEED" | "PROCEED_WITH_SNAPSHOT" | "WARN" | "BLOCK";
	level: "L" | "M" | "H";
	factors: Array<{ source: string; score: number; description: string }>;
	gitRisk?: {
		multiplier: number;
		uncommittedChanges?: boolean;
		detachedHead?: boolean;
		onMainBranch?: boolean;
	};
	fatigue?: {
		level: "rested" | "normal" | "elevated" | "fatigued";
		riskBoost: number;
	};
	rollbackWarning?: {
		confidence: number;
		message: string;
		riskBoost: number;
	};
	poisoning?: {
		detected: boolean;
		files?: string[];
		riskBoost?: number;
	};
	fileRisks?: Record<string, { fragility: number; rollbackCount?: number; reason?: string }>;
	coChanges?: Array<{ source: string; target: string; confidence: number }>;
}

// =============================================================================
// Types
// =============================================================================

export interface VrekoParams {
	/** What you are about to do. Be specific. */
	task: string;
	/** Files you intend to modify, if known. Omit if unsure. */
	files?: string[];
}

interface SessionData {
	id?: string;
	taskId?: string;
	task?: string;
	active: boolean;
}

// =============================================================================
// Handler
// =============================================================================

/**
 * Handle vreko tool call
 *
 * Flow:
 * 1. Pre-flight health check (for better error messages)
 * 2. Check for active session (idempotent - resume if exists)
 * 3. Start new session if none active
 * 4. Get risk assessment for intended files
 * 5. Get compiled context from daemon
 * 6. Format as natural language intelligence briefing
 *
 * IMPORTANT: We never create local fallback sessions - they break cross-tool
 * session continuity. If the daemon can't create a session, we return a clear
 * degraded mode response instead.
 */
export const handleVreko: ToolHandler = async (args, context): Promise<ToolResult> => {
	// Security: Validate and sanitize all user inputs
	const validation = validateSnapStartParams(args);
	if (!validation.success) {
		return {
			content: [
				{
					type: "text",
					text: `❌ Input validation failed:\n${validation.errors?.join("\n") ?? "Unknown validation error"}`,
				},
			],
			isError: true,
		};
	}

	// Extract validated params, with task falling back to raw args for compatibility
	const validatedData = validation.data;
	const params: VrekoParams = {
		task: validatedData?.task ?? ((args as Record<string, unknown>).task as string) ?? "",
		files: validatedData?.files,
	};
	if (!params.task?.trim()) {
		return {
			content: [{ type: "text", text: "Error: task parameter is required and cannot be empty." }],
			isError: true,
		};
	}

	const workspace = resolveWorkspace(context);
	const daemon = getDaemonClient(workspace);

	// SESSION-03: Drain pending.jsonl (and pending.archive.jsonl) before compiling the briefing.
	// Learnings queued while daemon was offline are replayed now that the daemon is reachable.
	// Drain is best-effort  -  failures per entry are skipped, overall drain errors are non-fatal.
	try {
		await drainPendingQueue(workspace, async (entry) => {
			await daemon.request("learning/add", {
				workspace,
				type: entry.type,
				trigger: entry.trigger,
				action: entry.action,
				...(entry.source ? { source: entry.source } : {}),
			});
		});
	} catch {
		// Non-fatal: if drain fails at the outer level, continue with normal briefing.
	}

	// Step 1: Check for active session
	let session: SessionData | null = null;
	let isResumed = false;
	// Bug 1 Fix: Store the full begin result for the formatter
	let beginData: SessionBeginResult | null = null;
	// LLM UX Issue 3: Session vitals for resume context
	let sessionVitals: { filesModified: number; snapshotsCreated: number; learningsCaptured: number } | null = null;
	// RECUR-01: Fetched regardless of gate; brief injection is gated separately.
	let recurrenceCandidates: Array<{
		file: string;
		confidence: number;
		surfaceable: boolean;
		wording: string;
		coChangePartners: string[];
		kind: string;
	}> = [];

	try {
		const currentSession = await daemon.request<SessionCurrentResult>(
			"session/current",
			buildSessionCurrentParams(workspace),
		);

		// Use shared utility for consistent session state check
		if (currentSession && isActiveSession(currentSession)) {
			session = {
				id: currentSession.id,
				taskId: currentSession.taskId,
				task: currentSession.task,
				active: true,
			};
			isResumed = true;

			// FIX 2: Update task name if different from resumed session
			if (params.task && params.task !== session.task) {
				const previousTask = session.task;
				session.task = params.task; // Optimistic update
				try {
					await daemon.request("session/update-task", {
						workspacePath: workspace,
						task: params.task,
					});
				} catch (_updateError) {
					session.task = previousTask; // Revert on failure
				}
			}

			// RESUME INTELLIGENCE FIX: Fetch intelligence for resumed sessions
			// When resuming, we don't call session/start, so beginData is null.
			// Fetch intelligence directly to provide rich context for resumed sessions.
			try {
				// Fetch fragile files
				const fragileResult = await daemon.request<{
					files: Array<{ path: string; fragility: number; reason?: string }>;
				}>("intelligence/fragile-files", { workspace });

				// Fetch co-change patterns
				const coChangeResult = await daemon.request<{
					pairs: Array<{ source: string; target: string; confidence: number }>;
				}>("intelligence/co-changes", { workspace });

				// Fetch warnings
				const _warningsResult = await daemon.request<{
					warnings: Array<{ severity: string; message: string }>;
				}>("intelligence/warnings", { workspace });

				// RECUR-01: Fetch all calibrated findings (IPC handler no longer filters to surfaceable).
				// Recording is independent of the gate; only brief injection is gated below.
				try {
					const recurrenceResult = await daemon.request<{
						candidates: typeof recurrenceCandidates;
					}>("intelligence/recurrence-candidates", { workspace });
					recurrenceCandidates = recurrenceResult?.candidates ?? [];
				} catch {
					// Non-fatal: surface gate controls injection regardless
				}

				// Build beginData-like structure for the formatter using contract pair shape
				beginData = {
					id: currentSession.id,
					context: {
						fragileFilesInScope: fragileResult?.files ?? [],
						coChangePatternsInScope: coChangeResult?.pairs ?? [],
						concurrentSessionWarning: null,
					},
					learnings: [], // Will be populated by context/get below
				};

				// LLM UX Issue 3: Fetch session vitals for resume context
				try {
					const vitalsResult = await daemon.request<{
						pulse: string;
						pressure: number;
						trajectory: string;
						snapshotRecommended: boolean;
						filesModified: number;
						snapshotsCreated: number;
						learningsCaptured: number;
					}>("session/vitals", { workspacePath: workspace });
					if (vitalsResult) {
						sessionVitals = {
							filesModified: vitalsResult.filesModified ?? 0,
							snapshotsCreated: vitalsResult.snapshotsCreated ?? 0,
							learningsCaptured: vitalsResult.learningsCaptured ?? 0,
						};
					}
				} catch (vitalsError) {
					// Intentionally ignored: vitals enrichment is optional during session resume
					logNonFatalError({
						tool: "vreko",
						operation: "session/vitals",
						workspace,
						error: vitalsError,
						metadata: { sessionId: currentSession.id },
					});
				}
			} catch (resumeError) {
				// Intentionally ignored: session resume failure falls through to session/start
				logNonFatalError({
					tool: "vreko",
					operation: "session-resume-intelligence",
					workspace,
					error: resumeError,
					metadata: { sessionId: currentSession.id },
				});
			}
		}
	} catch (error) {
		// GAP 2 FIX: Don't silently swallow session/current errors
		// If this is a daemon connection error, surface it instead of falling through
		// to session/start which would auto-end any existing session.
		if (isDaemonConnectionError(error)) {
			return formatDaemonError(classifyDaemonError(error));
		}
	}

	// Step 2: Start new session if none active
	if (!session) {
		try {
			const beginResult = await daemon.request<SessionBeginResult>(
				"session/start",
				buildSessionStartParams(workspace, {
					task: params.task,
					files: params.files ?? [],
				}),
			);

			// Bug 1 Fix: Store the full begin result
			beginData = beginResult;

			if (beginResult && (beginResult.id || beginResult.taskId)) {
				session = {
					id: beginResult.id || beginResult.taskId,
					taskId: beginResult.taskId || beginResult.id,
					task: beginResult.metadata?.task || params.task,
					active: true,
				};
			} else if (isDaemonNullResponse(beginResult)) {
				// CRITICAL FIX: Don't create local fallback sessions!
				// Local sessions break cross-tool continuity (vreko_learn, vreko_end won't see them).
				// BUT we can still get context/learnings from the daemon.

				// Still try to get context - this often works even when session creation fails
				let degradedContext: ContextGetResult | null = null;
				try {
					degradedContext = await daemon.request<ContextGetResult>("context/get", {
						workspace,
						task: params.task,
						files: params.files,
					});
				} catch (contextError) {
					// Context retrieval also failed in degraded mode
					logNonFatalError({
						tool: "vreko",
						operation: "context/get-degraded",
						workspace,
						error: contextError,
						metadata: { task: params.task },
					});
				}

				// Build degraded response WITH learnings if available
				const sections: string[] = [];
				sections.push(`⚠️ **Degraded Mode**: Vreko session could not be created for task "${params.task}".`);
				sections.push(
					"\n**Likely cause:** The Vreko daemon rejected the session request (memory pressure / admission throttle) or is not running." +
						"\n**Fix:** Tell the developer to run `vreko daemon start --detach` in their terminal if the daemon is not running, or wait 30s and retry if it is.",
				);
				sections.push(
					"\n**Why sessions require the daemon**: Vreko session state is daemon-resident  -  not held in the MCP " +
						"server process. This means session context (learned patterns, risk tracking, snapshot history) does " +
						"not persist between MCP tool calls unless the daemon is running. This is by design: the daemon is " +
						"the single source of truth shared across VS Code, CLI, and MCP tools. " +
						"Without it, `vreko_learn` and `vreko_end` cannot find the session started here.",
				);

				// Include learnings even in degraded mode - these are valuable!
				const degradedLearnings = degradedContext?.learnings ?? [];
				if (degradedLearnings.length > 0) {
					sections.push("\n## Relevant Learnings (read-only)\n");
					for (const learning of degradedLearnings.slice(0, 5)) {
						const typeTag = learning.type ? `[${learning.type}]` : "";
						sections.push(`- ${typeTag} ${learning.trigger} → ${learning.action}`);
					}
				}

				sections.push("\n**Available**: Learnings (read-only via context/get), Manual snapshots via CLI");
				sections.push(
					"**Unavailable**: Session tracking, cross-tool state, vreko_learn, vreko_end, automatic snapshots",
				);

				return {
					content: [{ type: "text", text: sections.join("\n") }],
				};
			}
		} catch (error) {
			if (isDaemonConnectionError(error)) {
				return formatDaemonError(classifyDaemonError(error));
			}
			return formatUnexpectedError("session begin", error);
		}
	}

	if (!session) {
		// Run health check only when needed  -  session creation failed and we need a better error message
		const health = await checkDaemonHealth(daemon, workspace);
		if (!health.healthy) {
			return formatDaemonError(classifyDaemonError(null));
		}
		// Shouldn't reach here, but safety net
		return formatDaemonError();
	}

	// Step 3: Get risk assessment for intended files
	let riskAssessment: RiskAssessResult | null = null;
	if (params.files && params.files.length > 0) {
		try {
			riskAssessment = await daemon.request<RiskAssessResult>("risk/assess", {
				workspace,
				files: params.files,
				context: { task: params.task, sessionId: session.id || session.taskId },
			});
		} catch (riskError) {
			// Risk assessment failure is non-fatal  -  intelligence is degraded, not absent
			logNonFatalError({
				tool: "vreko",
				operation: "risk/assess",
				workspace,
				error: riskError,
				metadata: { sessionId: session.id || session.taskId, fileCount: params.files?.length },
			});
		}
	}

	// Step 4: Get compiled context
	let contextData: ContextGetResult | null = null;
	try {
		contextData = await daemon.request<ContextGetResult>("context/get", {
			workspace,
			task: params.task,
			files: params.files,
		});

		// RESUME INTELLIGENCE FIX: Merge learnings into beginData for resumed sessions
		if (isResumed && beginData && contextData?.learnings) {
			beginData = {
				...beginData,
				learnings: contextData.learnings,
			};
		}
	} catch (contextError) {
		// Context compilation may not be available  -  non-fatal
		logNonFatalError({
			tool: "vreko",
			operation: "context/get",
			workspace,
			error: contextError,
			metadata: { sessionId: session.id || session.taskId, task: params.task },
		});
	}

	// Step 5: Format response as natural language intelligence briefing
	// Bug 1 Fix: Pass beginData to the formatter
	return formatVrekoResponse({
		session,
		isResumed,
		riskAssessment,
		contextData,
		beginData,
		task: params.task,
		files: params.files,
		sessionVitals, // LLM UX Issue 3: Session state on resume
		recurrenceCandidates,
	});
};

// =============================================================================
// Response Formatter
// =============================================================================

interface RecurrenceCandidate {
	file: string;
	confidence: number;
	surfaceable: boolean;
	wording: string;
	coChangePartners: string[];
	kind: string;
}

interface FormatParams {
	session: SessionData;
	isResumed: boolean;
	riskAssessment: RiskAssessResult | null;
	contextData: ContextGetResult | null;
	/** Bug 1 Fix: Intelligence from session/start */
	beginData: SessionBeginResult | null;
	task: string;
	files?: string[];
	/** LLM UX Issue 3: Session state on resume for context window continuity */
	sessionVitals?: {
		filesModified: number;
		snapshotsCreated: number;
		learningsCaptured: number;
	} | null;
	/** RECUR-01: All calibrated findings from IPC handler; brief injection gated below. */
	recurrenceCandidates?: RecurrenceCandidate[];
}

export function formatVrekoResponse(data: FormatParams): ToolResult {
	// Defensive defaults  -  all nullable params are narrowed here.
	// data.session is typed non-null in FormatParams but can be null at cold-start call sites.
	const session = data.session ?? {
		id: undefined as string | undefined,
		taskId: undefined as string | undefined,
		task: data.task ?? "unknown",
		active: false,
	};
	const beginData = data.beginData ?? null;
	const riskAssessment = data.riskAssessment ?? null;
	const contextData = data.contextData ?? null;
	const sessionVitals = data.sessionVitals ?? null;
	const recurrenceCandidates = data.recurrenceCandidates ?? [];

	const sections: string[] = [];

	// Header
	if (data.isResumed) {
		sections.push(`Session resumed for: ${data.task}`);
		sections.push("Continuing from previous work in this workspace.");

		// LLM UX Issue 3: Session state on resume for context window continuity
		// Shows what work has already been done in this session
		if (sessionVitals) {
			const { filesModified, snapshotsCreated, learningsCaptured } = sessionVitals;
			sections.push(
				`\n📊 **Session state**: ${filesModified} files modified | ${snapshotsCreated} snapshots | ${learningsCaptured} learnings captured`,
			);
		}
	} else {
		sections.push(`Session started for: ${data.task}`);
	}

	// =============================================================================
	// TIER 1: DIRECT RELEVANCE (Must-show - highest priority)
	// Files and patterns directly related to the current task
	// =============================================================================

	const tier1Sections: string[] = [];
	let hasTier1 = false;

	// Query-aware learnings (highest relevance - from Intelligence query)
	if (beginData?.context?.queryAwareLearnings && beginData.context.queryAwareLearnings.length > 0) {
		hasTier1 = true;
		tier1Sections.push("### Relevant Learnings for This Task\n");
		for (const learning of beginData.context.queryAwareLearnings) {
			const severityIcon = learning.severity === "critical" ? "🚨" : learning.severity === "warning" ? "⚠️" : "ℹ️";
			tier1Sections.push(`- ${severityIcon} ${learning.insight}`);
			if (learning.files?.length > 0) {
				tier1Sections.push(
					`  - Applies to: ${learning.files.slice(0, 3).join(", ")}${learning.files.length > 3 ? "..." : ""}`,
				);
			}
		}
	}

	// Fragile files in scope (direct relevance to touched files)
	if (beginData?.context?.fragileFilesInScope && beginData.context.fragileFilesInScope.length > 0) {
		hasTier1 = true;
		tier1Sections.push("\n### Fragile Files in Scope\n");
		for (const file of beginData.context.fragileFilesInScope) {
			const reason =
				file.reason ??
				(file.fragility != null ? `Fragility score: ${file.fragility.toFixed(2)}` : "High fragility detected");
			tier1Sections.push(`- ⚠️ **${file.path}**: ${reason}`);
		}
	}

	// Existing learnings from session/start (legacy support)
	if (beginData?.learnings && beginData.learnings.length > 0) {
		// Dedupe with queryAwareLearnings
		const queryInsights = new Set((beginData.context?.queryAwareLearnings ?? []).map((l) => l.insight));
		const legacyLearnings = beginData.learnings.filter((l) => !queryInsights.has(`${l.trigger} → ${l.action}`));
		if (legacyLearnings.length > 0) {
			hasTier1 = true;
			tier1Sections.push("\n### Previous Session Learnings\n");
			for (const learning of legacyLearnings.slice(0, 5)) {
				const prefix = learning.type ? `[${learning.type}]` : "";
				tier1Sections.push(`- ${prefix} ${learning.trigger} → ${learning.action}`);
			}
		}
	}

	// Previous session context (Fix 2 G-03/G-07: precise session-scoped data from the just-ended session)
	const prevSession = (
		beginData as Record<string, unknown> & {
			previousSession?: {
				taskName: string;
				duration: number;
				fileCount: number;
				snapshotCount: number;
				learningCount: number;
				modifiedFiles: string[];
			} | null;
		}
	)?.previousSession;

	if (prevSession) {
		hasTier1 = true;
		const durationMin = Math.round(prevSession.duration / 60000);
		tier1Sections.push(`\n### Previous Session: ${prevSession.taskName}`);
		tier1Sections.push(
			`${durationMin}m · ${prevSession.fileCount} files · ${prevSession.snapshotCount} snapshots · ${prevSession.learningCount} learnings`,
		);
		if (prevSession.modifiedFiles?.length > 0) {
			tier1Sections.push(
				`Files touched: ${prevSession.modifiedFiles.slice(0, 8).join(", ")}${prevSession.modifiedFiles.length > 8 ? "..." : ""}`,
			);
		}
	}

	if (hasTier1) {
		sections.push("\n## 🎯 Direct Relevance\n");
		sections.push(...tier1Sections);
	}

	// =============================================================================
	// TIER 2: AMBIENT CONTEXT (Useful context - medium priority)
	// Broader patterns and knowledge that might be relevant
	// =============================================================================

	const tier2Sections: string[] = [];
	let hasTier2 = false;

	// Query-aware knowledge chunks (from Intelligence knowledge store)
	if (beginData?.context?.queryAwareKnowledge && beginData.context.queryAwareKnowledge.length > 0) {
		hasTier2 = true;
		tier2Sections.push("### Knowledge Base\n");
		for (const chunk of beginData.context.queryAwareKnowledge.slice(0, 3)) {
			const preview = chunk.content.length > 150 ? `${chunk.content.substring(0, 150)}...` : chunk.content;
			tier2Sections.push(`- ${preview}`);
		}
	}

	// Co-change patterns (ambient awareness)
	if (beginData?.context?.coChangePatternsInScope && beginData.context.coChangePatternsInScope.length > 0) {
		hasTier2 = true;
		tier2Sections.push("\n### Files That Change Together\n");
		for (const pair of beginData.context.coChangePatternsInScope) {
			tier2Sections.push(
				`- When you modify **${pair.source}**, you usually need to update **${pair.target}** too (${Math.round(pair.confidence * 100)}% confidence)`,
			);
		}
	}

	// RECUR-01: Gate controls brief injection. Fetch always happens; surface does not.
	if (RECURRENCE_SURFACING_ENABLED) {
		const surfaceable = recurrenceCandidates.filter((c) => c.surfaceable);
		if (surfaceable.length > 0) {
			hasTier2 = true;
			tier2Sections.push("\n### Recurrence Signals\n");
			for (const candidate of surfaceable.slice(0, 3)) {
				tier2Sections.push(`- ⚠️ **${candidate.file}**: ${candidate.wording}`);
			}
		}
	}

	// Additional context from context/get (deduped)
	if (contextData?.learnings && contextData.learnings.length > 0) {
		// Use consistent " → " separator to match insight format from session/start
		const beginLearningKeys = new Set((beginData?.learnings ?? []).map((l) => `${l.trigger} → ${l.action}`));
		const queryInsightKeys = new Set((beginData?.context?.queryAwareLearnings ?? []).map((l) => l.insight));
		const newLearnings = contextData.learnings.filter(
			(l) =>
				!beginLearningKeys.has(`${l.trigger} → ${l.action}`) &&
				!queryInsightKeys.has(`${l.trigger} → ${l.action}`),
		);

		if (newLearnings.length > 0) {
			hasTier2 = true;
			tier2Sections.push("\n### Additional Learnings\n");
			for (const learning of newLearnings.slice(0, 3)) {
				const typeTag = learning.type ? `[${learning.type}]` : "";
				tier2Sections.push(`- ${typeTag} ${learning.trigger} → ${learning.action}`);
			}
		}
	}

	if (hasTier2) {
		sections.push("\n## 📚 Ambient Context\n");
		sections.push(...tier2Sections);
	}

	// =============================================================================
	// TIER 3: GUIDANCE (Behavioral recommendations - conditional)
	// Warnings and recommendations based on risk assessment
	// =============================================================================

	const tier3Sections: string[] = [];
	let hasTier3 = false;

	// Concurrent session warning
	if (beginData?.context?.concurrentSessionWarning) {
		const warn = beginData.context.concurrentSessionWarning;
		hasTier3 = true;
		tier3Sections.push("### ⚠️ Concurrent Session Detected\n");
		tier3Sections.push(
			`Another session is active in this workspace, touching: ${warn.touchedFiles?.join(", ") ?? "unknown files"}`,
		);
	}

	// Risk warnings
	if (riskAssessment) {
		const warnings = extractWarnings(riskAssessment);
		if (warnings.length > 0) {
			hasTier3 = true;
			tier3Sections.push("\n### Warnings\n");
			for (const warning of warnings) {
				tier3Sections.push(`- ⚠️ ${warning}`);
			}
		}

		// Additional fragile files from risk assessment (dedupe with beginData)
		const riskFragile = extractFragileFiles(riskAssessment);
		const beginFragilePaths = new Set((beginData?.context?.fragileFilesInScope ?? []).map((f) => f.path));
		const newFragile = riskFragile.filter((f) => !beginFragilePaths.has(f.path));
		if (newFragile.length > 0) {
			hasTier3 = true;
			tier3Sections.push("\n### Additional Fragile Files\n");
			for (const file of newFragile) {
				tier3Sections.push(`- ⚠️ **${file.path}**: ${file.reason}`);
			}
		}

		// Additional co-changes from risk assessment (dedupe with beginData)
		const riskCoChanges = extractCoChangeAlerts(riskAssessment);
		// Build set of all file pairs from coChangePatternsInScope (contract shape: source/target pairs)
		const beginCoChangePairs = new Set<string>();
		for (const pair of beginData?.context?.coChangePatternsInScope ?? []) {
			beginCoChangePairs.add(`${pair.source}:${pair.target}`);
			beginCoChangePairs.add(`${pair.target}:${pair.source}`); // Bidirectional
		}
		const newCoChanges = riskCoChanges.filter((c) => !beginCoChangePairs.has(`${c.file}:${c.partner}`));
		if (newCoChanges.length > 0) {
			hasTier3 = true;
			tier3Sections.push("\n### Additional Co-Change Patterns\n");
			for (const pair of newCoChanges) {
				tier3Sections.push(
					`- When you modify **${pair.file}**, **${pair.partner}** usually needs updating too`,
				);
			}
		}
	}

	if (hasTier3) {
		sections.push("\n## 💡 Guidance\n");
		sections.push(...tier3Sections);
	}

	// =============================================================================
	// TOOL BLIND SPOTS (Connective Intelligence)
	// Show tool-specific blind spots when confidence >= 0.7
	// =============================================================================

	// Check if daemon returned tool identity in metadata
	const toolIdentity = (
		beginData as unknown as { metadata?: { toolIdentity?: { tool: string; confidence: number } } }
	)?.metadata?.toolIdentity;

	if (toolIdentity && toolIdentity.confidence >= 0.7) {
		const blindSpotsSection = formatBlindSpotsForBriefing(toolIdentity.tool, toolIdentity.confidence);
		if (blindSpotsSection) {
			sections.push(blindSpotsSection);
		}
	}

	// Cold-start transparency: surface intelligence depth so agents know what to expect
	// Report card v2 fix: "When briefing is empty, say why  -  converts confusion into trust"
	const learningCount = contextData?.metadata?.learningCount ?? 0;
	if (!hasTier1 && !hasTier2) {
		if (learningCount === 0) {
			sections.push(
				"\n📊 No intelligence yet  -  Vreko is learning. Data accumulates with each session. " +
					"Learnings, fragile file warnings, and co-change patterns will surface here once the workspace has history.",
			);
		} else {
			sections.push(
				`\n📊 ${learningCount} learning${learningCount === 1 ? "" : "s"} in knowledge base  -  no patterns matched the current task/files. ` +
					"Specify files or a more specific task to surface relevant intelligence.",
			);
		}
	}

	// Safety note + close reminder (LLM UX: Issue 1)
	sections.push(
		"\nVreko is now monitoring this session. Files are automatically snapshotted when risk pressure exceeds 70%  -  no manual action needed.",
	);
	sections.push(
		'\n⚠️ **REQUIRED**: Call `vreko_end({ outcome: "completed" })` when your task is complete to close the session and capture learnings.',
	);

	// Session ID (opaque  -  LLM passes it through, doesn't interpret)
	// Include learning count for cold-start awareness (report card v2: sessions_count + learnings_count)
	const kbNote =
		learningCount > 0 ? ` [${learningCount} learnings in knowledge base]` : " [session 1  -  building baseline]";
	sections.push(`\n[session: ${session.id ?? session.taskId}]${kbNote}`);

	return {
		content: [{ type: "text", text: sections.join("\n") }],
	};
}

// =============================================================================
// Helper Functions
// =============================================================================

function extractWarnings(risk: RiskAssessResult): string[] {
	const warnings: string[] = [];

	// Git risk pillar
	if (risk.gitRisk) {
		if (risk.gitRisk.uncommittedChanges) {
			warnings.push("You have uncommitted changes. Consider committing before making AI-assisted modifications.");
		}
		if (risk.gitRisk.detachedHead) {
			warnings.push("You're on a detached HEAD. Changes may be hard to recover without Vreko.");
		}
		if (risk.gitRisk.onMainBranch) {
			warnings.push("You're working directly on main branch. Consider creating a feature branch.");
		}
	}

	// Fatigue pillar
	if (risk.fatigue) {
		if (risk.fatigue.level === "fatigued" || risk.fatigue.level === "elevated") {
			warnings.push("High change velocity detected. You've been making rapid changes  -  slow down and review.");
		}
	}

	// Rollback warning
	if (risk.rollbackWarning) {
		warnings.push(risk.rollbackWarning.message);
	}

	// Poisoning detection
	if (risk.poisoning?.detected) {
		const files = risk.poisoning.files?.join(", ") || "some files";
		warnings.push(
			`Repeated pattern of rejected changes detected in ${files}. The AI may have a persistent misunderstanding about this code.`,
		);
	}

	// Overall risk level
	const riskScore = risk.score ?? 0;
	if (riskScore >= 2.0) {
		warnings.push(
			`Overall risk is HIGH (${riskScore.toFixed(1)}). Proceed with extra caution  -  Vreko will snapshot aggressively.`,
		);
	} else if (riskScore >= 1.5) {
		warnings.push(
			`Elevated risk detected (${riskScore.toFixed(1)}). Vreko will create additional safety snapshots.`,
		);
	}

	return warnings;
}

function extractFragileFiles(risk: RiskAssessResult): Array<{ path: string; reason: string }> {
	const fragile: Array<{ path: string; reason: string }> = [];

	if (risk.fileRisks) {
		for (const [path, fileRisk] of Object.entries(risk.fileRisks)) {
			if (fileRisk.fragility > 0.7) {
				fragile.push({
					path,
					reason: fileRisk.reason || `${fileRisk.rollbackCount || "Multiple"} rollbacks in recent sessions`,
				});
			}
		}
	}

	return fragile;
}

function extractCoChangeAlerts(risk: RiskAssessResult): Array<{ file: string; partner: string }> {
	const pairs: Array<{ file: string; partner: string }> = [];

	if (risk.coChanges) {
		for (const pair of risk.coChanges) {
			pairs.push({ file: pair.source, partner: pair.target });
		}
	}

	return pairs;
}

