/**
 * MCP Server Factory (Unified)
 *
 * Creates and configures the MCP server with all tools registered.
 * This is the main entry point for server creation.
 *
 * Sprint 4 (Unification): Single dispatch path using ToolRegistry.
 * Both `createMcpServer()` and `createMcpServerWithRegistry()` now
 * converge on the same ToolRegistry-based implementation.
 *
 * Day 4: Removed direct @vreko/intelligence imports. Vector search
 * and context retrieval now route through daemon IPC.
 *
 * @module server
 */

import * as fs from "node:fs";
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { CallToolRequestSchema, ListToolsRequestSchema, PingRequestSchema } from "@modelcontextprotocol/sdk/types.js";
import { generateWorkspaceId } from "@vreko/workspace-identity";
import { recordToolCallEventAsync } from "./adapters/session-adapter.js";
import type { VrekoAPIClient } from "./api/api-client.js";
import { createDaemonClient } from "./daemon/local-service-adapter.js";
import { createRequestContext, log, logError, logSuccess } from "./errors/index.js";
import { repairWorkspaceIssues, validateWorkspaceHealth } from "./health/integration.js";
import { getAdaptedConsolidatedTools } from "./registry/adapter.js";
import { applyV2Surface } from "./registry/apply-v2-surface.js";
import { CapabilityManager } from "./registry/CapabilityManager.js";
import { createToolRegistry, type ToolRegistry } from "./registry/ToolRegistry.js";
import type { ToolContext as NewToolContext } from "./registry/types.js";
import { resolveInputSchemaForMcp } from "./registry/types.js";
import { initializeHybridRetrieval } from "./services/hybrid-retrieval-service.js";
import { type IVitalsProvider, VitalsEnricherService } from "./services/vitals-enricher-service.js";
import { McpEventTracker } from "./telemetry/mcp-event-tracker.js";
import { CONSOLIDATED_TOOLS, getMigrationGuidance, isConsolidatedTool } from "./tools/consolidated/registry.js";
import type { ToolResult } from "./types/tool-types.js";
import { getToolSchema, validateInput } from "./validation.js";

/**
 * Create a vitals provider that queries the daemon for actual session health
 * Pass 2 - Single Source of Truth: Vitals computed from daemon's session registry
 */
function createVitalsProvider(
	workspaceRoot: string,
	daemonClient: ReturnType<typeof createDaemonClient>,
): IVitalsProvider {
	return {
		getVitalsSnapshot: async (_root: string) => {
			try {
				// Query daemon for actual session vitals computed from session registry
				const result = await daemonClient.request<{
					pulse: string;
					pressure: number;
					trajectory: string;
					snapshotRecommended: boolean;
					filesModified: number;
					snapshotsCreated: number;
					learningsCaptured: number;
					changesPerMinute?: number;
				}>("session/vitals", { workspacePath: workspaceRoot });

				if (result) {
					return {
						pulse: { level: result.pulse, changesPerMinute: result.changesPerMinute ?? 0 },
						pressure: { value: result.pressure },
						trajectory: result.trajectory,
					};
				}

				// Fallback to defaults if no result (no active session)
				return {
					pulse: { level: "resting" as const, changesPerMinute: 0 },
					pressure: { value: 0 },
					trajectory: "stable" as const,
				};
			} catch {
				return {
					pulse: { level: "resting" as const, changesPerMinute: 0 },
					pressure: { value: -1 }, // -1 signals degraded/unknown, not a real pressure reading
					trajectory: "stable" as const,
				};
			}
		},
	};
}

/**
 * Options for creating an MCP server
 */
export interface McpServerOptions {
	/** Absolute path to workspace root */
	workspaceRoot: string;
	/** User tier for gating features */
	tier: "free" | "pro" | "enterprise";
	/**
	 * Storage mode - determines filesystem write permissions
	 *
	 * - "local": Full read/write access (for local CLI usage)
	 * - "remote": Read-only access (for remote/hosted MCP servers)
	 * - "readonly": Read-only access (default, prevents filesystem writes)
	 *
	 * Remote/hosted MCP servers should NEVER attempt filesystem writes.
	 * Defaults to "readonly" to prevent permission errors.
	 */
	storageMode?: "local" | "remote" | "readonly";
	/** Optional API client for backend operations */
	apiClient?: VrekoAPIClient;
	/** Optional auth context */
	auth?: {
		apiKey?: string;
		userId?: string;
	};
	/** Optional telemetry sink */
	telemetry?: {
		log: (event: string, data: Record<string, unknown>) => void;
	};
	/**
	 * Enable semantic search using vector embeddings
	 * @default false - Disabled for faster startup
	 */
	enableSemanticSearch?: boolean;
	/**
	 * Path for vector storage (relative to workspace root)
	 * @default ".vreko/vectors"
	 */
	vectorStoragePath?: string;
	/**
	 * Remote API configuration for Pro-tier intelligence tools.
	 * When provided, enables routing certain tools to remote API.
	 * Optional - if absent, all tools use daemon (local/IPC).
	 */
	remote?: import("./bridge/types.js").RemoteConfig;
}

/**
 * Options for creating an MCP server with ToolRegistry
 * Extends McpServerOptions with optional registry for dependency injection
 */
export interface McpServerWithRegistryOptions extends McpServerOptions {
	/** Optional ToolRegistry instance for dependency injection */
	registry?: ToolRegistry;
}

// =============================================================================
// Unified Server Factory (Sprint 4: Single Dispatch Path)
// =============================================================================

/**
 * Create an MCP server with all tools registered.
 *
 * This is the primary public API. When called without a registry,
 * it auto-creates one and loads the consolidated tools. When a
 * registry is pre-populated (e.g., by the stdio/http transports),
 * it uses it directly.
 *
 * All dispatch flows through the ToolRegistry, ensuring:
 * - Workspace validation
 * - Tier gating (via ToolRegistry.execute)
 * - Input validation (Zod schemas via getToolSchema fallback)
 * - Telemetry tracking
 * - Vitals enrichment
 * - Error diagnostics
 * - Migration guidance for deprecated tools
 *
 * @param options - Server configuration options
 * @returns Configured MCP Server instance
 *
 * @example
 * ```typescript
 * const server = createMcpServer({
 *   workspaceRoot: "/path/to/workspace",
 *   tier: "pro",
 * });
 * ```
 */
export async function createMcpServer(options: McpServerOptions): Promise<Server> {
	// Delegate to the unified factory with no pre-built registry
	return createUnifiedServer(options);
}

/**
 * Create an MCP server with optional ToolRegistry support (ADR-003).
 *
 * Both code paths now converge on the same ToolRegistry-based dispatch.
 * If a registry is provided it is used directly; otherwise one is
 * created and populated with the consolidated tools.
 *
 * @param options - Server configuration options with optional registry
 * @returns Configured MCP Server instance
 */
export async function createMcpServerWithRegistry(options: McpServerWithRegistryOptions): Promise<Server> {
	return createUnifiedServer(options, options.registry);
}

/**
 * Unified server implementation.
 *
 * Merges all middleware that previously lived in separate legacy and
 * registry code paths into one authoritative dispatch pipeline:
 *
 * 1. Workspace validation
 * 2. ToolRegistry creation (if not injected)
 * 3. ListTools / Ping / CallTool handlers
 * 4. CallTool middleware chain:
 *    a. Migration guidance for deprecated tools
 *    b. Tier gating (ToolRegistry handles via execute)
 *    c. Input validation (Zod schemas)
 *    d. Execution via ToolRegistry.execute()
 *    e. Vitals enrichment on success
 *    f. Enhanced error diagnostics on failure
 *    g. Telemetry tracking (fire-and-forget)
 */
async function createUnifiedServer(options: McpServerOptions, injectedRegistry?: ToolRegistry): Promise<Server> {
	const { workspaceRoot, tier } = options;

	// ------------------------------------------------------------------
	// 1. Workspace validation
	// ------------------------------------------------------------------
	// Skip filesystem validation for remote mode - workspace is just an identifier,
	// not a local path that needs to exist on the server.
	// This enables remote MCP servers (Fly.io) to work with client workspace paths.
	if (options.storageMode !== "remote") {
		if (!fs.existsSync(workspaceRoot)) {
			throw new Error(`Workspace does not exist: ${workspaceRoot}`);
		}
		if (!fs.statSync(workspaceRoot).isDirectory()) {
			throw new Error(`Workspace is not a directory: ${workspaceRoot}`);
		}
	} else {
		// Intentionally empty: remote mode skips local filesystem validation
	}

	// ------------------------------------------------------------------
	// 1b. Startup Health Validation  -  deferred, never blocks transport connect
	// ------------------------------------------------------------------
	// Run asynchronously so it never delays the MCP handshake. The transport
	// must connect before any async I/O; health issues are logged but do not
	// prevent serving.
	// Skip entirely for remote mode - no local filesystem to validate.
	if (options.storageMode !== "remote") {
		Promise.resolve().then(async () => {
			try {
				const health = await validateWorkspaceHealth(workspaceRoot);

				if (!health.healthy) {
					if (health.autoFixable.length > 0) {
						// Silently repair auto-fixable issues
						const _repairResult = await repairWorkspaceIssues(workspaceRoot, health.autoFixable);
					}

					if (health.requiresUserAction.length > 0) {
						for (const _issue of health.requiresUserAction) {
							// Intentionally ignored: user-action issues are logged by health validator, no action here
						}
					}
				}
			} catch (_healthError) {
				// Intentionally ignored: health validation is deferred and non-blocking
			}
		});
	}

	// ------------------------------------------------------------------
	// 1c. Workspace ID Generation
	// ------------------------------------------------------------------
	// Note: workspaceId is generated for context/service configuration (reserved for future use)
	const _workspaceId = generateWorkspaceId(workspaceRoot);

	// Day 4: Vector store initialization moved to daemon
	// Semantic search is now handled via daemon IPC (context/get, embeddings/*)
	// The daemon manages vector storage and embedding generation centrally

	// ------------------------------------------------------------------
	// 2. ToolRegistry  -  use injected or create + populate
	// ------------------------------------------------------------------
	const registry: ToolRegistry = injectedRegistry ?? createToolRegistry();

	// If no injected registry, load consolidated tools synchronously
	// NOTE: For the sync createMcpServer() path we cannot await, so we
	// eagerly populate the registry using a cached promise and handle
	// the race via a "loading" flag that ListTools / CallTool can await.
	let toolsReady: Promise<void> | null = null;
	if (!injectedRegistry) {
		toolsReady = (async () => {
			try {
				const adaptedTools = await getAdaptedConsolidatedTools();
				for (const tool of adaptedTools) {
					if (!registry.has(tool.name)) {
						registry.register(tool);
					}
				}
			} catch (_err) {
				// Intentionally ignored: consolidated tool loading is best-effort, V2 tools are primary
			}

			// Register the V2 surface (vreko, vreko_pulse, vreko_learn, vreko_end).
			// Shared with the HTTP transport via applyV2Surface so the two
			// `tools/list` surfaces cannot diverge (ARCH-09).
			await applyV2Surface(registry);
		})();
	}

	// ------------------------------------------------------------------
	// 3. Create MCP Server instance
	// ------------------------------------------------------------------
	const server = new Server(
		{
			name: "vreko-mcp",
			version: "1.0.0",
		},
		{
			capabilities: {
				tools: {},
				resources: {},
				experimental: {
					serverInfo: {
						storageMode: options.storageMode || "readonly",
						writeCapable: (options.storageMode || "readonly") === "local",
						cliAvailable: true,
						cliSetupCommand: "npm install -g @vreko/cli && vreko tools configure",
					},
				},
			},
			instructions: [
				"Vreko MCP  -  V2 4-Tool Surface (authoritative, overrides individual descriptions):",
				"",
				"Workflow: vreko → [work] → vreko_learn (optional) → vreko_end.",
				"",
				"Tool Usage:",
				"  1. Call vreko FIRST before any code changes  -  returns intelligence briefing",
				"  2. Call vreko_learn when you discover something worth remembering",
				"  3. Call vreko_end when task is complete  -  returns session summary",
				"",
				"Key Points:",
				"  - vreko is idempotent  -  calling twice resumes the same session",
				"  - vreko_learn creates implicit session if needed",
				"  - All files are automatically protected  -  no manual snapshot needed",
				"  - Workspace isolation: learnings and context are scoped to this workspace",
			].join("\n"),
		},
	);

	// ------------------------------------------------------------------
	// 4. Shared infrastructure
	// ------------------------------------------------------------------

	// Create daemon client for intelligence tools
	const daemonClient = createDaemonClient(workspaceRoot);

	// Create session manager stub
	const _sessionManager = {
		detectLoop: (_sessionId: string) => ({
			detected: false,
			confidence: 0,
			evidence: [] as string[],
			action: "continue" as const,
		}),
	};

	// Pioneer service (optional, requires API client)
	const _pioneerService = options.apiClient
		? {
				recordAction: async (
					userId: string,
					action: string,
					metadata?: Record<string, unknown>,
					idempotencyKey?: string,
				) => {
					try {
						const response = await options.apiClient?.request<{ pointsAwarded?: number }>(
							"pioneer.recordAction",
							{ userId, action, metadata, idempotencyKey },
						);
						return { success: true, pointsAwarded: response?.pointsAwarded ?? 0 };
					} catch {
						return { success: false, pointsAwarded: 0 };
					}
				},
			}
		: undefined;

	// New-style base context for ToolRegistry execution
	const baseNewContext: Partial<NewToolContext> = {
		workspace: { path: workspaceRoot, tier },
		user: options.auth?.userId ? { id: options.auth.userId, email: "" } : undefined,
		request: { id: "unknown", timestamp: new Date(), source: "unknown" },
	};

	// Telemetry & Vitals
	const eventTracker = new McpEventTracker(options.telemetry ?? null);
	const vitalsProvider = createVitalsProvider(workspaceRoot, daemonClient);
	const vitalsEnricher = new VitalsEnricherService(vitalsProvider);

	// Capability manager (singleton)
	const capManager = new CapabilityManager();

	// Log server creation
	const _toolCount = injectedRegistry ? registry.getToolNames().length : "(loading)";

	// Initialize hybrid retrieval (non-blocking)
	initializeHybridRetrieval(workspaceRoot).catch((_error) => {
		// Intentionally ignored: hybrid retrieval initialization is non-blocking
	});

	// ------------------------------------------------------------------
	// 5. Request Handlers
	// ------------------------------------------------------------------

	// Ping  -  MCP 2024-11-05 spec compliance
	server.setRequestHandler(PingRequestSchema, async () => ({}));

	// ListTools  -  always served from the registry
	server.setRequestHandler(ListToolsRequestSchema, async () => {
		// Ensure tools are loaded before listing
		if (toolsReady) {
			await toolsReady;
		}

		const tools = registry.list({ tier });

		return {
			tools: tools.map((tool) => ({
				name: tool.name,
				description: tool.description,
				inputSchema: resolveInputSchemaForMcp(tool.inputSchema),
				annotations: tool.annotations,
			})),
		};
	});

	// CallTool  -  unified dispatch pipeline
	server.setRequestHandler(CallToolRequestSchema, async (request) => {
		// Ensure tools are loaded before dispatching
		if (toolsReady) {
			await toolsReady;
		}

		const { name, arguments: args } = request.params;
		const startTime = Date.now();

		// Capture clientInfo from MCP handshake (authoritative attribution)
		const clientInfo = server.getClientVersion?.() ?? null;
		const clientName = clientInfo?.name ?? "unknown";
		const clientVersion = clientInfo?.version ?? "unknown";

		// Structured logging context
		const reqCtx = createRequestContext(name, { userId: options.auth?.userId, tier, clientName, clientVersion });
		log("info", reqCtx, "Tool call started", { args: Object.keys(args || {}), clientName, clientVersion });

		// --- Middleware (a): Migration guidance for deprecated tools ---
		if (!isConsolidatedTool(name)) {
			const guidance = getMigrationGuidance(name);
			if (guidance) {
				log("warn", reqCtx, "Legacy tool called", { guidance });
				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								error: "E601_DEPRECATED_TOOL",
								message: `Tool '${name}' is deprecated. ${guidance}`,
								migration: guidance,
								availableTools: CONSOLIDATED_TOOLS.map((t) => t.name),
							}),
						},
					],
					isError: true,
				};
			}
		}

		// --- Middleware (b): Input sanitization (graceful degradation) ---
		// Forgiving Format pattern: strip invalid fields with warnings instead of failing
		const { args: sanitizedArgs, warnings: inputWarnings } = sanitizeInput(
			name,
			(args as Record<string, unknown>) || {},
		);

		// Log warnings for observability (but don't fail)
		if (inputWarnings.length > 0) {
			log("info", reqCtx, `INPUT_SANITIZED: Stripped ${inputWarnings.length} invalid field(s) with warnings`);
		}

		// --- Middleware (d): Input validation (Zod schemas) ---
		const schema = getToolSchema(name);
		if (schema) {
			const validation = validateInput(schema, sanitizedArgs);
			if (!validation.valid) {
				logError(reqCtx, "E104_VALIDATION_FAILED", validation.error);
				const guidance = getValidationGuidance(name, validation.error);

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								error: "E104_VALIDATION_FAILED",
								message: validation.error + guidance,
								tool: name,
								issues: validation.issues,
								hint: "Check the tool's inputSchema for required parameters and accepted values",
							}),
						},
					],
					isError: true,
				};
			}
		}

		// --- Middleware (e): Execute via ToolRegistry ---
		try {
			const activeCapabilities = capManager.getActiveCapabilities({ path: workspaceRoot, tier });

			// Build services using daemon-first pattern
			// Daemon handles persistence, we delegate via daemonClient.request()
			const intelligenceServices = {
				// Required services (stubs - tools should use storage directly)
				runtime: {
					createSnapshot: async () => ({ snapshotId: "", snapshot: {} as unknown }),
					getSnapshot: async () => null,
					listSnapshots: async () => [],
					restoreSnapshot: async () => ({ success: false, restoredFiles: [], conflicts: [], errors: [] }),
					deleteSnapshot: async () => false,
				},
				telemetry: {
					track: async () => undefined,
					flush: async () => undefined,
				},
				learning: {
					getRelevant: async () => [],
					create: async (_learning: { trigger: string; action: string }) => ({ id: `learn_${Date.now()}` }),
					list: async () => [],
				},
				// Intelligence v2 stores - delegate to daemon/local-service
				decisionStore: {
					getDecisionForSnapshot: async (snapshotId: string, _workspace: string) => {
						// Delegate to daemon's intelligence service
						if (daemonClient.isAvailable()) {
							return daemonClient.request<{
								id: string;
								file_path: string;
								ai_tool: string | null;
								signal_ids: string[];
							} | null>("intelligence.getDecision", { snapshotId, workspace: workspaceRoot });
						}
						return null;
					},
					recordOutcome: async (id: string, outcome: "rolled_back") => {
						// Delegate to daemon's intelligence service
						if (daemonClient.isAvailable()) {
							await daemonClient.request("intelligence.decisionOutcome", {
								decisionId: id,
								outcome: outcome === "rolled_back" ? "recovered" : outcome,
								workspace: workspaceRoot,
							});
						}
					},
				},
				stateStore: {
					addLearning: (learning: {
						type: "pattern" | "pitfall" | "efficiency" | "discovery" | "workflow";
						trigger: string;
						action: string;
						source?: "survey" | "manual" | "violation" | "curated";
						tier: "hot" | "warm" | "cold";
						domain?: string;
					}) => {
						// Delegate to daemon's intelligence service
						if (daemonClient.isAvailable()) {
							daemonClient
								.request<{ captured: boolean }>("intelligence.capture", {
									workspace: workspaceRoot,
									content: `${learning.trigger}\n${learning.action}`,
									domain: learning.domain,
									type: learning.type,
									filePath: learning.trigger,
									aiTool: "claude" as const,
									risk:
										learning.tier === "hot" ? "high" : learning.tier === "warm" ? "medium" : "low",
								})
								.catch((_err) => {
									/* intentionally empty */
								});
						}
						return { id: `learn_${Date.now()}` };
					},
				},
				analytics: {
					track: (eventName: string, properties: Record<string, unknown>) => {
						// Delegate to daemon's analytics service
						if (daemonClient.isAvailable()) {
							daemonClient
								.request("analytics.track", {
									event: eventName,
									properties: { ...properties, workspace: workspaceRoot },
								})
								.catch(() => {
									// Silently ignore analytics failures
								});
						}
					},
				},
			};

			const context: NewToolContext = {
				...baseNewContext,
				activeCapabilities,
				services: intelligenceServices,
				request: {
					id: `req-${Date.now()}`,
					timestamp: new Date(),
					source: "unknown",
				},
			} as NewToolContext;

			// Use sanitized args (invalid fields stripped with warnings)
			const result = await registry.execute(name, sanitizedArgs, context);

			// --- Middleware (g): Telemetry (fire-and-forget) + local session log ---
			const durationMs = Date.now() - startTime;
			const mode =
				args && typeof args === "object" && "mode" in (args as Record<string, unknown>)
					? String((args as Record<string, unknown>).mode)
					: undefined;

			// Local tool call log for behavior analytics (LLM tool observability)
			await recordToolCallEventAsync(workspaceRoot, {
				tool: name,
				mode,
				durationMs,
				success: result.success,
				errorCode: result.error,
				clientName,
				clientVersion,
			});

			// External telemetry sink (PostHog, etc.)
			eventTracker.trackToolCalled({
				tool_name: name,
				client_type: clientName, // Use actual client name from MCP handshake
				client_version: clientVersion,
				parameters: args || {},
				execution_time_ms: durationMs,
				was_successful: result.success,
				error_code: result.error,
			});

			// Handle failure from ToolRegistry
			if (!result.success) {
				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								error: result.error,
								tool: name,
								stack: result.stack,
							}),
						},
					],
					isError: true,
				};
			}

			// Handle ToolResult format (legacy adapted handlers return this)
			const toolResult = result.result as ToolResult | undefined;
			if (toolResult?.content && Array.isArray(toolResult.content)) {
				logSuccess(reqCtx, "Tool call completed", { isError: toolResult.isError });

				// --- Middleware (f): Vitals enrichment ---
				// Skip enrichment for meta tool and vreko_end (session is ending)
				const shouldEnrich = name !== "meta" && name !== "vreko_end";
				const enhanced = shouldEnrich
					? await vitalsEnricher.enhance(toolResult, workspaceRoot, eventTracker)
					: toolResult;

				// --- Middleware (g): Inject input warnings (graceful degradation feedback) ---
				const enrichedContent = (enhanced.content || []).map((c: { type: string; text: string }) => ({
					type: "text" as const,
					text: c.text,
				}));

				if (inputWarnings.length > 0) {
					// Prepend warnings to response so agent learns from the correction
					const warningsText = [
						"⚠️ INPUT_SANITIZED:",
						...inputWarnings.map((w) => {
							const opts = w.validOptions ? ` Valid: ${w.validOptions.join("|")}` : "";
							const suggestion = w.suggestion ? ` Example: ${JSON.stringify(w.suggestion)}` : "";
							return `  • ${w.message}${opts}${suggestion}`;
						}),
						"", // blank line separator
					].join("\n");

					// Find the wire format separator and inject warnings after it
					const firstContent = enrichedContent[0];
					if (firstContent && typeof firstContent.text === "string") {
						// Look for the internal separator (---) used in wire format
						const separatorIndex = firstContent.text.indexOf("---");
						if (separatorIndex > 0) {
							// Insert warnings after the wire line, before human-readable section
							const wirePart = firstContent.text.slice(0, separatorIndex + 3);
							const humanPart = firstContent.text.slice(separatorIndex + 3);
							firstContent.text = `${wirePart}\n${warningsText}${humanPart}`;
						} else {
							// No separator - prepend warnings
							firstContent.text = `${warningsText}${firstContent.text}`;
						}
					}
				}

				// --- Middleware (h): LLM UX Issue 4 - Suggested learning on error recovery ---
				// When a tool fails, prompt the LLM to capture the failure pattern as a learning.
				// The LLM decides whether to call vreko_learn - keeps developer in the loop.
				if (enhanced.isError && name !== "vreko_learn" && name !== "vreko_end") {
					const firstContent = enrichedContent[0];
					if (firstContent && typeof firstContent.text === "string") {
						const learningHint = [
							"",
							"💡 SUGGESTED_LEARNING: This tool call failed. Consider capturing the failure pattern:",
							`  vreko_learn({ type: "pitfall", trigger: "${name} error", action: "..." })`,
							"  (Replace '...' with the specific insight from this failure)",
							"",
						].join("\n");
						firstContent.text = `${firstContent.text}${learningHint}`;
					}
				}

				return {
					content: enrichedContent,
					isError: enhanced.isError,
				};
			}

			// Handle generic result (non-ToolResult shape)
			return {
				content: [
					{
						type: "text" as const,
						text: JSON.stringify(result.result),
					},
				],
				isError: false,
			};
		} catch (outerError) {
			const errorMessage = outerError instanceof Error ? outerError.message : String(outerError);
			const errorStack = outerError instanceof Error ? outerError.stack : undefined;

			logError(reqCtx, "E502_HANDLER_ERROR", errorMessage);

			// Track failed tool call (local session log + external telemetry)
			const durationMs = Date.now() - startTime;
			const mode =
				args && typeof args === "object" && "mode" in (args as Record<string, unknown>)
					? String((args as Record<string, unknown>).mode)
					: undefined;

			await recordToolCallEventAsync(workspaceRoot, {
				tool: name,
				mode,
				durationMs,
				success: false,
				errorCode: outerError instanceof Error ? outerError.name : "UNKNOWN_ERROR",
				clientName,
				clientVersion,
			});

			// Track failed tool call
			eventTracker.trackToolCalled({
				tool_name: name,
				client_type: clientName,
				client_version: clientVersion,
				parameters: args || {},
				execution_time_ms: durationMs,
				was_successful: false,
				error_code: outerError instanceof Error ? outerError.name : "UNKNOWN_ERROR",
			});

			// --- Middleware (f): Enhanced error diagnostics ---
			try {
				const { formatDiagnosticError } = await import("./errors/index.js");
				const diagnostic = formatDiagnosticError(outerError, {
					tool: name,
					workspace: workspaceRoot,
				});
				const diagnosticList = Array.isArray(diagnostic.diagnostics) ? diagnostic.diagnostics : [];
				const diagnosticText = [
					`\u{1F9E2}|H|status:ERROR|code:${diagnostic.code}`,
					"DIAGNOSTICS:",
					...diagnosticList.map((d) => `- ${d}`),
					diagnostic.fix ? `\nFIX: ${diagnostic.fix}` : "",
				]
					.filter(Boolean)
					.join("\n");

				return {
					content: [{ type: "text" as const, text: diagnosticText }],
					isError: true,
				};
			} catch {
				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								error: errorMessage,
								tool: name,
								stack: errorStack,
								_source: "unhandled_calltool_error",
							}),
						},
					],
					isError: true,
				};
			}
		}
	});

	return server;
}

// =============================================================================
// Validation Guidance Helper
// =============================================================================

/**
 * Generate LLM-friendly validation guidance based on tool and error.
 */
function getValidationGuidance(name: string, error: string): string {
	if (name === "vreko" && error.includes("mode")) {
		return (
			"\n\n\u{1F4A1} TIP: The 'vreko' tool accepts EITHER:\n" +
			'  - mode: "start" | "context" (full-word, recommended)\n' +
			'  - m: "s" | "x" (legacy single-letter)\n\n' +
			'Example: vreko({ mode: "start", task: "fix bug" })'
		);
	}
	if (name === "vreko_learn" && error.includes("trigger")) {
		return (
			"\n\n\u{1F4A1} TIP: The 'vreko_learn' tool requires BOTH:\n" +
			'  - trigger: "when X happens" (or legacy: t)\n' +
			'  - action: "do Y" (or legacy: a)\n\n' +
			'Example: vreko_learn({ trigger: "auth token refresh", action: "check expiry before API call" })'
		);
	}
	if (name === "vreko_violation" && error.includes("description")) {
		return (
			"\n\n\u{1F4A1} TIP: The 'vreko_violation' tool requires:\n" +
			"  - type: \"violation_key\" (e.g., 'silent_catch')\n" +
			'  - file: "path/to/file"\n' +
			'  - description: "what went wrong" (or legacy: what)\n' +
			'  - prevention: "how to avoid" (or legacy: prevent)\n\n' +
			'Example: vreko_violation({ type: "silent_catch", file: "auth.ts", description: "Caught error without logging", prevention: "Always log in catch blocks" })'
		);
	}
	if (name === "check" && error.includes("mode")) {
		return (
			"\n\n\u{1F4A1} TIP: The 'check' tool accepts EITHER:\n" +
			'  - mode: "quick" | "full" | "patterns" | "build" | "impact" | "circular" | "docs" | "learnings" | "architecture" (recommended)\n' +
			'  - m: "q" | "f" | "p" | "b" | "i" | "c" | "d" | "l" | "a" (legacy)\n\n' +
			'Example: check({ mode: "quick", files: ["src/auth.ts"] })'
		);
	}
	return "";
}

// =============================================================================
// Input Sanitization (Graceful Degradation)
// =============================================================================

/** Valid goal metrics for vreko tool */
const VALID_GOAL_METRICS = ["bundle", "performance", "coverage"] as const;

/** Common invalid metrics that agents might try (for better error messages) */
const KNOWN_INVALID_METRICS: Record<string, string> = {
	momentum: "Momentum is a scoring system concept, not a task goal metric",
	velocity: "Velocity is not a valid goal metric",
	quality: "Quality is not a valid goal metric - use 'coverage' for test coverage",
	speed: "Speed is not a valid goal metric - use 'performance' for timing",
	size: "Size is not a valid goal metric - use 'bundle' for bundle size",
};

/**
 * Structured warning for LLM comprehension and self-correction
 */
export interface InputWarning {
	field: string;
	received: unknown;
	message: string;
	validOptions?: readonly string[];
	suggestion?: Record<string, unknown>;
}

/**
 * Result of input sanitization
 */
interface SanitizeResult {
	/** Sanitized arguments (invalid fields stripped) */
	args: Record<string, unknown>;
	/** Warnings about stripped/corrected fields */
	warnings: InputWarning[];
}

/**
 * Sanitize vreko tool input with graceful degradation.
 *
 * Instead of failing on invalid goal.metric, strip the invalid goal
 * and return a warning. This allows the task to proceed while
 * educating the agent about valid values.
 *
 * Implements "Forgiving Format" UX pattern:
 * - Accept the invalid input
 * - Strip the problematic field
 * - Warn (don't silently drop)
 * - Continue execution
 */
function sanitizeSnapInput(args: Record<string, unknown>): SanitizeResult {
	const warnings: InputWarning[] = [];
	const sanitized = { ...args };

	// Check goal.metric validity
	if (sanitized.goal && typeof sanitized.goal === "object") {
		const goal = sanitized.goal as Record<string, unknown>;
		const metric = goal.metric;

		if (metric !== undefined && !VALID_GOAL_METRICS.includes(metric as (typeof VALID_GOAL_METRICS)[number])) {
			// Build helpful warning message
			const knownReason = typeof metric === "string" ? KNOWN_INVALID_METRICS[metric.toLowerCase()] : undefined;
			const message = knownReason
				? `Invalid goal.metric "${metric}" ignored. ${knownReason}.`
				: `Invalid goal.metric "${metric}" ignored.`;

			warnings.push({
				field: "goal.metric",
				received: metric,
				message,
				validOptions: VALID_GOAL_METRICS,
				suggestion: { metric: "coverage", target: 80, unit: "%" },
			});

			// Strip the invalid goal entirely (metric is required in goal object)
			delete sanitized.goal;
		}
	}

	return { args: sanitized, warnings };
}

/**
 * Sanitize input for any tool with graceful degradation.
 * Currently supports: vreko
 *
 * Returns sanitized args and any warnings generated.
 */
function sanitizeInput(name: string, args: Record<string, unknown>): SanitizeResult {
	switch (name) {
		case "vreko":
			return sanitizeSnapInput(args);
		default:
			return { args, warnings: [] };
	}
}
