/**
 * Registry Adapter (ADR-003 Migration)
 *
 * Bridges the OLD registry types (VrekoTool, ToolHandler, ToolContext)
 * to the NEW registry types (ToolDefinition, ToolHandler, ToolContext).
 *
 * This allows gradual migration without breaking existing code.
 *
 * @module registry/adapter
 */

import type {
	ToolContext as LegacyToolContext,
	ToolHandler as LegacyToolHandler,
	ToolResult,
	VrekoTool,
} from "../types/tool-types.js";

import {
	type ToolContext as NewToolContext,
	type ToolHandler as NewToolHandler,
	ToolCapability,
	type ToolDefinition,
	type ToolTier,
} from "./types.js";

// =============================================================================
// CAPABILITY INFERENCE
// =============================================================================

/**
 * Capability mapping for each tool (V2 + consolidated)
 */
const TOOL_CAPABILITY_MAP: Record<string, ToolCapability[]> = {
	// V2 tools (primary)
	vreko: [ToolCapability.SNAPSHOT_WRITE, ToolCapability.SESSION_WRITE, ToolCapability.LEARNING_READ],
	vreko_learn: [ToolCapability.LEARNING_WRITE],
	vreko_end: [ToolCapability.SESSION_WRITE, ToolCapability.TELEMETRY_WRITE],
	vreko_pulse: [ToolCapability.SESSION_READ],

	// Consolidated tools (legacy, for backward compatibility)
	snap_end: [ToolCapability.SESSION_WRITE, ToolCapability.TELEMETRY_WRITE],
	snap_learn: [ToolCapability.LEARNING_WRITE],
	snap_violation: [ToolCapability.LEARNING_WRITE],
	snap_fix: [ToolCapability.SNAPSHOT_WRITE],
	snap_help: [],
	check: [ToolCapability.VALIDATE_READ],
};

/**
 * Infer capabilities from tool name
 *
 * @param toolName - Name of the tool
 * @returns Array of capabilities the tool requires
 */
export function inferCapabilities(toolName: string): ToolCapability[] {
	return TOOL_CAPABILITY_MAP[toolName] ?? [];
}

// =============================================================================
// CONTEXT ADAPTERS
// =============================================================================

/**
 * Create a legacy context from a new context
 *
 * Extracts fields from NewToolContext to create LegacyToolContext
 * for backward compatibility with existing handlers.
 *
 * @param newContext - New-style ToolContext
 * @returns Legacy-style ToolContext
 */
export function createLegacyContextFromNew(newContext: NewToolContext): LegacyToolContext {
	return {
		workspaceRoot: newContext.workspace.path,
		tier: newContext.workspace.tier,
		storageMode: "local", // Default to local for legacy compatibility
		userId: newContext.user?.id,
		sessionId: undefined, // Not available in new context structure
	};
}

// =============================================================================
// HANDLER ADAPTER
// =============================================================================

/**
 * Adapt a legacy handler to the new handler signature
 *
 * Wraps a LegacyToolHandler to work with NewToolContext.
 * The legacy handler receives a converted context.
 *
 * @param legacyHandler - Original handler from old registry
 * @returns New-style handler compatible with ToolRegistry
 */
export function adaptLegacyHandler(legacyHandler: LegacyToolHandler): NewToolHandler {
	return async (input: unknown, context: NewToolContext): Promise<ToolResult> => {
		// Convert new context to legacy context
		const legacyContext = createLegacyContextFromNew(context);

		// Call the legacy handler with adapted context
		const result = await legacyHandler(input as Record<string, unknown>, legacyContext);

		// Return result unchanged (ToolResult is compatible)
		return result;
	};
}

// =============================================================================
// TOOL ADAPTER
// =============================================================================

/**
 * Adapt a legacy VrekoTool to a new ToolDefinition
 *
 * Converts the old tool format to the new format, including:
 * - Inferring capabilities from tool name
 * - Mapping tier (with default to "free")
 * - Wrapping handler for context adaptation
 * - Preserving annotations and deprecated flag
 *
 * @param legacyTool - VrekoTool from old registry
 * @param handler - Legacy handler function
 * @returns ToolDefinition compatible with new ToolRegistry
 */
export function adaptLegacyTool(legacyTool: VrekoTool, handler: LegacyToolHandler): ToolDefinition {
	// Map legacy tier to new tier (legacy only has "free" | "pro")
	const mapTier = (legacyTier?: "free" | "pro"): ToolTier => {
		if (legacyTier === "pro") {
			return "pro";
		}
		return "free";
	};

	return {
		name: legacyTool.name,
		description: legacyTool.description ?? `Tool: ${legacyTool.name}`,
		inputSchema: legacyTool.inputSchema,
		capabilities: inferCapabilities(legacyTool.name),
		tier: mapTier(legacyTool.tier),
		handler: adaptLegacyHandler(handler),
		annotations: legacyTool.annotations,
		deprecated: legacyTool.deprecated,
	};
}

// =============================================================================
// BATCH ADAPTER
// =============================================================================

/**
 * Adapt multiple legacy tools at once
 *
 * @param tools - Array of [VrekoTool, LegacyToolHandler] pairs
 * @returns Array of ToolDefinitions
 */
export function adaptLegacyTools(tools: Array<[VrekoTool, LegacyToolHandler]>): ToolDefinition[] {
	return tools.map(([tool, handler]) => adaptLegacyTool(tool, handler));
}

// =============================================================================
// CONVENIENCE: Pre-adapted Consolidated Tools
// =============================================================================

/**
 * Get all consolidated tools adapted to ToolDefinition format
 *
 * This is a convenience function that imports the consolidated tools
 * and adapts them for use with the new ToolRegistry.
 *
 * Respects VREKO_MCP_INTELLIGENCE_SURFACE environment variable:
 * - "minimal" (default): Returns EXPOSED_MCP_TOOLS (7-command mental model)
 * - "full": Returns CONSOLIDATED_TOOLS (includes intelligence layer)
 *
 * @returns Promise resolving to array of adapted ToolDefinitions
 *
 * @example
 * ```typescript
 * import { createToolRegistry } from './registry';
 * import { getAdaptedConsolidatedTools } from './registry/adapter';
 *
 * const registry = createToolRegistry();
 * const tools = await getAdaptedConsolidatedTools();
 * tools.forEach(tool => registry.register(tool));
 * ```
 */
export async function getAdaptedConsolidatedTools(): Promise<ToolDefinition[]> {
	// Dynamic import to avoid circular dependencies
	const { CONSOLIDATED_TOOLS, EXPOSED_MCP_TOOLS, CONSOLIDATED_HANDLERS } = await import(
		"../tools/consolidated/registry.js"
	);

	// Check intelligence surface mode
	const intelligenceSurface = process.env.VREKO_MCP_INTELLIGENCE_SURFACE || "minimal";
	const toolsToExpose = intelligenceSurface === "full" ? CONSOLIDATED_TOOLS : EXPOSED_MCP_TOOLS;

	const toolPairs = toolsToExpose.map((tool) => [
		tool as VrekoTool,
		CONSOLIDATED_HANDLERS[tool.name] as LegacyToolHandler,
	]) as Array<[VrekoTool, LegacyToolHandler]>;

	return adaptLegacyTools(toolPairs);
}
